            <div className="sm:w-48 h-48 sm:h-auto overflow-hidden shrink-0">
              <img src={item.imageUrl} alt={item.name} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
            </div>
            <div className="flex-1 p-6 flex flex-col justify-between relative">
              <div>
                <div className="flex justify-between items-start mb-2">
                  <h3 className="text-lg font-bold text-slate-800 group-hover:text-amber-600 transition-colors">{item.name}</h3>
                  <span className="text-amber-600 font-black">Rp {(item.price/1000).toFixed(0)}k</span>
                </div>
                <p className={`text-slate-500 text-xs line-clamp-3 mb-4 italic leading-relaxed transition-all duration-700 ${successId === item.id ? 'text-amber-600 bg-amber-50 rounded-lg p-2' : ''}`}>
                  {item.description}
                </p>
                <div className="flex items-center gap-3">
                  <span className="px-2 py-1 bg-slate-50 text-slate-400 rounded-lg text-[9px] font-black uppercase tracking-widest border border-slate-100">{item.category}</span>
                  <span className="text-[10px] text-slate-400 font-bold uppercase tracking-tighter">{item.salesCount} Penjualan</span>
                </div>
              </div>

              <div className="mt-6 flex items-center gap-2">
                <button 
                  onClick={() => handleAIUIOptimize(item)}
                  disabled={!!optimizingId}
                  className={`flex-1 text-[10px] font-black uppercase tracking-widest py-3 rounded-xl flex items-center justify-center gap-2 transition-all border ${
                    optimizingId === item.id 
                      ? 'bg-amber-100 text-amber-700 border-amber-200 animate-pulse' 
                      : 'bg-white hover:bg-slate-50 text-slate-600 border-slate-200'
                  } disabled:opacity-50`}
                >
                  {optimizingId === item.id ? (
                    <Loader2 size={14} className="animate-spin" />
                  ) : (
                    <Sparkles size={14} className="text-amber-500" />
                  )}
                  {optimizingId === item.id ? 'Optimasi AI...' : 'AI Deskripsi'}
                </button>
                <button className="p-3 bg-rose-50 text-rose-400 hover:text-rose-600 hover:bg-rose-100 rounded-xl transition-all" onClick={() => onUpdateMenu(menu.filter(m => m.id !== item.id))}>
                  <Trash2 size={16} />
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* ADD MENU MODAL */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setIsModalOpen(false)}></div>
          <div className="bg-white rounded-[2.5rem] w-full max-w-lg overflow-hidden shadow-2xl relative z-10 animate-in zoom-in-95 duration-300">
            <div className="p-8 pb-4 flex justify-between items-center">
              <div>
                <h3 className="text-2xl font-black text-slate-900">Tambah Menu Baru</h3>
                <p className="text-sm text-slate-400">Buat hidangan katering baru untuk katalog Anda.</p>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-slate-50 rounded-full text-slate-400 transition-all">
                <X size={24} />
              </button>
            </div>

            <div className="p-8 pt-4 space-y-5">
              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div className="col-span-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">Nama Hidangan</label>
                    <input 
                      type="text" 
                      placeholder="Contoh: Nasi Tumpeng Mini"
                      className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-4 py-3 text-sm font-semibold outline-none focus:ring-2 focus:ring-amber-500/20"
                      value={formData.name}
                      onChange={(e) => setFormData({...formData, name: e.target.value})}
                    />
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">Kategori</label>
                    <select 
                      className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-4 py-3 text-sm font-semibold outline-none focus:ring-2 focus:ring-amber-500/20"
                      value={formData.category}
                      onChange={(e) => setFormData({...formData, category: e.target.value as any})}
                    >
                      <option value="Main Course">Main Course</option>
                      <option value="Appetizer">Appetizer</option>
                      <option value="Dessert">Dessert</option>
                      <option value="Package">Paket</option>
                    </select>
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">Harga Jual (Rp)</label>
                    <input 
                      type="number" 
                      placeholder="45000"
                      className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-4 py-3 text-sm font-semibold outline-none focus:ring-2 focus:ring-amber-500/20"
                      value={formData.price}
                      onChange={(e) => setFormData({...formData, price: Number(e.target.value)})}
                    />
                  </div>
                </div>

                <div>
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">Deskripsi Singkat</label>
                  <textarea 
                    placeholder="Deskripsikan kelezatan hidangan ini..."
                    rows={3}
                    className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-4 py-3 text-sm font-semibold outline-none focus:ring-2 focus:ring-amber-500/20 resize-none"
                    value={formData.description}
                    onChange={(e) => setFormData({...formData, description: e.target.value})}
                  />
                </div>

                <div>
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">URL Gambar Hidangan</label>
                  <div className="flex items-center bg-slate-50 border border-slate-100 rounded-2xl px-4 py-3">
                    <ImageIcon size={18} className="text-slate-400 mr-3" />
                    <input 
                      type="text" 
                      placeholder="https://..."
                      className="bg-transparent border-none outline-none text-xs w-full font-semibold"
                      value={formData.imageUrl}
                      onChange={(e) => setFormData({...formData, imageUrl: e.target.value})}
                    />
                  </div>
                </div>
              </div>

              <button 
                onClick={handleSaveNewItem}
                className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold flex items-center justify-center gap-2 hover:bg-amber-600 transition-all shadow-xl shadow-slate-100"
              >
                <Check size={20} />
                Simpan Ke Katalog
              </button>
            </div>
          </div>
        </div>
      )}

      {/* SHARE MODAL */}
      {isShareModalOpen && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setIsShareModalOpen(false)}></div>
          <div className="bg-white rounded-[2.5rem] w-full max-w-md overflow-hidden shadow-2xl relative z-10 animate-in zoom-in-95 duration-300">
            <div className="bg-amber-500 p-8 text-white relative overflow-hidden">
              <h3 className="text-2xl font-black mb-2">Pusat Berbagi</h3>
              <p className="text-amber-100 text-sm font-medium leading-relaxed">
