            </div>

            <div className="p-8 space-y-8">
              <div className="flex flex-col items-center gap-4">
                <div className="bg-white p-4 rounded-[2rem] shadow-xl border-4 border-slate-50 relative group">
                  <div className="w-48 h-48 bg-slate-100 rounded-2xl flex items-center justify-center border-2 border-dashed border-slate-200">
                    <QrCode size={120} className="text-slate-300" />
                  </div>
                  <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity bg-white/80 backdrop-blur-sm rounded-[1.8rem]">
                     <button className="bg-slate-900 text-white px-4 py-2 rounded-xl text-xs font-bold flex items-center gap-2">
