import React, { useState } from 'react';
import { Plus, Search, Filter, MoreHorizontal, ShoppingBag, X, Check, User, Hash, CreditCard, ChevronDown } from 'lucide-react';
import { Order } from '../types';

interface OrdersListProps {
  orders: Order[];
  onUpdateOrder: (orderId: string, updates: Partial<Order>) => void;
}

const OrdersList: React.FC<OrdersListProps> = ({ orders, onUpdateOrder }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [updatingPaymentId, setUpdatingPaymentId] = useState<string | null>(null);

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'Delivered': return 'bg-emerald-50 text-emerald-600 border-emerald-100';
      case 'Confirmed': return 'bg-blue-50 text-blue-600 border-blue-100';
      case 'Pending': return 'bg-amber-50 text-amber-600 border-amber-100';
      case 'Cancelled': return 'bg-rose-50 text-rose-600 border-rose-100';
      default: return 'bg-slate-50 text-slate-600 border-slate-100';
    }
  };

  const getPaymentBadge = (status: string) => {
    switch (status) {
      case 'Paid': return 'bg-emerald-100 text-emerald-700 border-emerald-200';
      case 'Partial': return 'bg-amber-100 text-amber-700 border-amber-200';
      case 'Unpaid': return 'bg-rose-100 text-rose-700 border-rose-200';
      default: return 'bg-slate-100 text-slate-600 border-slate-200';
    }
  };

  const handleUpdatePayment = (orderId: string, status: 'Paid' | 'Partial' | 'Unpaid') => {
    const order = orders.find(o => o.id === orderId);
    if (!order) return;

    let amountPaid = order.amountPaid;
    if (status === 'Paid') amountPaid = order.totalPrice;
    else if (status === 'Unpaid') amountPaid = 0;

    onUpdateOrder(orderId, { paymentStatus: status, amountPaid });
    setUpdatingPaymentId(null);
  };

  return (
    <div className="bg-white rounded-3xl p-6 md:p-8 border border-slate-100 shadow-sm animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-8">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Manajemen Pesanan</h2>
          <p className="text-sm text-slate-400 mt-1">Catat pesanan dari WhatsApp atau Telepon di sini.</p>
        </div>
        <button 
          onClick={() => setIsModalOpen(true)}
          className="bg-slate-900 text-white px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 hover:bg-slate-800 transition-all shadow-lg shadow-slate-200"
        >
          <Plus size={18} /> Input Pesanan Manual
        </button>
      </div>

      <div className="overflow-x-auto -mx-6 md:mx-0">
        <table className="w-full text-left border-separate border-spacing-y-3">
          <thead>
            <tr className="text-slate-400 text-[10px] font-black uppercase tracking-[0.2em] px-4">
              <th className="pb-4 pl-6">ID / Customer</th>
              <th className="pb-4">Menu Items</th>
              <th className="pb-4">Status</th>
              <th className="pb-4">Payment</th>
              <th className="pb-4 text-right">Aksi</th>
            </tr>
          </thead>
          <tbody>
            {orders.map((o) => (
              <tr key={o.id} className="group hover:bg-slate-50 transition-all">
                <td className="py-4 pl-6 bg-white border-y border-l border-slate-50 rounded-l-2xl group-hover:bg-slate-50">
                  <div className="flex items-center gap-4">
                    <div className="w-10 h-10 bg-slate-50 rounded-xl flex items-center justify-center text-slate-400 group-hover:bg-white group-hover:text-amber-500 transition-all">
                      <ShoppingBag size={20} />
                    </div>
                    <div>
                      <p className="font-bold text-slate-800 text-sm">#{o.id}</p>
                      <p className="text-xs text-slate-500">{o.customerName}</p>
                    </div>
                  </div>
                </td>
                <td className="py-4 bg-white border-y border-slate-50 group-hover:bg-slate-50">
                  <p className="text-xs text-slate-600 font-medium line-clamp-1">{o.items.join(', ')}</p>
                  <p className="text-[10px] text-slate-400 mt-1">{o.date}</p>
