  return (
    <aside className={`${isOpen ? 'w-72' : 'w-20'} bg-white border-r border-slate-200 transition-all duration-500 ease-[cubic-bezier(0.4,0,0.2,1)] hidden md:flex flex-col relative z-30`}>
      <button 
