            <div className={`overflow-hidden transition-all duration-500 ease-in-out ${isOpen ? 'w-40 opacity-100 ml-4' : 'w-0 opacity-0 ml-0'}`}>
              <span className="text-sm font-semibold whitespace-nowrap">{item.label}</span>
            </div>
          </button>
        ))}
      </nav>

      <div className="p-4 border-t border-slate-100 space-y-2">
        <button 
          onClick={onPreviewMenu}
          className="w-full group relative flex items-center px-4 py-3.5 rounded-xl bg-amber-50 text-amber-600 hover:bg-amber-100 transition-all duration-300 border border-amber-100 shadow-sm"
        >
          <div className="group-hover:rotate-12 transition-transform">
            <Eye size={22} />
          </div>
          <div className={`overflow-hidden transition-all duration-500 ${isOpen ? 'w-40 opacity-100 ml-4' : 'w-0 opacity-0 ml-0'}`}>
            <span className="text-sm font-black whitespace-nowrap uppercase tracking-wider">Preview Menu</span>
          </div>
        </button>

        <button className="w-full group flex items-center px-4 py-3.5 rounded-xl text-rose-400 hover:bg-rose-50 hover:text-rose-600 transition-all duration-300">
          <LogOut size={22} />
          <div className={`overflow-hidden transition-all duration-500 ${isOpen ? 'w-40 opacity-100 ml-4' : 'w-0 opacity-0 ml-0'}`}>
            <span className="text-sm font-semibold whitespace-nowrap">Keluar</span>
          </div>
        </button>
      </div>
    </aside>
  );
};

