import React, { useRef } from 'react';
import { Save, MessageCircle, Store, MapPin, BadgeDollarSign, CheckCircle2, Image as ImageIcon, Upload, X } from 'lucide-react';
import { StoreSettings } from '../types';

interface SettingsProps {
  settings: StoreSettings;
  onUpdateSettings: (settings: StoreSettings) => void;
}

const Settings: React.FC<SettingsProps> = ({ settings, onUpdateSettings }) => {
  const [localSettings, setLocalSettings] = React.useState(settings);
  const [showSaved, setShowSaved] = React.useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSave = () => {
    onUpdateSettings(localSettings);
    setShowSaved(true);
    setTimeout(() => setShowSaved(false), 3000);
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setLocalSettings({ ...localSettings, logoUrl: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-end mb-4">
        <button 
          onClick={handleSave}
          className="bg-slate-900 text-white px-8 py-3.5 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-amber-500 transition-all shadow-xl shadow-slate-200 flex items-center gap-2"
        >
          <Save size={18} />
          Simpan Konfigurasi
        </button>
      </div>

      {showSaved && (
        <div className="bg-emerald-50 border border-emerald-100 p-4 rounded-2xl flex items-center gap-3 text-emerald-700 animate-in slide-in-from-top-2">
          <CheckCircle2 size={20} />
          <p className="text-sm font-bold">Pengaturan berhasil diperbarui!</p>
        </div>
      )}

      <div className="space-y-6 pb-12">
        {/* Logo Toko */}
        <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm space-y-6">
          <div className="flex items-center gap-3">
            <div className="p-2.5 bg-slate-50 rounded-xl border border-slate-100">
              <ImageIcon size={20} className="text-slate-600" />
            </div>
            <h3 className="font-black text-slate-800 uppercase tracking-widest text-[10px]">Logo Toko</h3>
          </div>

          <div className="flex flex-col sm:flex-row items-center gap-8">
            <div className="relative group">
              <div className="w-32 h-32 rounded-[2rem] bg-slate-100 border-4 border-white shadow-xl overflow-hidden flex items-center justify-center">
                {localSettings.logoUrl ? (
                  <img src={localSettings.logoUrl} alt="Logo Preview" className="w-full h-full object-cover" />
                ) : (
                  <Store size={40} className="text-slate-300" />
                )}
              </div>
              {localSettings.logoUrl && (
                <button 
                  onClick={() => setLocalSettings({...localSettings, logoUrl: ''})}
                  className="absolute -top-2 -right-2 bg-rose-500 text-white p-1.5 rounded-full shadow-lg hover:bg-rose-600 transition-colors"
                >
                  <X size={14} />
                </button>
              )}
            </div>

            <div className="flex-1 w-full space-y-4">
              <p className="text-xs text-slate-500 font-medium leading-relaxed">
                Gunakan logo yang mewakili brand katering Anda. Logo ini akan muncul di Katalog Menu Digital dan Dashboard.
              </p>
              <div className="flex flex-wrap gap-3">
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className="bg-slate-100 text-slate-700 px-5 py-2.5 rounded-xl text-xs font-bold hover:bg-slate-200 transition-all flex items-center gap-2"
                >
                  <Upload size={16} />
                  Upload Gambar
                </button>
                <input 
                  type="file" 
                  ref={fileInputRef} 
                  onChange={handleLogoUpload} 
                  className="hidden" 
                  accept="image/*" 
                />
                <div className="flex-1 min-w-[200px]">
                   <input 
                    type="text" 
                    placeholder="Atau masukkan URL logo..."
                    className="w-full bg-slate-50 border border-slate-100 rounded-xl px-4 py-2.5 text-xs font-semibold outline-none focus:ring-2 focus:ring-amber-500/20"
                    value={localSettings.logoUrl}
                    onChange={(e) => setLocalSettings({...localSettings, logoUrl: e.target.value})}
                  />
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Profile Bisnis */}
        <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm space-y-6">
          <div className="flex items-center gap-3">
            <div className="p-2.5 bg-slate-50 rounded-xl border border-slate-100">
              <Store size={20} className="text-slate-600" />
            </div>
            <h3 className="font-black text-slate-800 uppercase tracking-widest text-[10px]">Identitas Bisnis</h3>
          </div>

          <div className="space-y-5">
            <div>
              <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">Nama Katering</label>
              <input 
                type="text" 
                className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-3.5 text-sm font-semibold outline-none focus:ring-2 focus:ring-amber-500/20 focus:bg-white transition-all"
                value={localSettings.storeName}
                onChange={(e) => setLocalSettings({...localSettings, storeName: e.target.value})}
              />
            </div>
            <div>
              <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">Alamat Kantor / Dapur</label>
              <div className="flex items-start bg-slate-50 border border-slate-100 rounded-2xl px-5 py-4 focus-within:ring-2 focus-within:ring-amber-500/20 focus-within:bg-white transition-all">
                <MapPin size={18} className="text-slate-400 mt-0.5 mr-3 shrink-0" />
                <textarea 
                  className="bg-transparent border-none outline-none text-sm w-full font-semibold resize-none"
                  rows={3}
                  value={localSettings.address}
                  onChange={(e) => setLocalSettings({...localSettings, address: e.target.value})}
                ></textarea>
              </div>
            </div>
          </div>
        </div>

        {/* WhatsApp & Integrasi */}
        <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm space-y-6">
          <div className="flex items-center gap-3">
            <div className="p-2.5 bg-emerald-50 rounded-xl border border-emerald-100">
              <MessageCircle size={20} className="text-emerald-600" />
            </div>
            <h3 className="font-black text-slate-800 uppercase tracking-widest text-[10px]">Integrasi WhatsApp</h3>
          </div>

          <div className="space-y-6">
            <div className="p-6 bg-emerald-50/50 rounded-3xl border border-emerald-100">
              <div className="flex items-center gap-3 mb-3 text-emerald-700">
                <MessageCircle size={18} fill="currentColor" className="opacity-20" />
                <span className="text-[9px] font-black uppercase tracking-widest">WhatsApp Admin</span>
              </div>
              <p className="text-xs text-emerald-800/60 mb-5 font-medium leading-relaxed">Masukkan nomor WhatsApp aktif. Semua pesanan dari menu digital akan dikirimkan ke nomor ini.</p>
              <div className="relative">
                <span className="absolute left-5 top-1/2 -translate-y-1/2 text-sm font-black text-slate-400">+</span>
                <input 
                  type="text" 
                  placeholder="628123456789"
                  className="w-full pl-8 pr-5 py-4 bg-white border border-emerald-100 rounded-2xl text-sm font-black text-slate-800 outline-none focus:ring-4 focus:ring-emerald-500/10 shadow-sm"
                  value={localSettings.whatsappNumber}
                  onChange={(e) => setLocalSettings({...localSettings, whatsappNumber: e.target.value.replace(/\D/g, '')})}
                />
              </div>
              <p className="text-[9px] text-emerald-600 font-black mt-3 uppercase tracking-tighter italic">* Pastikan menggunakan kode negara (62)</p>
            </div>

            <div className="px-1">
              <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">Mata Uang</label>
              <div className="flex items-center bg-slate-50 border border-slate-100 rounded-2xl px-5 py-4 focus-within:ring-2 focus-within:ring-amber-500/20 focus-within:bg-white transition-all">
                <BadgeDollarSign size={18} className="text-slate-400 mr-3" />
                <input 
                  type="text" 
                  className="bg-transparent border-none outline-none text-sm w-full font-bold text-slate-800"
                  value={localSettings.currencySymbol}
                  onChange={(e) => setLocalSettings({...localSettings, currencySymbol: e.target.value})}
                />
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

