import React, { useState, useRef } from 'react';
import { Plus, Sparkles, Trash2, Loader2, X, Image as ImageIcon, Save, CheckCircle, Upload, Share2, Copy, QrCode, ExternalLink, Check, Tag } from 'lucide-react';
import { MenuItem } from '../types';
import { optimizeMenuDescription } from '../services/geminiService';

interface MenuManagerProps {
  menu: MenuItem[];
  onUpdateMenu: (menu: MenuItem[]) => void;
  categories: string[];
  onUpdateCategories: (categories: string[]) => void;
}

const MenuManager: React.FC<MenuManagerProps> = ({ menu, onUpdateMenu, categories, onUpdateCategories }) => {
  const [optimizingId, setOptimizingId] = useState<string | null>(null);
  const [successId, setSuccessId] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isShareModalOpen, setIsShareModalOpen] = useState(false);
  const [isCatModalOpen, setIsCatModalOpen] = useState(false);
  const [newCatName, setNewCatName] = useState('');
  const [copySuccess, setCopySuccess] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<MenuItem>>({
    name: '',
    category: categories[0] || '',
    price: 0,
    cost: 0,
    description: '',
    imageUrl: ''
  });

  const handleCopyLink = () => {
    setCopySuccess(true);
    setTimeout(() => setCopySuccess(false), 2000);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData({ ...formData, imageUrl: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAIUIOptimize = async (item: MenuItem) => {
    setOptimizingId(item.id);
    try {
      const newDesc = await optimizeMenuDescription(item.name, item.description);
      if (newDesc) {
        const updatedMenu = menu.map(m => 
          m.id === item.id ? { ...m, description: newDesc.trim() } : m
        );
        onUpdateMenu(updatedMenu);
        setSuccessId(item.id);
        setTimeout(() => setSuccessId(null), 3000);
      }
    } catch (error) {
      console.error("Optimization failed", error);
    } finally {
      setOptimizingId(null);
    }
  };

  const handleSaveNewItem = () => {
    const newItem: MenuItem = {
      id: Math.random().toString(36).substr(2, 9),
      name: formData.name || 'Menu Baru',
      category: formData.category || categories[0] || 'Uncategorized',
      price: Number(formData.price) || 0,
      cost: Number(formData.cost) || 0,
      description: formData.description || '',
      salesCount: 0,
      imageUrl: formData.imageUrl || 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&q=80&w=400'
    };
    onUpdateMenu([...menu, newItem]);
    setIsModalOpen(false);
    setFormData({ name: '', category: categories[0], price: 0, cost: 0, description: '', imageUrl: '' });
  };

  const handleAddCategory = () => {
    if (newCatName && !categories.includes(newCatName)) {
      onUpdateCategories([...categories, newCatName]);
      setNewCatName('');
    }
  };

  const handleDeleteCategory = (cat: string) => {
    onUpdateCategories(categories.filter(c => c !== cat));
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Manajemen Menu</h2>
          <p className="text-sm text-slate-500 mt-1">Atur hidangan katering dan bagikan ke pelanggan.</p>
        </div>
        <div className="flex flex-wrap gap-2 w-full sm:w-auto">
          <button 
            onClick={() => setIsCatModalOpen(true)}
            className="flex-1 sm:flex-none bg-white text-slate-600 border border-slate-200 px-5 py-2.5 rounded-xl flex items-center justify-center gap-2 hover:bg-slate-50 transition-all font-bold text-sm"
          >
            <Tag size={18} />
            Kelola Kategori
          </button>
          <button 
            onClick={() => setIsShareModalOpen(true)}
            className="flex-1 sm:flex-none bg-amber-50 text-amber-700 border border-amber-200 px-5 py-2.5 rounded-xl flex items-center justify-center gap-2 hover:bg-amber-100 transition-all font-bold text-sm"
          >
            <Share2 size={18} />
            Bagikan Menu
          </button>
          <button 
            onClick={() => setIsModalOpen(true)}
            className="flex-1 sm:flex-none bg-slate-900 hover:bg-slate-800 text-white px-5 py-2.5 rounded-xl flex items-center justify-center gap-2 transition-all shadow-lg shadow-slate-200 font-bold text-sm"
          >
            <Plus size={20} />
            Tambah Menu
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {menu.map((item) => (
          <div key={item.id} className="bg-white rounded-3xl border border-slate-100 overflow-hidden flex flex-col sm:flex-row group hover:shadow-xl hover:shadow-slate-100 transition-all">
            <div className="sm:w-48 h-48 sm:h-auto overflow-hidden shrink-0">
              <img src={item.imageUrl} alt={item.name} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
            </div>
            <div className="flex-1 p-6 flex flex-col justify-between relative">
              <div>
                <div className="flex justify-between items-start mb-2">
                  <h3 className="text-lg font-bold text-slate-800 group-hover:text-amber-600 transition-colors">{item.name}</h3>
                  <span className="text-amber-600 font-black">Rp {(item.price/1000).toFixed(0)}k</span>
                </div>
                <p className={`text-slate-500 text-xs line-clamp-3 mb-4 italic leading-relaxed transition-all duration-700 ${successId === item.id ? 'text-amber-600 bg-amber-50 rounded-lg p-2' : ''}`}>
                  {item.description}
                </p>
                <div className="flex items-center gap-3">
                  <span className="px-2 py-1 bg-slate-50 text-slate-400 rounded-lg text-[9px] font-black uppercase tracking-widest border border-slate-100">{item.category}</span>
                  <span className="text-[10px] text-slate-400 font-bold uppercase tracking-tighter">{item.salesCount} Penjualan</span>
                </div>
              </div>

              <div className="mt-6 flex items-center gap-2">
                <button 
                  onClick={() => handleAIUIOptimize(item)}
                  disabled={!!optimizingId}
                  className={`flex-1 text-[10px] font-black uppercase tracking-widest py-3 rounded-xl flex items-center justify-center gap-2 transition-all border ${
                    optimizingId === item.id 
                      ? 'bg-amber-100 text-amber-700 border-amber-200 animate-pulse' 
                      : 'bg-white hover:bg-slate-50 text-slate-600 border-slate-200'
                  } disabled:opacity-50`}
                >
                  {optimizingId === item.id ? (
                    <Loader2 size={14} className="animate-spin" />
                  ) : (
                    <Sparkles size={14} className="text-amber-500" />
                  )}
                  {optimizingId === item.id ? 'Optimasi AI...' : 'AI Deskripsi'}
                </button>
                <button className="p-3 bg-rose-50 text-rose-400 hover:text-rose-600 hover:bg-rose-100 rounded-xl transition-all" onClick={() => onUpdateMenu(menu.filter(m => m.id !== item.id))}>
                  <Trash2 size={16} />
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* CATEGORY MANAGEMENT MODAL */}
      {isCatModalOpen && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setIsCatModalOpen(false)}></div>
          <div className="bg-white rounded-[2.5rem] w-full max-w-md overflow-hidden shadow-2xl relative z-10 animate-in zoom-in-95 duration-300">
            <div className="p-8 pb-4 flex justify-between items-center">
              <div>
                <h3 className="text-2xl font-black text-slate-900">Kelola Kategori</h3>
                <p className="text-sm text-slate-400">Atur kategori pengelompokan menu.</p>
              </div>
              <button onClick={() => setIsCatModalOpen(false)} className="p-2 hover:bg-slate-50 rounded-full text-slate-400 transition-all">
                <X size={24} />
              </button>
            </div>

            <div className="p-8 pt-4 space-y-6">
              <div className="flex gap-2">
                <input 
                  type="text" 
                  placeholder="Kategori Baru..."
                  className="flex-1 bg-slate-50 border border-slate-100 rounded-2xl px-4 py-3 text-sm font-semibold outline-none focus:ring-2 focus:ring-amber-500/20"
                  value={newCatName}
                  onChange={(e) => setNewCatName(e.target.value)}
                  onKeyPress={(e) => e.key === 'Enter' && handleAddCategory()}
                />
                <button 
                  onClick={handleAddCategory}
                  className="bg-slate-900 text-white p-3 px-5 rounded-2xl font-bold hover:bg-amber-600 transition-all"
                >
                  Tambah
                </button>
              </div>

              <div className="space-y-2 max-h-60 overflow-y-auto no-scrollbar">
                {categories.map((cat) => (
                  <div key={cat} className="flex justify-between items-center p-4 bg-slate-50 rounded-2xl border border-slate-100">
                    <span className="text-sm font-bold text-slate-700">{cat}</span>
                    <button 
                      onClick={() => handleDeleteCategory(cat)}
                      className="p-2 text-rose-400 hover:bg-rose-50 rounded-xl transition-all"
                    >
                      <Trash2 size={16} />
                    </button>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* ADD MENU MODAL */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setIsModalOpen(false)}></div>
          <div className="bg-white rounded-[2.5rem] w-full max-w-lg overflow-hidden shadow-2xl relative z-10 animate-in zoom-in-95 duration-300">
            <div className="p-8 pb-4 flex justify-between items-center">
              <div>
                <h3 className="text-2xl font-black text-slate-900">Tambah Menu Baru</h3>
                <p className="text-sm text-slate-400">Buat hidangan katering baru untuk katalog Anda.</p>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-slate-50 rounded-full text-slate-400 transition-all">
                <X size={24} />
              </button>
            </div>

            <div className="p-8 pt-4 space-y-5">
              <div className="space-y-4">
                <div className="flex flex-col sm:flex-row items-center gap-6 mb-4">
                  <div className="relative group">
                    <div className="w-28 h-28 rounded-2xl bg-slate-100 border-2 border-dashed border-slate-200 flex items-center justify-center overflow-hidden">
                      {formData.imageUrl ? (
                        <img src={formData.imageUrl} alt="Preview" className="w-full h-full object-cover" />
                      ) : (
                        <ImageIcon size={32} className="text-slate-300" />
                      )}
                    </div>
                    {formData.imageUrl && (
                      <button 
                        onClick={() => setFormData({...formData, imageUrl: ''})}
                        className="absolute -top-2 -right-2 bg-rose-500 text-white p-1 rounded-full shadow-lg"
                      >
                        <X size={12} />
                      </button>
                    )}
                  </div>
                  <div className="flex-1 space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 block">Foto Hidangan</label>
                    <button 
                      onClick={() => fileInputRef.current?.click()}
                      className="bg-slate-100 text-slate-700 px-4 py-2 rounded-xl text-xs font-bold hover:bg-slate-200 transition-all flex items-center gap-2"
                    >
                      <Upload size={14} />
                      Unggah Gambar
                    </button>
                    <input 
                      type="file" 
                      ref={fileInputRef} 
                      onChange={handleImageUpload} 
                      className="hidden" 
                      accept="image/*" 
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="col-span-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">Nama Hidangan</label>
                    <input 
                      type="text" 
                      placeholder="Contoh: Nasi Tumpeng Mini"
                      className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-4 py-3 text-sm font-semibold outline-none focus:ring-2 focus:ring-amber-500/20"
                      value={formData.name}
                      onChange={(e) => setFormData({...formData, name: e.target.value})}
                    />
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">Kategori</label>
                    <select 
                      className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-4 py-3 text-sm font-semibold outline-none focus:ring-2 focus:ring-amber-500/20"
                      value={formData.category}
                      onChange={(e) => setFormData({...formData, category: e.target.value})}
                    >
                      {categories.map(cat => (
                        <option key={cat} value={cat}>{cat}</option>
                      ))}
                    </select>
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">Harga Jual (Rp)</label>
                    <input 
                      type="number" 
                      placeholder="45000"
                      className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-4 py-3 text-sm font-semibold outline-none focus:ring-2 focus:ring-amber-500/20"
                      value={formData.price}
                      onChange={(e) => setFormData({...formData, price: Number(e.target.value)})}
                    />
                  </div>
                </div>

                <div>
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">Deskripsi Singkat</label>
                  <textarea 
                    placeholder="Deskripsikan kelezatan hidangan ini..."
                    rows={3}
                    className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-4 py-3 text-sm font-semibold outline-none focus:ring-2 focus:ring-amber-500/20 resize-none"
                    value={formData.description}
                    onChange={(e) => setFormData({...formData, description: e.target.value})}
                  />
                </div>
              </div>

              <button 
                onClick={handleSaveNewItem}
                className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold flex items-center justify-center gap-2 hover:bg-amber-600 transition-all shadow-xl shadow-slate-100"
              >
                <Check size={20} />
                Simpan Ke Katalog
              </button>
            </div>
          </div>
        </div>
      )}

      {/* SHARE MODAL */}
      {isShareModalOpen && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setIsShareModalOpen(false)}></div>
          <div className="bg-white rounded-[2.5rem] w-full max-w-md overflow-hidden shadow-2xl relative z-10 animate-in zoom-in-95 duration-300">
            <div className="bg-amber-500 p-8 text-white relative overflow-hidden">
              <h3 className="text-2xl font-black mb-2">Pusat Berbagi</h3>
              <p className="text-amber-100 text-sm font-medium leading-relaxed">
                Pelanggan tidak perlu download apa pun. Kirim link ini atau tunjukkan QR Code.
              </p>
              <div className="absolute -bottom-8 -right-8 opacity-20 rotate-12">
                <Share2 size={120} />
              </div>
            </div>

            <div className="p-8 space-y-8">
              <div className="flex flex-col items-center gap-4">
                <div className="bg-white p-4 rounded-[2rem] shadow-xl border-4 border-slate-50 relative group">
                  <div className="w-48 h-48 bg-slate-100 rounded-2xl flex items-center justify-center border-2 border-dashed border-slate-200">
                    <QrCode size={120} className="text-slate-300" />
                  </div>
                  <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity bg-white/80 backdrop-blur-sm rounded-[1.8rem]">
