import React, { useState, useRef } from 'react';
import { Sparkles, Camera, CheckCircle2, AlertCircle, Loader2, Package, Utensils, History, TrendingDown, Scale, Plus, Trash2, ShoppingCart } from 'lucide-react';
import { analyzeKitchenStock } from '../services/geminiService';
import { AnalysisResult } from '../types';

interface IngredientStock {
  id: string;
  name: string;
  quantity: string;
  status: 'Aman' | 'Menipis' | 'Habis';
}

const SmartAdvisor: React.FC = () => {
  const [analyzing, setAnalyzing] = useState(false);
  const [result, setResult] = useState<AnalysisResult | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const [inventory, setInventory] = useState<IngredientStock[]>([
    { id: '1', name: 'Beras Premium', quantity: '25kg', status: 'Aman' },
    { id: '2', name: 'Ayam Broiler', quantity: '5kg', status: 'Menipis' },
    { id: '3', name: 'Minyak Goreng', quantity: '2L', status: 'Habis' },
  ]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64String = reader.result as string;
        setPreview(base64String);
        setAnalyzing(true);
        try {
          const res = await analyzeKitchenStock(base64String);
          setResult(res);
        } catch (error) {
          console.error("AI Analysis failed", error);
        } finally {
          setAnalyzing(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Aman': return 'text-emerald-500 bg-emerald-50 border-emerald-100';
      case 'Menipis': return 'text-amber-500 bg-amber-50 border-amber-100';
      case 'Habis': return 'text-rose-500 bg-rose-50 border-rose-100';
      default: return 'text-slate-500 bg-slate-50 border-slate-100';
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      <div className="bg-slate-900 rounded-[2.5rem] p-8 md:p-12 text-white relative overflow-hidden shadow-2xl">
        <div className="relative z-10 flex flex-col md:flex-row items-center gap-10">
          <div className="flex-1">
            <div className="flex items-center gap-2 mb-6">
              <div className="p-2 bg-amber-500 rounded-xl shadow-lg shadow-amber-500/20">
                <Utensils size={20} className="text-white" />
              </div>
              <span className="uppercase tracking-[0.3em] text-[10px] font-black text-amber-500">Kitchen AI & MRP Control</span>
            </div>
            <h2 className="text-4xl font-black mb-6 leading-tight">Optimasi Bahan Baku & Stok</h2>
            <p className="text-slate-400 text-lg mb-8 leading-relaxed font-medium">
              Analisis stok dapur secara visual dengan AI. Pantau tingkat kesegaran bahan dan dapatkan estimasi kapan harus melakukan pengadaan ulang (MRP).
            </p>
            <div className="flex flex-wrap gap-4">
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="bg-white text-slate-900 px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-amber-500 hover:text-white transition-all flex items-center gap-3 shadow-xl"
              >
                <Camera size={20} />
                Analisis Bahan Baku
              </button>
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleFileChange} 
                className="hidden" 
                accept="image/*"
              />
            </div>
          </div>

          <div className="w-full md:w-80 aspect-square bg-white/5 rounded-[2.5rem] border-2 border-dashed border-white/10 flex flex-col items-center justify-center relative group transition-all hover:border-amber-500/50 overflow-hidden">
            {preview ? (
              <img src={preview} alt="Ingredient Preview" className="w-full h-full object-cover" />
            ) : (
              <div className="text-center p-6">
                <div className="w-20 h-20 bg-white/5 rounded-full flex items-center justify-center mx-auto mb-4 group-hover:scale-110 transition-transform">
                  <Package size={40} className="text-slate-600" />
                </div>
                <span className="text-xs font-bold text-slate-500 uppercase tracking-widest">Drop Foto Bahan</span>
              </div>
            )}
            {analyzing && (
              <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-md flex flex-col items-center justify-center p-6 text-center">
                <div className="relative mb-4">
                   <Loader2 className="animate-spin text-amber-500" size={48} />
                   <Sparkles className="absolute -top-2 -right-2 text-white animate-pulse" size={20} />
                </div>
                <span className="text-white text-[10px] font-black tracking-[0.3em] uppercase">AI SEDANG MENGANALISIS...</span>
              </div>
            )}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        {/* Left: Inventory List (MRP) */}
        <div className="lg:col-span-4 space-y-6">
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
            <div className="flex items-center justify-between mb-8">
              <h3 className="text-lg font-black text-slate-800">Daftar Inventaris</h3>
              <button className="p-2 bg-slate-50 text-slate-400 hover:text-amber-500 rounded-xl transition-all">
                <Plus size={20} />
              </button>
            </div>

            <div className="space-y-4">
              {inventory.map(item => (
                <div key={item.id} className="p-4 bg-slate-50 border border-slate-100 rounded-2xl flex items-center justify-between group hover:border-amber-200 transition-all">
                  <div>
                    <p className="text-sm font-black text-slate-800">{item.name}</p>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{item.quantity}</p>
                  </div>
                  <span className={`text-[9px] font-black px-2 py-1 rounded-lg border uppercase tracking-wider ${getStatusColor(item.status)}`}>
                    {item.status}
                  </span>
                </div>
              ))}
            </div>

            <button className="w-full mt-8 bg-slate-900 text-white py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 hover:bg-amber-600 transition-all shadow-lg shadow-slate-200">
              <ShoppingCart size={16} />
              Buat Daftar Belanja
            </button>
          </div>
        </div>

        {/* Right: AI Results */}
        <div className="lg:col-span-8 space-y-6">
          {result ? (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 animate-in slide-in-from-right duration-700">
              <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col items-center text-center justify-center">
                <div className="relative mb-6">
                  <svg className="w-32 h-32">
                    <circle cx="64" cy="64" r="58" fill="none" stroke="#f1f5f9" strokeWidth="10" />
                    <circle 
                      cx="64" cy="64" r="58" fill="none" 
                      stroke={result.freshnessScore > 70 ? '#10b981' : result.freshnessScore > 40 ? '#f59e0b' : '#ef4444'} 
                      strokeWidth="10" 
                      strokeDasharray={364} 
                      strokeDashoffset={364 - (364 * result.freshnessScore) / 100}
                      strokeLinecap="round"
                    />
                  </svg>
                  <div className="absolute inset-0 flex flex-col items-center justify-center">
                    <span className="text-3xl font-black text-slate-900">{result.freshnessScore}%</span>
                    <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest">Freshness</span>
                  </div>
                </div>
                <h4 className="text-xl font-black text-slate-800 mb-1">{result.status}</h4>
                <p className="text-[10px] font-bold text-amber-500 uppercase tracking-widest">Terdeteksi: {result.estimatedQuantity}</p>
              </div>

              <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6">Diagnosis & Rekomendasi</h3>
                <div className="bg-slate-50 p-5 rounded-2xl border border-slate-100 italic text-slate-600 text-xs leading-relaxed mb-6">
                  "{result.diagnosis}"
                </div>
                <div className="space-y-3">
                  {result.recommendations.map((rec, i) => (
                    <div key={i} className="flex gap-3 items-center">
                      <div className="w-5 h-5 bg-amber-100 text-amber-600 rounded-lg flex items-center justify-center text-[10px] font-black">{i + 1}</div>
                      <p className="text-[11px] font-bold text-slate-700">{rec}</p>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          ) : (
            <div className="h-full bg-white/50 rounded-[2.5rem] border-2 border-dashed border-slate-200 flex flex-col items-center justify-center p-12 text-center">
              <Sparkles size={48} className="text-slate-200 mb-4" />
              <p className="text-slate-400 font-bold italic">Belum ada analisis visual.<br/>Ambil foto stok untuk memulai otomatisasi MRP.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default SmartAdvisor;

