import React, { useState, useMemo } from 'react';
import { Search, ShoppingCart, MessageCircle, Info, MapPin, WifiOff, Monitor } from 'lucide-react';
import { MenuItem, StoreSettings } from '../types';

interface PublicMenuProps {
  menu: MenuItem[];
  settings: StoreSettings;
  categories: string[];
  onBackToAdmin: () => void;
}

const PublicMenu: React.FC<PublicMenuProps> = ({ menu, settings, categories, onBackToAdmin }) => {
  const [activeCategory, setActiveCategory] = useState<string>('Semua');
  const [searchQuery, setSearchQuery] = useState('');
  const [cart, setCart] = useState<{ [key: string]: number }>({});

  const displayCategories = ['Semua', ...categories];

  const filteredMenu = useMemo(() => {
    return menu.filter(item => {
      const matchesCategory = activeCategory === 'Semua' || item.category === activeCategory;
      const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase());
      return matchesCategory && matchesSearch;
    });
  }, [menu, activeCategory, searchQuery]);

  const addToCart = (id: string) => {
    setCart(prev => ({ ...prev, [id]: (prev[id] || 0) + 1 }));
  };

  const cartCount = (Object.values(cart) as number[]).reduce((a, b) => a + b, 0);
  const cartTotal = (Object.entries(cart) as [string, number][]).reduce((total, [id, qty]) => {
    const item = menu.find(m => m.id === id);
    return total + (item ? item.price * qty : 0);
  }, 0);

  const handleOrderWhatsApp = () => {
    const cartItemsText = (Object.entries(cart) as [string, number][])
      .map(([id, qty]) => {
        const item = menu.find(m => m.id === id);
        return item ? `• ${item.name} (${qty}x)` : '';
      })
      .filter(text => text !== '')
      .join('\n');

    const message = `Halo ${settings.storeName},\n\nSaya ingin memesan menu katering berikut:\n\n${cartItemsText}\n\nTotal Estimasi: Rp ${cartTotal.toLocaleString()}\n\nMohon informasi selanjutnya. Terima kasih!`;
    window.open(`https://wa.me/${settings.whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 pb-32">
      {/* Hero Header */}
      <div className="bg-[#0f172a] text-white p-8 pt-12 rounded-b-[3.5rem] shadow-2xl relative overflow-hidden min-h-[280px]">
        <div className="relative z-20">
          {/* Offline Toast */}
          <div className="absolute top-0 left-1/2 -translate-x-1/2 w-full max-w-[280px] animate-in slide-in-from-top duration-500">
            <div className="bg-white rounded-xl shadow-2xl p-4 flex items-center gap-3 border border-slate-100">
              <div className="text-rose-400">
                <WifiOff size={18} />
              </div>
              <span className="text-slate-700 text-sm font-medium">You are currently offline</span>
            </div>
          </div>

          <div className="flex justify-between items-center mb-8 mt-12">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-amber-500 rounded-xl flex items-center justify-center font-black text-white shadow-lg overflow-hidden">
                {settings.logoUrl ? (
                  <img src={settings.logoUrl} alt="Logo" className="w-full h-full object-cover" />
                ) : (
                  "CE"
                )}
              </div>
              <span className="font-bold tracking-tight text-lg">{settings.storeName} Digital Menu</span>
            </div>
            <button className="p-2 bg-white/10 rounded-full text-white/80">
              <Info size={20} />
            </button>
          </div>

          <h1 className="text-4xl font-bold mb-3 tracking-tight">Selamat Datang!</h1>
          <p className="text-slate-400 text-sm leading-relaxed max-w-[280px]">
            Pilih hidangan katering terbaik untuk acara spesial Anda.
          </p>
        </div>
        <div className="absolute top-0 right-0 w-64 h-64 bg-slate-800/30 rounded-full -mr-32 -mt-32 blur-3xl"></div>
      </div>

      {/* Search Bar - Overlapping */}
      <div className="px-6 -mt-8 relative z-30">
        <div className="bg-white rounded-[2rem] shadow-xl shadow-slate-200/60 p-1 flex items-center">
          <div className="pl-5 pr-3 text-slate-400">
            <Search size={22} />
          </div>
          <input 
            type="text" 
            placeholder="Cari hidangan favorit..." 
            className="flex-1 py-5 outline-none text-sm font-medium placeholder:text-slate-400"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
      </div>

      {/* Categories */}
      <div className="px-6 mt-10">
        <div className="flex gap-4 overflow-x-auto pb-6 no-scrollbar">
          {displayCategories.map(cat => (
            <button
              key={cat}
              onClick={() => setActiveCategory(cat)}
              className={`px-8 py-3.5 rounded-2xl text-sm font-bold whitespace-nowrap transition-all duration-300 ${
                activeCategory === cat 
                  ? 'bg-gradient-to-br from-amber-400 to-amber-600 text-white shadow-[0_10px_20px_-5px_rgba(245,158,11,0.5)] scale-105' 
                  : 'bg-[#f1f5f9] text-slate-500'
              }`}
            >
              {cat}
            </button>
          ))}
        </div>
      </div>

      {/* Menu Grid */}
      <div className="px-6 mt-4 space-y-10">
        {filteredMenu.map(item => (
          <div key={item.id} className="animate-in fade-in duration-700">
            <div className="relative aspect-[16/11] rounded-[2.5rem] overflow-hidden shadow-2xl shadow-slate-200 mb-6">
              <img src={item.imageUrl} alt={item.name} className="w-full h-full object-cover" />
              <div className="absolute top-6 right-6 bg-white rounded-2xl px-4 py-2 shadow-lg">
                <span className="text-[10px] font-black uppercase tracking-[0.15em] text-slate-800">
                  {item.category === 'Paket Buffet' ? 'PACKAGE' : item.category.toUpperCase()}
                </span>
              </div>
            </div>

            <div className="flex justify-between items-start gap-4">
              <div className="flex-1">
                <h3 className="font-bold text-2xl text-slate-900 mb-2">{item.name}</h3>
                <p className="text-sm text-slate-500 line-clamp-2 italic leading-relaxed">
                  {item.description}
                </p>
                <div className="mt-4 flex items-center gap-1.5 text-amber-600">
                  <span className="text-xl font-black">Rp {(item.price/1000).toFixed(0)}k</span>
                </div>
              </div>
              <button 
                onClick={() => addToCart(item.id)}
                className="w-14 h-14 bg-white rounded-[1.2rem] shadow-xl shadow-slate-200 flex items-center justify-center text-slate-800 hover:bg-amber-500 hover:text-white transition-all active:scale-90 border border-slate-50"
              >
                <ShoppingCart size={22} />
              </button>
            </div>
          </div>
        ))}
      </div>

      {/* Floating Admin Switcher Button - Exact from Screenshot */}
      <div className="fixed bottom-8 left-1/2 -translate-x-1/2 z-50">
        <button 
          onClick={onBackToAdmin}
          className="bg-[#0f172a] text-white px-8 py-5 rounded-[1.5rem] flex items-center gap-5 shadow-2xl shadow-slate-400 group transition-all"
        >
          <div className="bg-amber-500 p-2 rounded-lg text-white">
            <Monitor size={22} strokeWidth={2.5} />
          </div>
          <div className="text-left">
            <p className="text-sm font-bold leading-tight">Kembali ke</p>
            <p className="text-sm font-bold leading-tight">Mode Admin</p>
          </div>
        </button>
      </div>

      {/* Cart Summary (only if items exist) */}
      {cartCount > 0 && (
        <div className="fixed bottom-[120px] left-1/2 -translate-x-1/2 w-[90%] max-w-md animate-in slide-in-from-bottom-8 duration-500 z-40">
          <div className="bg-emerald-600 text-white rounded-[2rem] p-5 flex items-center justify-between shadow-2xl">
            <div className="flex items-center gap-4">
              <div className="bg-white/20 p-2 rounded-xl">
                <ShoppingCart size={20} />
              </div>
              <div>
                <p className="text-xs font-bold opacity-80">{cartCount} Item dipilih</p>
                <p className="text-lg font-black">Rp {(cartTotal/1000).toFixed(0)}k</p>
              </div>
            </div>
            <button 
              className="bg-white text-emerald-700 px-6 py-3 rounded-xl font-bold flex items-center gap-2"
              onClick={handleOrderWhatsApp}
            >
              <MessageCircle size={20} />
              Pesan Sekarang
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default PublicMenu;

