import React, { useState, useMemo } from 'react';
import { Search, ShoppingCart, Info, Monitor, MessageCircle, UtensilsCrossed } from 'lucide-react';
import { MenuItem, StoreSettings } from '../types';

interface PublicMenuProps {
  menu: MenuItem[];
  settings: StoreSettings;
  categories: string[];
  onBackToAdmin: () => void;
}

const PublicMenu: React.FC<PublicMenuProps> = ({ menu, settings, categories, onBackToAdmin }) => {
  const [activeCategory, setActiveCategory] = useState<string>('Semua');
  const [searchQuery, setSearchQuery] = useState('');
  const [cart, setCart] = useState<{ [key: string]: number }>({});

  const displayCategories = ['Semua', ...categories];

  const filteredMenu = useMemo(() => {
    return menu.filter(item => {
      const matchesCategory = activeCategory === 'Semua' || item.category === activeCategory;
      const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase());
      return matchesCategory && matchesSearch;
    });
  }, [menu, activeCategory, searchQuery]);

  const addToCart = (id: string) => {
    setCart(prev => ({ ...prev, [id]: (prev[id] || 0) + 1 }));
  };

  const cartTotal = (Object.entries(cart) as [string, number][]).reduce((total, [id, qty]) => {
    const item = menu.find(m => m.id === id);
    return total + (item ? item.price * qty : 0);
  }, 0);

  const handleOrderWhatsApp = () => {
    const cartItemsText = (Object.entries(cart) as [string, number][])
      .map(([id, qty]) => {
        const item = menu.find(m => m.id === id);
        return item ? `• ${item.name} (${qty}x)` : '';
      })
      .filter(text => text !== '')
      .join('\n');

    const message = `Halo ${settings.storeName},\n\nSaya ingin memesan menu katering berikut:\n\n${cartItemsText}\n\nTotal Estimasi: Rp ${cartTotal.toLocaleString()}\n\nMohon informasi selanjutnya. Terima kasih!`;
    window.open(`https://wa.me/${settings.whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 pb-40 font-sans selection:bg-emerald-100">
      {/* Header & Hero */}
      <div className="bg-white border-b border-slate-100 px-6 py-8 rounded-b-[2.5rem] shadow-sm">
        <div className="flex justify-between items-center mb-10">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-emerald-500 rounded-xl flex items-center justify-center text-white shadow-lg shadow-emerald-200 overflow-hidden">
              {settings.logoUrl ? (
                <img src={settings.logoUrl} alt="Logo" className="w-full h-full object-cover" />
              ) : (
                <UtensilsCrossed size={20} />
              )}
            </div>
            <span className="font-bold text-lg tracking-tight text-slate-800">{settings.storeName}</span>
          </div>
          <button className="w-10 h-10 bg-slate-50 rounded-full flex items-center justify-center text-slate-400 hover:bg-emerald-50 hover:text-emerald-500 transition-all">
            <Info size={20} />
          </button>
        </div>

        <h1 className="text-3xl font-black text-slate-900 mb-2 leading-tight">Pilih Menu Favorit Anda</h1>
        <p className="text-slate-500 text-sm font-medium leading-relaxed max-w-[280px]">
          Nikmati hidangan katering premium untuk setiap momen spesial.
        </p>
      </div>

      {/* Search Bar */}
      <div className="px-6 -mt-6 relative z-10">
        <div className="bg-white rounded-2xl shadow-xl shadow-slate-200/50 p-2 flex items-center border border-slate-100 h-14">
          <div className="pl-4 pr-3 text-slate-400">
            <Search size={20} />
          </div>
          <input 
            type="text" 
            placeholder="Cari hidangan..." 
            className="flex-1 bg-transparent outline-none text-sm font-semibold placeholder:text-slate-300"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
      </div>

      {/* Categories */}
      <div className="px-6 mt-8">
        <div className="flex gap-3 overflow-x-auto pb-4 no-scrollbar">
          {displayCategories.map(cat => (
            <button
              key={cat}
              onClick={() => setActiveCategory(cat)}
              className={`px-6 py-3 rounded-xl text-xs font-black uppercase tracking-widest whitespace-nowrap transition-all duration-300 ${
                activeCategory === cat 
                  ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-200' 
                  : 'bg-white text-slate-400 border border-slate-100 hover:border-emerald-200'
              }`}
            >
              {cat}
            </button>
          ))}
        </div>
      </div>

      {/* Menu Grid */}
      <div className="px-6 mt-4 space-y-8">
        {filteredMenu.map(item => (
          <div key={item.id} className="bg-white rounded-3xl border border-slate-100 overflow-hidden group shadow-sm hover:shadow-md transition-all">
            <div className="relative aspect-[16/10] overflow-hidden">
              <img src={item.imageUrl} alt={item.name} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700" />
              <div className="absolute top-4 left-4">
                <span className="bg-white/90 backdrop-blur px-3 py-1.5 rounded-lg text-[10px] font-black text-emerald-700 uppercase tracking-widest border border-emerald-100">
                  {item.category}
                </span>
              </div>
            </div>

            <div className="p-6">
              <div className="flex justify-between items-start gap-4 mb-3">
                <h3 className="font-black text-xl text-slate-800 leading-tight">{item.name}</h3>
                <span className="text-emerald-600 font-black text-lg">Rp {(item.price/1000).toFixed(0)}k</span>
              </div>
              <p className="text-xs text-slate-400 font-medium leading-relaxed italic mb-6 line-clamp-2">
                {item.description}
              </p>

              <button 
                onClick={() => addToCart(item.id)}
                className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] flex items-center justify-center gap-3 active:scale-95 transition-all shadow-lg shadow-slate-200"
              >
                <ShoppingCart size={16} />
                Tambah ke Pesanan
              </button>
            </div>
          </div>
        ))}
      </div>

      {/* Simple Footer Text */}
      <div className="p-10 text-center">
        <p className="text-[10px] font-black text-slate-300 uppercase tracking-[0.3em]">CaterElite Digital Catalog</p>
      </div>

      {/* Admin Switcher - Simple Floating Button */}
      <button 
        onClick={onBackToAdmin}
        className="fixed top-6 right-6 z-[60] bg-slate-900/10 backdrop-blur-md text-slate-500 p-3 rounded-full hover:bg-slate-900 hover:text-white transition-all shadow-sm"
        title="Admin Mode"
      >
        <Monitor size={20} />
      </button>

      {/* Checkout Bar */}
      {cartTotal > 0 && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 w-[90%] max-w-md z-50">
          <div className="bg-white border border-slate-100 rounded-3xl p-4 flex items-center justify-between shadow-2xl animate-in slide-in-from-bottom-4">
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-emerald-500 text-white rounded-2xl flex items-center justify-center shadow-lg shadow-emerald-100">
                <ShoppingCart size={20} />
              </div>
              <div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest leading-none mb-1">Total Estimasi</p>
                <p className="text-lg font-black text-slate-800">Rp {cartTotal.toLocaleString()}</p>
              </div>
            </div>
            <button 
              className="bg-emerald-600 text-white px-6 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center gap-2 hover:bg-emerald-700 transition-all"
              onClick={handleOrderWhatsApp}
            >
              Kirim WA
              <MessageCircle size={16} />
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default PublicMenu;

