                      strokeDasharray={364} 
                      strokeDashoffset={364 - (364 * result.freshnessScore) / 100}
                      strokeLinecap="round"
                    />
                  </svg>
                  <div className="absolute inset-0 flex flex-col items-center justify-center">
                    <span className="text-3xl font-black text-slate-900">{result.freshnessScore}%</span>
                    <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest">Freshness</span>
                  </div>
                </div>
                <h4 className="text-xl font-black text-slate-800 mb-1">{result.status}</h4>
                <p className="text-[10px] font-bold text-amber-500 uppercase tracking-widest">Terdeteksi: {result.estimatedQuantity}</p>
              </div>

              <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6">Diagnosis & Rekomendasi</h3>
                <div className="bg-slate-50 p-5 rounded-2xl border border-slate-100 italic text-slate-600 text-xs leading-relaxed mb-6">
                  "{result.diagnosis}"
                </div>
                <div className="space-y-3">
                  {result.recommendations.map((rec, i) => (
                    <div key={i} className="flex gap-3 items-center">
                      <div className="w-5 h-5 bg-amber-100 text-amber-600 rounded-lg flex items-center justify-center text-[10px] font-black">{i + 1}</div>
                      <p className="text-[11px] font-bold text-slate-700">{rec}</p>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          ) : (
            <div className="h-full bg-white/50 rounded-[2.5rem] border-2 border-dashed border-slate-200 flex flex-col items-center justify-center p-12 text-center">
              <Sparkles size={48} className="text-slate-200 mb-4" />
              <p className="text-slate-400 font-bold italic">Belum ada analisis visual.<br/>Ambil foto stok untuk memulai otomatisasi MRP.</p>
            </div>
          )}
        </div>
      </div>

      {/* ADD INGREDIENT MODAL */}
      {isAddModalOpen && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setIsAddModalOpen(false)}></div>
          <div className="bg-white rounded-[2.5rem] w-full max-w-md overflow-hidden shadow-2xl relative z-10 animate-in zoom-in-95 duration-300">
            <div className="p-8 pb-4 flex justify-between items-center">
              <div>
                <h3 className="text-2xl font-black text-slate-900">Tambah Bahan</h3>
                <p className="text-sm text-slate-400">Input stok manual ke inventaris.</p>
              </div>
              <button onClick={() => setIsAddModalOpen(false)} className="p-2 hover:bg-slate-50 rounded-full text-slate-400 transition-all">
                <X size={24} />
              </button>
            </div>

            <div className="p-8 pt-4 space-y-6">
              <div className="space-y-4">
                <div>
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">Nama Bahan</label>
                  <input 
                    type="text" 
                    placeholder="Contoh: Ayam Broiler, Wortel"
                    className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-4 py-3 text-sm font-semibold outline-none focus:ring-2 focus:ring-amber-500/20"
                    value={newItem.name}
                    onChange={(e) => setNewItem({...newItem, name: e.target.value})}
                  />
                </div>
                <div>
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">Jumlah / Satuan</label>
                  <input 
                    type="text" 
                    placeholder="Contoh: 10kg, 5 Ikat, 2 Liter"
                    className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-4 py-3 text-sm font-semibold outline-none focus:ring-2 focus:ring-amber-500/20"
                    value={newItem.quantity}
                    onChange={(e) => setNewItem({...newItem, quantity: e.target.value})}
                  />
                </div>
                <div>
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">Status Stok</label>
                  <div className="grid grid-cols-3 gap-2">
                    {(['Aman', 'Menipis', 'Habis'] as const).map(s => (
                      <button
                        key={s}
                        onClick={() => setNewItem({...newItem, status: s})}
                        className={`py-2 rounded-xl text-[10px] font-black uppercase tracking-wider border transition-all ${
                          newItem.status === s 
                            ? (s === 'Aman' ? 'bg-emerald-500 text-white border-emerald-500' : s === 'Menipis' ? 'bg-amber-500 text-white border-amber-500' : 'bg-rose-500 text-white border-rose-500')
                            : 'bg-white text-slate-400 border-slate-100 hover:border-slate-200'
                        }`}
                      >
                        {s}
                      </button>
                    ))}
                  </div>
                </div>
              </div>

              <button 
                onClick={handleAddIngredient}
                className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 hover:bg-amber-600 transition-all shadow-lg shadow-slate-100"
              >
                <Save size={18} />
                Simpan Bahan Baku
              </button>
            </div>
          </div>
        </div>
      )}

      {/* SHOPPING LIST MODAL */}
      {isShoppingModalOpen && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setIsShoppingModalOpen(false)}></div>
          <div className="bg-white rounded-[2.5rem] w-full max-w-md overflow-hidden shadow-2xl relative z-10 animate-in zoom-in-95 duration-300">
            <div className="bg-amber-500 p-8 text-white relative overflow-hidden">
              <h3 className="text-2xl font-black mb-2">Daftar Belanja MRP</h3>
              <p className="text-amber-100 text-sm font-medium leading-relaxed">
                Berikut adalah bahan yang perlu segera dibeli berdasarkan analisis stok terakhir.
              </p>
              <div className="absolute -bottom-8 -right-8 opacity-20 rotate-12">
                <ShoppingCart size={120} />
              </div>
            </div>

            <div className="p-8 space-y-6">
              <div className="space-y-3 max-h-64 overflow-y-auto no-scrollbar pr-2">
                {itemsToBuy.length > 0 ? (
                  itemsToBuy.map(item => (
                    <div key={item.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100">
                      <div className="flex items-center gap-3">
                        <div className="w-2 h-2 rounded-full bg-rose-500 animate-pulse"></div>
                        <span className="text-sm font-bold text-slate-700">{item.name}</span>
                      </div>
                      <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{item.quantity}</span>
                    </div>
                  ))
                ) : (
                  <div className="text-center py-6 text-slate-400 italic">
                    Stok aman. Tidak ada bahan yang perlu dibeli!
                  </div>
                )}
              </div>

              {itemsToBuy.length > 0 && (
                <div className="grid grid-cols-1 gap-3">
                  <button 
                    onClick={handleCopyList}
                    className={`w-full py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 transition-all ${
                      copySuccess ? 'bg-emerald-500 text-white' : 'bg-slate-100 text-slate-600 border border-slate-200 hover:bg-slate-200'
                    }`}
                  >
                    {copySuccess ? <Check size={16} /> : <Copy size={16} />}
                    {copySuccess ? 'Berhasil Disalin' : 'Salin Daftar Belanja'}
                  </button>
                  <button 
                    onClick={handleShareWA}
                    className="w-full bg-[#25D366] text-white py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 shadow-lg shadow-emerald-100 hover:brightness-105"
                  >
                    <MessageCircle size={16} />
                    Kirim ke Supplier (WA)
                  </button>
                </div>
              )}

              <button 
                onClick={() => setIsShoppingModalOpen(false)}
                className="w-full text-center text-[10px] font-black text-slate-400 uppercase tracking-widest py-2"
              >
                Tutup
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default SmartAdvisor;

import { GoogleGenAI, Type } from "@google/genai";
import { MenuItem, Client, AIRecommendation, AnalysisResult, SocialStrategy } from "../types";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const optimizeMenuDescription = async (itemName: string, currentDesc: string) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Nama Hidangan: ${itemName}\nDeskripsi Saat Ini: ${currentDesc}`,
    config: {
      systemInstruction: "Anda adalah copywriter kuliner kelas dunia untuk layanan katering mewah. Tugas Anda adalah menulis ulang deskripsi hidangan agar terlihat sangat menggugah selera. Gunakan Bahasa Indonesia yang elegan.",
      temperature: 0.8,
    },
  });
  return response.text;
};

export const generateSocialStrategy = async (topItems: MenuItem[]): Promise<SocialStrategy[]> => {
  const ai = getAI();
  const itemsText = topItems.map(i => `${i.name} (${i.salesCount} terjual)`).join(", ");
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Menu Terlaris: ${itemsText}`,
    config: {
      systemInstruction: "Anda adalah ahli strategi media sosial untuk bisnis katering. Berikan 3 ide konten promosi untuk Instagram, TikTok, dan WhatsApp Status berdasarkan menu terlaris tersebut. Berikan juga waktu posting terbaik dan draf caption yang menarik perhatian dalam Bahasa Indonesia.",
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            platform: { type: Type.STRING },
            contentIdea: { type: Type.STRING },
            bestTimeToPost: { type: Type.STRING },
            suggestedCaption: { type: Type.STRING }
          },
          required: ["platform", "contentIdea", "bestTimeToPost", "suggestedCaption"]
        }
      }
    },
  });
  return JSON.parse(response.text || "[]");
};

export const generatePromoImage = async (itemName: string): Promise<string> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [
        {
          text: `A high-end, professional food photography of ${itemName}. Luxury catering presentation, elegant lighting, bokeh background, commercial food styling, vibrant colors, 4k resolution.`,
        },
      ],
    },
    config: {
      imageConfig: {
        aspectRatio: "1:1"
      },
    },
  });

  for (const part of response.candidates[0].content.parts) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }
  throw new Error("Gagal menghasilkan gambar");
};

export const generateCollectionPitch = async (customerName: string, amountDue: number, daysOverdue: number) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Pelanggan: ${customerName}\nJumlah Tunggakan: Rp ${amountDue.toLocaleString()}\nKeterlambatan: ${daysOverdue} hari`,
    config: {
      systemInstruction: "Anda adalah asisten keuangan katering profesional. Buatlah draf pesan penagihan (collection) yang sopan, elegan, namun tegas dalam Bahasa Indonesia. Fokus pada menjaga hubungan baik dengan pelanggan sambil meminta kepastian pembayaran.",
      temperature: 0.7,
    },
  });
  return response.text;
};

export const getSalesOutreachSuggestions = async (clients: Client[]): Promise<AIRecommendation[]> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Daftar Pelanggan: ${JSON.stringify(clients)}`,
    config: {
      systemInstruction: "Analisis data pelanggan katering ini. Berikan 3 rekomendasi pelanggan mana yang harus dihubungi hari ini dan apa isi pesannya (pitch).",
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            clientName: { type: Type.STRING },
            reason: { type: Type.STRING },
            suggestedAction: { type: Type.STRING },
            pitch: { type: Type.STRING }
          },
          required: ["clientName", "reason", "suggestedAction", "pitch"]
        }
      }
    },
