  return JSON.parse(response.text || "[]");
};

export const analyzeKitchenStock = async (base64Data: string): Promise<AnalysisResult> => {
  const ai = getAI();
  const imagePart = {
    inlineData: {
      mimeType: 'image/jpeg',
      data: base64Data.split(',')[1],
    },
  };
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: { parts: [imagePart, { text: "Analisis stok dapur ini. Identifikasi nama bahan, estimasi jumlah, dan klasifikasikan status stok secara ketat ke salah satu dari: 'Aman', 'Menipis', atau 'Habis' berdasarkan apa yang terlihat." }] },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          status: { type: Type.STRING, description: "Nama bahan yang dideteksi (Misal: Tomat, Ayam)" },
          freshnessScore: { type: Type.NUMBER, description: "Skor kesegaran 0-100" },
          diagnosis: { type: Type.STRING, description: "Analisis kondisi bahan" },
          estimatedQuantity: { type: Type.STRING, description: "Perkiraan jumlah (Misal: 2kg, 10 butir)" },
          recommendations: { type: Type.ARRAY, items: { type: Type.STRING } },
          mrpStatus: { type: Type.STRING, description: "WAJIB salah satu: 'Aman', 'Menipis', 'Habis'" }
        },
        required: ["status", "freshnessScore", "diagnosis", "estimatedQuantity", "recommendations", "mrpStatus"]
      }
    }
  });
  return JSON.parse(response.text || "{}");
};

import React, { useState, useRef } from 'react';
import { 
  Sparkles, Camera, CheckCircle2, AlertCircle, Loader2, Package, 
  Utensils, Plus, Trash2, ShoppingCart, X, Copy, MessageCircle, Check, Save, Zap
} from 'lucide-react';
import { analyzeKitchenStock } from '../services/geminiService';
import { AnalysisResult } from '../types';

interface IngredientStock {
  id: string;
  name: string;
  quantity: string;
  status: 'Aman' | 'Menipis' | 'Habis';
}

const SmartAdvisor: React.FC = () => {
  const [analyzing, setAnalyzing] = useState(false);
  const [result, setResult] = useState<AnalysisResult & { mrpStatus?: string } | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const [isShoppingModalOpen, setIsShoppingModalOpen] = useState(false);
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);
  const [isApplied, setIsApplied] = useState(false);

  const [inventory, setInventory] = useState<IngredientStock[]>([
    { id: '1', name: 'Beras Premium', quantity: '25kg', status: 'Aman' },
    { id: '2', name: 'Ayam Broiler', quantity: '5kg', status: 'Menipis' },
    { id: '3', name: 'Minyak Goreng', quantity: '2L', status: 'Habis' },
    { id: '4', name: 'Bawang Merah', quantity: '500g', status: 'Menipis' },
  ]);

  const [newItem, setNewItem] = useState<Partial<IngredientStock>>({
    name: '',
    quantity: '',
    status: 'Aman'
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const itemsToBuy = inventory.filter(item => item.status === 'Menipis' || item.status === 'Habis');

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64String = reader.result as string;
        setPreview(base64String);
        setAnalyzing(true);
        setIsApplied(false);
        try {
          const res = await analyzeKitchenStock(base64String);
          setResult(res as any);
        } catch (error) {
          console.error("AI Analysis failed", error);
        } finally {
          setAnalyzing(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleApplyAIResult = () => {
    if (result) {
      const ingredient: IngredientStock = {
        id: Math.random().toString(36).substr(2, 9),
        name: result.status, // AI menggunakan field status untuk nama bahan di prompt kita
        quantity: result.estimatedQuantity,
        status: (result.mrpStatus as any) || 'Aman'
      };
      setInventory(prev => [ingredient, ...prev]);
      setIsApplied(true);
      setTimeout(() => setIsApplied(false), 2000);
    }
  };

  const handleAddIngredient = () => {
    if (newItem.name && newItem.quantity) {
      const ingredient: IngredientStock = {
        id: Math.random().toString(36).substr(2, 9),
        name: newItem.name,
        quantity: newItem.quantity,
        status: newItem.status as any || 'Aman'
      };
      setInventory([ingredient, ...inventory]);
      setIsAddModalOpen(false);
      setNewItem({ name: '', quantity: '', status: 'Aman' });
    }
  };

  const handleDeleteIngredient = (id: string) => {
    setInventory(inventory.filter(item => item.id !== id));
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Aman': return 'text-emerald-500 bg-emerald-50 border-emerald-100';
      case 'Menipis': return 'text-amber-500 bg-amber-50 border-amber-100';
      case 'Habis': return 'text-rose-500 bg-rose-50 border-rose-100';
      default: return 'text-slate-500 bg-slate-50 border-slate-100';
    }
  };

  const generateShoppingText = () => {
    const header = `*DAFTAR BELANJA DAPUR - ${new Date().toLocaleDateString('id-ID')}*\n\n`;
    const list = itemsToBuy.map(item => `- ${item.name} (${item.quantity})`).join('\n');
    const footer = `\n\n_Mohon segera disiapkan. Terima kasih._`;
    return header + list + footer;
  };

  const handleCopyList = () => {
    navigator.clipboard.writeText(generateShoppingText());
    setCopySuccess(true);
    setTimeout(() => setCopySuccess(false), 2000);
  };

  const handleShareWA = () => {
    const text = encodeURIComponent(generateShoppingText());
    window.open(`https://wa.me/?text=${text}`, '_blank');
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      <div className="bg-slate-900 rounded-[2.5rem] p-8 md:p-12 text-white relative overflow-hidden shadow-2xl">
        <div className="relative z-10 flex flex-col md:flex-row items-center gap-10">
          <div className="flex-1">
            <div className="flex items-center gap-2 mb-6">
              <div className="p-2 bg-amber-500 rounded-xl shadow-lg shadow-amber-500/20">
                <Utensils size={20} className="text-white" />
              </div>
              <span className="uppercase tracking-[0.3em] text-[10px] font-black text-amber-500">Kitchen AI & MRP Control</span>
            </div>
            <h2 className="text-4xl font-black mb-6 leading-tight">Optimasi Bahan Baku & Stok</h2>
            <p className="text-slate-400 text-lg mb-8 leading-relaxed font-medium">
              Analisis stok dapur secara visual dengan AI. Pantau tingkat kesegaran bahan dan otomatiskan daftar belanja (MRP) Anda.
            </p>
            <div className="flex flex-wrap gap-4">
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="bg-white text-slate-900 px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-amber-500 hover:text-white transition-all flex items-center gap-3 shadow-xl"
              >
                <Camera size={20} />
                Analisis Visual Stok
              </button>
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleFileChange} 
                className="hidden" 
                accept="image/*"
              />
            </div>
          </div>

          <div className="w-full md:w-80 aspect-square bg-white/5 rounded-[2.5rem] border-2 border-dashed border-white/10 flex flex-col items-center justify-center relative group transition-all hover:border-amber-500/50 overflow-hidden">
            {preview ? (
              <img src={preview} alt="Ingredient Preview" className="w-full h-full object-cover" />
            ) : (
              <div className="text-center p-6">
                <div className="w-20 h-20 bg-white/5 rounded-full flex items-center justify-center mx-auto mb-4 group-hover:scale-110 transition-transform">
                  <Package size={40} className="text-slate-600" />
                </div>
                <span className="text-xs font-bold text-slate-500 uppercase tracking-widest">Drop Foto Bahan</span>
              </div>
            )}
            {analyzing && (
              <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-md flex flex-col items-center justify-center p-6 text-center">
                <div className="relative mb-4">
                   <Loader2 className="animate-spin text-amber-500" size={48} />
                   <Sparkles className="absolute -top-2 -right-2 text-white animate-pulse" size={20} />
                </div>
                <span className="text-white text-[10px] font-black tracking-[0.3em] uppercase">AI SEDANG MENGANALISIS...</span>
              </div>
            )}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        {/* Left: Inventory List (MRP) */}
        <div className="lg:col-span-4 space-y-6">
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
            <div className="flex items-center justify-between mb-8">
              <h3 className="text-lg font-black text-slate-800">Daftar Inventaris</h3>
              <button 
                onClick={() => setIsAddModalOpen(true)}
                className="p-2 bg-slate-50 text-slate-400 hover:text-amber-500 hover:bg-amber-50 rounded-xl transition-all"
              >
                <Plus size={20} />
              </button>
            </div>

            <div className="space-y-4 max-h-[400px] overflow-y-auto no-scrollbar pr-1">
              {inventory.map(item => (
                <div key={item.id} className="p-4 bg-slate-50 border border-slate-100 rounded-2xl flex items-center justify-between group hover:border-amber-200 transition-all animate-in slide-in-from-left duration-300">
                  <div className="flex-1">
                    <p className="text-sm font-black text-slate-800">{item.name}</p>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{item.quantity}</p>
                  </div>
                  <div className="flex items-center gap-3">
                    <span className={`text-[9px] font-black px-2 py-1 rounded-lg border uppercase tracking-wider ${getStatusColor(item.status)}`}>
                      {item.status}
                    </span>
                    <button 
                      onClick={() => handleDeleteIngredient(item.id)}
                      className="p-2 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-all"
                    >
                      <Trash2 size={14} />
                    </button>
                  </div>
                </div>
              ))}
              {inventory.length === 0 && (
                <div className="text-center py-10 text-slate-400 italic text-sm">
                  Belum ada bahan baku...
                </div>
              )}
            </div>

            <button 
              onClick={() => setIsShoppingModalOpen(true)}
              className="w-full mt-8 bg-slate-900 text-white py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 hover:bg-amber-600 transition-all shadow-lg shadow-slate-200 disabled:opacity-50"
              disabled={itemsToBuy.length === 0}
            >
              <ShoppingCart size={16} />
              Buat Daftar Belanja ({itemsToBuy.length})
            </button>
          </div>
        </div>

        {/* Right: AI Results */}
        <div className="lg:col-span-8 space-y-6">
          {result ? (
