} from 'lucide-react';

interface SidebarProps {
  isOpen: boolean;
  setIsOpen: (open: boolean) => void;
  activeTab: string;
  setActiveTab: (tab: any) => void;
  onPreviewMenu: () => void;
  logoUrl?: string;
  onOpenSettings: () => void;
}

const Sidebar: React.FC<SidebarProps> = ({ 
  isOpen, 
  setIsOpen, 
  activeTab,
  setActiveTab,
  onPreviewMenu, 
  logoUrl,
  onOpenSettings,
}) => {
  if (!isOpen) return null;

  const NavButton = ({ id, label, icon: Icon, color = "emerald" }: { id: string, label: string, icon: any, color?: string }) => {
    const isActive = activeTab === id;
    return (
      <button 
        onClick={() => {
          setActiveTab(id);
          setIsOpen(false);
        }}
        className={`w-full flex items-center justify-between px-4 py-3.5 rounded-2xl transition-all duration-300 group ${
          isActive 
            ? 'bg-emerald-50 text-emerald-700 shadow-sm' 
            : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900'
        }`}
      >
        <div className="flex items-center">
          <Icon size={20} className={`mr-4 transition-colors ${isActive ? 'text-emerald-600' : 'text-slate-400 group-hover:text-slate-600'}`} />
          <span className={`text-sm font-bold ${isActive ? 'font-black' : ''}`}>{label}</span>
        </div>
        {isActive && <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></div>}
        {!isActive && <ChevronRight size={14} className="text-slate-300 opacity-0 group-hover:opacity-100 transition-all" />}
      </button>
    );
  };

  return (
    <div className="fixed inset-0 z-[110] lg:hidden">
      {/* Backdrop */}
      <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md transition-opacity duration-300" onClick={() => setIsOpen(false)}></div>

      {/* Drawer */}
      <aside className="absolute left-0 top-0 bottom-0 w-80 bg-white flex flex-col shadow-2xl animate-in slide-in-from-left duration-500 ease-out rounded-r-[3rem]">
        <div className="p-8 flex items-center justify-between border-b border-slate-50">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-slate-900 rounded-xl flex items-center justify-center text-white overflow-hidden shadow-xl shadow-slate-200">
              {logoUrl ? <img src={logoUrl} className="w-full h-full object-cover" /> : <UtensilsCrossed size={18} />}
            </div>
            <div>
              <span className="font-black text-lg text-slate-800 tracking-tight block leading-none">CaterElite</span>
              <span className="text-[9px] font-black text-emerald-600 uppercase tracking-widest mt-1">Enterprise AI</span>
            </div>
          </div>
          <button onClick={() => setIsOpen(false)} className="p-2.5 bg-slate-50 text-slate-400 hover:text-rose-500 rounded-full transition-all">
            <X size={18} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto px-6 py-8 no-scrollbar space-y-9">
          {/* Main Menu */}
          <section>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.25em] mb-4 ml-4">Navigasi Utama</p>
            <div className="space-y-1.5">
              <NavButton id="dashboard" label="Dashboard Overview" icon={LayoutDashboard} />
              <NavButton id="orders" label="Daftar Pesanan" icon={ShoppingBag} />
              <NavButton id="menu" label="Katalog Menu" icon={UtensilsCrossed} />
            </div>
          </section>

          {/* Business Insights */}
          <section>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.25em] mb-4 ml-4">Wawasan & Pertumbuhan</p>
            <div className="space-y-1.5">
              <NavButton id="social" label="Analisis Sosial Media" icon={Share2} />
              <NavButton id="advisor" label="Kitchen MRP AI" icon={PackageSearch} />
            </div>
          </section>

          {/* Operations & Settings */}
          <section>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.25em] mb-4 ml-4">Tim & Sistem</p>
            <div className="space-y-1.5">
              <NavButton id="receivables" label="Manajemen Piutang" icon={Wallet} />
              <NavButton id="admins" label="Profil Tim Admin" icon={User} />
              <button 
                onClick={() => {
                  onOpenSettings();
                  setIsOpen(false);
                }}
                className="w-full flex items-center px-4 py-3.5 rounded-2xl text-slate-500 hover:bg-slate-50 hover:text-slate-900 transition-all font-bold text-sm group"
              >
                <SettingsIcon size={20} className="mr-4 text-slate-400 group-hover:text-slate-600" />
                Pengaturan Toko
              </button>
            </div>
          </section>
        </div>

        <div className="p-6 border-t border-slate-50 space-y-3 bg-slate-50/30 rounded-br-[3rem]">
          <button 
            onClick={() => {
              onPreviewMenu();
              setIsOpen(false);
            }} 
            className="w-full py-4 bg-slate-900 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 shadow-xl shadow-slate-200 hover:bg-amber-600 active:scale-95 transition-all"
          >
            <Eye size={18} /> Preview Katalog Digital
