          <button className="w-full py-3 text-rose-400 font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 hover:bg-rose-50 rounded-xl transition-all">
            <LogOut size={16} /> Keluar Aplikasi
          </button>
        </div>
      </aside>
    </div>
  );
};

