import AdminProfiles from './components/AdminProfiles';
import SocialAnalytics from './components/SocialAnalytics';
import { MenuItem, Order, StoreSettings } from './types';

const INITIAL_MENU: MenuItem[] = [
  { id: '1', name: 'Nasi Liwet Sunda Premium', category: 'Paket Buffet', price: 45000, cost: 25000, description: 'Nasi gurih dimasak dengan rempah khas, disajikan dengan ayam goreng, sambal, dan lalapan segar.', salesCount: 154, imageUrl: 'https://images.unsplash.com/photo-1541529086526-db283c563270?auto=format&fit=crop&q=80&w=400' },
  { id: '2', name: 'Premium Beef Teriyaki Bento', category: 'Nasi Box', price: 55000, cost: 32000, description: 'Daging sapi pilihan dengan saus teriyaki.', salesCount: 210, imageUrl: 'https://images.unsplash.com/photo-1512058560366-cd2427ff1141?auto=format&fit=crop&q=80&w=400' },
];

const INITIAL_ORDERS: Order[] = [
  { id: '101', customerName: 'Bank BCA Office', items: ['Nasi Liwet (50)'], totalPrice: 2250000, amountPaid: 1000000, date: '2024-05-20', status: 'Delivered', paymentStatus: 'Partial', type: 'Corporate' },
  { id: '102', customerName: 'Wedding Rizky & Sarah', items: ['Buffet Wedding A'], totalPrice: 45000000, amountPaid: 45000000, date: '2024-05-21', status: 'Confirmed', paymentStatus: 'Paid', type: 'Wedding' },
  { id: '103', customerName: 'Ani Wijaya', items: ['Bento Box (5)'], totalPrice: 325000, amountPaid: 0, date: '2024-05-22', status: 'Pending', paymentStatus: 'Unpaid', type: 'Individual' },
  { id: '104', customerName: 'Tokopedia HQ', items: ['Bento Box (100)'], totalPrice: 5500000, amountPaid: 0, date: '2024-05-25', status: 'Delivered', paymentStatus: 'Unpaid', type: 'Corporate' },
];

const INITIAL_SETTINGS: StoreSettings = {
  storeName: 'CaterElite',
  whatsappNumber: '628123456789',
  address: 'Jl. Katering Elite No. 88, Jakarta Selatan',
  currencySymbol: 'Rp',
  logoUrl: 'https://images.unsplash.com/photo-1543007630-9710e4a00a20?auto=format&fit=crop&q=80&w=200',
  instagramHandle: 'caterelite.premium',
  tiktokHandle: 'caterelite_official'
};

const INITIAL_CATEGORIES = ['Paket Buffet', 'Nasi Box', 'Snack Box', 'Dessert'];

const App: React.FC = () => {
  const [viewMode, setViewMode] = useState<'admin' | 'customer'>('admin');
  const [activeTab, setActiveTab] = useState<'dashboard' | 'menu' | 'orders' | 'receivables' | 'advisor' | 'admins' | 'social'>('dashboard');
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const [menu, setMenu] = useState<MenuItem[]>(INITIAL_MENU);
  const [orders, setOrders] = useState<Order[]>(INITIAL_ORDERS);
  const [settings, setSettings] = useState<StoreSettings>(INITIAL_SETTINGS);
  const [categories, setCategories] = useState<string[]>(INITIAL_CATEGORIES);

  const handleUpdateOrder = (orderId: string, updates: Partial<Order>) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, ...updates } : o));
  };

  const navItems = [
    { id: 'dashboard', label: 'Home', icon: LayoutDashboard },
    { id: 'orders', label: 'Pesanan', icon: ShoppingBag },
    { id: 'menu', label: 'Menu', icon: UtensilsCrossed, isProminent: true },
    { id: 'receivables', label: 'Piutang', icon: Wallet },
    { id: 'advisor', label: 'Kitchen', icon: PackageSearch },
  ];

  if (viewMode === 'customer') {
    return (
      <PublicMenu 
        menu={menu} 
        settings={settings} 
        categories={categories} 
        onBackToAdmin={() => setViewMode('admin')} 
      />
    );
  }

  return (
    <div className="min-h-screen bg-[#f8fafc] flex flex-col font-sans selection:bg-emerald-100">
      {/* Header Eksklusif */}
      <header className="h-20 bg-white border-b border-slate-100 flex items-center justify-between px-6 sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <button onClick={() => setIsSidebarOpen(true)} className="p-2 text-slate-400 lg:hidden">
            <MenuIcon size={22} />
          </button>
          <div className="flex items-center gap-2 bg-[#ecfdf5] text-[#059669] px-3 py-1 rounded-full border border-[#d1fae5]">
