            <span className="text-[10px] font-bold uppercase tracking-wider">Admin Control</span>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <button className="p-2 text-slate-400 hover:text-emerald-500 transition-colors">
            <Bell size={22} />
          </button>
          <div 
            className="w-10 h-10 rounded-full bg-slate-100 border-2 border-white shadow-sm overflow-hidden cursor-pointer"
            onClick={() => setIsSettingsOpen(true)}
          >
            <img src={settings.logoUrl || "https://picsum.photos/100/100"} alt="Profile" className="w-full h-full object-cover" />
          </div>
          <button className="p-2 text-slate-400 hover:text-slate-600 transition-colors">
            <MoreVertical size={20} />
          </button>
        </div>
      </header>

      <Sidebar 
        isOpen={isSidebarOpen} 
        setIsOpen={setIsSidebarOpen} 
        activeTab={activeTab} 
        setActiveTab={setActiveTab}
        onPreviewMenu={() => setViewMode('customer')}
        logoUrl={settings.logoUrl}
        onOpenSettings={() => setIsSettingsOpen(true)}
      />

      <main className="flex-1 overflow-y-auto px-4 py-6 md:px-8 md:py-8 pb-32">
        <div className="max-w-6xl mx-auto space-y-6">
          {activeTab === 'dashboard' && <Dashboard orders={orders} menu={menu} />}
          {activeTab === 'menu' && <MenuManager menu={menu} onUpdateMenu={setMenu} categories={categories} onUpdateCategories={setCategories} />}
          {activeTab === 'orders' && <OrdersList orders={orders} onUpdateOrder={handleUpdateOrder} />}
          {activeTab === 'receivables' && <ReceivablesList orders={orders} onUpdateOrder={handleUpdateOrder} />}
          {activeTab === 'advisor' && <SmartAdvisor />}
          {activeTab === 'admins' && <AdminProfiles />}
          {activeTab === 'social' && <SocialAnalytics menu={menu} settings={settings} />}
        </div>
      </main>

      {/* Navigasi Bawah dengan Tombol Menu Kotak yang Menonjol */}
      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-xl border-t border-slate-100 px-6 py-4 flex justify-between items-center z-[40] shadow-[0_-10px_40px_rgba(0,0,0,0.04)] rounded-t-[2.5rem] lg:hidden">
        {navItems.map((item) => {
          if (item.isProminent) {
            return (
              <div key={item.id} className="relative -mt-10 flex flex-col items-center">
                <button
                  onClick={() => setActiveTab(item.id as any)}
                  className={`w-20 h-20 rounded-[2rem] flex flex-col items-center justify-center transition-all duration-500 shadow-2xl relative overflow-hidden group ${
                    activeTab === item.id 
                      ? 'bg-gradient-to-br from-emerald-500 to-emerald-700 text-white shadow-emerald-200 scale-110 ring-4 ring-white' 
                      : 'bg-slate-900 text-white shadow-slate-200'
                  }`}
