export const analyzeStockFromText = async (text: string): Promise<AnalysisResult & { mrpStatus: string }> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Laporan Stok: ${text}`,
    config: {
      systemInstruction: "Anda adalah asisten MRP katering. Analisis teks laporan stok yang diberikan. Identifikasi satu bahan utama yang paling krusial dari teks tersebut. Berikan output dalam format JSON dengan key: status (nama bahan), freshnessScore (0-100), diagnosis, estimatedQuantity, recommendations (array of strings), mrpStatus ('Aman', 'Menipis', atau 'Habis').",
      responseMimeType: "application/json",
    },
  });

  return JSON.parse(response.text || "{}");
};

export const analyzeKitchenStock = async (base64Data: string): Promise<AnalysisResult> => {
  const ai = getAI();
  const imagePart = {
    inlineData: {
      mimeType: 'image/jpeg',
      data: base64Data.split(',')[1],
    },
  };

  const prompt = "Analisis stok dapur ini. Identifikasi nama bahan, estimasi jumlah, dan klasifikasikan status stok secara ketat ke salah satu dari: 'Aman', 'Menipis', atau 'Habis' berdasarkan apa yang terlihat. Berikan output dalam format JSON valid dengan key: status (nama bahan), freshnessScore (0-100), diagnosis, estimatedQuantity, recommendations (array of strings), mrpStatus ('Aman', 'Menipis', atau 'Habis').";

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: { parts: [imagePart, { text: prompt }] },
  });

  const cleanJson = (response.text || "{}").replace(/```json/g, '').replace(/```/g, '').trim();
  return JSON.parse(cleanJson || "{}");
};

import React, { useState, useRef } from 'react';
import { 
  Sparkles, Camera, CheckCircle2, AlertCircle, Loader2, Package, 
  Utensils, Plus, Trash2, ShoppingCart, X, Copy, MessageCircle, Check, Save, Zap,
  FileText, Send, MessageSquare
} from 'lucide-react';
import { analyzeKitchenStock, analyzeStockFromText } from '../services/geminiService';
import { AnalysisResult } from '../types';

interface IngredientStock {
  id: string;
  name: string;
  quantity: string;
  status: 'Aman' | 'Menipis' | 'Habis';
}

const SmartAdvisor: React.FC = () => {
  const [analysisMode, setAnalysisMode] = useState<'image' | 'text'>('image');
  const [analyzing, setAnalyzing] = useState(false);
  const [textInput, setTextInput] = useState('');
  const [result, setResult] = useState<AnalysisResult & { mrpStatus?: string } | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const [isShoppingModalOpen, setIsShoppingModalOpen] = useState(false);
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);
  const [isApplied, setIsApplied] = useState(false);

  const [inventory, setInventory] = useState<IngredientStock[]>([
    { id: '1', name: 'Beras Premium', quantity: '25kg', status: 'Aman' },
    { id: '2', name: 'Ayam Broiler', quantity: '5kg', status: 'Menipis' },
    { id: '3', name: 'Minyak Goreng', quantity: '2L', status: 'Habis' },
    { id: '4', name: 'Bawang Merah', quantity: '500g', status: 'Menipis' },
  ]);

  const [newItem, setNewItem] = useState<Partial<IngredientStock>>({
    name: '',
    quantity: '',
    status: 'Aman'
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const itemsToBuy = inventory.filter(item => item.status === 'Menipis' || item.status === 'Habis');

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64String = reader.result as string;
        setPreview(base64String);
        setAnalyzing(true);
        setIsApplied(false);
        try {
          const res = await analyzeKitchenStock(base64String);
          setResult(res as any);
        } catch (error) {
          console.error("AI Analysis failed", error);
        } finally {
          setAnalyzing(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleTextAnalysis = async () => {
    if (!textInput.trim()) return;
    setAnalyzing(true);
    setIsApplied(false);
    setPreview(null);
    try {
      const res = await analyzeStockFromText(textInput);
      setResult(res as any);
    } catch (error) {
      console.error("AI Text Analysis failed", error);
    } finally {
      setAnalyzing(false);
    }
  };

  const handleApplyAIResult = () => {
    if (result) {
      const ingredient: IngredientStock = {
        id: Math.random().toString(36).substr(2, 9),
        name: result.status,
        quantity: result.estimatedQuantity,
        status: (result.mrpStatus as any) || 'Aman'
      };
      setInventory(prev => [ingredient, ...prev]);
      setIsApplied(true);
      setTimeout(() => setIsApplied(false), 2000);
    }
  };

  const handleAddIngredient = () => {
    if (newItem.name && newItem.quantity) {
      const ingredient: IngredientStock = {
        id: Math.random().toString(36).substr(2, 9),
        name: newItem.name,
        quantity: newItem.quantity,
        status: newItem.status as any || 'Aman'
      };
      setInventory([ingredient, ...inventory]);
      setIsAddModalOpen(false);
      setNewItem({ name: '', quantity: '', status: 'Aman' });
    }
  };

  const handleDeleteIngredient = (id: string) => {
    setInventory(inventory.filter(item => item.id !== id));
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Aman': return 'text-emerald-500 bg-emerald-50 border-emerald-100';
      case 'Menipis': return 'text-amber-500 bg-amber-50 border-amber-100';
      case 'Habis': return 'text-rose-500 bg-rose-50 border-rose-100';
      default: return 'text-slate-500 bg-slate-50 border-slate-100';
    }
  };

  const generateShoppingText = () => {
    const header = `*DAFTAR BELANJA DAPUR - ${new Date().toLocaleDateString('id-ID')}*\n\n`;
    const list = itemsToBuy.map(item => `- ${item.name} (${item.quantity})`).join('\n');
    const footer = `\n\n_Mohon segera disiapkan. Terima kasih._`;
    return header + list + footer;
  };

  const handleCopyList = () => {
    navigator.clipboard.writeText(generateShoppingText());
    setCopySuccess(true);
    setTimeout(() => setCopySuccess(false), 2000);
  };

  const handleShareWA = () => {
    const text = encodeURIComponent(generateShoppingText());
    window.open(`https://wa.me/?text=${text}`, '_blank');
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      <div className="bg-slate-900 rounded-[2.5rem] p-8 md:p-12 text-white relative overflow-hidden shadow-2xl">
        <div className="relative z-10 flex flex-col md:flex-row items-center gap-10">
          <div className="flex-1">
            <div className="flex items-center gap-4 mb-8">
              <button 
                onClick={() => setAnalysisMode('image')}
                className={`px-5 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
                  analysisMode === 'image' ? 'bg-amber-500 text-white shadow-lg' : 'bg-white/5 text-slate-400 hover:bg-white/10'
                }`}
              >
                Analisis Foto
              </button>
              <button 
                onClick={() => setAnalysisMode('text')}
                className={`px-5 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
                  analysisMode === 'text' ? 'bg-amber-500 text-white shadow-lg' : 'bg-white/5 text-slate-400 hover:bg-white/10'
                }`}
              >
                Laporan Teks
              </button>
            </div>

            <div className="flex items-center gap-2 mb-6">
              <div className="p-2 bg-amber-500 rounded-xl shadow-lg shadow-amber-500/20">
                {analysisMode === 'image' ? <Camera size={20} /> : <FileText size={20} />}
              </div>
              <span className="uppercase tracking-[0.3em] text-[10px] font-black text-amber-500">
                {analysisMode === 'image' ? 'Visual AI Stock Control' : 'Smart Text AI MRP'}
              </span>
            </div>

            <h2 className="text-4xl font-black mb-6 leading-tight">
              {analysisMode === 'image' ? 'Optimasi Stok Visual' : 'Laporan Stok Cepat'}
            </h2>
            <p className="text-slate-400 text-lg mb-8 leading-relaxed font-medium">
              {analysisMode === 'image' 
                ? 'Analisis stok dapur secara visual dengan AI. Pantau tingkat kesegaran bahan otomatis.' 
                : 'Ketikkan kondisi stok Anda hari ini. AI akan merangkum dan memperbarui inventaris secara otomatis.'}
            </p>

            <div className="flex flex-wrap gap-4">
              {analysisMode === 'image' ? (
                <>
                  <button 
                    onClick={() => fileInputRef.current?.click()}
                    className="bg-white text-slate-900 px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-amber-500 hover:text-white transition-all flex items-center gap-3 shadow-xl"
