                </>
              ) : (
                <div className="w-full space-y-3">
                  <div className="relative group">
                    <MessageSquare size={20} className="absolute left-4 top-4 text-slate-500" />
                    <textarea 
                      value={textInput}
                      onChange={(e) => setTextInput(e.target.value)}
                      placeholder="Contoh: Beras sisa 1 karung, ayam hampir habis, bawang merah aman..."
                      className="w-full pl-12 pr-6 py-4 bg-white/5 border border-white/10 rounded-2xl text-sm font-medium outline-none focus:ring-2 focus:ring-amber-500/50 transition-all text-white min-h-[100px] resize-none"
                    />
                  </div>
                  <button 
                    onClick={handleTextAnalysis}
                    disabled={analyzing || !textInput.trim()}
