  const [isProfileDropdownOpen, setIsProfileDropdownOpen] = useState(false);
  const [isShiftDropdownOpen, setIsShiftDropdownOpen] = useState(false);
  const [newOrderNotification, setNewOrderNotification] = useState<string | null>(null);

  const [menu, setMenu] = useState<MenuItem[]>(INITIAL_MENU);
  const [orders, setOrders] = useState<Order[]>(INITIAL_ORDERS);
  const [settings, setSettings] = useState<StoreSettings>(INITIAL_SETTINGS);
  const [categories, setCategories] = useState<string[]>(INITIAL_CATEGORIES);

  const handleLogin = (name: string, shift: ShiftType, role: UserRole) => {
    setCurrentUser({
      id: Math.random().toString(),
      name,
      role,
      shift,
      avatarUrl: name === 'Siti Aminah' 
        ? 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?auto=format&fit=facearea&facepad=2&w=100&h=100&q=80' 
        : 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?auto=format&fit=facearea&facepad=2&w=100&h=100&q=80'
    });
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setIsProfileDropdownOpen(false);
  };

  const handleUpdateShift = (newShift: ShiftType) => {
    if (currentUser) {
      setCurrentUser({ ...currentUser, shift: newShift });
    }
    setIsShiftDropdownOpen(false);
  };

  const handleUpdateOrder = (orderId: string, updates: Partial<Order>) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, ...updates } : o));
