      <main className="flex-1 overflow-y-auto px-4 py-6 md:px-8 md:py-8 pb-32">
        <div className="max-w-6xl mx-auto space-y-6">
          <div className={`p-4 rounded-[1.5rem] border flex items-center justify-between animate-in slide-in-from-top-4 ${getShiftColor(currentUser.shift)}`}>
            <div className="flex items-center gap-3">
              {getShiftIcon(currentUser.shift)}
              <div>
                <p className="text-[10px] font-black uppercase tracking-widest leading-none">Console Bertugas</p>
                <p className="text-xs font-bold mt-1">Halo {currentUser.name}, Anda masuk sebagai {currentUser.role}.</p>
              </div>
            </div>
            <div className="hidden sm:block text-[9px] font-black uppercase bg-white/50 px-3 py-1 rounded-full">
              {new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' })} WIB
            </div>
          </div>

          {activeTab === 'dashboard' && <Dashboard orders={orders} menu={menu} />}
          {activeTab === 'menu' && <MenuManager menu={menu} onUpdateMenu={setMenu} categories={categories} onUpdateCategories={setCategories} />}
          {activeTab === 'orders' && <OrdersList orders={orders} onUpdateOrder={handleUpdateOrder} />}
          {activeTab === 'receivables' && <ReceivablesList orders={orders} onUpdateOrder={handleUpdateOrder} />}
          {activeTab === 'advisor' && <SmartAdvisor />}
          {activeTab === 'security' && <AccountSecurity />}

          {/* Proteksi Akses Tim Admin */}
          {activeTab === 'admins' && (
            isSuperAdmin ? <AdminProfiles /> : (
              <div className="py-20 flex flex-col items-center justify-center text-center bg-white rounded-[2.5rem] border border-slate-100 shadow-sm animate-in zoom-in-95 duration-500">
                <div className="w-20 h-20 bg-rose-50 text-rose-500 rounded-3xl flex items-center justify-center mb-6 shadow-xl shadow-rose-100">
                  <ShieldAlert size={40} />
                </div>
                <h3 className="text-2xl font-black text-slate-900 mb-2">Akses Dibatasi</h3>
                <p className="text-slate-500 max-w-sm font-medium">Hanya Super Admin yang dapat mengelola profil tim dan hak akses pengguna.</p>
                <button 
                  onClick={() => setActiveTab('dashboard')}
                  className="mt-8 px-8 py-3 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-800 transition-all"
                >
                  Kembali ke Dashboard
                </button>
              </div>
            )
          )}

          {activeTab === 'social' && <SocialAnalytics menu={menu} settings={settings} />}
        </div>
      </main>

      {/* Navigasi Bawah */}
      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-xl border-t border-slate-100 px-6 py-4 flex justify-between items-center z-[40] shadow-[0_-10px_40px_rgba(0,0,0,0.04)] rounded-t-[2.5rem] lg:hidden">
        {navItems.map((item) => {
          if (item.isProminent) {
            return (
              <div key={item.id} className="relative -mt-12 flex flex-col items-center">
                <div className={`absolute inset-0 blur-3xl rounded-[2rem] transition-all duration-500 ${
                  activeTab === item.id ? 'bg-emerald-500/30 scale-125' : 'bg-slate-900/10 scale-100'
                }`}></div>
                <button
                  onClick={() => setActiveTab(item.id as any)}
                  className={`w-20 h-20 rounded-[2rem] flex flex-col items-center justify-center transition-all duration-500 relative overflow-hidden group ${
                    activeTab === item.id 
                      ? 'bg-gradient-to-br from-emerald-500 to-emerald-700 text-white shadow-[0_20px_40px_rgba(16,185,129,0.4)] scale-110 ring-4 ring-white' 
                      : 'bg-slate-900 text-white shadow-[0_15px_30px_rgba(15,23,42,0.3)] hover:-translate-y-1'
                  }`}
                >
                  <item.icon size={24} strokeWidth={2.5} className="mb-1" />
                  <span className="text-[9px] font-black uppercase tracking-[0.2em]">
                    {item.label}
                  </span>
                </button>
              </div>
            );
          }
          return (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id as any)}
              className={`flex flex-col items-center justify-center transition-all px-2 relative ${
                activeTab === item.id ? 'text-emerald-600' : 'text-slate-400 hover:text-slate-600'
              }`}
            >
              <item.icon size={20} strokeWidth={activeTab === item.id ? 2.5 : 2} />
              <span className="text-[8px] font-black mt-1.5 uppercase tracking-widest">{item.label}</span>
            </button>
          );
        })}
      </nav>

      {/* Modal Settings - Proteksi Internal */}
      {isSettingsOpen && isSuperAdmin && (
        <div className="fixed inset-0 z-[100] flex justify-end">
          <div className="absolute inset-0 bg-slate-900/20 backdrop-blur-[2px]" onClick={() => setIsSettingsOpen(false)}></div>
          <div className="w-full max-w-lg bg-white h-full relative z-10 shadow-2xl animate-in slide-in-from-right duration-300 flex flex-col border-l border-slate-100">
            <div className="p-6 border-b border-slate-50 flex items-center justify-between">
              <h2 className="text-xl font-bold text-slate-800">Pengaturan Toko</h2>
              <button onClick={() => setIsSettingsOpen(false)} className="p-2 hover:bg-slate-50 rounded-full text-slate-400"><X size={24} /></button>
            </div>
            <div className="flex-1 overflow-y-auto p-6">
              <Settings settings={settings} onUpdateSettings={setSettings} />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { 
  Search, ShoppingCart, Monitor, MessageCircle, 
  UtensilsCrossed, Star, Clock, MapPin, ChevronRight, 
  Flame, Leaf, Heart, Plus, Minus, Instagram, 
  CheckCircle, Award, Users, Utensils, Info, Loader2
} from 'lucide-react';
import { MenuItem, StoreSettings } from '../types';

interface PublicMenuProps {
  menu: MenuItem[];
  settings: StoreSettings;
  categories: string[];
  onBackToAdmin: () => void;
  onPlaceOrder?: (orderData: { items: string[], total: number }) => void;
}

const PublicMenu: React.FC<PublicMenuProps> = ({ menu, settings, categories, onBackToAdmin, onPlaceOrder }) => {
  const [activeCategory, setActiveCategory] = useState<string>('Semua');
  const [searchQuery, setSearchQuery] = useState('');
  const [cart, setCart] = useState<{ [key: string]: number }>({});
  const [selectedItem, setSelectedItem] = useState<MenuItem | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  const displayCategories = ['Semua', ...categories];

  const filteredMenu = useMemo(() => {
    return menu.filter(item => {
      const matchesCategory = activeCategory === 'Semua' || item.category === activeCategory;
      const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase());
      return matchesCategory && matchesSearch;
    });
  }, [menu, activeCategory, searchQuery]);

  const addToCart = (id: string, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    setCart(prev => ({ ...prev, [id]: (prev[id] || 0) + 1 }));
  };

  const removeFromCart = (id: string, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    setCart(prev => {
      const newCart = { ...prev };
      if (newCart[id] > 1) newCart[id] -= 1;
      else delete newCart[id];
      return newCart;
    });
  };

  const cartTotal = (Object.entries(cart) as [string, number][]).reduce((total, [id, qty]) => {
    const item = menu.find(m => m.id === id);
    return total + (item ? item.price * qty : 0);
  }, 0);

  const cartCount = Object.values(cart).reduce((a: number, b: number) => a + b, 0);

  const handleOrderWhatsApp = () => {
    if (isProcessing) return;

    setIsProcessing(true);

    // Siapkan data untuk sistem admin
    const itemsList = (Object.entries(cart) as [string, number][])
      .map(([id, qty]) => {
        const item = menu.find(m => m.id === id);
        return item ? `${item.name} (${qty}x)` : '';
      })
      .filter(text => text !== '');

    // 1. Simpan ke sistem admin secara otomatis
    if (onPlaceOrder) {
      onPlaceOrder({ items: itemsList, total: cartTotal });
    }

    // 2. Siapkan teks pesan WhatsApp
    const cartItemsText = itemsList.map(text => `• ${text}`).join('\n');
    const message = `Halo ${settings.storeName},\n\nSaya tertarik dengan menu katering Anda:\n\n${cartItemsText}\n\nTotal Estimasi: Rp ${cartTotal.toLocaleString()}\n\nMohon informasi ketersediaan untuk tanggal katering saya. Terima kasih!`;

    // Simulasi delay proses agar terasa eksklusif
    setTimeout(() => {
      window.open(`https://wa.me/${settings.whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');
      setIsProcessing(false);
      setCart({}); // Kosongkan keranjang setelah order
    }, 1500);
  };

  return (
    <div className="min-h-screen bg-[#fafafb] text-slate-900 pb-40 font-sans selection:bg-emerald-100 selection:text-emerald-900">

      {/* Overlay Processing */}
      {isProcessing && (
        <div className="fixed inset-0 z-[300] bg-slate-900/90 backdrop-blur-xl flex flex-col items-center justify-center text-white text-center p-8 animate-in fade-in duration-300">
           <div className="relative mb-8">
              <Loader2 className="animate-spin text-emerald-400" size={64} />
              <div className="absolute inset-0 flex items-center justify-center">
                 <ShoppingBag size={24} className="text-white" />
              </div>
           </div>
           <h2 className="text-3xl font-black mb-4">Mencatat Pesanan Anda...</h2>
           <p className="text-slate-400 max-w-xs font-medium leading-relaxed italic">
             "Mohon tunggu sebentar, kami sedang menyiapkan jalur chat prioritas untuk Anda."
           </p>
        </div>
      )}

      {/* Immersive Gourmet Hero */}
      <div className="relative h-[65vh] w-full overflow-hidden">
        <img 
          src="https://images.unsplash.com/photo-1555244162-803834f70033?auto=format&fit=crop&q=80&w=2000" 
          className="w-full h-full object-cover scale-105"
          alt="Catering Hero"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-[#fafafb] via-slate-900/60 to-slate-900/30"></div>

        {/* Navbar-like Branding */}
        <div className="absolute top-0 left-0 right-0 p-8 flex justify-between items-center z-50">
          <div className="flex items-center gap-4 bg-white/10 backdrop-blur-xl px-5 py-2.5 rounded-[2rem] border border-white/20 shadow-2xl">
            <div className="w-10 h-10 bg-white rounded-2xl flex items-center justify-center text-emerald-600 shadow-xl overflow-hidden ring-4 ring-white/10">
              {settings.logoUrl ? (
                <img src={settings.logoUrl} alt="Logo" className="w-full h-full object-cover" />
              ) : (
                <UtensilsCrossed size={20} />
              )}
            </div>
            <div className="hidden sm:block">
              <span className="font-black text-xs tracking-[0.2em] text-white uppercase block leading-none">{settings.storeName}</span>
              <span className="text-[8px] font-bold text-emerald-400 uppercase tracking-widest mt-1">Premium Catering</span>
            </div>
          </div>

          <button 
            onClick={onBackToAdmin}
            className="w-12 h-12 bg-white/10 backdrop-blur-xl rounded-2xl flex items-center justify-center text-white border border-white/20 hover:bg-white hover:text-slate-900 transition-all group"
          >
            <Monitor size={20} className="group-hover:scale-110 transition-transform" />
          </button>
        </div>

        {/* Hero Content with Storytelling */}
        <div className="absolute bottom-24 left-0 right-0 px-8 max-w-6xl mx-auto">
          <div className="flex flex-wrap items-center gap-3 mb-6">
            <div className="flex items-center gap-1.5 bg-emerald-500/90 backdrop-blur-md text-white text-[10px] font-black uppercase tracking-[0.2em] px-4 py-1.5 rounded-full shadow-xl">
              <CheckCircle size={12} /> Certified Hygiene
            </div>
            <div className="flex items-center gap-1.5 bg-amber-500/90 backdrop-blur-md text-white text-[10px] font-black uppercase tracking-[0.2em] px-4 py-1.5 rounded-full shadow-xl">
              <Award size={12} /> Top Rated 2024
            </div>
          </div>
          <h1 className="text-5xl md:text-7xl font-black text-white mb-6 leading-[1.1] tracking-tight">
            Rayakan Momen<br/>
            <span className="text-transparent bg-clip-text bg-gradient-to-r from-emerald-400 to-teal-300">Dengan Kelezatan.</span>
          </h1>
          <div className="flex flex-wrap items-center gap-8 text-white/80 text-sm font-bold">
             <div className="flex items-center gap-2"><Clock size={18} className="text-emerald-400" /> Waktu Pesan Fleksibel</div>
             <div className="flex items-center gap-2"><Users size={18} className="text-emerald-400" /> Melayani 10 - 1000 Pax</div>
             <div className="flex items-center gap-2"><MapPin size={18} className="text-emerald-400" /> Area JABODETABEK</div>
          </div>
        </div>
      </div>

      {/* Modern Search & Stats Bar */}
      <div className="max-w-6xl mx-auto px-8">
        <div className="bg-white rounded-[3rem] shadow-[0_30px_60px_-15px_rgba(0,0,0,0.1)] -mt-16 relative z-30 flex flex-col md:flex-row divide-y md:divide-y-0 md:divide-x divide-slate-100 border border-white">
          <div className="flex-1 p-4 flex items-center gap-4">
            <div className="w-12 h-12 bg-slate-50 rounded-2xl flex items-center justify-center text-slate-400">
              <Search size={22} />
            </div>
            <input 
              type="text" 
              placeholder="Cari hidangan favorit Anda..." 
              className="flex-1 bg-transparent outline-none text-base font-bold placeholder:text-slate-300"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <div className="hidden lg:flex items-center gap-6 px-10 py-4">
            <div className="text-center">
              <p className="text-xl font-black text-slate-800 leading-none">4.9</p>
              <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest mt-1">Rating</p>
            </div>
            <div className="text-center">
              <p className="text-xl font-black text-slate-800 leading-none">1.2k+</p>
              <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest mt-1">Events</p>
            </div>
          </div>
        </div>
      </div>

      {/* Category Pills - Clean & Aesthetic */}
      <div className="max-w-6xl mx-auto px-8 mt-16">
        <div className="flex gap-4 overflow-x-auto pb-4 no-scrollbar">
          {displayCategories.map(cat => (
            <button
              key={cat}
              onClick={() => setActiveCategory(cat)}
              className={`px-10 py-4 rounded-[1.8rem] text-[10px] font-black uppercase tracking-[0.2em] whitespace-nowrap transition-all duration-300 ${
                activeCategory === cat 
                  ? 'bg-slate-900 text-white shadow-2xl shadow-slate-200 translate-y-[-2px]' 
                  : 'bg-white text-slate-400 hover:text-emerald-600 hover:bg-emerald-50'
              }`}
            >
              {cat}
            </button>
          ))}
        </div>
      </div>

      {/* Main Menu Explore Grid */}
      <div className="max-w-6xl mx-auto px-8 mt-24 mb-32">
        <div className="flex items-center gap-6 mb-12">
          <h2 className="text-3xl font-black text-slate-800 tracking-tight whitespace-nowrap">Jelajahi Pilihan Menu</h2>
          <div className="h-px bg-slate-200 flex-1"></div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-10">
          {filteredMenu.map(item => (
            <div 
              key={item.id} 
              className="bg-white rounded-[2.8rem] border border-slate-100 overflow-hidden flex flex-col group hover:shadow-[0_40px_80px_-20px_rgba(0,0,0,0.08)] hover:border-emerald-100 transition-all duration-500 cursor-pointer"
              onClick={() => setSelectedItem(item)}
            >
              <div className="relative aspect-[1/1] overflow-hidden">
                <img src={item.imageUrl} alt={item.name} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700" />
                <div className="absolute top-4 right-4 flex flex-col gap-2">
                  <div className="bg-white/90 backdrop-blur-md p-2.5 rounded-2xl shadow-xl text-slate-400 hover:text-rose-500 transition-colors">
                    <Heart size={18} />
                  </div>
                </div>
                <div className="absolute bottom-4 left-4 flex gap-2">
                  {item.price > 50000 && <div className="bg-amber-500 text-white p-1.5 rounded-xl"><Award size={14} /></div>}
                  <div className="bg-white/90 backdrop-blur text-[8px] font-black px-3 py-1.5 rounded-xl uppercase tracking-widest shadow-lg">
                    {item.category}
                  </div>
                </div>
              </div>

              <div className="p-8 flex flex-col flex-1">
                <div className="flex items-center gap-1.5 mb-3">
                  <Flame size={12} className="text-rose-500" />
                  <span className="text-[9px] font-black text-slate-400 uppercase tracking-[0.2em]">Authentic Recipe</span>
                </div>
                <h3 className="font-black text-xl text-slate-800 mb-3 group-hover:text-emerald-600 transition-colors leading-tight line-clamp-1">{item.name}</h3>

                <p className="text-[11px] text-slate-400 font-medium leading-[1.6] mb-8 line-clamp-2">
                  {item.description}
                </p>

                <div className="mt-auto pt-6 border-t border-slate-50 flex items-center justify-between">
                  <div className="flex flex-col">
                    <span className="text-[9px] font-black text-slate-300 uppercase tracking-widest mb-1">Estimasi</span>
                    <span className="text-xl font-black text-slate-900 tracking-tight">Rp {(item.price/1000).toFixed(0)}k <span className="text-[10px] text-slate-400 font-bold uppercase">/ Pax</span></span>
                  </div>

                  <div className="flex items-center">
                    {cart[item.id] ? (
                      <div className="flex items-center bg-slate-900 text-white p-1.5 rounded-2xl shadow-xl animate-in zoom-in-95">
                        <button onClick={(e) => removeFromCart(item.id, e)} className="p-2.5 hover:bg-white/10 rounded-xl transition-all">
                          <Minus size={14} />
                        </button>
                        <span className="px-3 font-black text-xs">{cart[item.id]}</span>
                        <button onClick={(e) => addToCart(item.id, e)} className="p-2.5 hover:bg-white/10 rounded-xl transition-all">
                          <Plus size={14} />
                        </button>
                      </div>
                    ) : (
                      <button 
                        onClick={(e) => addToCart(item.id, e)}
                        className="w-12 h-12 bg-slate-50 text-slate-900 rounded-2xl flex items-center justify-center hover:bg-emerald-600 hover:text-white transition-all active:scale-90 group-hover:bg-emerald-500 group-hover:text-white group-hover:shadow-lg shadow-emerald-200"
                      >
                        <Plus size={20} />
                      </button>
                    )}
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Item Quick-View Modal */}
      {selectedItem && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-md" onClick={() => setSelectedItem(null)}></div>
          <div className="bg-white w-full max-w-4xl rounded-[3.5rem] overflow-hidden shadow-2xl relative z-10 animate-in zoom-in-95 duration-500 flex flex-col md:flex-row h-[85vh] md:h-auto">
            <div className="md:w-1/2 relative h-64 md:h-auto">
              <img src={selectedItem.imageUrl} className="w-full h-full object-cover" alt={selectedItem.name} />
              <button 
                onClick={() => setSelectedItem(null)}
                className="absolute top-6 left-6 w-10 h-10 bg-white/20 backdrop-blur-md rounded-full flex items-center justify-center text-white border border-white/20"
              >
                <ChevronRight size={20} className="rotate-180" />
              </button>
            </div>
            <div className="md:w-1/2 p-10 md:p-14 overflow-y-auto">
              <div className="flex items-center gap-2 mb-4">
                <span className="bg-emerald-50 text-emerald-600 text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-lg border border-emerald-100">
                  {selectedItem.category}
                </span>
                <span className="bg-slate-50 text-slate-400 text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-lg">
                  Halal Certified
                </span>
              </div>
              <h3 className="text-4xl font-black text-slate-900 mb-6 leading-tight">{selectedItem.name}</h3>
              <p className="text-slate-500 text-sm font-medium leading-relaxed mb-10 italic">
                {selectedItem.description}
              </p>

              <div className="space-y-6 mb-10">
                <div className="flex items-center gap-4 p-4 bg-slate-50 rounded-2xl border border-slate-100">
                   <Utensils size={20} className="text-emerald-500" />
                   <div>
                     <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-0.5">Highlight</p>
                     <p className="text-xs font-bold text-slate-700">Premium Taste, Authentic Spices, Fresh Ingredients</p>
                   </div>
                </div>
                <div className="flex items-center gap-4 p-4 bg-slate-50 rounded-2xl border border-slate-100">
                   <Clock size={20} className="text-amber-500" />
                   <div>
                     <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-0.5">Persiapan</p>
                     <p className="text-xs font-bold text-slate-700">Dimasak segar beberapa jam sebelum pengiriman.</p>
                   </div>
                </div>
              </div>

              <div className="flex items-center justify-between pt-8 border-t border-slate-100">
                <div className="flex flex-col">
                  <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest mb-1">Harga Satuan</span>
                  <span className="text-3xl font-black text-slate-900 tracking-tight">Rp {selectedItem.price.toLocaleString()}</span>
                </div>
                <button 
                  onClick={() => { addToCart(selectedItem.id); setSelectedItem(null); }}
                  className="bg-slate-900 text-white px-10 py-5 rounded-[2rem] font-black text-xs uppercase tracking-widest flex items-center gap-3 hover:bg-emerald-600 transition-all shadow-xl shadow-slate-200"
                >
                  <Plus size={20} /> Tambah Ke Pesanan
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Floating Glass Cart */}
      {cartTotal > 0 && (
        <div className="fixed bottom-12 left-1/2 -translate-x-1/2 w-[90%] max-w-lg z-[150]">
          <div className="bg-slate-900/90 backdrop-blur-2xl border border-white/10 rounded-[3rem] p-6 flex items-center justify-between shadow-[0_40px_80px_-15px_rgba(0,0,0,0.3)] animate-in slide-in-from-bottom-20 duration-700 ring-1 ring-white/10">
            <div className="flex items-center gap-6 pl-4">
              <div className="relative">
                <div className="w-16 h-16 bg-gradient-to-br from-emerald-400 to-teal-500 text-white rounded-[2rem] flex items-center justify-center shadow-2xl shadow-emerald-500/20">
                  <ShoppingCart size={28} />
                </div>
                <div className="absolute -top-3 -right-3 bg-white text-slate-900 w-8 h-8 rounded-full flex items-center justify-center text-[12px] font-black shadow-xl border-[3px] border-slate-900 scale-110">
