                <p className="text-2xl font-black text-white leading-none">Rp {cartTotal.toLocaleString()}</p>
              </div>
            </div>
            <button 
              className="bg-white text-slate-900 px-10 py-6 rounded-[2.2rem] font-black text-xs uppercase tracking-[0.15em] flex items-center gap-3 hover:bg-emerald-500 hover:text-white transition-all shadow-xl active:scale-95 group"
