                        ))}
                      </div>
                    )}
                  </td>
                  <td className="py-4 pr-6 bg-white border-y border-r border-slate-50 rounded-r-2xl text-right group-hover:bg-slate-50">
                    <div className="flex justify-end items-center gap-2">
                      <div className="text-right mr-3">
                         <p className="font-bold text-slate-900 text-sm leading-none">Rp {(o.totalPrice/1000).toFixed(0)}k</p>
                         <p className="text-[9px] text-slate-400 font-bold uppercase mt-1">Total</p>
                      </div>
                      <button className="p-2 hover:bg-white rounded-lg text-slate-400 hover:text-slate-800 transition-colors">
                        <MoreHorizontal size={18} />
                      </button>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {/* Manual Order Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsModalOpen(false)}></div>
          <div className="bg-white rounded-[2.5rem] w-full max-w-lg overflow-hidden shadow-2xl relative z-10 animate-in zoom-in-95 duration-300">
            <div className="p-8 pb-4 flex justify-between items-center">
              <div>
                <h3 className="text-2xl font-black text-slate-900">Pesanan Baru</h3>
                <p className="text-sm text-slate-400">Input data pesanan dari WhatsApp/Offline</p>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="p-3 hover:bg-slate-50 rounded-full text-slate-400 transition-all">
                <X size={20} />
              </button>
            </div>

            <div className="p-8 pt-4 space-y-6">
              <div className="space-y-4">
                <div className="relative group">
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">Nama Pelanggan</label>
                  <div className="flex items-center bg-slate-50 border border-slate-100 rounded-2xl px-4 py-3 focus-within:ring-2 focus-within:ring-amber-500 transition-all group-hover:border-slate-200">
