                </button>
              </div>
            )
          )}

          {activeTab === 'social' && <SocialAnalytics menu={menu} settings={settings} />}
        </div>
      </main>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-xl border-t border-slate-100 px-6 py-4 flex justify-between items-center z-[40] shadow-[0_-10px_40px_rgba(0,0,0,0.04)] rounded-t-[2.5rem] lg:hidden">
        {navItems.map((item) => {
          if (item.isProminent) {
            return (
              <div key={item.id} className="relative -mt-12 flex flex-col items-center">
                <div className={`absolute inset-0 blur-3xl rounded-[2rem] transition-all duration-500 ${
                  activeTab === item.id ? 'bg-emerald-500/30 scale-125' : 'bg-slate-900/10 scale-100'
                }`}></div>
                <button
                  onClick={() => setActiveTab(item.id as any)}
                  className={`w-20 h-20 rounded-[2rem] flex flex-col items-center justify-center transition-all duration-500 relative overflow-hidden group ${
                    activeTab === item.id 
                      ? 'bg-gradient-to-br from-emerald-500 to-emerald-700 text-white shadow-[0_20px_40px_rgba(16,185,129,0.4)] scale-110 ring-4 ring-white' 
                      : 'bg-slate-900 text-white shadow-[0_15px_30px_rgba(15,23,42,0.3)] hover:-translate-y-1'
                  }`}
                >
                  <item.icon size={24} strokeWidth={2.5} className="mb-1" />
                  <span className="text-[9px] font-black uppercase tracking-[0.2em]">
                    {item.label}
                  </span>
                </button>
              </div>
            );
          }
          return (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id as any)}
              className={`flex flex-col items-center justify-center transition-all px-2 relative ${
                activeTab === item.id ? 'text-emerald-600' : 'text-slate-400 hover:text-slate-600'
              }`}
            >
              <item.icon size={20} strokeWidth={activeTab === item.id ? 2.5 : 2} />
              <span className="text-[8px] font-black mt-1.5 uppercase tracking-widest">{item.label}</span>
            </button>
          );
        })}
      </nav>

      {isSettingsOpen && isSuperAdmin && (
        <div className="fixed inset-0 z-[100] flex justify-end">
          <div className="absolute inset-0 bg-slate-900/20 backdrop-blur-[2px]" onClick={() => setIsSettingsOpen(false)}></div>
          <div className="w-full max-w-lg bg-white h-full relative z-10 shadow-2xl animate-in slide-in-from-right duration-300 flex flex-col border-l border-slate-100">
            <div className="p-6 border-b border-slate-50 flex items-center justify-between">
              <h2 className="text-xl font-bold text-slate-800">Pengaturan Toko</h2>
              <button onClick={() => setIsSettingsOpen(false)} className="p-2 hover:bg-slate-50 rounded-full text-slate-400"><X size={24} /></button>
            </div>
            <div className="flex-1 overflow-y-auto p-6">
              <Settings settings={settings} onUpdateSettings={setSettings} />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

