import React, { useState, useMemo } from 'react';
import { 
  Search, ShoppingCart, Monitor, MessageCircle, 
  UtensilsCrossed, Star, Clock, MapPin, ChevronRight, 
  Flame, Leaf, Heart, Plus, Minus, Instagram, 
  CheckCircle, Award, Users, Utensils, Info, Loader2,
  ShoppingBag, Facebook, Video
} from 'lucide-react';
import { MenuItem, StoreSettings } from '../types';

interface PublicMenuProps {
  menu: MenuItem[];
  settings: StoreSettings;
  categories: string[];
  onBackToAdmin: () => void;
  onPlaceOrder?: (orderData: { items: string[], total: number }) => void;
}

const PublicMenu: React.FC<PublicMenuProps> = ({ menu, settings, categories, onBackToAdmin, onPlaceOrder }) => {
  const [activeCategory, setActiveCategory] = useState<string>('Semua');
  const [searchQuery, setSearchQuery] = useState('');
  const [cart, setCart] = useState<{ [key: string]: number }>({});
  const [selectedItem, setSelectedItem] = useState<MenuItem | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  const displayCategories = ['Semua', ...categories];

  const filteredMenu = useMemo(() => {
    return menu.filter(item => {
      const matchesCategory = activeCategory === 'Semua' || item.category === activeCategory;
      const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase());
      return matchesCategory && matchesSearch;
    });
  }, [menu, activeCategory, searchQuery]);

  const addToCart = (id: string, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    setCart(prev => ({ ...prev, [id]: (prev[id] || 0) + 1 }));
  };

  const removeFromCart = (id: string, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    setCart(prev => {
      const newCart = { ...prev };
      if (newCart[id] > 1) newCart[id] -= 1;
      else delete newCart[id];
      return newCart;
    });
  };

  const cartTotal = (Object.entries(cart) as [string, number][]).reduce((total, [id, qty]) => {
    const item = menu.find(m => m.id === id);
    return total + (item ? item.price * qty : 0);
  }, 0);

  const cartCount = Object.values(cart).reduce((a: number, b: number) => a + b, 0);

  const handleOrderWhatsApp = () => {
    if (isProcessing) return;

    setIsProcessing(true);

    const itemsList = (Object.entries(cart) as [string, number][])
      .map(([id, qty]) => {
        const item = menu.find(m => m.id === id);
        return item ? `${item.name} (${qty}x)` : '';
      })
      .filter(text => text !== '');

    if (onPlaceOrder) {
      onPlaceOrder({ items: itemsList, total: cartTotal });
    }

    const cartItemsText = itemsList.map(text => `• ${text}`).join('\n');
    const message = `Halo ${settings.storeName},\n\nSaya tertarik dengan menu katering Anda:\n\n${cartItemsText}\n\nTotal Estimasi: Rp ${cartTotal.toLocaleString()}\n\nMohon informasi ketersediaan untuk tanggal katering saya. Terima kasih!`;

    setTimeout(() => {
      window.open(`https://wa.me/${settings.whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');
      setIsProcessing(false);
      setCart({});
    }, 1500);
  };

  return (
    <div className="min-h-screen bg-[#fafafb] text-slate-900 pb-40 font-sans selection:bg-emerald-100 selection:text-emerald-900">

      {/* Overlay Processing */}
      {isProcessing && (
        <div className="fixed inset-0 z-[300] bg-slate-900/90 backdrop-blur-xl flex flex-col items-center justify-center text-white text-center p-8 animate-in fade-in duration-300">
           <div className="relative mb-8">
              <Loader2 className="animate-spin text-emerald-400" size={64} />
              <div className="absolute inset-0 flex items-center justify-center">
                 <ShoppingBag size={24} className="text-white" />
              </div>
           </div>
           <h2 className="text-3xl font-black mb-4">Mencatat Pesanan Anda...</h2>
           <p className="text-slate-400 max-w-xs font-medium leading-relaxed italic">
             "Mohon tunggu sebentar, kami sedang menyiapkan jalur chat prioritas untuk Anda."
           </p>
        </div>
      )}

      {/* Immersive Gourmet Hero */}
      <div className="relative h-[65vh] w-full overflow-hidden">
        <img 
          src="https://images.unsplash.com/photo-1555244162-803834f70033?auto=format&fit=crop&q=80&w=2000" 
          className="w-full h-full object-cover scale-105"
          alt="Catering Hero"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-[#fafafb] via-slate-900/60 to-slate-900/30"></div>

        <div className="absolute top-0 left-0 right-0 p-8 flex justify-between items-center z-50">
          <div className="flex items-center gap-4 bg-white/10 backdrop-blur-xl px-5 py-2.5 rounded-[2rem] border border-white/20 shadow-2xl">
            <div className="w-10 h-10 bg-white rounded-2xl flex items-center justify-center text-emerald-600 shadow-xl overflow-hidden ring-4 ring-white/10">
              {settings.logoUrl ? (
                <img src={settings.logoUrl} alt="Logo" className="w-full h-full object-cover" />
              ) : (
                <UtensilsCrossed size={20} />
              )}
            </div>
            <div className="hidden sm:block">
              <span className="font-black text-xs tracking-[0.2em] text-white uppercase block leading-none">{settings.storeName}</span>
              <span className="text-[8px] font-bold text-emerald-400 uppercase tracking-widest mt-1">Premium Catering</span>
