          </div>
          <h1 className="text-5xl md:text-7xl font-black text-white mb-6 leading-[1.1] tracking-tight">
            Rayakan Momen<br/>
            <span className="text-transparent bg-clip-text bg-gradient-to-r from-emerald-400 to-teal-300">Dengan Kelezatan.</span>
          </h1>
          <div className="flex flex-wrap items-center gap-8 text-white/80 text-sm font-bold">
