                <button
                  onClick={() => setActiveTab(item.id as any)}
                  className={`w-20 h-20 rounded-[2rem] flex flex-col items-center justify-center transition-all duration-500 relative overflow-hidden group ${
                    activeTab === item.id 
                      ? 'bg-gradient-to-br from-emerald-500 to-emerald-700 text-white shadow-[0_20px_40px_rgba(16,185,129,0.4)] scale-110 ring-4 ring-white' 
                      : 'bg-slate-900 text-white shadow-[0_15px_30px_rgba(15,23,42,0.3)] hover:-translate-y-1'
                  }`}
                >
                  <item.icon size={24} strokeWidth={2.5} className="mb-1" />
                  <span className="text-[9px] font-black uppercase tracking-[0.2em]">
                    {item.label}
                  </span>
                </button>
              </div>
            );
          }
          return (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id as any)}
              className={`flex flex-col items-center justify-center transition-all px-2 relative ${
                activeTab === item.id ? 'text-emerald-600' : 'text-slate-400 hover:text-slate-600'
              }`}
            >
              <item.icon size={20} strokeWidth={activeTab === item.id ? 2.5 : 2} />
              <span className="text-[8px] font-black mt-1.5 uppercase tracking-widest">{item.label}</span>
            </button>
          );
        })}
      </nav>

      {isSettingsOpen && isSuperAdmin && (
        <div className="fixed inset-0 z-[100] flex justify-end">
          <div className="absolute inset-0 bg-slate-900/20 backdrop-blur-[2px]" onClick={() => setIsSettingsOpen(false)}></div>
          <div className="w-full max-w-lg bg-white h-full relative z-10 shadow-2xl animate-in slide-in-from-right duration-300 flex flex-col border-l border-slate-100">
            <div className="p-6 border-b border-slate-50 flex items-center justify-between">
              <h2 className="text-xl font-bold text-slate-800">Pengaturan Toko</h2>
              <button onClick={() => setIsSettingsOpen(false)} className="p-2 hover:bg-slate-50 rounded-full text-slate-400"><X size={24} /></button>
            </div>
            <div className="flex-1 overflow-y-auto p-6">
              <Settings settings={settings} onUpdateSettings={setSettings} />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell, BarChart, Bar
} from 'recharts';
import { 
  TrendingUp, ArrowUpRight, ArrowDownRight, 
  DollarSign, ShoppingBag, PieChart as PieChartIcon,
  FileSpreadsheet, FileText, Calendar, Activity,
  Target, Wallet, CreditCard, ShieldCheck, AlertCircle,
  Zap, ArrowRight, BarChart3, Download, Sun, Moon, Clock, RefreshCcw
} from 'lucide-react';
import { Order, MenuItem, ShiftType } from '../types';

interface SalesReportProps {
  orders: Order[];
  menu: MenuItem[];
}

const SalesReport: React.FC<SalesReportProps> = ({ orders, menu }) => {
  const [period, setPeriod] = useState<'Weekly' | 'Monthly' | 'Yearly'>('Monthly');
  const [activeTab, setActiveTab] = useState<'overview' | 'daily' | 'shifts'>('overview');

  // Realistic mock data generation for charts
  const chartData = useMemo(() => {
    const dataMap = {
      'Weekly': [
        { name: 'Sen', revenue: 4500000, receivables: 1200000, cost: 2100000 },
        { name: 'Sel', revenue: 5200000, receivables: 800000, cost: 2400000 },
        { name: 'Rab', revenue: 3800000, receivables: 1500000, cost: 1900000 },
        { name: 'Kam', revenue: 6100000, receivables: 2000000, cost: 2800000 },
        { name: 'Jum', revenue: 8500000, receivables: 3400000, cost: 3900000 },
        { name: 'Sab', revenue: 12000000, receivables: 4500000, cost: 5500000 },
        { name: 'Min', revenue: 9500000, receivables: 2100000, cost: 4200000 },
      ],
      'Monthly': [
        { name: 'Mgg 1', revenue: 25000000, receivables: 8000000, cost: 11000000 },
        { name: 'Mgg 2', revenue: 32000000, receivables: 12000000, cost: 14500000 },
        { name: 'Mgg 3', revenue: 28000000, receivables: 5000000, cost: 12800000 },
        { name: 'Mgg 4', revenue: 45000000, receivables: 15000000, cost: 20000000 },
      ],
      'Yearly': [
        { name: 'Jan', revenue: 120000000, receivables: 30000000, cost: 55000000 },
        { name: 'Feb', revenue: 145000000, receivables: 40000000, cost: 65000000 },
        { name: 'Mar', revenue: 130000000, receivables: 25000000, cost: 60000000 },
        { name: 'Apr', revenue: 160000000, receivables: 55000000, cost: 72000000 },
        { name: 'Mei', revenue: 190000000, receivables: 70000000, cost: 85000000 },
        { name: 'Jun', revenue: 175000000, receivables: 45000000, cost: 78000000 },
      ]
    };
    return dataMap[period];
  }, [period]);

  const stats = useMemo(() => {
    const totalRevenue = chartData.reduce((acc, curr) => acc + curr.revenue, 0);
    const totalReceivables = chartData.reduce((acc, curr) => acc + curr.receivables, 0);
    const totalCost = chartData.reduce((acc, curr) => acc + curr.cost, 0);
    const grossProfit = totalRevenue - totalCost;
    const collectionRate = ((totalRevenue - totalReceivables) / totalRevenue) * 100;

    return {
      totalRevenue,
      totalReceivables,
      grossProfit,
      totalCost,
      collectionRate
    };
  }, [chartData]);

  // Daily Ledger Grouping
  const dailyReport = useMemo(() => {
    // Fix: Added explicit type casting to string for 'a' and 'b' to resolve TypeScript unknown property error
    const dates = Array.from(new Set(orders.map(o => o.date))).sort((a, b) => (b as string).localeCompare(a as string));
    return dates.map(date => {
      const dayOrders = orders.filter(o => o.date === date);
      const revenue = dayOrders.reduce((acc, o) => acc + o.totalPrice, 0);
      const paid = dayOrders.reduce((acc, o) => acc + o.amountPaid, 0);
      const receivables = revenue - paid;
      return { date, revenue, paid, receivables, count: dayOrders.length };
    });
  }, [orders]);

  // Shift Analysis
  const shiftData = useMemo(() => {
    const shifts: ShiftType[] = ['Pagi', 'Siang', 'Malam'];
    return shifts.map(s => {
      // Mocking some data if no orders have shifts yet
      const shiftOrders = orders.filter(o => o.shift === s);
      const revenue = shiftOrders.length > 0 
        ? shiftOrders.reduce((acc, o) => acc + o.totalPrice, 0) 
        : (s === 'Pagi' ? stats.totalRevenue * 0.4 : s === 'Siang' ? stats.totalRevenue * 0.45 : stats.totalRevenue * 0.15);

      return { 
        name: s, 
        revenue, 
        color: s === 'Pagi' ? '#f59e0b' : s === 'Siang' ? '#0ea5e9' : '#6366f1' 
      };
    });
  }, [orders, stats]);

  const handleExportData = () => {
    let csvContent = "LAPORAN KEUANGAN KATERING MENYELURUH\n";
    csvContent += `Tanggal Export: ${new Date().toLocaleString('id-ID')}\n\n`;

    csvContent += "1. RINGKASAN EKSEKUTIF\n";
    csvContent += `Total Omzet;Rp ${stats.totalRevenue.toLocaleString()}\n`;
    csvContent += `Total Piutang;Rp ${stats.totalReceivables.toLocaleString()}\n`;
    csvContent += `Profit Kotor;Rp ${stats.grossProfit.toLocaleString()}\n\n`;

    csvContent += "2. LAPORAN HARIAN (DAILY LEDGER)\n";
    csvContent += "Tanggal;Total Pesanan;Omzet;Terbayar;Piutang\n";
    dailyReport.forEach(d => {
      csvContent += `${d.date};${d.count};${d.revenue};${d.paid};${d.receivables}\n`;
    });
    csvContent += "\n";

    csvContent += "3. DISTRIBUSI SIFT\n";
    csvContent += "Shift;Kontribusi Omzet\n";
    shiftData.forEach(s => {
      csvContent += `${s.name};${s.revenue}\n`;
    });

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `Master_Financial_Report_${new Date().getTime()}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-10 animate-in fade-in slide-in-from-bottom-8 duration-1000 pb-20">
      {/* Executive Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-8 border-b border-slate-100 pb-8">
        <div>
          <div className="flex items-center gap-2 mb-2">
            <div className="w-1.5 h-1.5 rounded-full bg-indigo-500 animate-pulse"></div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em]">Enterprise Resource Insights</p>
          </div>
          <h2 className="text-4xl font-black text-slate-900 tracking-tight">Financial Intelligence</h2>
          <p className="text-sm text-slate-500 font-medium mt-1">Laporan menyeluruh per sift dan per hari.</p>
        </div>

        <div className="flex flex-wrap gap-3">
          <button 
            onClick={handleExportData}
            className="px-6 py-3 bg-white border border-slate-100 rounded-2xl text-[10px] font-black uppercase tracking-widest flex items-center gap-3 hover:bg-slate-50 transition-all shadow-sm"
          >
            <Download size={18} /> Export Master Ledger
          </button>
          <div className="flex items-center gap-1 bg-white p-1.5 rounded-[1.8rem] border border-slate-100 shadow-sm">
            {(['overview', 'daily', 'shifts'] as const).map((t) => (
              <button
                key={t}
                onClick={() => setActiveTab(t)}
                className={`px-6 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${
                  activeTab === t ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-400 hover:text-slate-600'
                }`}
              >
                {t}
              </button>
            ))}
          </div>
        </div>
      </div>

      {activeTab === 'overview' && (
        <>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Total Omzet</p>
              <h3 className="text-3xl font-black text-slate-900 tracking-tighter mb-4">Rp {(stats.totalRevenue/1000000).toFixed(1)} JT</h3>
              <div className="text-emerald-500 font-black text-[10px] flex items-center gap-1"><TrendingUp size={12} /> Target 95%</div>
            </div>
            <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Total Piutang</p>
              <h3 className="text-3xl font-black text-rose-600 tracking-tighter mb-4">Rp {(stats.totalReceivables/1000000).toFixed(1)} JT</h3>
              <div className="text-rose-400 font-black text-[10px] flex items-center gap-1"><AlertCircle size={12} /> Tertahan di pelanggan</div>
            </div>
            <div className="bg-slate-900 p-8 rounded-[2.5rem] text-white shadow-xl">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">HPP / Modal</p>
              <h3 className="text-3xl font-black text-white tracking-tighter mb-4">Rp {(stats.totalCost/1000000).toFixed(1)} JT</h3>
              <div className="text-indigo-400 font-black text-[10px] flex items-center gap-1"><Activity size={12} /> Food Cost 35%</div>
            </div>
            <div className="bg-emerald-500 p-8 rounded-[2.5rem] text-white shadow-xl">
              <p className="text-[10px] font-black text-white/70 uppercase tracking-widest mb-1">Net Profit</p>
              <h3 className="text-3xl font-black text-white tracking-tighter mb-4">Rp {(stats.grossProfit/1000000).toFixed(1)} JT</h3>
              <div className="text-white/80 font-black text-[10px] flex items-center gap-1"><ShieldCheck size={12} /> Saldo Aman</div>
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            <div className="lg:col-span-8 bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm">
              <h3 className="text-xl font-black text-slate-800 tracking-tight mb-8">Growth Curve</h3>
              <div className="h-[350px]">
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={chartData}>
                    <defs>
                      <linearGradient id="colorRev" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#4f46e5" stopOpacity={0.1}/>
                        <stop offset="95%" stopColor="#4f46e5" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                    <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10}} />
                    <YAxis hide />
                    <Tooltip />
                    <Area type="monotone" dataKey="revenue" stroke="#4f46e5" strokeWidth={4} fill="url(#colorRev)" />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
            </div>
            <div className="lg:col-span-4 bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm flex flex-col justify-center items-center text-center">
              <PieChartIcon size={48} className="text-indigo-500 mb-6" />
              <h3 className="text-xl font-black text-slate-800 tracking-tight mb-2">Likuiditas Kas</h3>
              <p className="text-xs text-slate-400 mb-8 font-medium italic">"Seberapa cepat piutang dikonversi menjadi kas nyata."</p>
              <div className="text-5xl font-black text-slate-900 mb-2">{stats.collectionRate.toFixed(0)}%</div>
              <p className="text-[10px] font-black text-emerald-500 uppercase tracking-widest">Collection Rate</p>
            </div>
          </div>
        </>
      )}

      {activeTab === 'daily' && (
        <div className="bg-white rounded-[3rem] p-10 border border-slate-100 shadow-sm">
