    csvContent += "RINGKASAN EKSEKUTIF\n";
    csvContent += `Total Omzet;Rp ${stats.totalRevenue.toLocaleString()}\n`;
    csvContent += `Total Kas Masuk;Rp ${stats.totalPaid.toLocaleString()}\n`;
    csvContent += `Total Piutang;Rp ${stats.totalReceivables.toLocaleString()}\n`;
    csvContent += `Profit Estimasi;Rp ${stats.grossProfit.toLocaleString()}\n\n`;

    const addSection = (title: string, data: any[]) => {
      csvContent += `${title}\n`;
      csvContent += "Periode;Order;Revenue;Paid;Receivables;Profit\n";
      data.forEach(d => {
        csvContent += `${d.label};${d.count};${d.revenue};${d.paid};${d.receivables};${d.revenue - d.cost}\n`;
      });
      csvContent += "\n";
    };

    addSection("LAPORAN HARIAN", reports.daily);
    addSection("LAPORAN MINGGUAN", reports.weekly);
    addSection("LAPORAN BULANAN", reports.monthly);
    addSection("LAPORAN TAHUNAN", reports.yearly);

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `CaterElite_Full_Financial_Audit_${new Date().getTime()}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
