                  Rp {d.revenue.toLocaleString()}
                </td>
                <td className="py-6 bg-slate-50 border-y border-slate-100 group-hover:bg-white transition-all font-black text-emerald-600">
                  Rp {d.paid.toLocaleString()}
                </td>
                <td className="py-6 pr-6 bg-slate-50 border-y border-r border-slate-100 rounded-r-2xl group-hover:bg-white transition-all text-right font-black text-indigo-600">
                  Rp {(d.revenue - d.cost).toLocaleString()}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );

  return (
