        <div>
          <div className="flex items-center gap-2 mb-2">
            <div className="w-1.5 h-1.5 rounded-full bg-indigo-500 animate-pulse"></div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em]">Financial Hub & Audit</p>
          </div>
          <h2 className="text-4xl font-black text-slate-900 tracking-tight">Financial Intelligence</h2>
          <p className="text-sm text-slate-500 font-medium mt-1">Laporan komprehensif dari harian hingga tahunan.</p>
        </div>

        <div className="flex flex-wrap gap-2 bg-white p-2 rounded-[2rem] border border-slate-100 shadow-sm w-full xl:w-auto overflow-x-auto no-scrollbar">
          {(['overview', 'daily', 'weekly', 'monthly', 'yearly', 'shifts'] as const).map((t) => (
            <button
              key={t}
              onClick={() => setActiveTab(t)}
              className={`whitespace-nowrap px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${
                activeTab === t ? 'bg-slate-900 text-white shadow-xl' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-50'
              }`}
            >
              {t}
