          ))}
        </div>
      </div>

      <div className="flex justify-end">
        <button 
          onClick={handleExportData}
          className="px-8 py-4 bg-emerald-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] flex items-center gap-3 hover:bg-emerald-700 transition-all shadow-xl shadow-emerald-100"
        >
          <Download size={18} /> Export Full Financial Audit
        </button>
      </div>

      {activeTab === 'overview' && (
        <>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Total Revenue</p>
              <h3 className="text-3xl font-black text-slate-900 tracking-tighter mb-4">Rp {(stats.totalRevenue/1000000).toFixed(1)} JT</h3>
              <div className="text-emerald-500 font-black text-[10px] flex items-center gap-1"><TrendingUp size={12} /> Target achieved</div>
            </div>
            <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Unpaid Receivables</p>
              <h3 className="text-3xl font-black text-rose-600 tracking-tighter mb-4">Rp {(stats.totalReceivables/1000000).toFixed(1)} JT</h3>
              <div className="text-rose-400 font-black text-[10px] flex items-center gap-1"><AlertCircle size={12} /> Pending collections</div>
