    csvContent += `Total Kas Masuk;Rp ${stats.totalPaid.toLocaleString()}\n`;
    csvContent += `Total Piutang;Rp ${stats.totalReceivables.toLocaleString()}\n`;
    csvContent += `Estimasi Laba;Rp ${stats.grossProfit.toLocaleString()}\n\n`;

