        csvContent += `${d.label};${d.count};${d.revenue};${d.cost};${d.paid};${d.receivables};${d.revenue - d.cost}\n`;
      });
      csvContent += "\n";
    };

    addSection("LAPORAN HARIAN", reports.daily);
    addSection("LAPORAN MINGGUAN", reports.weekly);
    addSection("LAPORAN BULANAN", reports.monthly);
    addSection("LAPORAN TAHUNAN", reports.yearly);

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `CaterElite_Audit_Finansial_Lengkap_${new Date().getTime()}.csv`);
    document.body.appendChild(link);
