            </div>

            {isProfileDropdownOpen && (
              <div className="absolute top-full right-0 mt-2 bg-white border border-slate-100 rounded-[2rem] shadow-2xl p-4 w-56 animate-in fade-in slide-in-from-top-4 z-[60]">
                <div className="pb-4 border-b border-slate-50 mb-4 px-2">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Status Sift</p>
                  <p className="text-xs font-bold text-slate-800 flex items-center gap-2">
                    {getShiftIcon(currentUser.shift)} Sift {currentUser.shift}
                  </p>
                </div>

                {isSuperAdmin && (
                  <button 
                    onClick={() => { setIsSettingsOpen(true); setIsProfileDropdownOpen(false); }}
                    className="w-full flex items-center gap-3 px-3 py-3 text-[10px] font-black uppercase tracking-widest text-slate-600 hover:bg-slate-50 rounded-xl transition-all"
                  >
                    <MoreVertical size={16} /> Edit Profil
                  </button>
