      <Sidebar 
        isOpen={isSidebarOpen} 
        setIsOpen={setIsSidebarOpen} 
        activeTab={activeTab} 
        setActiveTab={setActiveTab}
        onPreviewMenu={() => setViewMode('customer')}
        logoUrl={settings.logoUrl}
        onOpenSettings={() => isSuperAdmin && setIsSettingsOpen(true)}
        role={currentUser.role}
      />

      <main className="flex-1 overflow-y-auto px-4 py-6 md:px-8 md:py-8 pb-32">
        <div className="max-w-6xl mx-auto space-y-6">
          <div className={`p-4 rounded-[1.5rem] border flex items-center justify-between animate-in slide-in-from-top-4 ${getShiftColor(currentUser.shift)}`}>
            <div className="flex items-center gap-3">
              {getShiftIcon(currentUser.shift)}
              <div>
                <p className="text-[10px] font-black uppercase tracking-widest leading-none">Console Bertugas</p>
                <p className="text-xs font-bold mt-1">Halo {currentUser.name}, Anda masuk sebagai {currentUser.role}.</p>
              </div>
            </div>
            <div className="hidden sm:block text-[9px] font-black uppercase bg-white/50 px-3 py-1 rounded-full">
              {new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' })} WIB
            </div>
          </div>

          {activeTab === 'dashboard' && <Dashboard orders={orders} menu={menu} />}
          {activeTab === 'menu' && <MenuManager menu={menu} onUpdateMenu={setMenu} categories={categories} onUpdateCategories={setCategories} />}
          {activeTab === 'orders' && <OrdersList orders={orders} onUpdateOrder={handleUpdateOrder} />}
          {activeTab === 'receivables' && <ReceivablesList orders={orders} onUpdateOrder={handleUpdateOrder} />}
          {activeTab === 'advisor' && <SmartAdvisor />}
          {activeTab === 'security' && <AccountSecurity />}
          {activeTab === 'sales-report' && <SalesReport orders={orders} menu={menu} />}

          {activeTab === 'admins' && (
            isSuperAdmin ? <AdminProfiles /> : (
              <div className="py-20 flex flex-col items-center justify-center text-center bg-white rounded-[2.5rem] border border-slate-100 shadow-sm animate-in zoom-in-95 duration-500">
                <div className="w-20 h-20 bg-rose-50 text-rose-500 rounded-3xl flex items-center justify-center mb-6 shadow-xl shadow-rose-100">
                  <ShieldAlert size={40} />
                </div>
                <h3 className="text-2xl font-black text-slate-900 mb-2">Akses Dibatasi</h3>
                <p className="text-slate-500 max-w-sm font-medium">Hanya Super Admin yang dapat mengelola profil tim dan hak akses pengguna.</p>
                <button 
                  onClick={() => setActiveTab('dashboard')}
                  className="mt-8 px-8 py-3 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-800 transition-all"
