            </div>
            <div className="flex-1 overflow-y-auto p-6">
              <Settings settings={settings} onUpdateSettings={setSettings} />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Plus, Search, Filter, MoreHorizontal, ShoppingBag, X, Check, User, Hash, CreditCard, ChevronDown, Clock, AlertCircle } from 'lucide-react';
import { Order } from '../types';

interface OrdersListProps {
  orders: Order[];
  onUpdateOrder: (orderId: string, updates: Partial<Order>) => void;
}

const OrdersList: React.FC<OrdersListProps> = ({ orders, onUpdateOrder }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [updatingPaymentId, setUpdatingPaymentId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const [newOrder, setNewOrder] = useState<Partial<Order>>({
    customerName: '',
    type: 'Individual',
    totalPrice: 0,
    items: [],
    deliveryTime: ''
  });

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'Delivered': return 'bg-emerald-50 text-emerald-600 border-emerald-100';
      case 'Confirmed': return 'bg-blue-50 text-blue-600 border-blue-100';
      case 'Pending': return 'bg-amber-50 text-amber-600 border-amber-100';
      case 'Cancelled': return 'bg-rose-50 text-rose-600 border-rose-100';
      default: return 'bg-slate-50 text-slate-600 border-slate-100';
    }
  };

  const getPaymentBadge = (status: string) => {
    switch (status) {
      case 'Paid': return 'bg-emerald-100 text-emerald-700 border-emerald-200';
      case 'Partial': return 'bg-amber-100 text-amber-700 border-amber-200';
      case 'Unpaid': return 'bg-rose-100 text-rose-700 border-rose-200';
      default: return 'bg-slate-100 text-slate-600 border-slate-200';
    }
  };

  const handleUpdatePayment = (orderId: string, status: 'Paid' | 'Partial' | 'Unpaid') => {
    const order = orders.find(o => o.id === orderId);
    if (!order) return;

    let amountPaid = order.amountPaid;
    if (status === 'Paid') amountPaid = order.totalPrice;
    else if (status === 'Unpaid') amountPaid = 0;

    onUpdateOrder(orderId, { paymentStatus: status, amountPaid });
    setUpdatingPaymentId(null);
  };

  const handleSaveOrder = () => {
    // Validasi
    if (!newOrder.customerName?.trim()) return setError('Nama pelanggan wajib diisi!');
    if (!newOrder.items || newOrder.items.length === 0) return setError('Item pesanan minimal satu!');
    if (!newOrder.totalPrice || newOrder.totalPrice <= 0) return setError('Total harga harus valid!');
    if (!newOrder.deliveryTime) return setError('Waktu pengiriman wajib ditentukan!');

    // Mock save logic (would normally call onAddOrder from App)
    // For now we just close and reset
    setIsModalOpen(false);
    setError(null);
    setNewOrder({ customerName: '', type: 'Individual', totalPrice: 0, items: [], deliveryTime: '' });
  };

  return (
    <div className="bg-white rounded-3xl p-6 md:p-8 border border-slate-100 shadow-sm animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-8">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Manajemen Pesanan</h2>
          <p className="text-sm text-slate-400 mt-1">Catat pesanan dari WhatsApp atau Telepon di sini.</p>
        </div>
        <button 
          onClick={() => setIsModalOpen(true)}
          className="bg-slate-900 text-white px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 hover:bg-slate-800 transition-all shadow-lg shadow-slate-200"
        >
          <Plus size={18} /> Input Pesanan Manual
        </button>
      </div>

      <div className="overflow-x-auto -mx-6 md:mx-0">
        <table className="w-full text-left border-separate border-spacing-y-3">
          <thead>
            <tr className="text-slate-400 text-[10px] font-black uppercase tracking-[0.2em] px-4">
              <th className="pb-4 pl-6">ID / Customer</th>
              <th className="pb-4">Menu Items</th>
              <th className="pb-4">Status</th>
              <th className="pb-4">Payment</th>
              <th className="pb-4 text-right">Aksi</th>
            </tr>
          </thead>
          <tbody>
            {orders.map((o) => {
              const isAutoNew = o.id.length === 4 && o.status === 'Pending';

              return (
                <tr key={o.id} className={`group hover:bg-slate-50 transition-all ${isAutoNew ? 'ring-2 ring-emerald-500/20 animate-pulse' : ''}`}>
                  <td className="py-4 pl-6 bg-white border-y border-l border-slate-50 rounded-l-2xl group-hover:bg-slate-50">
                    <div className="flex items-center gap-4">
                      <div className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${isAutoNew ? 'bg-emerald-500 text-white' : 'bg-slate-50 text-slate-400 group-hover:bg-white group-hover:text-amber-500'}`}>
                        <ShoppingBag size={20} />
                      </div>
                      <div>
                        <div className="flex items-center gap-2">
                           <p className="font-bold text-slate-800 text-sm">#{o.id}</p>
                           {isAutoNew && <span className="text-[8px] font-black text-emerald-600 bg-emerald-50 px-1.5 py-0.5 rounded-md border border-emerald-100 uppercase animate-bounce">New</span>}
                        </div>
                        <p className="text-xs text-slate-500">{o.customerName}</p>
                      </div>
                    </div>
                  </td>
                  <td className="py-4 bg-white border-y border-slate-50 group-hover:bg-slate-50">
                    <p className="text-xs text-slate-600 font-medium line-clamp-1">{o.items.join(', ')}</p>
                    <p className="text-[10px] text-slate-400 mt-1 flex items-center gap-2">
                      {o.date} <span className="w-1 h-1 rounded-full bg-slate-300"></span> <Clock size={10} /> {o.deliveryTime || '--:--'}
                    </p>
                  </td>
                  <td className="py-4 bg-white border-y border-slate-50 group-hover:bg-slate-50">
                    <span className={`text-[10px] font-black uppercase tracking-wider px-3 py-1.5 rounded-lg border ${getStatusBadge(o.status)}`}>
                      {o.status}
                    </span>
                  </td>
                  <td className="py-4 bg-white border-y border-slate-50 group-hover:bg-slate-50 relative">
                    <div className="flex items-center gap-2">
                      <span className={`text-[10px] font-bold px-2 py-1 rounded-lg border ${getPaymentBadge(o.paymentStatus)}`}>
                        {o.paymentStatus}
                      </span>
                      <button 
                        onClick={() => setUpdatingPaymentId(updatingPaymentId === o.id ? null : o.id)}
                        className="p-1 hover:bg-slate-100 rounded text-slate-400"
                      >
                        <ChevronDown size={14} />
                      </button>
                    </div>

                    {updatingPaymentId === o.id && (
                      <div className="absolute top-full left-0 z-50 mt-1 bg-white border border-slate-100 shadow-xl rounded-xl p-2 min-w-[120px] animate-in fade-in slide-in-from-top-2">
                        {(['Paid', 'Partial', 'Unpaid'] as const).map(status => (
                          <button
                            key={status}
                            onClick={() => handleUpdatePayment(o.id, status)}
                            className="w-full text-left px-3 py-2 text-[10px] font-black uppercase tracking-widest hover:bg-slate-50 rounded-lg text-slate-600"
                          >
                            Mark as {status}
                          </button>
                        ))}
                      </div>
                    )}
                  </td>
                  <td className="py-4 pr-6 bg-white border-y border-r border-slate-50 rounded-r-2xl text-right group-hover:bg-slate-50">
                    <div className="flex justify-end items-center gap-2">
                      <div className="text-right mr-3">
                         <p className="font-bold text-slate-900 text-sm leading-none">Rp {(o.totalPrice/1000).toFixed(0)}k</p>
                         <p className="text-[9px] text-slate-400 font-bold uppercase mt-1">Total</p>
                      </div>
                      <button className="p-2 hover:bg-white rounded-lg text-slate-400 hover:text-slate-800 transition-colors">
                        <MoreHorizontal size={18} />
                      </button>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {/* Manual Order Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => { setIsModalOpen(false); setError(null); }}></div>
          <div className="bg-white rounded-[2.5rem] w-full max-w-lg overflow-hidden shadow-2xl relative z-10 animate-in zoom-in-95 duration-300">
            <div className="p-8 pb-4 flex justify-between items-center">
              <div>
                <h3 className="text-2xl font-black text-slate-900">Pesanan Baru</h3>
                <p className="text-sm text-slate-400">Input data pesanan dari WhatsApp/Offline</p>
              </div>
              <button onClick={() => { setIsModalOpen(false); setError(null); }} className="p-3 hover:bg-slate-50 rounded-full text-slate-400 transition-all">
                <X size={20} />
              </button>
            </div>

            <div className="p-8 pt-4 space-y-6">
              {error && (
                <div className="p-4 bg-rose-50 border border-rose-100 rounded-2xl flex items-center gap-3 text-rose-600 animate-in shake duration-500">
                   <AlertCircle size={20} />
                   <p className="text-xs font-black uppercase tracking-widest">{error}</p>
                </div>
              )}

              <div className="space-y-4">
                <div className="relative group">
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">Nama Pelanggan</label>
                  <div className="flex items-center bg-slate-50 border border-slate-100 rounded-2xl px-4 py-3 focus-within:ring-2 focus-within:ring-amber-500 transition-all group-hover:border-slate-200">
                    <User size={18} className="text-slate-400 mr-3" />
                    <input 
                      type="text" 
                      placeholder="Contoh: Ibu Ani - Wedding" 
                      className="bg-transparent border-none outline-none text-sm w-full font-semibold"
                      value={newOrder.customerName}
                      onChange={(e) => setNewOrder({...newOrder, customerName: e.target.value})}
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="relative group">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">Tipe Order</label>
                    <select 
                      className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-4 py-3 text-sm font-semibold outline-none focus:ring-2 focus:ring-amber-500 transition-all"
                      value={newOrder.type}
                      onChange={(e) => setNewOrder({...newOrder, type: e.target.value as any})}
                    >
                      <option value="Individual">Individual</option>
                      <option value="Corporate">Corporate</option>
                      <option value="Wedding">Wedding</option>
                    </select>
                  </div>
                  <div className="relative group">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">Jam Pengiriman</label>
                    <div className="flex items-center bg-slate-50 border border-slate-100 rounded-2xl px-4 py-3 transition-all">
                      <Clock size={16} className="text-slate-400 mr-3" />
                      <input 
                        type="time" 
                        className="bg-transparent border-none outline-none text-sm w-full font-bold"
                        value={newOrder.deliveryTime}
                        onChange={(e) => setNewOrder({...newOrder, deliveryTime: e.target.value})}
                      />
                    </div>
                  </div>
                </div>

                <div className="relative group">
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">Total Harga (Rp)</label>
                  <div className="flex items-center bg-slate-50 border border-slate-100 rounded-2xl px-4 py-3 transition-all">
                    <input 
                      type="number" 
                      placeholder="500000" 
                      className="bg-transparent border-none outline-none text-sm w-full font-bold text-amber-600"
                      value={newOrder.totalPrice || ''}
                      onChange={(e) => setNewOrder({...newOrder, totalPrice: Number(e.target.value)})}
                    />
                  </div>
                </div>

                <div className="relative group">
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">Item Pesanan (Pisahkan Koma)</label>
                  <textarea 
                    placeholder="Contoh: Nasi Liwet (20), Es Jeruk (20)" 
                    rows={3}
                    className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-4 py-3 text-sm font-semibold outline-none focus:ring-2 focus:ring-amber-500 transition-all resize-none"
                    value={newOrder.items?.join(', ')}
                    onChange={(e) => setNewOrder({...newOrder, items: e.target.value.split(',').map(i => i.trim())})}
                  ></textarea>
                </div>
              </div>

              <button 
                onClick={handleSaveOrder}
                className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold flex items-center justify-center gap-2 hover:bg-emerald-600 transition-all shadow-xl shadow-slate-200"
              >
                <Check size={20} />
                Simpan Pesanan
              </button>
            </div>
          </div>
        </div>
      )}

      {orders.length === 0 && (
        <div className="py-20 text-center">
          <p className="text-slate-400 italic">Belum ada pesanan masuk...</p>
        </div>
      )}
    </div>
  );
};

export default OrdersList;

import React, { useState, useRef } from 'react';
import { Plus, Sparkles, Trash2, Loader2, X, Image as ImageIcon, Save, CheckCircle, Upload, Share2, Copy, QrCode, ExternalLink, Check, Tag, AlertCircle } from 'lucide-react';
import { MenuItem } from '../types';
import { optimizeMenuDescription } from '../services/geminiService';

interface MenuManagerProps {
  menu: MenuItem[];
  onUpdateMenu: (menu: MenuItem[]) => void;
  categories: string[];
  onUpdateCategories: (categories: string[]) => void;
}

const MenuManager: React.FC<MenuManagerProps> = ({ menu, onUpdateMenu, categories, onUpdateCategories }) => {
  const [optimizingId, setOptimizingId] = useState<string | null>(null);
  const [successId, setSuccessId] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isShareModalOpen, setIsShareModalOpen] = useState(false);
  const [isCatModalOpen, setIsCatModalOpen] = useState(false);
  const [newCatName, setNewCatName] = useState('');
  const [copySuccess, setCopySuccess] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<MenuItem>>({
    name: '',
    category: categories[0] || '',
    price: 0,
    cost: 0,
    description: '',
    imageUrl: ''
  });

  const handleCopyLink = () => {
    setCopySuccess(true);
    setTimeout(() => setCopySuccess(false), 2000);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData({ ...formData, imageUrl: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAIUIOptimize = async (item: MenuItem) => {
    setOptimizingId(item.id);
    try {
      const newDesc = await optimizeMenuDescription(item.name, item.description);
      if (newDesc) {
        const updatedMenu = menu.map(m => 
          m.id === item.id ? { ...m, description: newDesc.trim() } : m
        );
        onUpdateMenu(updatedMenu);
        setSuccessId(item.id);
        setTimeout(() => setSuccessId(null), 3000);
      }
    } catch (error) {
      console.error("Optimization failed", error);
    } finally {
      setOptimizingId(null);
    }
  };

  const handleSaveNewItem = () => {
    // Validasi input
    if (!formData.name?.trim()) return setError('Nama hidangan wajib diisi!');
    if (!formData.price || formData.price <= 0) return setError('Harga jual harus lebih dari 0!');
    if (!formData.description?.trim()) return setError('Deskripsi menu wajib diisi untuk katalog!');
    if (!formData.imageUrl) return setError('Pilih foto hidangan agar menu lebih menarik!');

    const newItem: MenuItem = {
      id: Math.random().toString(36).substr(2, 9),
      name: formData.name || 'Menu Baru',
      category: formData.category || categories[0] || 'Uncategorized',
      price: Number(formData.price) || 0,
      cost: Number(formData.cost) || 0,
      description: formData.description || '',
