import React, { useState, useMemo } from 'react';
import { Plus, Search, Filter, MoreHorizontal, ShoppingBag, X, Check, User, Hash, CreditCard, ChevronDown, Clock, AlertCircle, Timer, AlertTriangle } from 'lucide-react';
import { Order } from '../types';

interface OrdersListProps {
  orders: Order[];
  onUpdateOrder: (orderId: string, updates: Partial<Order>) => void;
}

const OrdersList: React.FC<OrdersListProps> = ({ orders, onUpdateOrder }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [updatingPaymentId, setUpdatingPaymentId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const [newOrder, setNewOrder] = useState<Partial<Order>>({
    customerName: '',
    type: 'Individual',
    totalPrice: 0,
    items: [],
    deliveryTime: ''
  });

  // Calculate deadline status
  const getDeadlineStatus = (order: Order) => {
    if (order.status === 'Delivered' || order.status === 'Cancelled' || !order.deliveryTime) return null;

    const today = new Date().toISOString().split('T')[0];
    if (order.date !== today) return null;

    const now = new Date();
    const [hour, min] = order.deliveryTime.split(':').map(Number);
    const deliveryDate = new Date();
    deliveryDate.setHours(hour, min, 0);

    const diffMs = deliveryDate.getTime() - now.getTime();
    const diffMins = Math.floor(diffMs / (1000 * 60));

    if (diffMins < 0) return { label: 'Terlambat', color: 'text-rose-600 bg-rose-50 border-rose-100', icon: AlertTriangle, urgent: true };
    if (diffMins <= 180) return { label: `${diffMins} Menit Lagi`, color: 'text-amber-600 bg-amber-50 border-amber-100', icon: Timer, urgent: true };
    return null;
  };

  const sortedOrders = useMemo(() => {
    return [...orders].sort((a, b) => {
      // Prioritaskan yang belum selesai dan ada hari ini
      const today = new Date().toISOString().split('T')[0];
      if (a.date === today && b.date !== today) return -1;
      if (a.date !== today && b.date === today) return 1;

      // Kemudian sort berdasarkan delivery time
      if (a.deliveryTime && b.deliveryTime) {
        return a.deliveryTime.localeCompare(b.deliveryTime);
      }
      return 0;
    });
  }, [orders]);

  const filteredOrders = useMemo(() => {
    return sortedOrders.filter(o => 
      o.customerName.toLowerCase().includes(searchQuery.toLowerCase()) ||
      o.id.includes(searchQuery)
    );
  }, [sortedOrders, searchQuery]);

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'Delivered': return 'bg-emerald-50 text-emerald-600 border-emerald-100';
      case 'Confirmed': return 'bg-blue-50 text-blue-600 border-blue-100';
      case 'Pending': return 'bg-amber-50 text-amber-600 border-amber-100';
      case 'Cancelled': return 'bg-rose-50 text-rose-600 border-rose-100';
      default: return 'bg-slate-50 text-slate-600 border-slate-100';
    }
  };

  const getPaymentBadge = (status: string) => {
    switch (status) {
      case 'Paid': return 'bg-emerald-100 text-emerald-700 border-emerald-200';
      case 'Partial': return 'bg-amber-100 text-amber-700 border-amber-200';
      case 'Unpaid': return 'bg-rose-100 text-rose-700 border-rose-200';
      default: return 'bg-slate-100 text-slate-600 border-slate-200';
    }
  };

  const handleUpdatePayment = (orderId: string, status: 'Paid' | 'Partial' | 'Unpaid') => {
    const order = orders.find(o => o.id === orderId);
    if (!order) return;

    let amountPaid = order.amountPaid;
    if (status === 'Paid') amountPaid = order.totalPrice;
    else if (status === 'Unpaid') amountPaid = 0;

    onUpdateOrder(orderId, { paymentStatus: status, amountPaid });
    setUpdatingPaymentId(null);
  };

  const handleSaveOrder = () => {
    if (!newOrder.customerName?.trim()) return setError('Nama pelanggan wajib diisi!');
    if (!newOrder.items || newOrder.items.length === 0) return setError('Item pesanan minimal satu!');
    if (!newOrder.totalPrice || newOrder.totalPrice <= 0) return setError('Total harga harus valid!');
    if (!newOrder.deliveryTime) return setError('Waktu pengiriman wajib ditentukan!');

    // Logic penambahan pesanan biasanya di App.tsx, di sini kita simulasi
    setIsModalOpen(false);
    setError(null);
    setNewOrder({ customerName: '', type: 'Individual', totalPrice: 0, items: [], deliveryTime: '' });
  };

  return (
    <div className="bg-white rounded-3xl p-6 md:p-8 border border-slate-100 shadow-sm animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-6 mb-10">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Daftar Pesanan & Deadline</h2>
          <p className="text-sm text-slate-400 font-medium mt-1">Pantau waktu pengiriman untuk ketepatan layanan.</p>
        </div>

        <div className="flex flex-col sm:flex-row gap-4 w-full xl:w-auto">
          <div className="relative flex-1 sm:w-64">
            <Search size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
            <input 
              type="text" 
              placeholder="Cari pesanan..."
              className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-100 rounded-2xl text-sm font-semibold outline-none focus:ring-2 focus:ring-amber-500/20 transition-all"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <button 
            onClick={() => setIsModalOpen(true)}
            className="bg-slate-900 text-white px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-3 hover:bg-slate-800 transition-all shadow-xl shadow-slate-200"
          >
            <Plus size={18} /> Input Pesanan
          </button>
        </div>
      </div>

      <div className="overflow-x-auto">
