                <div className="p-4 bg-rose-50 border border-rose-100 rounded-2xl flex items-center gap-3 text-rose-600 animate-in shake duration-500">
                   <AlertCircle size={20} />
                   <p className="text-[10px] font-black uppercase tracking-widest">{error}</p>
                </div>
              )}

