          <button onClick={() => setIsSidebarOpen(true)} className="p-2 text-slate-400 lg:hidden">
            <MenuIcon size={22} />
          </button>

          <div className="hidden md:flex items-center gap-3">
            <div className={`flex items-center gap-2 px-3 py-1 rounded-full border ${isSuperAdmin ? 'bg-amber-50 text-amber-600 border-amber-200' : 'bg-slate-50 text-slate-500 border-slate-200'}`}>
