              <span className="text-[10px] font-black uppercase tracking-widest">{currentUser.role}</span>
            </div>

            <div className="relative">
              <button 
                onClick={() => setIsShiftDropdownOpen(!isShiftDropdownOpen)}
                className={`flex items-center gap-2 px-3 py-1 rounded-full border transition-all hover:shadow-sm ${getShiftColor(currentUser.shift)}`}
              >
                {getShiftIcon(currentUser.shift)}
                <span className="text-[10px] font-black uppercase tracking-widest">Sift {currentUser.shift}</span>
                <ChevronDown size={10} />
              </button>

              {isShiftDropdownOpen && (
