import React, { useState, useMemo } from 'react';
import { Plus, Search, Filter, MoreHorizontal, ShoppingBag, X, Check, User, Hash, CreditCard, ChevronDown, Clock, AlertCircle, Timer, AlertTriangle } from 'lucide-react';
import { Order } from '../types';

interface OrdersListProps {
  orders: Order[];
  onUpdateOrder: (orderId: string, updates: Partial<Order>) => void;
  onNotify?: (message: string, type: 'success' | 'error' | 'warning') => void;
}

const OrdersList: React.FC<OrdersListProps> = ({ orders, onUpdateOrder, onNotify }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [updatingPaymentId, setUpdatingPaymentId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const [newOrder, setNewOrder] = useState<Partial<Order>>({
    customerName: '',
    type: 'Individual',
    totalPrice: 0,
    items: [],
    deliveryTime: ''
  });

  // Calculate deadline status
  const getDeadlineStatus = (order: Order) => {
    if (order.status === 'Delivered' || order.status === 'Cancelled' || !order.deliveryTime) return null;

    const today = new Date().toISOString().split('T')[0];
    if (order.date !== today) return null;

    const now = new Date();
    const [hour, min] = order.deliveryTime.split(':').map(Number);
    const deliveryDate = new Date();
    deliveryDate.setHours(hour, min, 0);

    const diffMs = deliveryDate.getTime() - now.getTime();
    const diffMins = Math.floor(diffMs / (1000 * 60));

    if (diffMins < 0) return { label: 'Terlambat', color: 'text-rose-600 bg-rose-50 border-rose-100', icon: AlertTriangle, urgent: true };
    if (diffMins <= 180) return { label: `${diffMins} Menit Lagi`, color: 'text-amber-600 bg-amber-50 border-amber-100', icon: Timer, urgent: true };
    return null;
  };

  const sortedOrders = useMemo(() => {
    return [...orders].sort((a, b) => {
      const today = new Date().toISOString().split('T')[0];
      if (a.date === today && b.date !== today) return -1;
      if (a.date !== today && b.date === today) return 1;
      if (a.deliveryTime && b.deliveryTime) {
        return a.deliveryTime.localeCompare(b.deliveryTime);
      }
      return 0;
    });
  }, [orders]);

  const filteredOrders = useMemo(() => {
    return sortedOrders.filter(o => 
      o.customerName.toLowerCase().includes(searchQuery.toLowerCase()) ||
      o.id.includes(searchQuery)
    );
  }, [sortedOrders, searchQuery]);

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'Delivered': return 'bg-emerald-50 text-emerald-600 border-emerald-100';
      case 'Confirmed': return 'bg-blue-50 text-blue-600 border-blue-100';
      case 'Pending': return 'bg-amber-50 text-amber-600 border-amber-100';
      case 'Cancelled': return 'bg-rose-50 text-rose-600 border-rose-100';
      default: return 'bg-slate-50 text-slate-600 border-slate-100';
    }
  };

  const getPaymentBadge = (status: string) => {
    switch (status) {
      case 'Paid': return 'bg-emerald-100 text-emerald-700 border-emerald-200';
      case 'Partial': return 'bg-amber-100 text-amber-700 border-amber-200';
      case 'Unpaid': return 'bg-rose-100 text-rose-700 border-rose-200';
      default: return 'bg-slate-100 text-slate-600 border-slate-200';
    }
  };

  const handleUpdatePayment = (orderId: string, status: 'Paid' | 'Partial' | 'Unpaid') => {
    const order = orders.find(o => o.id === orderId);
    if (!order) return;

    let amountPaid = order.amountPaid;
    if (status === 'Paid') amountPaid = order.totalPrice;
    else if (status === 'Unpaid') amountPaid = 0;

    onUpdateOrder(orderId, { paymentStatus: status, amountPaid });
    setUpdatingPaymentId(null);
  };

  const handleSaveOrder = () => {
    if (!newOrder.customerName?.trim()) {
      return onNotify?.('Nama pelanggan wajib diisi!', 'error');
    }
    if (!newOrder.items || newOrder.items.length === 0) {
      return onNotify?.('Item pesanan minimal satu!', 'error');
    }
    if (!newOrder.totalPrice || newOrder.totalPrice <= 0) {
      return onNotify?.('Total harga harus valid!', 'error');
    }
    if (!newOrder.deliveryTime) {
      return onNotify?.('Waktu pengiriman wajib ditentukan!', 'error');
    }

    setIsModalOpen(false);
    onNotify?.(`Pesanan ${newOrder.customerName} berhasil disimpan.`, 'success');
    setNewOrder({ customerName: '', type: 'Individual', totalPrice: 0, items: [], deliveryTime: '' });
  };

  return (
    <div className="bg-white rounded-3xl p-6 md:p-8 border border-slate-100 shadow-sm animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-6 mb-10">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Daftar Pesanan & Deadline</h2>
          <p className="text-sm text-slate-400 font-medium mt-1">Pantau waktu pengiriman untuk ketepatan layanan.</p>
        </div>

        <div className="flex flex-col sm:flex-row gap-4 w-full xl:w-auto">
          <div className="relative flex-1 sm:w-64">
            <Search size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
            <input 
              type="text" 
              placeholder="Cari pesanan..."
              className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-100 rounded-2xl text-sm font-semibold outline-none focus:ring-2 focus:ring-amber-500/20 transition-all"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <button 
            onClick={() => setIsModalOpen(true)}
            className="bg-slate-900 text-white px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-3 hover:bg-slate-800 transition-all shadow-xl shadow-slate-200"
          >
            <Plus size={18} /> Input Pesanan
          </button>
        </div>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-left border-separate border-spacing-y-4">
          <thead>
            <tr className="text-slate-400 text-[10px] font-black uppercase tracking-widest px-4">
              <th className="pb-2 pl-6">ID & Pelanggan</th>
              <th className="pb-2">Waktu Pengiriman</th>
              <th className="pb-2">Items</th>
              <th className="pb-2">Status</th>
              <th className="pb-2 text-right pr-6">Aksi</th>
            </tr>
          </thead>
          <tbody>
            {filteredOrders.map((o) => {
              const deadline = getDeadlineStatus(o);
              const isAutoNew = o.id.length === 4 && o.status === 'Pending';

              return (
                <tr key={o.id} className={`group hover:bg-slate-50/50 transition-all ${deadline?.urgent ? 'bg-rose-50/20' : ''}`}>
                  <td className="py-6 pl-6 bg-white border-y border-l border-slate-50 rounded-l-[2rem] group-hover:bg-slate-50 transition-all">
                    <div className="flex items-center gap-4">
                      <div className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${deadline?.urgent ? 'bg-rose-500 text-white animate-pulse' : 'bg-slate-50 text-slate-400'}`}>
                        <ShoppingBag size={20} />
                      </div>
                      <div>
                        <div className="flex items-center gap-2">
                           <p className="font-black text-slate-900 text-sm tracking-tight">#{o.id}</p>
                           {isAutoNew && <span className="text-[8px] font-black text-emerald-600 bg-emerald-50 px-2 py-0.5 rounded-lg border border-emerald-100 uppercase">Baru</span>}
                        </div>
                        <p className="text-xs font-bold text-slate-500 mt-0.5">{o.customerName}</p>
                      </div>
                    </div>
                  </td>
                  <td className="py-6 bg-white border-y border-slate-50 group-hover:bg-slate-50 transition-all">
                    <div className="flex flex-col gap-2">
                      <div className="flex items-center gap-2 text-slate-800 font-black text-sm">
                        <Clock size={14} className="text-indigo-500" />
                        {o.deliveryTime || '--:--'}
                      </div>
                      {deadline && (
                        <div className={`flex items-center gap-1.5 px-3 py-1 rounded-lg border text-[9px] font-black uppercase tracking-wider w-fit ${deadline.color}`}>
                          <deadline.icon size={12} />
                          {deadline.label}
                        </div>
                      )}
                    </div>
                  </td>
                  <td className="py-6 bg-white border-y border-slate-50 group-hover:bg-slate-50 transition-all max-w-[200px]">
                    <p className="text-xs text-slate-500 font-bold truncate">{o.items.join(', ')}</p>
                    <p className="text-[10px] text-slate-400 font-medium mt-1">{o.date}</p>
                  </td>
                  <td className="py-6 bg-white border-y border-slate-50 group-hover:bg-slate-50 transition-all">
                    <div className="flex flex-col gap-2">
                       <span className={`text-[9px] font-black uppercase tracking-widest px-3 py-1 rounded-lg border w-fit ${getStatusBadge(o.status)}`}>
                        {o.status}
                      </span>
                      <span className={`text-[9px] font-bold px-3 py-1 rounded-lg border w-fit ${getPaymentBadge(o.paymentStatus)}`}>
                        {o.paymentStatus}
                      </span>
                    </div>
                  </td>
                  <td className="py-6 pr-6 bg-white border-y border-r border-slate-50 rounded-r-[2rem] text-right group-hover:bg-slate-50 transition-all">
                    <div className="flex flex-col items-end gap-2">
                      <p className="font-black text-slate-900 text-base leading-none">Rp {o.totalPrice.toLocaleString()}</p>
                      <button className="p-2.5 hover:bg-slate-100 rounded-xl text-slate-400 hover:text-slate-900 transition-all">
                        <MoreHorizontal size={18} />
                      </button>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => { setIsModalOpen(false); }}></div>
          <div className="bg-white rounded-[3rem] w-full max-w-lg overflow-hidden shadow-2xl relative z-10 animate-in zoom-in-95 duration-300">
            <div className="p-10 pb-4 flex justify-between items-center">
              <div>
                <h3 className="text-2xl font-black text-slate-900 tracking-tight">Input Pesanan Manual</h3>
                <p className="text-sm text-slate-400 font-medium mt-1">Lengkapi data untuk sistem alert pengiriman.</p>
              </div>
              <button onClick={() => { setIsModalOpen(false); }} className="p-3 hover:bg-slate-50 rounded-full text-slate-400 transition-all">
                <X size={20} />
              </button>
            </div>

            <div className="p-10 pt-4 space-y-6">
              <div className="space-y-4">
                <div>
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">Nama Pelanggan / Acara</label>
                  <div className="flex items-center bg-slate-50 border border-slate-100 rounded-2xl px-5 py-3.5 focus-within:ring-2 focus-within:ring-amber-500/20 transition-all">
                    <User size={18} className="text-slate-400 mr-3" />
                    <input 
                      type="text" 
                      placeholder="Contoh: PT Angkasa Pura - Makan Siang" 
                      className="bg-transparent border-none outline-none text-sm w-full font-bold text-slate-800"
                      value={newOrder.customerName}
                      onChange={(e) => setNewOrder({...newOrder, customerName: e.target.value})}
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">Jam Pengiriman</label>
                    <div className="flex items-center bg-slate-50 border border-slate-100 rounded-2xl px-5 py-3.5 transition-all">
                      <Clock size={16} className="text-slate-400 mr-3" />
                      <input 
                        type="time" 
                        className="bg-transparent border-none outline-none text-sm w-full font-black text-indigo-600"
                        value={newOrder.deliveryTime}
                        onChange={(e) => setNewOrder({...newOrder, deliveryTime: e.target.value})}
                      />
                    </div>
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">Tipe Layanan</label>
                    <select 
                      className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-3.5 text-sm font-black text-slate-800 outline-none focus:ring-2 focus:ring-amber-500/20"
                      value={newOrder.type}
                      onChange={(e) => setNewOrder({...newOrder, type: e.target.value as any})}
                    >
                      <option value="Individual">Individual</option>
                      <option value="Corporate">Corporate</option>
                      <option value="Wedding">Wedding</option>
                    </select>
                  </div>
                </div>

                <div>
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">Total Harga (Rp)</label>
                  <input 
                    type="number" 
                    placeholder="Contoh: 2500000" 
                    className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-3.5 text-sm font-black text-slate-900 outline-none focus:ring-2 focus:ring-amber-500/20"
                    value={newOrder.totalPrice || ''}
                    onChange={(e) => setNewOrder({...newOrder, totalPrice: Number(e.target.value)})}
                  />
                </div>

                <div>
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">Detail Menu (Koma sebagai pemisah)</label>
                  <textarea 
                    placeholder="Nasi Box Premium (50), Snack Box A (50)..." 
                    rows={3}
                    className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-4 text-sm font-bold text-slate-700 outline-none focus:ring-2 focus:ring-amber-500/20 transition-all resize-none"
                    value={newOrder.items?.join(', ')}
                    onChange={(e) => setNewOrder({...newOrder, items: e.target.value.split(',').map(i => i.trim())})}
                  ></textarea>
                </div>
              </div>

              <button 
                onClick={handleSaveOrder}
                className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-3 hover:bg-emerald-600 transition-all shadow-2xl shadow-slate-200"
              >
                <Check size={20} />
                Simpan & Aktifkan Alarm
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

