import React, { useState, useRef } from 'react';
import { Plus, Sparkles, Trash2, Loader2, X, Image as ImageIcon, Save, CheckCircle, Upload, Share2, Copy, QrCode, ExternalLink, Check, Tag, AlertCircle } from 'lucide-react';
import { MenuItem } from '../types';
import { optimizeMenuDescription } from '../services/geminiService';

interface MenuManagerProps {
  menu: MenuItem[];
  onUpdateMenu: (menu: MenuItem[]) => void;
  categories: string[];
  onUpdateCategories: (categories: string[]) => void;
  onNotify?: (message: string, type: 'success' | 'error' | 'warning') => void;
}

const MenuManager: React.FC<MenuManagerProps> = ({ menu, onUpdateMenu, categories, onUpdateCategories, onNotify }) => {
  const [optimizingId, setOptimizingId] = useState<string | null>(null);
  const [successId, setSuccessId] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isShareModalOpen, setIsShareModalOpen] = useState(false);
  const [isCatModalOpen, setIsCatModalOpen] = useState(false);
  const [newCatName, setNewCatName] = useState('');
  const [copySuccess, setCopySuccess] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<MenuItem>>({
    name: '',
    category: categories[0] || '',
    price: 0,
    cost: 0,
    description: '',
    imageUrl: ''
  });

  const handleCopyLink = () => {
    setCopySuccess(true);
    onNotify?.('Link katalog disalin ke clipboard!', 'success');
    setTimeout(() => setCopySuccess(false), 2000);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData({ ...formData, imageUrl: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAIUIOptimize = async (item: MenuItem) => {
    setOptimizingId(item.id);
    onNotify?.('AI sedang merangkai kata-kata elegan...', 'warning');
    try {
      const newDesc = await optimizeMenuDescription(item.name, item.description);
      if (newDesc) {
        const updatedMenu = menu.map(m => 
          m.id === item.id ? { ...m, description: newDesc.trim() } : m
        );
        onUpdateMenu(updatedMenu);
        setSuccessId(item.id);
        onNotify?.('Deskripsi menu berhasil ditingkatkan!', 'success');
        setTimeout(() => setSuccessId(null), 3000);
      }
    } catch (error) {
      console.error("Optimization failed", error);
      onNotify?.('Gagal mengoptimasi deskripsi.', 'error');
    } finally {
      setOptimizingId(null);
    }
  };

  const handleSaveNewItem = () => {
    if (!formData.name?.trim()) return onNotify?.('Nama hidangan wajib diisi!', 'error');
    if (!formData.price || formData.price <= 0) return onNotify?.('Harga jual harus lebih dari 0!', 'error');
    if (!formData.description?.trim()) return onNotify?.('Deskripsi menu wajib diisi!', 'error');
    if (!formData.imageUrl) return onNotify?.('Pilih foto hidangan agar menu lebih menarik!', 'error');

    const newItem: MenuItem = {
      id: Math.random().toString(36).substr(2, 9),
      name: formData.name || 'Menu Baru',
      category: formData.category || categories[0] || 'Uncategorized',
      price: Number(formData.price) || 0,
      cost: Number(formData.cost) || 0,
      description: formData.description || '',
      salesCount: 0,
      imageUrl: formData.imageUrl || ''
    };

    onUpdateMenu([...menu, newItem]);
    setIsModalOpen(false);
    onNotify?.(`${newItem.name} telah ditambahkan ke katalog.`, 'success');
    setFormData({ name: '', category: categories[0], price: 0, cost: 0, description: '', imageUrl: '' });
  };

  const handleAddCategory = () => {
    if (newCatName && !categories.includes(newCatName)) {
