                      </div>
                    ))}
                    {(!formData.recipe || formData.recipe.length === 0) && (
                      <div className="py-8 text-center text-white/20 italic text-xs">Isian box belum ditentukan.</div>
                    )}
                  </div>
                </div>

                <button 
                  onClick={handleSaveNewItem}
                  className="w-full bg-slate-900 text-white py-5 rounded-[2rem] font-black text-xs uppercase tracking-widest flex items-center justify-center gap-3 hover:bg-emerald-600 transition-all shadow-2xl shadow-slate-200"
                >
                  <Save size={20} /> Simpan Katalog Menu
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

