export const analyzeStockFromText = async (text: string): Promise<AnalysisResult & { mrpStatus: string }> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Laporan Stok: ${text}`,
    config: {
      systemInstruction: "Anda adalah asisten MRP katering. Analisis teks laporan stok yang diberikan. Identifikasi satu bahan utama yang paling krusial dari teks tersebut. Berikan output dalam format JSON dengan key: status (nama bahan), freshnessScore (0-100), diagnosis, estimatedQuantity, recommendations (array of strings), mrpStatus ('Aman', 'Menipis', atau 'Habis').",
      responseMimeType: "application/json",
    },
  });

  return JSON.parse(response.text || "{}");
};

export const analyzeKitchenStock = async (base64Data: string): Promise<AnalysisResult> => {
  const ai = getAI();
  const imagePart = {
    inlineData: {
      mimeType: 'image/jpeg',
      data: base64Data.split(',')[1],
    },
  };

  const prompt = "Analisis stok dapur ini. Identifikasi nama bahan, estimasi jumlah, dan klasifikasikan status stok secara ketat ke salah satu dari: 'Aman', 'Menipis', atau 'Habis' berdasarkan apa yang terlihat. Berikan output dalam format JSON valid dengan key: status (nama bahan), freshnessScore (0-100), diagnosis, estimatedQuantity, recommendations (array of strings), mrpStatus ('Aman', 'Menipis', atau 'Habis').";

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: { parts: [imagePart, { text: prompt }] },
  });

  const cleanJson = (response.text || "{}").replace(/```json/g, '').replace(/```/g, '').trim();
  return JSON.parse(cleanJson || "{}");
};

import React, { useState, useRef } from 'react';
import { Plus, Sparkles, Trash2, Loader2, X, Image as ImageIcon, Save, CheckCircle, Upload, Share2, Copy, QrCode, ExternalLink, Check, Tag, AlertCircle, ListPlus, Box, BrainCircuit, Target, TrendingUp, Lightbulb } from 'lucide-react';
import { MenuItem, MenuRecipe, IngredientStock } from '../types';
import { optimizeMenuDescription, analyzeMenuAppeal } from '../services/geminiService';

interface MenuManagerProps {
  menu: MenuItem[];
  onUpdateMenu: (menu: MenuItem[]) => void;
  categories: string[];
  onUpdateCategories: (categories: string[]) => void;
  inventory: IngredientStock[];
  onNotify?: (message: string, type: 'success' | 'error' | 'warning') => void;
}

const MenuManager: React.FC<MenuManagerProps> = ({ menu, onUpdateMenu, categories, onUpdateCategories, inventory, onNotify }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [analyzingId, setAnalyzingId] = useState<string | null>(null);
  const [aiInsights, setAiInsights] = useState<{ [key: string]: any }>({});

  const [formData, setFormData] = useState<Partial<MenuItem>>({
    name: '',
    category: categories[0] || '',
    price: 0,
    cost: 0,
    description: '',
    imageUrl: '',
    recipe: []
  });

  const [newIngredient, setNewIngredient] = useState<Partial<MenuRecipe>>({
    ingredientId: '',
    amountPerUnit: 0,
    unit: ''
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleAnalyzeAppeal = async (item: MenuItem) => {
    setAnalyzingId(item.id);
    onNotify?.('AI sedang mempelajari profil menu Anda...', 'warning');
    try {
      const insight = await analyzeMenuAppeal(item);
      setAiInsights(prev => ({ ...prev, [item.id]: insight }));
      onNotify?.('Wawasan pasar AI berhasil dihasilkan!', 'success');
    } catch (error) {
      console.error(error);
      onNotify?.('Gagal menganalisis menu.', 'error');
    } finally {
      setAnalyzingId(null);
    }
  };

  const handleAddIngredientToRecipe = () => {
    if (!newIngredient.ingredientId || !newIngredient.amountPerUnit) return;
    const invItem = inventory.find(i => i.id === newIngredient.ingredientId);
    if (!invItem) return;

    const recipeItem: MenuRecipe = {
      ingredientId: invItem.id,
      name: invItem.name,
      amountPerUnit: Number(newIngredient.amountPerUnit),
      unit: invItem.unit
    };

    setFormData({
      ...formData,
      recipe: [...(formData.recipe || []), recipeItem]
    });
    setNewIngredient({ ingredientId: '', amountPerUnit: 0, unit: '' });
  };

  const handleRemoveRecipeItem = (idx: number) => {
    setFormData({
      ...formData,
      recipe: formData.recipe?.filter((_, i) => i !== idx)
    });
  };

  const handleSaveNewItem = () => {
    if (!formData.name?.trim()) return onNotify?.('Nama hidangan wajib diisi!', 'error');
    if (!formData.price || formData.price <= 0) return onNotify?.('Harga jual harus lebih dari 0!', 'error');

    const newItem: MenuItem = {
      id: Math.random().toString(36).substr(2, 9),
      name: formData.name || 'Menu Baru',
      category: formData.category || categories[0] || 'Uncategorized',
      price: Number(formData.price) || 0,
      cost: Number(formData.cost) || 0,
