                <p className="text-[11px] text-slate-400 font-medium leading-[1.6] mb-8 line-clamp-2">{item.description}</p>

                <div className="mt-auto pt-6 border-t border-slate-50 flex items-center justify-between">
                  <div className="flex flex-col">
                    <span className="text-[9px] font-black text-slate-300 uppercase tracking-widest mb-1">Estimasi Harga</span>
                    <span className="text-xl font-black text-slate-900 tracking-tight">Rp {item.price.toLocaleString()}</span>
                  </div>
                  <button onClick={(e) => addToCart(item.id, e)} className="w-12 h-12 bg-slate-50 text-slate-900 rounded-2xl flex items-center justify-center hover:bg-emerald-600 hover:text-white transition-all">
                    <Plus size={20} />
