import React, { useState, useRef } from 'react';
import { Plus, Sparkles, Trash2, Loader2, X, Image as ImageIcon, Save, CheckCircle, Upload, Share2, Copy, QrCode, ExternalLink, Check, Tag, AlertCircle, ListPlus, Box, BrainCircuit, Target, TrendingUp, Lightbulb } from 'lucide-react';
import { MenuItem, MenuRecipe, IngredientStock } from '../types';
import { optimizeMenuDescription, analyzeMenuAppeal } from '../services/geminiService';

interface MenuManagerProps {
  menu: MenuItem[];
  onUpdateMenu: (menu: MenuItem[]) => void;
  categories: string[];
  onUpdateCategories: (categories: string[]) => void;
  inventory: IngredientStock[];
  onNotify?: (message: string, type: 'success' | 'error' | 'warning') => void;
}

const MenuManager: React.FC<MenuManagerProps> = ({ menu, onUpdateMenu, categories, onUpdateCategories, inventory, onNotify }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [analyzingInModal, setAnalyzingInModal] = useState(false);
  const [modalAiInsight, setModalAiInsight] = useState<any>(null);

  const [formData, setFormData] = useState<Partial<MenuItem>>({
    name: '',
    category: categories[0] || '',
    price: 0,
    cost: 0,
    description: '',
    imageUrl: '',
    recipe: []
  });

  const [newIngredient, setNewIngredient] = useState<Partial<MenuRecipe>>({
    ingredientId: '',
    amountPerUnit: 0,
    unit: ''
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleAnalyzeInModal = async () => {
    if (!formData.name || !formData.description) {
      return onNotify?.('Lengkapi Nama dan Deskripsi sebelum menganalisis!', 'warning');
    }
    setAnalyzingInModal(true);
    setModalAiInsight(null);
    try {
      const insight = await analyzeMenuAppeal(formData as MenuItem);
      setModalAiInsight(insight);
      onNotify?.('Strategi pemasaran AI telah dirangkai!', 'success');
    } catch (error) {
      onNotify?.('Gagal mendapatkan insight AI.', 'error');
    } finally {
      setAnalyzingInModal(false);
    }
  };

  const handleAddIngredientToRecipe = () => {
    if (!newIngredient.ingredientId || !newIngredient.amountPerUnit) return;
    const invItem = inventory.find(i => i.id === newIngredient.ingredientId);
    if (!invItem) return;

    const recipeItem: MenuRecipe = {
      ingredientId: invItem.id,
      name: invItem.name,
      amountPerUnit: Number(newIngredient.amountPerUnit),
      unit: invItem.unit
    };

    setFormData({
      ...formData,
      recipe: [...(formData.recipe || []), recipeItem]
    });
    setNewIngredient({ ingredientId: '', amountPerUnit: 0, unit: '' });
  };

  const handleRemoveRecipeItem = (idx: number) => {
    setFormData({
      ...formData,
      recipe: formData.recipe?.filter((_, i) => i !== idx)
    });
  };

  const handleSaveNewItem = () => {
    if (!formData.name?.trim()) return onNotify?.('Nama hidangan wajib diisi!', 'error');
    if (!formData.price || formData.price <= 0) return onNotify?.('Harga jual harus lebih dari 0!', 'error');

    const newItem: MenuItem = {
      id: Math.random().toString(36).substr(2, 9),
      name: formData.name || 'Menu Baru',
      category: formData.category || categories[0] || 'Uncategorized',
      price: Number(formData.price) || 0,
      cost: Number(formData.cost) || 0,
      description: formData.description || '',
      salesCount: 0,
      imageUrl: formData.imageUrl || 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&q=80&w=400',
      recipe: formData.recipe || []
    };

    onUpdateMenu([...menu, newItem]);
    setIsModalOpen(false);
    onNotify?.(`${newItem.name} berhasil disimpan.`, 'success');
    setFormData({ name: '', category: categories[0], price: 0, cost: 0, description: '', imageUrl: '', recipe: [] });
    setModalAiInsight(null);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setFormData({ ...formData, imageUrl: reader.result as string });
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
