        </div>
        <button 
          onClick={() => {
            setModalAiInsight(null);
            setIsModalOpen(true);
          }}
          className="bg-slate-900 hover:bg-slate-800 text-white px-8 py-3 rounded-2xl flex items-center justify-center gap-2 transition-all shadow-xl shadow-slate-200 font-black text-[10px] uppercase tracking-widest"
        >
