import React, { useState, useMemo } from 'react';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell, BarChart, Bar
} from 'recharts';
import { 
  TrendingUp, ArrowUpRight, ArrowDownRight, 
  DollarSign, ShoppingBag, PieChart as PieChartIcon,
  FileSpreadsheet, FileText, Calendar, Activity,
  Target, Wallet, CreditCard, ShieldCheck, AlertCircle,
  Zap, ArrowRight, BarChart3, Download, Sun, Moon, Clock, RefreshCcw,
  CalendarDays, CalendarRange, Layers, Calculator, Receipt, FileDown, MoreHorizontal, Filter, Search, X
} from 'lucide-react';
import { Order, MenuItem, ShiftType } from '../types';

interface SalesReportProps {
  orders: Order[];
  menu: MenuItem[];
}

const CustomTooltip = ({ active, payload, label }: any) => {
  if (active && payload && payload.length) {
    return (
      <div className="bg-white/90 backdrop-blur-md p-4 rounded-2xl shadow-2xl border border-slate-100 animate-in zoom-in-95 duration-200">
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{label}</p>
        <p className="text-sm font-black text-indigo-600">
          Rp {payload[0].value.toLocaleString()}
        </p>
        <div className="mt-2 pt-2 border-t border-slate-50">
          <p className="text-[9px] font-bold text-slate-400">Total Pendapatan Bersih</p>
        </div>
      </div>
    );
  }
  return null;
};

const SalesReport: React.FC<SalesReportProps> = ({ orders, menu }) => {
  const [activeTab, setActiveTab] = useState<'ikhtisar' | 'harian' | 'mingguan' | 'bulanan' | 'tahunan' | 'sift'>('ikhtisar');
  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');

  const getWeekNumber = (d: Date) => {
    d = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
    d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7));
    const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
    return Math.ceil((((d.getTime() - yearStart.getTime()) / 86400000) + 1) / 7);
  };

  // Filter orders based on date range before processing
  const filteredOrdersByDate = useMemo(() => {
    return orders.filter(o => {
      if (!startDate && !endDate) return true;
      const orderDate = new Date(o.date);
      const start = startDate ? new Date(startDate) : new Date('2000-01-01');
      const end = endDate ? new Date(endDate) : new Date('2100-01-01');
      // Set hours to include the whole day
      end.setHours(23, 59, 59, 999);
      return orderDate >= start && orderDate <= end;
    });
  }, [orders, startDate, endDate]);

  const reports = useMemo(() => {
    const daily: any[] = [];
    const weekly: any[] = [];
    const monthly: any[] = [];
    const yearly: any[] = [];

    filteredOrdersByDate.forEach(o => {
      const d = new Date(o.date);
      const dayKey = o.date;
      const weekKey = `Minggu ${getWeekNumber(d)}, ${d.getFullYear()}`;
      const monthKey = d.toLocaleString('id-ID', { month: 'long', year: 'numeric' });
      const yearKey = `${d.getFullYear()}`;

      const processEntry = (arr: any[], key: string, label: string) => {
        let entry = arr.find(x => x.key === key);
        if (!entry) {
          entry = { key, label, revenue: 0, paid: 0, receivables: 0, count: 0, cost: 0 };
          arr.push(entry);
        }
        entry.revenue += o.totalPrice;
        entry.paid += o.amountPaid;
        entry.receivables += (o.totalPrice - o.amountPaid);
        entry.count += 1;
        entry.cost += o.totalPrice * 0.4;
      };

      processEntry(daily, dayKey, dayKey);
      processEntry(weekly, weekKey, weekKey);
      processEntry(monthly, monthKey, monthKey);
      processEntry(yearly, yearKey, yearKey);
    });

    return {
      daily: daily.sort((a, b) => b.key.localeCompare(a.key)),
      weekly: weekly, 
      monthly: monthly,
      yearly: yearly
    };
  }, [filteredOrdersByDate]);

  const stats = useMemo(() => {
    const totalRevenue = filteredOrdersByDate.reduce((acc, o) => acc + o.totalPrice, 0);
    const totalPaid = filteredOrdersByDate.reduce((acc, o) => acc + o.amountPaid, 0);
    const totalReceivables = totalRevenue - totalPaid;
    const totalCost = totalRevenue * 0.4;
    const grossProfit = totalRevenue - totalCost;
    const collectionRate = totalRevenue > 0 ? (totalPaid / totalRevenue) * 100 : 0;

    return { totalRevenue, totalReceivables, grossProfit, totalCost, collectionRate, totalPaid };
  }, [filteredOrdersByDate]);

  const downloadCSV = (content: string, filename: string) => {
    const blob = new Blob([content], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", filename);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleExportFull = () => {
    let csvContent = "LAPORAN AUDIT FINANSIAL LENGKAP - CATERELITE\n";
    csvContent += `Rentang Filter: ${startDate || 'Awal'} s/d ${endDate || 'Sekarang'}\n`;
    csvContent += `Dibuat: ${new Date().toLocaleString('id-ID')}\n\n`;

    csvContent += "RINGKASAN EKSEKUTIF\n";
    csvContent += `Total Omzet;Rp ${stats.totalRevenue.toLocaleString()}\n`;
    csvContent += `Total Pengeluaran;Rp ${stats.totalCost.toLocaleString()}\n`;
    csvContent += `Total Kas Masuk;Rp ${stats.totalPaid.toLocaleString()}\n`;
    csvContent += `Total Piutang;Rp ${stats.totalReceivables.toLocaleString()}\n`;
    csvContent += `Estimasi Laba;Rp ${stats.grossProfit.toLocaleString()}\n\n`;

    const addSection = (title: string, data: any[]) => {
      csvContent += `${title}\n`;
      csvContent += "Periode;Pesanan;Pendapatan;Pengeluaran;Terbayar;Piutang;Laba\n";
      data.forEach(d => {
        csvContent += `${d.label};${d.count};${d.revenue};${d.cost};${d.paid};${d.receivables};${d.revenue - d.cost}\n`;
      });
      csvContent += "\n";
    };

    addSection("LAPORAN HARIAN", reports.daily);
    addSection("LAPORAN MINGGUAN", reports.weekly);
    addSection("LAPORAN BULANAN", reports.monthly);
    addSection("LAPORAN TAHUNAN", reports.yearly);

    downloadCSV(csvContent, `CaterElite_Audit_Lengkap_${new Date().getTime()}.csv`);
  };

  const handleExportCurrentTab = () => {
    if (activeTab === 'ikhtisar' || activeTab === 'sift') return;

    const data = activeTab === 'harian' ? reports.daily : 
                 activeTab === 'mingguan' ? reports.weekly : 
                 activeTab === 'bulanan' ? reports.monthly : reports.yearly;

    let csvContent = `LAPORAN ${activeTab.toUpperCase()} - CATERELITE\n`;
    csvContent += `Rentang Filter: ${startDate || 'Awal'} s/d ${endDate || 'Sekarang'}\n`;
    csvContent += `Periode Export: ${new Date().toLocaleString('id-ID')}\n\n`;
    csvContent += "Periode;Pesanan;Pendapatan;Pengeluaran;Terbayar;Piutang;Laba\n";

    data.forEach(d => {
      csvContent += `${d.label};${d.count};${d.revenue};${d.cost};${d.paid};${d.receivables};${d.revenue - d.cost}\n`;
