    csvContent += `Estimasi Laba;Rp ${(item.revenue - item.cost).toLocaleString()}\n\n`;

    // Ambil data transaksi mentah yang masuk dalam periode ini dari filtered list
    const filteredOrders = filteredOrdersByDate.filter(o => {
      const d = new Date(o.date);
      if (activeTab === 'harian') return o.date === item.key;
      if (activeTab === 'mingguan') return `Minggu ${getWeekNumber(d)}, ${d.getFullYear()}` === item.key;
      if (activeTab === 'bulanan') return d.toLocaleString('id-ID', { month: 'long', year: 'numeric' }) === item.key;
      if (activeTab === 'tahunan') return `${d.getFullYear()}` === item.key;
      return false;
