      csvContent += "ID;Tanggal;Pelanggan;Items;Total;Terbayar;Sisa;Status;Payment\n";
      filteredOrders.forEach(o => {
        csvContent += `${o.id};${o.date};${o.customerName};${o.items.join(' | ')};${o.totalPrice};${o.amountPaid};${o.totalPrice - o.amountPaid};${o.status};${o.paymentStatus}\n`;
      });
    }

    downloadCSV(csvContent, `Audit_${item.label.replace(/\s+/g, '_')}.csv`);
  };

  const TableView = ({ data, title, desc, icon: Icon }: { data: any[], title: string, desc: string, icon: any }) => (
    <div className="bg-white rounded-[3rem] p-10 border border-slate-100 shadow-sm animate-in fade-in slide-in-from-bottom-4">
