      )}

      {activeTab === 'harian' && (
        <TableView 
          data={reports.daily} 
          title="Buku Kas Harian" 
          desc="Rekapitulasi performa finansial harian secara kronologis."
          icon={Calendar} 
        />
      )}
      {activeTab === 'mingguan' && (
        <TableView 
          data={reports.weekly} 
          title="Performa Mingguan" 
          desc="Analisis pendapatan, pengeluaran, dan laba bersih per minggu."
          icon={CalendarRange} 
        />
      )}
      {activeTab === 'bulanan' && (
        <TableView 
          data={reports.monthly} 
          title="Laporan Bulanan" 
          desc="Tinjauan finansial bulanan untuk evaluasi strategis."
          icon={CalendarDays} 
        />
      )}
      {activeTab === 'tahunan' && (
        <TableView 
          data={reports.yearly} 
          title="Tinjauan Tahunan" 
          desc="Rekapitulasi performa bisnis sepanjang tahun."
          icon={Layers} 
        />
      )}

      {activeTab === 'sift' && (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          <div className="lg:col-span-7 bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm">
            <div className="flex items-center justify-between mb-10">
              <div>
                <h3 className="text-2xl font-black text-slate-900 tracking-tight">Performa Sift</h3>
                <p className="text-sm text-slate-400 font-medium mt-1">Kontribusi pendapatan per jadwal petugas.</p>
