                </BarChart>
              </ResponsiveContainer>
            </div>

            <div className="space-y-4">
              {shiftData.map(s => (
                <div key={s.name} className="flex items-center justify-between p-5 bg-slate-50 rounded-2xl border border-slate-100">
                  <div className="flex items-center gap-4">
                    <div className="w-10 h-10 rounded-xl flex items-center justify-center text-white shadow-sm" style={{backgroundColor: s.color}}>
                      {s.name === 'Pagi' ? <Sun size={20} /> : s.name === 'Siang' ? <Clock size={20} /> : <Moon size={20} />}
                    </div>
                    <span className="text-sm font-black text-slate-800">Sift {s.name}</span>
                  </div>
                  <span className="text-lg font-black text-slate-900">Rp {s.revenue.toLocaleString()}</span>
                </div>
              ))}
            </div>
          </div>

          <div className="lg:col-span-5 bg-slate-900 rounded-[3rem] p-10 text-white shadow-2xl relative overflow-hidden">
            <div className="relative z-10">
