              <p className="text-sm text-slate-400 font-medium mb-10">Valuasi kas untuk serah terima operasional.</p>

              <div className="space-y-6 mb-12">
                <div className="flex justify-between items-center pb-4 border-b border-white/10">
                  <span className="text-xs text-slate-500 font-bold uppercase tracking-widest">Petugas Aktif</span>
                  <span className="text-xs font-black">Admin Sift</span>
                </div>
                <div className="flex justify-between items-center pb-4 border-b border-white/10">
                  <span className="text-xs text-slate-500 font-bold uppercase tracking-widest">Waktu Cetak</span>
                  <span className="text-xs font-black">{new Date().toLocaleTimeString('id-ID')} WIB</span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-xs text-slate-500 font-bold uppercase tracking-widest">Estimasi Kas Diterima</span>
                  <span className="text-2xl font-black text-emerald-400">Rp {(stats.totalPaid * 0.3).toLocaleString()}</span>
                </div>
              </div>

              <button className="w-full py-5 bg-white text-slate-900 rounded-[1.8rem] font-black text-[10px] uppercase tracking-[0.2em] flex items-center justify-center gap-4 hover:bg-emerald-400 transition-all shadow-xl shadow-slate-950">
                <RefreshCcw size={18} /> Cetak Ringkasan Serah Terima
              </button>
            </div>
            <div className="absolute -bottom-10 -right-10 opacity-10">
               <ShieldCheck size={200} />
