  const [notifications, setNotifications] = useState<Notification[]>([]);

  // Sound Engine
  const playAlertSound = useCallback((type: NotificationType) => {
    try {
      const context = new (window.AudioContext || (window as any).webkitAudioContext)();
      const oscillator = context.createOscillator();
      const gainNode = context.createGain();
      oscillator.connect(gainNode);
      gainNode.connect(context.destination);
      if (type === 'error') {
        oscillator.type = 'sawtooth';
        oscillator.frequency.setValueAtTime(150, context.currentTime);
        oscillator.frequency.exponentialRampToValueAtTime(50, context.currentTime + 0.3);
        gainNode.gain.setValueAtTime(0.1, context.currentTime);
      } else if (type === 'warning') {
        oscillator.type = 'sine';
        oscillator.frequency.setValueAtTime(440, context.currentTime);
        oscillator.frequency.exponentialRampToValueAtTime(880, context.currentTime + 0.1);
        gainNode.gain.setValueAtTime(0.1, context.currentTime);
      } else {
        oscillator.type = 'sine';
        oscillator.frequency.setValueAtTime(880, context.currentTime);
        oscillator.frequency.exponentialRampToValueAtTime(1200, context.currentTime + 0.1);
        gainNode.gain.setValueAtTime(0.05, context.currentTime);
      }
      oscillator.start();
      oscillator.stop(context.currentTime + 0.3);
    } catch (e) { console.warn("Audio Context blocked"); }
  }, []);

  const addNotification = useCallback((message: string, type: NotificationType) => {
    const id = Math.random().toString(36).substr(2, 9);
    setNotifications(prev => [{ id, message, type }, ...prev]);
    playAlertSound(type);
    setTimeout(() => setNotifications(prev => prev.filter(n => n.id !== id)), 5000);
  }, [playAlertSound]);

  // AUTO DEDUCTION LOGIC
  const deduceStockFromOrder = useCallback((order: Order) => {
    let inventoryCopy = [...inventory];
    let insufficientItems: string[] = [];

    order.items.forEach(orderItemStr => {
      // Extract name and quantity from "Menu Name (Quantity)"
      const match = orderItemStr.match(/(.*)\s\((\d+)\)/);
      if (!match) return;
      const [_, itemName, qtyStr] = match;
      const quantity = parseInt(qtyStr);

      const menuItem = menu.find(m => m.name === itemName.trim());
      if (menuItem?.recipe) {
        menuItem.recipe.forEach(ingredient => {
          const invItemIdx = inventoryCopy.findIndex(inv => inv.id === ingredient.ingredientId);
          if (invItemIdx > -1) {
            const totalNeeded = ingredient.amountPerUnit * quantity;
            if (inventoryCopy[invItemIdx].quantity < totalNeeded) {
              insufficientItems.push(`${inventoryCopy[invItemIdx].name} (Butuh ${totalNeeded}${ingredient.unit})`);
            } else {
              inventoryCopy[invItemIdx].quantity -= totalNeeded;
              // Auto update status
              const q = inventoryCopy[invItemIdx].quantity;
              if (q <= 0) inventoryCopy[invItemIdx].status = 'Habis';
              else if (q < 10) inventoryCopy[invItemIdx].status = 'Menipis';
            }
          }
        });
      }
    });

    if (insufficientItems.length > 0) {
      addNotification(`Gagal Konfirmasi! Stok tidak cukup: ${insufficientItems.join(', ')}`, 'error');
      return false;
    }

    setInventory(inventoryCopy);
    addNotification(`Stok inventori telah dipotong otomatis untuk Pesanan #${order.id}`, 'success');
    return true;
  }, [inventory, menu, addNotification]);

  const handleUpdateOrder = (orderId: string, updates: Partial<Order>) => {
    const targetOrder = orders.find(o => o.id === orderId);
    if (!targetOrder) return;

    // Trigger deduction when confirmed
    if (updates.status === 'Confirmed' && targetOrder.status !== 'Confirmed') {
      const success = deduceStockFromOrder(targetOrder);
      if (!success) return; // Prevent status update if stock fails
    }

    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, ...updates } : o));
    if (updates.status === 'Delivered') addNotification(`Pesanan #${orderId} berhasil dikirim!`, 'success');
