          <div className="flex items-center gap-3">
            <div className="p-2.5 bg-slate-50 rounded-xl border border-slate-100">
              <Store size={20} className="text-slate-600" />
            </div>
            <h3 className="font-black text-slate-800 uppercase tracking-widest text-[10px]">Identitas Bisnis Utama</h3>
          </div>

          <div className="flex flex-col md:flex-row gap-10">
            <div className="relative group shrink-0">
              <div className="w-32 h-32 rounded-[2.5rem] bg-slate-50 border-4 border-white shadow-xl overflow-hidden flex items-center justify-center">
                {localSettings.logoUrl ? (
                  <img src={localSettings.logoUrl} alt="Logo Preview" className="w-full h-full object-cover" />
                ) : (
                  <Store size={40} className="text-slate-200" />
                )}
              </div>
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="absolute inset-0 bg-black/40 text-white flex items-center justify-center opacity-0 group-hover:opacity-100 rounded-[2.5rem] transition-all font-black text-[8px] uppercase tracking-widest"
              >
                Ganti Logo
              </button>
              <input type="file" ref={fileInputRef} onChange={handleLogoUpload} className="hidden" accept="image/*" />
            </div>

            <div className="flex-1 space-y-5">
              <div>
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">Nama Katering</label>
                <input 
                  type="text" 
                  className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-3.5 text-sm font-bold outline-none focus:ring-2 focus:ring-emerald-500/20"
                  value={localSettings.storeName}
                  onChange={(e) => setLocalSettings({...localSettings, storeName: e.target.value})}
                />
              </div>
              <div>
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">WhatsApp Utama (MRP Alerts)</label>
                <div className="relative">
                   <span className="absolute left-5 top-1/2 -translate-y-1/2 text-sm font-black text-slate-400">+</span>
                   <input 
                    type="text" 
                    className="w-full pl-9 pr-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl text-sm font-black text-slate-800 outline-none"
                    value={localSettings.whatsappNumber}
                    onChange={(e) => setLocalSettings({...localSettings, whatsappNumber: e.target.value.replace(/\D/g, '')})}
                  />
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Multi-Account Manager */}
        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-8">
          <div className="flex items-center gap-3">
            <div className="p-2.5 bg-indigo-50 rounded-xl border border-indigo-100">
              <Link2 size={20} className="text-indigo-600" />
            </div>
            <h3 className="font-black text-slate-800 uppercase tracking-widest text-[10px]">Manajemen Multi-Akun Sosial</h3>
          </div>

          {/* Form Tambah Akun */}
          <div className="p-6 bg-slate-50 rounded-3xl border border-slate-100">
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-4">Daftarkan Akun Baru</p>
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
              <select 
                className="bg-white border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none"
                value={newAccount.platform}
                onChange={(e) => setNewAccount({...newAccount, platform: e.target.value as any})}
              >
                <option value="Instagram">Instagram</option>
                <option value="TikTok">TikTok</option>
                <option value="Facebook">Facebook</option>
              </select>
              <input 
                type="text" 
                placeholder="Username / Handle"
                className="bg-white border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none md:col-span-1"
                value={newAccount.handle}
                onChange={(e) => setNewAccount({...newAccount, handle: e.target.value})}
              />
              <input 
                type="text" 
                placeholder="Nama Label (Opsional)"
                className="bg-white border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none md:col-span-1"
                value={newAccount.name}
                onChange={(e) => setNewAccount({...newAccount, name: e.target.value})}
              />
              <button 
                onClick={handleAddAccount}
                className="bg-slate-900 text-white rounded-xl px-4 py-3 text-[10px] font-black uppercase tracking-widest hover:bg-emerald-600 transition-all flex items-center justify-center gap-2"
              >
                <Plus size={16} /> Tambah Akun
              </button>
            </div>
          </div>

          {/* Daftar Akun Terkoneksi */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            {(localSettings.socialAccounts || []).map((account) => (
              <div key={account.id} className="p-5 bg-white border border-slate-100 rounded-2xl flex items-center justify-between group hover:border-emerald-200 transition-all shadow-sm">
                <div className="flex items-center gap-4 overflow-hidden">
                  <div className="w-10 h-10 bg-slate-50 rounded-xl flex items-center justify-center shrink-0">
                    {getPlatformIcon(account.platform)}
                  </div>
                  <div className="overflow-hidden">
                    <p className="text-xs font-black text-slate-900 truncate">{account.displayName}</p>
                    <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest truncate">@{account.handle}</p>
                  </div>
                </div>
                <button 
                  onClick={() => handleRemoveAccount(account.id)}
                  className="p-2 text-slate-300 hover:text-rose-500 transition-colors"
                >
                  <Trash2 size={16} />
                </button>
              </div>
            ))}
            {(!localSettings.socialAccounts || localSettings.socialAccounts.length === 0) && (
              <div className="col-span-full py-12 text-center bg-slate-50/50 rounded-[2rem] border-2 border-dashed border-slate-100">
                <Link2 size={32} className="mx-auto text-slate-200 mb-3" />
                <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Belum ada akun sosial terkoneksi</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

