              <div className="w-9 h-9 rounded-full bg-slate-100 border-2 border-white shadow-sm overflow-hidden">
                <img src={currentUser.avatarUrl || "https://picsum.photos/100/100"} alt="Profile" className="w-full h-full object-cover" />
              </div>
              <div className="hidden sm:block text-left">
                <p className="text-[10px] font-black text-slate-800 leading-none mb-1 uppercase tracking-tight">{currentUser.name}</p>
                <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">{currentUser.role}</p>
              </div>
            </div>
            {isProfileDropdownOpen && (
              <div className="absolute top-full right-0 mt-2 bg-white border border-slate-100 rounded-[2rem] shadow-2xl p-4 w-56 animate-in fade-in slide-in-from-top-4 z-[60]">
                <button onClick={handleLogout} className="w-full flex items-center gap-3 px-3 py-3 text-[10px] font-black uppercase tracking-widest text-rose-500 hover:bg-rose-50 rounded-xl transition-all">
                  <LogOut size={16} /> Logout Sesi
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      <Sidebar isOpen={isSidebarOpen} setIsOpen={setIsSidebarOpen} activeTab={activeTab} setActiveTab={setActiveTab} onPreviewMenu={() => setViewMode('customer')} logoUrl={settings.logoUrl} onOpenSettings={() => isSuperAdmin && setIsSettingsOpen(true)} role={currentUser.role} />

      <main className="flex-1 overflow-y-auto px-4 py-6 md:px-8 md:py-8 pb-32">
        <div className="max-w-6xl mx-auto space-y-6">
          {activeTab === 'dashboard' && <Dashboard orders={orders} menu={menu} />}
          {activeTab === 'menu' && <MenuManager menu={menu} onUpdateMenu={setMenu} categories={categories} onUpdateCategories={setCategories} inventory={inventory} onNotify={addNotification} />}
          {activeTab === 'orders' && <OrdersList orders={orders} onUpdateOrder={handleUpdateOrder} onNotify={addNotification} />}
          {activeTab === 'receivables' && <ReceivablesList orders={orders} onUpdateOrder={handleUpdateOrder} />}
          {activeTab === 'advisor' && <SmartAdvisor inventory={inventory} onUpdateInventory={setInventory} onNotify={addNotification} />}
          {activeTab === 'security' && <AccountSecurity />}
          {activeTab === 'sales-report' && <SalesReport orders={orders} menu={menu} />}
          {activeTab === 'admins' && <AdminProfiles shiftConfigs={shiftConfigs} onUpdateShiftConfigs={setShiftConfigs} onNotify={addNotification} />}
          {activeTab === 'social' && <SocialAnalytics menu={menu} settings={settings} />}
        </div>
      </main>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-xl border-t border-slate-100 px-6 py-4 flex justify-between items-center z-[40] shadow-[0_-10px_40px_rgba(0,0,0,0.04)] rounded-t-[2.5rem] lg:hidden">
        {[
          { id: 'dashboard', label: 'Home', icon: LayoutDashboard },
          { id: 'orders', label: 'Pesanan', icon: ShoppingBag },
          { id: 'menu', label: 'Menu', icon: UtensilsCrossed, isProminent: true },
          { id: 'receivables', label: 'Piutang', icon: Wallet },
          { id: 'advisor', label: 'Dapur', icon: PackageSearch },
        ].map((item) => (
          <button key={item.id} onClick={() => setActiveTab(item.id as any)} className={`flex flex-col items-center justify-center transition-all px-2 ${activeTab === item.id ? 'text-emerald-600' : 'text-slate-400'}`}>
            <item.icon size={item.isProminent ? 24 : 20} />
            <span className="text-[8px] font-black mt-1.5 uppercase tracking-widest">{item.label}</span>
          </button>
        ))}
      </nav>

      {isSettingsOpen && isSuperAdmin && (
        <div className="fixed inset-0 z-[100] flex justify-end">
          <div className="absolute inset-0 bg-slate-900/20 backdrop-blur-[2px]" onClick={() => setIsSettingsOpen(false)}></div>
          <div className="w-full max-w-lg bg-white h-full relative z-10 shadow-2xl animate-in slide-in-from-right duration-300 border-l border-slate-100">
            <div className="p-6 border-b border-slate-50 flex items-center justify-between">
              <h2 className="text-xl font-bold text-slate-800">Pengaturan Toko</h2>
              <button onClick={() => setIsSettingsOpen(false)} className="p-2 text-slate-400"><X size={24} /></button>
            </div>
            <div className="flex-1 overflow-y-auto p-6"><Settings settings={settings} onUpdateSettings={setSettings} /></div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useRef, useState } from 'react';
import { 
  Save, MessageCircle, Store, MapPin, CheckCircle2, 
  Image as ImageIcon, Upload, X, Instagram, Facebook, 
  Video, Plus, Trash2, Link2, ExternalLink, Users, 
  ShieldCheck, Clock, Sun, SunMedium, Moon, ChevronRight,
  ShieldAlert, Sparkles, UserPlus
} from 'lucide-react';
import { StoreSettings, SocialAccount, ShiftConfig, ShiftType, UserRole } from '../types';

interface SettingsProps {
  settings: StoreSettings;
  onUpdateSettings: (settings: StoreSettings) => void;
  shiftConfigs: ShiftConfig[];
  onUpdateShiftConfigs: (configs: ShiftConfig[]) => void;
}

const Settings: React.FC<SettingsProps> = ({ 
  settings, 
  onUpdateSettings, 
  shiftConfigs, 
  onUpdateShiftConfigs 
}) => {
  const [localSettings, setLocalSettings] = useState(settings);
  const [localShifts, setLocalShifts] = useState<ShiftConfig[]>(shiftConfigs);
  const [showSaved, setShowSaved] = useState(false);
  const [newAccount, setNewAccount] = useState<{platform: SocialAccount['platform'], handle: string, name: string}>({
    platform: 'Instagram',
    handle: '',
    name: ''
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSave = () => {
    onUpdateSettings(localSettings);
    onUpdateShiftConfigs(localShifts);
    setShowSaved(true);
    setTimeout(() => setShowSaved(false), 3000);
  };

  const handleAddAccount = () => {
    if (!newAccount.handle) return;
    const account: SocialAccount = {
      id: Math.random().toString(36).substr(2, 9),
      platform: newAccount.platform,
      handle: newAccount.handle,
      displayName: newAccount.name || newAccount.handle
    };
    setLocalSettings({
      ...localSettings,
      socialAccounts: [...(localSettings.socialAccounts || []), account]
    });
    setNewAccount({ ...newAccount, handle: '', name: '' });
  };

  const handleRemoveAccount = (id: string) => {
    setLocalSettings({
      ...localSettings,
      socialAccounts: localSettings.socialAccounts.filter(a => a.id !== id)
    });
  };

  const handleShiftChange = (type: ShiftType, field: 'startTime' | 'endTime', value: string) => {
    setLocalShifts(prev => prev.map(s => s.type === type ? { ...s, [field]: value } : s));
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setLocalSettings({ ...localSettings, logoUrl: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const getPlatformIcon = (platform: string) => {
    switch (platform) {
      case 'Instagram': return <Instagram size={18} className="text-pink-500" />;
      case 'TikTok': return <Video size={18} className="text-slate-900" />;
      case 'Facebook': return <Facebook size={18} className="text-blue-600" />;
      default: return <Link2 size={18} />;
    }
  };

  const getShiftIcon = (type: ShiftType) => {
    switch (type) {
      case 'Pagi': return <Sun size={18} className="text-amber-500" />;
      case 'Siang': return <SunMedium size={18} className="text-sky-500" />;
      case 'Malam': return <Moon size={18} className="text-indigo-500" />;
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center mb-4 sticky top-0 bg-white z-20 pb-4 border-b border-slate-50">
        <h3 className="font-black text-slate-400 text-[10px] uppercase tracking-widest">Master Control Panel</h3>
        <button 
          onClick={handleSave}
          className="bg-slate-900 text-white px-6 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-emerald-600 transition-all shadow-xl shadow-slate-200 flex items-center gap-2"
        >
          <Save size={16} />
          Simpan Semua Perubahan
        </button>
      </div>

      {showSaved && (
        <div className="bg-emerald-50 border border-emerald-100 p-4 rounded-2xl flex items-center gap-3 text-emerald-700 animate-in slide-in-from-top-2">
          <CheckCircle2 size={20} />
          <p className="text-sm font-bold">Seluruh konfigurasi berhasil diperbarui!</p>
        </div>
      )}

      <div className="space-y-8 pb-12">
        {/* Section 1: Business Profile */}
        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-8">
          <div className="flex items-center gap-3">
            <div className="p-2.5 bg-slate-50 rounded-xl border border-slate-100">
              <Store size={20} className="text-slate-600" />
            </div>
            <h3 className="font-black text-slate-800 uppercase tracking-widest text-[10px]">Identitas Katering</h3>
          </div>

          <div className="flex flex-col md:flex-row gap-10">
            <div className="relative group shrink-0">
              <div className="w-28 h-28 rounded-[2rem] bg-slate-50 border-4 border-white shadow-xl overflow-hidden flex items-center justify-center">
                {localSettings.logoUrl ? (
                  <img src={localSettings.logoUrl} alt="Logo" className="w-full h-full object-cover" />
                ) : (
                  <Store size={32} className="text-slate-200" />
                )}
              </div>
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="absolute inset-0 bg-black/40 text-white flex items-center justify-center opacity-0 group-hover:opacity-100 rounded-[2rem] transition-all font-black text-[8px] uppercase tracking-widest"
              >
                Ganti Logo
              </button>
              <input type="file" ref={fileInputRef} onChange={handleLogoUpload} className="hidden" accept="image/*" />
            </div>

            <div className="flex-1 space-y-5">
              <div>
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">Nama Katering</label>
                <input 
                  type="text" 
                  className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-3.5 text-sm font-bold outline-none focus:ring-2 focus:ring-emerald-500/20"
                  value={localSettings.storeName}
                  onChange={(e) => setLocalSettings({...localSettings, storeName: e.target.value})}
                />
              </div>
              <div>
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">WhatsApp Business Utama</label>
                <div className="relative">
                   <span className="absolute left-5 top-1/2 -translate-y-1/2 text-sm font-black text-slate-400">+</span>
                   <input 
                    type="text" 
                    className="w-full pl-9 pr-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl text-sm font-black text-slate-800 outline-none"
                    value={localSettings.whatsappNumber}
                    onChange={(e) => setLocalSettings({...localSettings, whatsappNumber: e.target.value.replace(/\D/g, '')})}
                  />
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Section 2: Account Manager & Team */}
        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-8">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2.5 bg-indigo-50 rounded-xl border border-indigo-100">
                <Users size={20} className="text-indigo-600" />
              </div>
              <h3 className="font-black text-slate-800 uppercase tracking-widest text-[10px]">Manajemen Akses Tim</h3>
            </div>
            <button className="p-2 bg-slate-50 text-indigo-600 hover:bg-indigo-600 hover:text-white rounded-xl transition-all">
              <UserPlus size={18} />
            </button>
          </div>

          <div className="space-y-3">
            {/* Quick Staff List */}
            {[
              { name: 'Budi Santoso', role: 'Super Admin', status: 'Online' },
              { name: 'Siti Aminah', role: 'Admin Dapur', status: 'Sift Pagi' },
              { name: 'Rian Hidayat', role: 'Admin Sales', status: 'Sift Pagi' }
            ].map((staff, i) => (
              <div key={i} className="p-4 bg-slate-50 rounded-2xl border border-slate-100 flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <div className="w-8 h-8 rounded-full bg-indigo-100 flex items-center justify-center font-black text-[10px] text-indigo-600">
                    {staff.name.charAt(0)}
                  </div>
                  <div>
                    <p className="text-xs font-black text-slate-800 leading-none mb-1">{staff.name}</p>
                    <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">{staff.role}</p>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <span className="text-[8px] font-black text-emerald-500 bg-emerald-50 px-2 py-0.5 rounded-lg border border-emerald-100 uppercase">{staff.status}</span>
                  <ChevronRight size={14} className="text-slate-300" />
                </div>
              </div>
            ))}
          </div>

          {/* Shift Hours Manager Embedded */}
          <div className="pt-6 border-t border-slate-50">
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2">
              <Clock size={12} className="text-indigo-500" /> Jam Operasional Sift
            </p>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
              {localShifts.map((shift) => (
                <div key={shift.type} className="p-4 bg-white border border-slate-100 rounded-2xl shadow-sm">
                  <div className="flex items-center gap-2 mb-3">
                    {getShiftIcon(shift.type)}
                    <span className="text-[10px] font-black text-slate-700 uppercase">Sift {shift.type}</span>
                  </div>
                  <div className="grid grid-cols-2 gap-2">
                    <input 
                      type="time" 
                      value={shift.startTime}
                      onChange={(e) => handleShiftChange(shift.type, 'startTime', e.target.value)}
                      className="w-full bg-slate-50 border border-slate-100 rounded-lg px-2 py-1.5 text-[10px] font-black text-slate-700 outline-none"
                    />
                    <input 
                      type="time" 
                      value={shift.endTime}
                      onChange={(e) => handleShiftChange(shift.type, 'endTime', e.target.value)}
                      className="w-full bg-slate-50 border border-slate-100 rounded-lg px-2 py-1.5 text-[10px] font-black text-slate-700 outline-none"
                    />
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Section 3: Social Multi-Account */}
        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-8">
          <div className="flex items-center gap-3">
            <div className="p-2.5 bg-rose-50 rounded-xl border border-rose-100">
              <Link2 size={20} className="text-rose-600" />
            </div>
            <h3 className="font-black text-slate-800 uppercase tracking-widest text-[10px]">Ekosistem Sosial Media</h3>
          </div>

          <div className="p-5 bg-slate-50 rounded-3xl border border-slate-100">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-3">
              <select 
                className="bg-white border border-slate-200 rounded-xl px-4 py-3 text-[10px] font-black uppercase outline-none"
                value={newAccount.platform}
                onChange={(e) => setNewAccount({...newAccount, platform: e.target.value as any})}
              >
                <option value="Instagram">Instagram</option>
                <option value="TikTok">TikTok</option>
                <option value="Facebook">Facebook</option>
              </select>
              <input 
                type="text" 
                placeholder="@handle"
                className="bg-white border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none"
                value={newAccount.handle}
                onChange={(e) => setNewAccount({...newAccount, handle: e.target.value})}
              />
              <input 
                type="text" 
                placeholder="Label Nama"
                className="bg-white border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none"
                value={newAccount.name}
                onChange={(e) => setNewAccount({...newAccount, name: e.target.value})}
              />
              <button 
                onClick={handleAddAccount}
                className="bg-slate-900 text-white rounded-xl px-4 py-3 text-[10px] font-black uppercase tracking-widest hover:bg-emerald-600 transition-all flex items-center justify-center gap-2"
              >
                <Plus size={14} /> Tambah Akun
              </button>
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            {(localSettings.socialAccounts || []).map((account) => (
              <div key={account.id} className="p-4 bg-white border border-slate-100 rounded-2xl flex items-center justify-between group hover:border-emerald-200 transition-all shadow-sm">
                <div className="flex items-center gap-3 overflow-hidden">
                  <div className="w-9 h-9 bg-slate-50 rounded-xl flex items-center justify-center shrink-0">
                    {getPlatformIcon(account.platform)}
                  </div>
                  <div className="overflow-hidden">
                    <p className="text-[11px] font-black text-slate-900 truncate">{account.displayName}</p>
                    <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest truncate">@{account.handle}</p>
                  </div>
                </div>
                <button 
                  onClick={() => handleRemoveAccount(account.id)}
                  className="p-2 text-slate-200 hover:text-rose-500 transition-colors"
                >
                  <Trash2 size={14} />
                </button>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

