import React, { useRef, useState } from 'react';
import { 
  Save, Store, CheckCircle2, 
  X, Instagram, Facebook, 
  Video, Plus, Trash2, Link2, 
  Globe, Layout, Share2, 
  ExternalLink, Smartphone, MessageCircle
} from 'lucide-react';
