  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isProfileDropdownOpen, setIsProfileDropdownOpen] = useState(false);
  const [isShiftDropdownOpen, setIsShiftDropdownOpen] = useState(false);

  const [menu, setMenu] = useState<MenuItem[]>(INITIAL_MENU);
  const [orders, setOrders] = useState<Order[]>(INITIAL_ORDERS);
  const [inventory, setInventory] = useState<IngredientStock[]>(INITIAL_INVENTORY);
  const [settings, setSettings] = useState<StoreSettings>(INITIAL_SETTINGS);
  const [categories, setCategories] = useState<string[]>(INITIAL_CATEGORIES);
  const [shiftConfigs, setShiftConfigs] = useState<ShiftConfig[]>(INITIAL_SHIFTS);
  const [notifications, setNotifications] = useState<Notification[]>([]);

  // Sound Engine
  const playAlertSound = useCallback((type: NotificationType) => {
    try {
      const context = new (window.AudioContext || (window as any).webkitAudioContext)();
      const oscillator = context.createOscillator();
      const gainNode = context.createGain();
      oscillator.connect(gainNode);
      gainNode.connect(context.destination);
      if (type === 'error') {
        oscillator.type = 'sawtooth';
        oscillator.frequency.setValueAtTime(150, context.currentTime);
        oscillator.frequency.exponentialRampToValueAtTime(50, context.currentTime + 0.3);
        gainNode.gain.setValueAtTime(0.1, context.currentTime);
      } else if (type === 'warning') {
        oscillator.type = 'sine';
        oscillator.frequency.setValueAtTime(440, context.currentTime);
        oscillator.frequency.exponentialRampToValueAtTime(880, context.currentTime + 0.1);
        gainNode.gain.setValueAtTime(0.1, context.currentTime);
      } else {
        oscillator.type = 'sine';
        oscillator.frequency.setValueAtTime(880, context.currentTime);
        oscillator.frequency.exponentialRampToValueAtTime(1200, context.currentTime + 0.1);
        gainNode.gain.setValueAtTime(0.05, context.currentTime);
      }
      oscillator.start();
      oscillator.stop(context.currentTime + 0.3);
    } catch (e) { console.warn("Audio Context blocked"); }
  }, []);

  const addNotification = useCallback((message: string, type: NotificationType) => {
    const id = Math.random().toString(36).substr(2, 9);
    setNotifications(prev => [{ id, message, type }, ...prev]);
    playAlertSound(type);
    setTimeout(() => setNotifications(prev => prev.filter(n => n.id !== id)), 5000);
  }, [playAlertSound]);

  // AUTO DEDUCTION LOGIC
  const deduceStockFromOrder = useCallback((order: Order) => {
    let inventoryCopy = [...inventory];
    let insufficientItems: string[] = [];

    order.items.forEach(orderItemStr => {
      const match = orderItemStr.match(/(.*)\s\((\d+)\)/);
      if (!match) return;
      const [_, itemName, qtyStr] = match;
      const quantity = parseInt(qtyStr);

      const menuItem = menu.find(m => m.name === itemName.trim());
      if (menuItem?.recipe) {
        menuItem.recipe.forEach(ingredient => {
          const invItemIdx = inventoryCopy.findIndex(inv => inv.id === ingredient.ingredientId);
          if (invItemIdx > -1) {
            const totalNeeded = ingredient.amountPerUnit * quantity;
            if (inventoryCopy[invItemIdx].quantity < totalNeeded) {
              insufficientItems.push(`${inventoryCopy[invItemIdx].name} (Butuh ${totalNeeded}${ingredient.unit})`);
            } else {
              inventoryCopy[invItemIdx].quantity -= totalNeeded;
              const q = inventoryCopy[invItemIdx].quantity;
              if (q <= 0) inventoryCopy[invItemIdx].status = 'Habis';
              else if (q < 10) inventoryCopy[invItemIdx].status = 'Menipis';
            }
          }
        });
      }
    });

    if (insufficientItems.length > 0) {
      addNotification(`Gagal Konfirmasi! Stok tidak cukup: ${insufficientItems.join(', ')}`, 'error');
      return false;
    }

    setInventory(inventoryCopy);
    addNotification(`Stok inventori telah dipotong otomatis untuk Pesanan #${order.id}`, 'success');
    return true;
  }, [inventory, menu, addNotification]);

  const handleUpdateOrder = (orderId: string, updates: Partial<Order>) => {
    const targetOrder = orders.find(o => o.id === orderId);
    if (!targetOrder) return;

    if (updates.status === 'Confirmed' && targetOrder.status !== 'Confirmed') {
      const success = deduceStockFromOrder(targetOrder);
      if (!success) return; 
    }

    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, ...updates } : o));
    if (updates.status === 'Delivered') addNotification(`Pesanan #${orderId} berhasil dikirim!`, 'success');
  };

  const handleLogin = (name: string, shift: ShiftType, role: UserRole) => {
    setCurrentUser({
      id: Math.random().toString(),
      name, role, shift,
      avatarUrl: name === 'Siti Aminah' 
        ? 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?auto=format&fit=facearea&facepad=2&w=100&h=100&q=80' 
        : 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?auto=format&fit=facearea&facepad=2&w=100&h=100&q=80'
    });
    addNotification(`Selamat datang kembali, ${name}!`, 'success');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setIsProfileDropdownOpen(false);
  };

  const upcomingDeadlines = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    const now = new Date();
    return orders.filter(o => {
      if (o.status === 'Delivered' || o.status === 'Cancelled' || o.date !== today || !o.deliveryTime) return false;
      const [hour, min] = o.deliveryTime.split(':').map(Number);
      const deliveryDate = new Date();
      deliveryDate.setHours(hour, min, 0);
      const diffHrs = (deliveryDate.getTime() - now.getTime()) / (1000 * 60 * 60);
      return diffHrs > -1 && diffHrs <= 3;
    }).sort((a, b) => (a.deliveryTime || '').localeCompare(b.deliveryTime || ''));
  }, [orders]);

  const earliestDeadline = upcomingDeadlines[0];

  const getShiftIcon = (shift: ShiftType) => {
    switch (shift) {
      case 'Pagi': return <Sun size={14} className="text-amber-500" />;
      case 'Siang': return <SunMedium size={14} className="text-sky-500" />;
      case 'Malam': return <Moon size={14} className="text-indigo-500" />;
    }
  };

  const getShiftColor = (shift: ShiftType) => {
    switch (shift) {
      case 'Pagi': return 'bg-amber-50 text-amber-700 border-amber-100';
      case 'Siang': return 'bg-sky-50 text-sky-700 border-sky-100';
      case 'Malam': return 'bg-indigo-50 text-indigo-700 border-indigo-100';
    }
  };

  if (!currentUser) return <Login onLogin={handleLogin} shiftConfigs={shiftConfigs} />;
  const isSuperAdmin = currentUser.role === 'Super Admin';

  if (viewMode === 'customer') {
    return <PublicMenu menu={menu} settings={settings} categories={categories} onBackToAdmin={() => setViewMode('admin')} />;
  }

  return (
    <div className="min-h-screen bg-[#f8fafc] flex flex-col font-sans selection:bg-emerald-100 text-slate-900">

      {/* GLOBAL TOASTS */}
      <div className="fixed top-24 right-6 z-[200] flex flex-col gap-3 w-full max-w-sm pointer-events-none">
        {notifications.map((n) => (
          <div key={n.id} className={`pointer-events-auto p-4 rounded-[1.8rem] shadow-2xl backdrop-blur-xl border flex items-start gap-4 animate-in slide-in-from-right duration-500 ${
            n.type === 'error' ? 'bg-rose-600/90 text-white border-rose-500' :
            n.type === 'warning' ? 'bg-amber-500/90 text-white border-amber-400' : 'bg-emerald-600/90 text-white border-emerald-500'
          }`}>
            <div className="w-10 h-10 rounded-2xl bg-white/20 flex items-center justify-center shrink-0">
               {n.type === 'error' ? <AlertTriangle size={20} /> : n.type === 'warning' ? <Timer size={20} /> : <CheckCircle2 size={20} />}
            </div>
            <div className="flex-1">
              <p className="text-[10px] font-black uppercase tracking-widest opacity-70 mb-1">{n.type === 'error' ? 'Peringatan Sistem' : n.type === 'warning' ? 'Deadline' : 'Berhasil'}</p>
              <p className="text-sm font-bold leading-tight">{n.message}</p>
            </div>
            <button onClick={() => setNotifications(prev => prev.filter(x => x.id !== n.id))} className="text-white/40 hover:text-white"><X size={16} /></button>
          </div>
        ))}
      </div>

      <header className="h-20 bg-white border-b border-slate-100 flex items-center justify-between px-6 sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <button onClick={() => setIsSidebarOpen(true)} className="p-2 text-slate-400 lg:hidden"><MenuIcon size={22} /></button>
          <div className="hidden md:flex items-center gap-3">
            <div className={`flex items-center gap-2 px-3 py-1 rounded-full border ${isSuperAdmin ? 'bg-amber-50 text-amber-600 border-amber-200' : 'bg-slate-50 text-slate-500 border-slate-200'}`}>
              <div className={`w-1.5 h-1.5 rounded-full animate-pulse ${isSuperAdmin ? 'bg-amber-500' : 'bg-slate-400'}`}></div>
              <span className="text-[10px] font-black uppercase tracking-widest">{currentUser.role}</span>
            </div>
            <div className="relative">
              <button onClick={() => setIsShiftDropdownOpen(!isShiftDropdownOpen)} className={`flex items-center gap-2 px-3 py-1 rounded-full border transition-all hover:shadow-sm ${getShiftColor(currentUser.shift)}`}>
                {getShiftIcon(currentUser.shift)} <span className="text-[10px] font-black uppercase tracking-widest">Sift {currentUser.shift}</span> <ChevronDown size={10} />
              </button>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <div className="relative">
            <div className="flex items-center gap-3 cursor-pointer p-1 pr-3 rounded-full hover:bg-slate-50 border border-transparent hover:border-slate-100" onClick={() => setIsProfileDropdownOpen(!isProfileDropdownOpen)}>
              <div className="w-9 h-9 rounded-full bg-slate-100 border-2 border-white shadow-sm overflow-hidden">
                <img src={currentUser.avatarUrl || "https://picsum.photos/100/100"} alt="Profile" className="w-full h-full object-cover" />
              </div>
              <div className="hidden sm:block text-left">
                <p className="text-[10px] font-black text-slate-800 leading-none mb-1 uppercase tracking-tight">{currentUser.name}</p>
                <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">{currentUser.role}</p>
              </div>
            </div>
            {isProfileDropdownOpen && (
              <div className="absolute top-full right-0 mt-2 bg-white border border-slate-100 rounded-[2rem] shadow-2xl p-4 w-56 animate-in fade-in slide-in-from-top-4 z-[60]">
                <button onClick={handleLogout} className="w-full flex items-center gap-3 px-3 py-3 text-[10px] font-black uppercase tracking-widest text-rose-500 hover:bg-rose-50 rounded-xl transition-all">
                  <LogOut size={16} /> Logout Sesi
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      <Sidebar isOpen={isSidebarOpen} setIsOpen={setIsSidebarOpen} activeTab={activeTab} setActiveTab={setActiveTab} onPreviewMenu={() => setViewMode('customer')} logoUrl={settings.logoUrl} onOpenSettings={() => isSuperAdmin && setIsSettingsOpen(true)} role={currentUser.role} />

      <main className="flex-1 overflow-y-auto px-4 py-6 md:px-8 md:py-8 pb-32">
        <div className="max-w-6xl mx-auto space-y-6">
          {activeTab === 'dashboard' && <Dashboard orders={orders} menu={menu} />}
          {activeTab === 'menu' && <MenuManager menu={menu} onUpdateMenu={setMenu} categories={categories} onUpdateCategories={setCategories} inventory={inventory} onNotify={addNotification} />}
          {activeTab === 'orders' && <OrdersList orders={orders} onUpdateOrder={handleUpdateOrder} onNotify={addNotification} />}
          {activeTab === 'receivables' && <ReceivablesList orders={orders} onUpdateOrder={handleUpdateOrder} />}
          {activeTab === 'advisor' && <SmartAdvisor inventory={inventory} onUpdateInventory={setInventory} onNotify={addNotification} />}
          {activeTab === 'security' && <AccountSecurity />}
          {activeTab === 'sales-report' && <SalesReport orders={orders} menu={menu} />}
          {activeTab === 'admins' && <AdminProfiles shiftConfigs={shiftConfigs} onUpdateShiftConfigs={setShiftConfigs} onNotify={addNotification} />}
          {activeTab === 'social' && <SocialAnalytics menu={menu} settings={settings} onUpdateSettings={setSettings} />}
        </div>
      </main>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-xl border-t border-slate-100 px-6 py-4 flex justify-between items-center z-[40] shadow-[0_-10px_40px_rgba(0,0,0,0.04)] rounded-t-[2.5rem] lg:hidden">
        {[
          { id: 'dashboard', label: 'Home', icon: LayoutDashboard },
          { id: 'orders', label: 'Pesanan', icon: ShoppingBag },
          { id: 'menu', label: 'Menu', icon: UtensilsCrossed, isProminent: true },
          { id: 'receivables', label: 'Piutang', icon: Wallet },
          { id: 'advisor', label: 'Dapur', icon: PackageSearch },
        ].map((item) => (
          <button key={item.id} onClick={() => setActiveTab(item.id as any)} className={`flex flex-col items-center justify-center transition-all px-2 ${activeTab === item.id ? 'text-emerald-600' : 'text-slate-400'}`}>
            <item.icon size={item.isProminent ? 24 : 20} />
            <span className="text-[8px] font-black mt-1.5 uppercase tracking-widest">{item.label}</span>
          </button>
        ))}
      </nav>

      {isSettingsOpen && isSuperAdmin && (
        <div className="fixed inset-0 z-[100] flex justify-end">
          <div className="absolute inset-0 bg-slate-900/20 backdrop-blur-[2px]" onClick={() => setIsSettingsOpen(false)}></div>
          <div className="w-full max-w-lg bg-white h-full relative z-10 shadow-2xl animate-in slide-in-from-right duration-300 border-l border-slate-100">
            <div className="p-6 border-b border-slate-50 flex items-center justify-between">
              <h2 className="text-xl font-bold text-slate-800">Konfigurasi Bisnis & Ekosistem</h2>
              <button onClick={() => setIsSettingsOpen(false)} className="p-2 text-slate-400"><X size={24} /></button>
            </div>
            <div className="flex-1 overflow-y-auto p-6">
              <Settings 
                settings={settings} 
                onUpdateSettings={setSettings} 
              />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  AreaChart, Area
} from 'recharts';
import { 
  Instagram, MessageCircle, Share2, TrendingUp, Sparkles, Loader2, 
  Send, Calendar, Clock, Image as ImageIcon, Video, Facebook,
  ExternalLink, Copy, Download, CheckCircle2, Layout, Link2, 
  ChevronRight, ChevronLeft, Search, UserCircle, Plus, Trash2, Edit3, X, Link as LinkIcon
} from 'lucide-react';
import { generateSocialStrategy, generatePromoImage } from '../services/geminiService';
import { MenuItem, SocialStrategy, StoreSettings, SocialAccount } from '../types';

interface SocialAnalyticsProps {
  menu: MenuItem[];
  settings: StoreSettings;
  onUpdateSettings?: (settings: StoreSettings) => void;
}

const SocialAnalytics: React.FC<SocialAnalyticsProps> = ({ menu, settings, onUpdateSettings }) => {
  const [loading, setLoading] = useState(false);
  const [genLoading, setGenLoading] = useState(false);
  const [strategies, setStrategies] = useState<SocialStrategy[]>([]);
  const [generatedPost, setGeneratedPost] = useState<{ image: string, caption: string, item: string } | null>(null);
  const [copyStatus, setCopyStatus] = useState<string | null>(null);
  const [selectedAccount, setSelectedAccount] = useState<SocialAccount | null>(settings.socialAccounts?.[0] || null);

  // Modal State for Account Management
  const [isAccountModalOpen, setIsAccountModalOpen] = useState(false);
  const [editingAccount, setEditingAccount] = useState<SocialAccount | null>(null);
  const [accountFormData, setAccountFormData] = useState<{
    platform: SocialAccount['platform'],
    handle: string,
    displayName: string
  }>({
    platform: 'Instagram',
    handle: '',
    displayName: ''
  });

  const engagementData = [
    { day: 'Mon', engagement: 1200 },
    { day: 'Tue', engagement: 1900 },
    { day: 'Wed', engagement: 1500 },
    { day: 'Thu', engagement: 2200 },
    { day: 'Fri', engagement: 3000 },
    { day: 'Sat', engagement: 4500 },
    { day: 'Sun', engagement: 3800 },
  ];

  const handleGenerateStrategy = async () => {
    setLoading(true);
    try {
      const topItems = [...menu].sort((a, b) => b.salesCount - a.salesCount).slice(0, 3);
      const res = await generateSocialStrategy(topItems);
      setStrategies(res);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const handleCreateVisualPromo = async (item: MenuItem) => {
    setGenLoading(true);
    try {
      const img = await generatePromoImage(item.name);
      setGeneratedPost({
        image: img,
        caption: `Nikmati kelezatan ${item.name} hari ini! Dibuat dengan bahan premium dan bumbu rahasia yang pasti memanjakan lidah Anda. ✨🍱\n\nHubungi kami sekarang untuk pemesanan katering acara Anda!\n\n#CaterElite #KateringPremium #KulinerJakarta #InstaFood`,
        item: item.name
      });
    } catch (error) {
      console.error(error);
    } finally {
      setGenLoading(false);
    }
  };

  const handleCopyCaption = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopyStatus("Tersalin!");
    setTimeout(() => setCopyStatus(null), 2000);
  };

  const getPlatformIcon = (platform: string) => {
    switch (platform) {
      case 'Instagram': return <Instagram size={20} className="text-pink-500" />;
      case 'TikTok': return <Video size={20} className="text-slate-900" />;
      case 'Facebook': return <Facebook size={20} className="text-blue-600" />;
      case 'WhatsApp': return <MessageCircle size={20} className="text-emerald-500" />;
      default: return <Link2 size={20} />;
    }
  };

  const filteredStrategies = useMemo(() => {
    if (!selectedAccount) return strategies;
    return strategies.filter(s => s.platform === selectedAccount.platform);
  }, [strategies, selectedAccount]);

  // Account Management Handlers
  const handleOpenAddModal = () => {
    setEditingAccount(null);
    setAccountFormData({ platform: 'Instagram', handle: '', displayName: '' });
    setIsAccountModalOpen(true);
  };

  const handleOpenEditModal = (account: SocialAccount, e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingAccount(account);
    setAccountFormData({
      platform: account.platform,
      handle: account.handle,
      displayName: account.displayName || ''
    });
    setIsAccountModalOpen(true);
  };

  const handleDeleteAccount = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!onUpdateSettings) return;
    const updatedAccounts = settings.socialAccounts.filter(a => a.id !== id);
    onUpdateSettings({ ...settings, socialAccounts: updatedAccounts });
    if (selectedAccount?.id === id) {
      setSelectedAccount(updatedAccounts[0] || null);
    }
  };

  const handleSaveAccount = () => {
    if (!onUpdateSettings || !accountFormData.handle) return;

    let updatedAccounts = [...settings.socialAccounts];
    if (editingAccount) {
      updatedAccounts = updatedAccounts.map(a => 
        a.id === editingAccount.id 
          ? { ...a, ...accountFormData } 
          : a
      );
    } else {
      const newAcc: SocialAccount = {
        id: Math.random().toString(36).substr(2, 9),
        ...accountFormData
      };
      updatedAccounts.push(newAcc);
    }

    onUpdateSettings({ ...settings, socialAccounts: updatedAccounts });
    setIsAccountModalOpen(false);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      {/* MULTI-ACCOUNT MONITORING HUB */}
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <div>
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em]">Social Media Hub</h3>
            <p className="text-xl font-black text-slate-800 tracking-tight">Ekosistem Media Sosial</p>
          </div>
          <button 
            onClick={handleOpenAddModal}
            className="flex items-center gap-2 px-4 py-2 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-emerald-600 transition-all shadow-lg shadow-slate-200"
          >
            <Plus size={14} /> Tambah Akun
          </button>
        </div>

        <div className="flex gap-4 overflow-x-auto pb-4 no-scrollbar">
          {(settings.socialAccounts || []).map((account) => (
            <div 
              key={account.id}
              onClick={() => setSelectedAccount(account)}
              className={`flex-shrink-0 w-72 p-6 rounded-[2.5rem] border transition-all relative overflow-hidden group cursor-pointer ${
                selectedAccount?.id === account.id 
                  ? 'bg-white border-indigo-500 shadow-xl shadow-indigo-50' 
                  : 'bg-white border-slate-100 shadow-sm hover:border-slate-200'
              }`}
            >
              {/* Floating Actions */}
              <div className="absolute top-4 right-4 flex gap-1.5 opacity-0 group-hover:opacity-100 transition-opacity">
                <button 
                  onClick={(e) => handleOpenEditModal(account, e)}
                  className="p-2 bg-indigo-50 text-indigo-600 rounded-lg hover:bg-indigo-600 hover:text-white transition-all"
                >
                  <Edit3 size={12} />
                </button>
                <button 
                  onClick={(e) => handleDeleteAccount(account.id, e)}
                  className="p-2 bg-rose-50 text-rose-600 rounded-lg hover:bg-rose-600 hover:text-white transition-all"
                >
                  <Trash2 size={12} />
                </button>
              </div>

              <div className="flex items-center gap-4">
                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shrink-0 transition-all ${
                  selectedAccount?.id === account.id ? 'bg-indigo-500 text-white' : 'bg-slate-50 border border-slate-100'
                }`}>
                  {getPlatformIcon(account.platform)}
                </div>
                <div className="text-left overflow-hidden">
                  <p className="text-sm font-black text-slate-800 truncate leading-none mb-1.5">{account.displayName}</p>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest truncate flex items-center gap-1.5">
                    <LinkIcon size={10} /> @{account.handle}
                  </p>
                </div>
              </div>

              <div className={`mt-4 pt-4 border-t border-slate-50 flex items-center justify-between text-[9px] font-black uppercase tracking-[0.2em] transition-all ${
                selectedAccount?.id === account.id ? 'text-indigo-600' : 'text-slate-300'
              }`}>
                <span>{account.platform}</span>
                {selectedAccount?.id === account.id && <CheckCircle2 size={14} />}
              </div>
            </div>
          ))}

          <button 
            onClick={handleOpenAddModal}
            className="flex-shrink-0 w-64 p-6 rounded-[2.5rem] border-2 border-dashed border-slate-200 bg-slate-50/50 flex flex-col items-center justify-center gap-2 group hover:border-indigo-400 hover:bg-indigo-50 transition-all"
          >
            <Plus size={32} className="text-slate-300 group-hover:text-indigo-500 transition-colors" />
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest group-hover:text-indigo-600">Daftarkan Akun Baru</span>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Visual Content Generator Section */}
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
            <div className="flex items-center justify-between mb-8">
              <div>
                <h3 className="text-xl font-black text-slate-800">AI Visual Promo Generator</h3>
                <p className="text-sm text-slate-400">Pilih menu untuk dibuatkan poster promosi otomatis oleh AI.</p>
              </div>
              <div className="p-3 bg-amber-50 text-amber-500 rounded-2xl">
                <Sparkles size={24} />
              </div>
            </div>

            <div className="flex gap-4 overflow-x-auto pb-6 no-scrollbar">
              {menu.slice(0, 5).map(item => (
                <button 
                  key={item.id}
                  onClick={() => handleCreateVisualPromo(item)}
                  className="shrink-0 flex flex-col items-center gap-2 group"
                >
                  <div className="w-20 h-20 rounded-2xl overflow-hidden border-2 border-transparent group-hover:border-amber-500 transition-all shadow-md">
                    <img src={item.imageUrl} alt={item.name} className="w-full h-full object-cover" />
                  </div>
                  <span className="text-[9px] font-black uppercase text-slate-400 group-hover:text-slate-900 transition-colors max-w-[80px] truncate">{item.name}</span>
                </button>
              ))}
            </div>

            {genLoading && (
              <div className="aspect-square w-full max-w-md mx-auto bg-slate-50 rounded-[2.5rem] border border-dashed border-slate-200 flex flex-col items-center justify-center gap-4 animate-pulse">
                <Loader2 size={40} className="animate-spin text-amber-500" />
                <p className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400">AI SEDANG MENDESAIN POSTER...</p>
              </div>
            )}

            {generatedPost && !genLoading && (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mt-4 animate-in fade-in slide-in-from-bottom-4">
                <div className="relative group">
                  <div className="aspect-square rounded-[2rem] overflow-hidden shadow-2xl border-4 border-white">
                    <img src={generatedPost.image} alt="Generated Promo" className="w-full h-full object-cover" />
                  </div>
                  <div className="absolute top-4 right-4 flex gap-2">
                    <button className="p-3 bg-white/90 backdrop-blur rounded-xl text-slate-800 hover:bg-white shadow-lg transition-all">
                      <Download size={18} />
                    </button>
                  </div>
                </div>

                <div className="flex flex-col h-full">
                  <div className="bg-slate-50 rounded-2xl p-6 border border-slate-100 flex-1 relative">
                    <div className="flex justify-between items-center mb-4">
                      <span className="text-[10px] font-black text-indigo-600 uppercase tracking-widest">Draf Caption AI</span>
                      <button 
                        onClick={() => handleCopyCaption(generatedPost.caption)}
                        className="text-slate-400 hover:text-indigo-600 transition-colors"
                      >
                        {copyStatus ? <CheckCircle2 size={16} className="text-emerald-500" /> : <Copy size={16} />}
                      </button>
                    </div>
                    <p className="text-sm text-slate-700 leading-relaxed font-medium italic">"{generatedPost.caption}"</p>
                  </div>

                  <div className="mt-4 grid grid-cols-2 gap-4">
                    <button className="bg-pink-600 text-white py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 shadow-lg shadow-pink-100">
                      <Instagram size={16} /> Instagram
                    </button>
                    <button className="bg-slate-900 text-white py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 shadow-lg shadow-slate-200">
                      <Layout size={16} /> WhatsApp
                    </button>
                  </div>
                </div>
              </div>
            )}
          </div>

          {/* Strategy Section */}
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
            <div className="flex items-center justify-between mb-8">
              <div>
                <h3 className="text-xl font-black text-slate-800">Strategi Konten {selectedAccount ? `(${selectedAccount.displayName})` : ''}</h3>
                <p className="text-xs text-slate-400 font-medium">Rekomendasi posting untuk meningkatkan engagement.</p>
              </div>
              <button 
                onClick={handleGenerateStrategy}
                disabled={loading}
                className="bg-indigo-600 text-white px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-indigo-700 transition-all flex items-center gap-2"
              >
                {loading ? <Loader2 size={14} className="animate-spin" /> : <Sparkles size={14} />}
                Generate Strategi
              </button>
            </div>

            <div className="space-y-4">
              {filteredStrategies.length > 0 ? (
                filteredStrategies.map((strat, i) => (
                  <div key={i} className="flex gap-6 p-6 bg-slate-50 rounded-3xl border border-slate-100 group hover:bg-white hover:border-indigo-100 transition-all">
                    <div className="w-14 h-14 rounded-2xl bg-white shadow-sm flex items-center justify-center text-indigo-500 shrink-0 group-hover:scale-110 transition-transform">
                      <Calendar size={24} />
                    </div>
                    <div>
                      <div className="flex items-center gap-3 mb-1">
                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{strat.platform}</span>
                        <span className="text-[10px] font-bold text-indigo-500 flex items-center gap-1"><Clock size={10} /> {strat.bestTimeToPost}</span>
                      </div>
                      <h4 className="font-bold text-slate-800">{strat.contentIdea}</h4>
                      <p className="text-[10px] text-slate-500 mt-2 line-clamp-1 italic">"{strat.suggestedCaption}"</p>
                    </div>
                  </div>
                ))
              ) : (
                <div className="py-12 text-center text-slate-400 italic">
                  Belum ada kalender konten. Klik "Generate Strategi" untuk memulai.
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Sidebar Analytics */}
        <div className="space-y-6">
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-lg font-black text-slate-800">Engagement</h3>
              {selectedAccount && getPlatformIcon(selectedAccount.platform)}
            </div>
            <div className="h-48">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={engagementData}>
                  <defs>
                    <linearGradient id="colorEngage" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="#6366f1" stopOpacity={0.1}/>
                      <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                    </linearGradient>
                  </defs>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                  <XAxis dataKey="day" hide />
                  <Tooltip contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}} />
                  <Area type="monotone" dataKey="engagement" stroke="#6366f1" strokeWidth={3} fillOpacity={1} fill="url(#colorEngage)" />
                </AreaChart>
              </ResponsiveContainer>
            </div>
            <div className="mt-4 flex justify-between items-center text-[10px] font-black text-slate-400 uppercase tracking-widest">
              <span>Senin</span>
              <span>Minggu</span>
            </div>
          </div>

          <div className="bg-slate-900 rounded-[2.5rem] p-8 text-white relative overflow-hidden">
            <div className="relative z-10">
              <h4 className="font-black text-xl mb-4 leading-tight">Insight Performa {selectedAccount?.displayName || 'Ekosistem'}</h4>
              <p className="text-indigo-200 text-xs mb-6 leading-relaxed">AI kami mendeteksi tren positif pada jam 19:00 untuk konten video. Pertimbangkan untuk memposting konten 'Behind the Kitchen'.</p>
              <div className="flex items-center gap-4">
                 <div className="flex-1">
