import React, { useState, useRef } from 'react';
import { Plus, Sparkles, Trash2, Loader2, X, Image as ImageIcon, Save, CheckCircle, Upload, Share2, Copy, QrCode, ExternalLink, Check, Tag, AlertCircle, ListPlus, Box, BrainCircuit, Target, TrendingUp, Lightbulb, Wand2, PencilLine } from 'lucide-react';
import { MenuItem, MenuRecipe, IngredientStock } from '../types';
import { optimizeMenuDescription, analyzeMenuAppeal } from '../services/geminiService';

interface MenuManagerProps {
  menu: MenuItem[];
  onUpdateMenu: (menu: MenuItem[]) => void;
  categories: string[];
  onUpdateCategories: (categories: string[]) => void;
  inventory: IngredientStock[];
  onNotify?: (message: string, type: 'success' | 'error' | 'warning') => void;
}

const MenuManager: React.FC<MenuManagerProps> = ({ menu, onUpdateMenu, categories, onUpdateCategories, inventory, onNotify }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [analyzingInModal, setAnalyzingInModal] = useState(false);
  const [isAiWriting, setIsAiWriting] = useState(false);
  const [modalAiInsight, setModalAiInsight] = useState<any>(null);

  const [formData, setFormData] = useState<Partial<MenuItem>>({
    name: '',
    category: categories[0] || '',
    price: 0,
    cost: 0,
    description: '',
    imageUrl: '',
    recipe: []
  });

  const [newIngredient, setNewIngredient] = useState<Partial<MenuRecipe>>({
    ingredientId: '',
    amountPerUnit: 0,
    unit: ''
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleOpenAddModal = () => {
    setEditingId(null);
    setModalAiInsight(null);
    setFormData({
      name: '',
      category: categories[0] || '',
      price: 0,
      cost: 0,
      description: '',
      imageUrl: '',
      recipe: []
    });
    setIsModalOpen(true);
  };

  const handleEditClick = (item: MenuItem) => {
    setEditingId(item.id);
    setModalAiInsight(null);
    setFormData({ ...item });
    setIsModalOpen(true);
  };

  const handleAiWriteDescription = async () => {
    if (!formData.name) {
      return onNotify?.('Beri nama menu dulu agar AI bisa menulis deskripsi!', 'warning');
    }

    setIsAiWriting(true);
    try {
      const ingredientNames = formData.recipe?.map(r => r.name) || [];
      const polishedDesc = await optimizeMenuDescription(formData.name, formData.description || '', ingredientNames);
      setFormData(prev => ({ ...prev, description: polishedDesc || prev.description }));
      onNotify?.('Deskripsi telah dipoles secara gourmet oleh AI!', 'success');
    } catch (error) {
      onNotify?.('Gagal memanggil AI Writer.', 'error');
    } finally {
      setIsAiWriting(false);
    }
  };

  const handleAnalyzeInModal = async () => {
    if (!formData.name || !formData.description) {
      return onNotify?.('Lengkapi Nama dan Deskripsi sebelum menganalisis strategi!', 'warning');
    }
    setAnalyzingInModal(true);
    setModalAiInsight(null);
    try {
      const insight = await analyzeMenuAppeal(formData as MenuItem);
      setModalAiInsight(insight);
      onNotify?.('Strategi pemasaran AI telah dirangkai!', 'success');
    } catch (error) {
      onNotify?.('Gagal mendapatkan insight AI.', 'error');
    } finally {
      setAnalyzingInModal(false);
    }
  };

  const handleAddIngredientToRecipe = () => {
    if (!newIngredient.ingredientId || !newIngredient.amountPerUnit) return;
    const invItem = inventory.find(i => i.id === newIngredient.ingredientId);
    if (!invItem) return;

    const recipeItem: MenuRecipe = {
      ingredientId: invItem.id,
      name: invItem.name,
      amountPerUnit: Number(newIngredient.amountPerUnit),
      unit: invItem.unit
    };

    setFormData({
      ...formData,
      recipe: [...(formData.recipe || []), recipeItem]
    });
    setNewIngredient({ ingredientId: '', amountPerUnit: 0, unit: '' });
  };

  const handleRemoveRecipeItem = (idx: number) => {
    setFormData({
      ...formData,
      recipe: formData.recipe?.filter((_, i) => i !== idx)
    });
  };

  const handleSaveItem = () => {
    if (!formData.name?.trim()) return onNotify?.('Nama hidangan wajib diisi!', 'error');
    if (!formData.price || formData.price <= 0) return onNotify?.('Harga jual harus lebih dari 0!', 'error');

    if (editingId) {
      const updatedMenu = menu.map(item => 
        item.id === editingId ? { ...item, ...formData } as MenuItem : item
      );
      onUpdateMenu(updatedMenu);
      onNotify?.(`${formData.name} berhasil diperbarui.`, 'success');
    } else {
      const newItem: MenuItem = {
        id: Math.random().toString(36).substr(2, 9),
        name: formData.name || 'Menu Baru',
        category: formData.category || categories[0] || 'Uncategorized',
        price: Number(formData.price) || 0,
        cost: Number(formData.cost) || 0,
        description: formData.description || '',
        salesCount: 0,
        imageUrl: formData.imageUrl || 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&q=80&w=400',
        recipe: formData.recipe || []
      };
      onUpdateMenu([...menu, newItem]);
      onNotify?.(`${newItem.name} berhasil disimpan.`, 'success');
    }

    setIsModalOpen(false);
    setEditingId(null);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setFormData({ ...formData, imageUrl: reader.result as string });
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Katalog Menu</h2>
          <p className="text-sm text-slate-500 font-medium mt-1">Kelola hidangan katering dan pantau komposisi bahan.</p>
        </div>
        <button 
          onClick={handleOpenAddModal}
          className="bg-slate-900 hover:bg-slate-800 text-white px-8 py-3 rounded-2xl flex items-center justify-center gap-2 transition-all shadow-xl shadow-slate-200 font-black text-[10px] uppercase tracking-widest border border-slate-700"
        >
          <Plus size={18} /> Tambah Menu Baru
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {menu.map((item) => (
          <div key={item.id} className="bg-white rounded-[2.5rem] border border-slate-100 overflow-hidden flex flex-col group hover:shadow-xl transition-all duration-300">
            <div className="h-48 overflow-hidden relative">
              <img src={item.imageUrl} alt={item.name} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
              <div className="absolute top-4 left-4 bg-white/90 backdrop-blur px-3 py-1.5 rounded-xl text-[8px] font-black uppercase tracking-widest shadow-lg border border-slate-100">
                {item.category}
              </div>

              {/* Halal Badge Preview */}
              <div className="absolute top-4 right-4 z-10">
                <div className="bg-white/90 backdrop-blur-md border border-slate-200 px-2 py-1 rounded-lg shadow-md flex items-center gap-1.5">
                  <div className="w-4 h-4 bg-emerald-500 rounded-full flex items-center justify-center text-white">
                    <Check size={10} strokeWidth={4} />
                  </div>
                  <span className="text-[7px] font-black uppercase tracking-widest text-slate-800">Halal</span>
                </div>
              </div>
            </div>
            <div className="p-6 flex-1 flex flex-col">
              <div className="flex justify-between items-start mb-2">
                <h3 className="font-black text-slate-900 tracking-tight">{item.name}</h3>
                <span className="text-indigo-600 font-black">Rp {item.price.toLocaleString()}</span>
              </div>
              <p className="text-slate-400 text-[10px] font-medium leading-relaxed mb-6 line-clamp-2 italic">"{item.description}"</p>

              <div className="bg-slate-50 rounded-2xl p-4 border border-slate-100 mt-auto">
                 <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center gap-2"><Box size={10} className="text-amber-500" /> Komposisi Bahan</p>
                 <div className="flex flex-wrap gap-1.5">
                    {item.recipe?.map((r, i) => (
                      <span key={i} className="text-[8px] font-bold bg-white px-2 py-0.5 rounded-lg border border-slate-200 text-slate-500">{r.name}</span>
                    ))}
                    {(!item.recipe || item.recipe.length === 0) && (
                      <span className="text-[8px] text-slate-300 italic">Resep belum diatur</span>
