                 >
                   Edit Detail
                 </button>
                 <button className="p-3 bg-rose-50 text-rose-400 hover:bg-rose-500 hover:text-white rounded-xl transition-all border border-rose-100" onClick={() => onUpdateMenu(menu.filter(m => m.id !== item.id))}>
                   <Trash2 size={16} />
                 </button>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* ADD/EDIT MODAL WITH AI ASSISTANT */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setIsModalOpen(false)}></div>
          <div className="bg-white rounded-[3rem] w-full max-w-6xl overflow-hidden shadow-2xl relative z-10 animate-in zoom-in-95 duration-300 flex flex-col max-h-[90vh]">
            <div className="p-8 border-b border-slate-50 flex justify-between items-center bg-slate-50/50">
              <div>
                <h3 className="text-2xl font-black text-slate-900">{editingId ? 'Edit Detail Menu' : 'Konfigurasi Menu Baru'}</h3>
                <p className="text-sm text-slate-400 font-medium">Lengkapi detail hidangan dan gunakan asisten AI untuk strategi.</p>
