  onBackToAdmin: () => void;
  onPlaceOrder?: (orderData: { items: string[], total: number }) => void;
}

const PublicMenu: React.FC<PublicMenuProps> = ({ menu, settings, categories, onBackToAdmin, onPlaceOrder }) => {
  const [activeCategory, setActiveCategory] = useState<string>('Semua');
  const [searchQuery, setSearchQuery] = useState('');
  const [cart, setCart] = useState<{ [key: string]: number }>({});
  const [selectedItem, setSelectedItem] = useState<MenuItem | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  const displayCategories = ['Semua', ...categories];

  const filteredMenu = useMemo(() => {
    return menu.filter(item => {
      const matchesCategory = activeCategory === 'Semua' || item.category === activeCategory;
      const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase());
      return matchesCategory && matchesSearch;
    });
  }, [menu, activeCategory, searchQuery]);

  const addToCart = (id: string, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    setCart(prev => ({ ...prev, [id]: (prev[id] || 0) + 1 }));
  };

  const removeFromCart = (id: string, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    setCart(prev => {
      const newCart = { ...prev };
      const currentQty = newCart[id];
      if (typeof currentQty === 'number' && currentQty > 1) {
        newCart[id] = currentQty - 1;
      } else {
        delete newCart[id];
      }
      return newCart;
    });
  };

  const cartTotal = (Object.entries(cart) as [string, number][]).reduce((total, [id, qty]) => {
    const item = menu.find(m => m.id === id);
    return total + (item ? item.price * qty : 0);
  }, 0);

  const cartCount = (Object.values(cart) as number[]).reduce((a: number, b: number) => a + b, 0);

  const handleOrderWhatsApp = () => {
    if (isProcessing) return;
    setIsProcessing(true);
    const itemsList = (Object.entries(cart) as [string, number][])
      .map(([id, qty]) => {
        const item = menu.find(m => m.id === id);
        return item ? `${item.name} (${qty}x)` : '';
      })
      .filter(text => text !== '');

    if (onPlaceOrder) onPlaceOrder({ items: itemsList, total: cartTotal });

    const cartItemsText = itemsList.map(text => `• ${text}`).join('\n');
    const message = `Halo ${settings.storeName},\n\nSaya tertarik dengan menu katering Anda:\n\n${cartItemsText}\n\nTotal Estimasi: Rp ${cartTotal.toLocaleString()}\n\nAlamat Saya: [Tulis Alamat]\n\nMohon informasi ketersediaan untuk tanggal katering saya. Terima kasih!`;

    setTimeout(() => {
      window.open(`https://wa.me/${settings.whatsappNumber}?text=${encodeURIComponent(message)}`, '_blank');
      setIsProcessing(false);
      setCart({});
    }, 1500);
  };

  return (
    <div className="min-h-screen bg-[#fafafb] text-slate-900 pb-40 font-sans selection:bg-emerald-100 selection:text-emerald-900">

      {/* Overlay Processing */}
      {isProcessing && (
        <div className="fixed inset-0 z-[300] bg-slate-900/90 backdrop-blur-xl flex flex-col items-center justify-center text-white text-center p-8 animate-in fade-in duration-300">
           <div className="relative mb-8">
              <Loader2 className="animate-spin text-emerald-400" size={64} />
              <div className="absolute inset-0 flex items-center justify-center">
                 <ShoppingBag size={24} className="text-white" />
              </div>
           </div>
           <h2 className="text-3xl font-black mb-4">Mencatat Pesanan Anda...</h2>
           <p className="text-slate-400 max-w-xs font-medium leading-relaxed italic">"Mohon tunggu sebentar, kami sedang menyiapkan jalur chat prioritas untuk Anda."</p>
        </div>
      )}

      {/* Hero Section */}
      <div className="relative h-[65vh] w-full overflow-hidden">
        <img src="https://images.unsplash.com/photo-1555244162-803834f70033?auto=format&fit=crop&q=80&w=2000" className="w-full h-full object-cover scale-105" alt="Catering Hero" />
        <div className="absolute inset-0 bg-gradient-to-t from-[#fafafb] via-slate-900/60 to-slate-900/30"></div>
        <div className="absolute top-0 left-0 right-0 p-8 flex justify-between items-center z-50">
          <div className="flex items-center gap-4 bg-white/10 backdrop-blur-xl px-5 py-2.5 rounded-[2rem] border border-white/20 shadow-2xl">
            <div className="w-10 h-10 bg-white rounded-2xl flex items-center justify-center text-emerald-600 shadow-xl overflow-hidden ring-4 ring-white/10">
              {settings.logoUrl ? <img src={settings.logoUrl} alt="Logo" className="w-full h-full object-cover" /> : <UtensilsCrossed size={20} />}
            </div>
            <div className="hidden sm:block">
              <span className="font-black text-xs tracking-[0.2em] text-white uppercase block leading-none">{settings.storeName}</span>
              {settings.address && (
                <span className="text-[8px] font-bold text-slate-300 uppercase tracking-widest mt-1 flex items-center gap-1">
                  <MapPin size={8} className="text-emerald-400" /> {settings.address}
                </span>
              )}
            </div>
          </div>
          <button onClick={onBackToAdmin} className="w-12 h-12 bg-white/10 backdrop-blur-xl rounded-2xl flex items-center justify-center text-white border border-white/20 hover:bg-white hover:text-slate-900 transition-all group">
            <Monitor size={20} className="group-hover:scale-110 transition-transform" />
          </button>
        </div>
        <div className="absolute bottom-24 left-0 right-0 px-8 max-w-6xl mx-auto">
          <div className="flex flex-wrap items-center gap-3 mb-6">
            <div className="flex items-center gap-1.5 bg-emerald-500/90 backdrop-blur-md text-white text-[10px] font-black uppercase tracking-[0.2em] px-4 py-1.5 rounded-full shadow-xl border border-emerald-400/30">
              <CheckCircle size={12} /> Certified Hygiene
            </div>
            <div className="flex items-center gap-1.5 bg-amber-500/90 backdrop-blur-md text-white text-[10px] font-black uppercase tracking-[0.2em] px-4 py-1.5 rounded-full shadow-xl border border-amber-400/30">
              <Award size={12} /> Top Rated 2024
            </div>
            {settings.address && (
              <div className="flex items-center gap-1.5 bg-white/20 backdrop-blur-md text-white text-[10px] font-black uppercase tracking-[0.2em] px-4 py-1.5 rounded-full shadow-xl border border-white/20">
                <MapPin size={12} className="text-emerald-400" /> {settings.address.split(',')[0]}
              </div>
            )}
          </div>
          <h1 className="text-5xl md:text-7xl font-black text-white mb-6 leading-[1.1] tracking-tight">Rayakan Momen<br/><span className="text-transparent bg-clip-text bg-gradient-to-r from-emerald-400 to-teal-300">Dengan Kelezatan.</span></h1>
        </div>
      </div>

      <div className="max-w-6xl mx-auto px-8">
        <div className="bg-white rounded-[3rem] shadow-[0_30px_60px_-15px_rgba(0,0,0,0.1)] -mt-16 relative z-30 flex flex-col md:flex-row divide-y md:divide-y-0 md:divide-x divide-slate-100 border border-slate-100">
          <div className="flex-1 p-4 flex items-center gap-4">
            <div className="w-12 h-12 bg-slate-50 rounded-2xl flex items-center justify-center text-slate-400 border border-slate-100"><Search size={22} /></div>
            <input type="text" placeholder="Cari hidangan favorit Anda..." className="flex-1 bg-transparent outline-none text-base font-bold placeholder:text-slate-300" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
          </div>
          {settings.address && (
             <div className="hidden md:flex flex-1 p-4 items-center gap-4 bg-slate-50/30">
               <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center text-emerald-600 border border-slate-100 shadow-sm"><MapPin size={22} /></div>
               <div>
                  <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">Lokasi Kami</p>
                  <p className="text-xs font-bold text-slate-700 truncate max-w-[200px]">{settings.address}</p>
               </div>
             </div>
          )}
        </div>
      </div>

      <div className="max-w-6xl mx-auto px-8 mt-16">
        <div className="flex gap-4 overflow-x-auto pb-4 no-scrollbar">
          {displayCategories.map(cat => (
            <button key={cat} onClick={() => setActiveCategory(cat)} className={`px-10 py-4 rounded-[1.8rem] text-[10px] font-black uppercase tracking-[0.2em] whitespace-nowrap transition-all duration-300 border ${activeCategory === cat ? 'bg-slate-900 text-white border-slate-800 shadow-2xl shadow-slate-200 translate-y-[-2px]' : 'bg-white text-slate-400 border-slate-100 hover:text-emerald-600 hover:bg-emerald-50 hover:border-emerald-100'}`}>{cat}</button>
          ))}
        </div>
      </div>

      <div className="max-w-6xl mx-auto px-8 mt-24 mb-32">
        <div className="flex items-center gap-6 mb-12">
          <h2 className="text-3xl font-black text-slate-800 tracking-tight whitespace-nowrap">Jelajahi Pilihan Menu</h2>
          <div className="h-px bg-slate-200 flex-1"></div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-10">
          {filteredMenu.map(item => (
            <div 
              key={item.id} 
              className="bg-white rounded-[2.8rem] border border-slate-100 overflow-hidden flex flex-col group hover:shadow-[0_40px_80px_-20px_rgba(0,0,0,0.08)] hover:border-emerald-100 transition-all duration-500 cursor-pointer relative"
