    customerName: '',
    type: 'Individual',
    totalPrice: 0,
    items: [],
    deliveryTime: ''
  });

  // Calculate deadline status and urgency level
  const getDeadlineInfo = (order: Order) => {
    if (order.status === 'Delivered' || order.status === 'Cancelled' || !order.deliveryTime) return null;

    const today = new Date().toISOString().split('T')[0];
    if (order.date !== today) return null;

    const now = new Date();
    const [hour, min] = order.deliveryTime.split(':').map(Number);
    const deliveryDate = new Date();
    deliveryDate.setHours(hour, min, 0);

    const diffMs = deliveryDate.getTime() - now.getTime();
    const diffMins = Math.floor(diffMs / (1000 * 60));

    if (diffMins < 0) return { label: 'Terlambat', color: 'text-rose-600 bg-rose-50 border-rose-200', icon: AlertTriangle, urgent: true, progress: 100 };
    if (diffMins <= 60) return { label: `${diffMins}m Lagi`, color: 'text-rose-600 bg-rose-50 border-rose-200', icon: Timer, urgent: true, progress: 90 };
    if (diffMins <= 180) return { label: `${Math.floor(diffMins/60)}j ${diffMins%60}m Lagi`, color: 'text-amber-600 bg-amber-50 border-amber-200', icon: Clock, urgent: false, progress: 60 };

