                  </div>
                </div>

                <div className="space-y-6">
                  <div>
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">Total Nilai Pesanan (Rp)</label>
                    <div className="flex items-center bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 focus-within:ring-4 focus-within:ring-slate-900/5 transition-all">
                      <CreditCard size={18} className="text-emerald-500 mr-4" />
                      <input 
                        type="number" 
                        placeholder="Harga total..." 
                        className="bg-transparent border-none outline-none text-sm w-full font-black text-slate-900"
                        value={newOrder.totalPrice || ''}
                        onChange={(e) => setNewOrder({...newOrder, totalPrice: Number(e.target.value)})}
