                        className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-6 py-5 text-sm font-bold text-slate-700 outline-none focus:ring-4 focus:ring-slate-900/5 transition-all resize-none italic placeholder:text-slate-300"
                        value={newOrder.items?.join(', ')}
