                      ></textarea>
                      <Sparkles size={16} className="absolute bottom-4 right-4 text-indigo-300" />
                    </div>
                  </div>
                </div>
              </div>

              <button 
                onClick={handleSaveOrder}
                className="w-full bg-slate-900 text-white py-6 rounded-3xl font-black text-[11px] uppercase tracking-[0.2em] flex items-center justify-center gap-4 hover:bg-emerald-600 transition-all shadow-2xl shadow-slate-200 border border-slate-800"
              >
                <CheckCircle2 size={24} />
                Simpan & Aktifkan Alarm Deadline
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

