const SalesReport: React.FC<SalesReportProps> = ({ orders, menu }) => {
  const [activeTab, setActiveTab] = useState<'ikhtisar' | 'harian' | 'mingguan' | 'bulanan' | 'tahunan' | 'sift'>('ikhtisar');
  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');

  const getWeekNumber = (d: Date) => {
    d = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
    d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7));
    const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
    return Math.ceil((((d.getTime() - yearStart.getTime()) / 86400000) + 1) / 7);
  };

  const filteredOrdersByDate = useMemo(() => {
    return orders.filter(o => {
      if (!startDate && !endDate) return true;
      const orderDate = new Date(o.date);
      const start = startDate ? new Date(startDate) : new Date('2000-01-01');
      const end = endDate ? new Date(endDate) : new Date('2100-01-01');
      end.setHours(23, 59, 59, 999);
      return orderDate >= start && orderDate <= end;
    });
  }, [orders, startDate, endDate]);

  const stats = useMemo(() => {
    const totalRevenue = filteredOrdersByDate.reduce((acc, o) => acc + o.totalPrice, 0);
    const totalPaid = filteredOrdersByDate.reduce((acc, o) => acc + o.amountPaid, 0);
    const totalReceivables = totalRevenue - totalPaid;
    const totalCost = totalRevenue * 0.4;
    const grossProfit = totalRevenue - totalCost;
    const collectionRate = totalRevenue > 0 ? (totalPaid / totalRevenue) * 100 : 0;

    return { totalRevenue, totalReceivables, grossProfit, totalCost, collectionRate, totalPaid };
  }, [filteredOrdersByDate]);

  const reports = useMemo(() => {
    const daily: any[] = [];
    const weekly: any[] = [];
    const monthly: any[] = [];
    const yearly: any[] = [];

    filteredOrdersByDate.forEach(o => {
      const d = new Date(o.date);
      const dayKey = o.date;
      const weekKey = `Minggu ${getWeekNumber(d)}, ${d.getFullYear()}`;
      const monthKey = d.toLocaleString('id-ID', { month: 'long', year: 'numeric' });
      const yearKey = `${d.getFullYear()}`;

      const processEntry = (arr: any[], key: string, label: string) => {
        let entry = arr.find(x => x.key === key);
        if (!entry) {
          entry = { key, label, revenue: 0, paid: 0, receivables: 0, count: 0, cost: 0 };
          arr.push(entry);
        }
        entry.revenue += o.totalPrice;
        entry.paid += o.amountPaid;
        entry.receivables += (o.totalPrice - o.amountPaid);
        entry.count += 1;
        entry.cost += o.totalPrice * 0.4;
      };

      processEntry(daily, dayKey, dayKey);
      processEntry(weekly, weekKey, weekKey);
      processEntry(monthly, monthKey, monthKey);
      processEntry(yearly, yearKey, yearKey);
    });

    return {
      daily: daily.sort((a, b) => b.key.localeCompare(a.key)),
      weekly: weekly, 
      monthly: monthly,
      yearly: yearly
    };
  }, [filteredOrdersByDate]);

  const TableView = ({ data, title, desc, icon: Icon }: { data: any[], title: string, desc: string, icon: any }) => (
    <div className="bg-white rounded-[3rem] p-10 border border-slate-100 shadow-sm animate-in fade-in slide-in-from-bottom-4">
      <div className="flex items-center justify-between mb-10">
        <div>
          <h3 className="text-2xl font-black text-slate-900 tracking-tight">{title}</h3>
          <p className="text-sm text-slate-400 font-medium mt-1">{desc}</p>
        </div>
        <div className="w-14 h-14 bg-slate-50 rounded-2xl flex items-center justify-center text-slate-300">
          <Icon size={28} />
        </div>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full text-left border-separate border-spacing-y-4">
          <thead>
            <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
              <th className="pb-4 pl-6">Periode</th>
              <th className="pb-4">Vol. Pesanan</th>
              <th className="pb-4">Nilai Pesanan</th>
              <th className="pb-4">Uang Masuk</th>
              <th className="pb-4 text-right pr-6">Hutang</th>
            </tr>
          </thead>
          <tbody>
            {data.map((d, i) => (
              <tr key={i} className="group hover:bg-slate-50 transition-all">
                <td className="py-6 pl-6 bg-slate-50 border-y border-l border-slate-100 rounded-l-2xl group-hover:bg-white transition-all">
                  <p className="text-sm font-black text-slate-800">{d.label}</p>
                </td>
                <td className="py-6 bg-slate-50 border-y border-slate-100 group-hover:bg-white transition-all font-bold text-slate-500 text-xs">
                  {d.count} Pesanan
                </td>
                <td className="py-6 bg-slate-50 border-y border-slate-100 group-hover:bg-white transition-all font-black text-slate-900 text-sm">
                  Rp {d.revenue.toLocaleString()}
                </td>
                <td className="py-6 bg-slate-50 border-y border-slate-100 group-hover:bg-white transition-all font-black text-emerald-600 text-sm">
                  Rp {d.paid.toLocaleString()}
                </td>
                <td className="py-6 pr-6 bg-slate-50 border-y border-r border-slate-100 rounded-r-2xl group-hover:bg-white transition-all text-right">
                   <p className={`text-sm font-black ${d.receivables > 0 ? 'text-rose-500' : 'text-slate-300'}`}>
                    Rp {d.receivables.toLocaleString()}
                   </p>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );

  return (
    <div className="space-y-10 animate-in fade-in slide-in-from-bottom-8 duration-1000 pb-20">
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-8 border-b border-slate-100 pb-8">
        <div>
          <div className="flex items-center gap-2 mb-2">
            <div className="w-1.5 h-1.5 rounded-full bg-indigo-500 animate-pulse"></div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em]">Audit Finansial Katering</p>
          </div>
          <h2 className="text-4xl font-black text-slate-900 tracking-tight">Performa Penjualan & Kas</h2>
          <p className="text-sm text-slate-500 font-medium mt-1">Pantau omzet riil dan piutang pelanggan secara akurat.</p>
