    });
    addNotification(`Selamat datang kembali, ${name}!`, 'success');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setIsProfileDropdownOpen(false);
  };

  const upcomingDeadlines = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    const now = new Date();
    return orders.filter(o => {
      if (o.status === 'Delivered' || o.status === 'Cancelled' || o.date !== today || !o.deliveryTime) return false;
      const [hour, min] = o.deliveryTime.split(':').map(Number);
      const deliveryDate = new Date();
      deliveryDate.setHours(hour, min, 0);
      const diffHrs = (deliveryDate.getTime() - now.getTime()) / (1000 * 60 * 60);
      return diffHrs > -1 && diffHrs <= 3;
    }).sort((a, b) => (a.deliveryTime || '').localeCompare(b.deliveryTime || ''));
  }, [orders]);

