import React, { useState, useMemo } from 'react';
import { 
  Plus, Search, MoreHorizontal, X, Check, 
  User, CreditCard, Clock, Truck, CheckCircle2, 
  Building2, User2, Calendar, Filter, Wallet, ArrowRight,
  AlertCircle, Banknote, Sun, Moon, SunMedium
} from 'lucide-react';
import { Order, ShiftType } from '../types';

interface OrdersListProps {
  orders: Order[];
  onAddOrder: (order: Order) => void;
  onUpdateOrder: (orderId: string, updates: Partial<Order>) => void;
  onNotify?: (message: string, type: 'success' | 'error' | 'warning') => void;
  currentShift?: ShiftType;
}

const OrdersList: React.FC<OrdersListProps> = ({ orders, onAddOrder, onUpdateOrder, onNotify, currentShift }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  const [newOrder, setNewOrder] = useState<Partial<Order>>({
    customerName: '',
    type: 'Individual',
    totalPrice: 0,
    amountPaid: 0,
    items: [],
    deliveryTime: ''
  });

  const filteredOrders = useMemo(() => {
    return orders
      .filter(o => 
        o.customerName.toLowerCase().includes(searchQuery.toLowerCase()) ||
        o.id.includes(searchQuery)
      )
      .sort((a, b) => b.id.localeCompare(a.id));
  }, [orders, searchQuery]);

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Delivered': return 'bg-emerald-100 text-emerald-700 border-emerald-200';
      case 'Confirmed': return 'bg-blue-100 text-blue-700 border-blue-200';
      case 'Pending': return 'bg-amber-100 text-amber-700 border-amber-200';
      case 'Cancelled': return 'bg-rose-100 text-rose-700 border-rose-200';
      default: return 'bg-slate-100 text-slate-600 border-slate-200';
    }
  };

  const getPaymentBadge = (order: Order) => {
    if (order.paymentStatus === 'Paid') return 'bg-emerald-50 text-emerald-600 border-emerald-100';
    if (order.paymentStatus === 'Partial') return 'bg-amber-50 text-amber-600 border-amber-100';
    return 'bg-rose-50 text-rose-600 border-rose-100';
  };

  const handleSaveOrder = () => {
    if (!newOrder.customerName?.trim()) return onNotify?.('Nama pelanggan wajib diisi!', 'error');
    if (!newOrder.totalPrice || newOrder.totalPrice <= 0) return onNotify?.('Total harga harus valid!', 'error');

    const total = newOrder.totalPrice || 0;
    const paid = newOrder.amountPaid || 0;

    let paymentStatus: Order['paymentStatus'] = 'Unpaid';
    if (paid >= total) paymentStatus = 'Paid';
    else if (paid > 0) paymentStatus = 'Partial';

    const orderToSave: Order = {
      id: Math.floor(1000 + Math.random() * 9000).toString(),
      customerName: newOrder.customerName || '',
      type: newOrder.type || 'Individual',
      totalPrice: total,
      amountPaid: paid,
      items: newOrder.items || [],
      deliveryTime: newOrder.deliveryTime || '',
      date: new Date().toISOString().split('T')[0],
      status: 'Pending',
      paymentStatus: paymentStatus,
      shift: currentShift || 'Pagi'
    };

    onAddOrder(orderToSave);
    setIsModalOpen(false);
    onNotify?.(`Pesanan #${orderToSave.id} berhasil dicatat pada Sift ${orderToSave.shift}.`, 'success');

    setNewOrder({ customerName: '', type: 'Individual', totalPrice: 0, amountPaid: 0, items: [], deliveryTime: '' });
  };

  const handleQuickPay = (order: Order) => {
    onUpdateOrder(order.id, { 
      paymentStatus: 'Paid', 
      amountPaid: order.totalPrice 
    });
    onNotify?.(`Pembayaran #${order.id} telah lunas.`, 'success');
  };

  return (
    <div className="bg-white rounded-[2rem] p-6 border border-slate-100 shadow-sm animate-in fade-in duration-500">
      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-8">
        <div>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">Manajemen Pesanan & Kas</h2>
          <p className="text-xs text-slate-400 font-medium">Pantau status produksi dan arus pelunasan katering.</p>
        </div>

        <div className="flex gap-3 w-full md:w-auto">
          <div className="relative flex-1 md:w-64">
            <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
            <input 
              type="text" 
              placeholder="Cari pesanan..."
              className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-slate-200 transition-all"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <button 
            onClick={() => setIsModalOpen(true)}
            className="bg-slate-900 text-white px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center gap-2 hover:bg-emerald-600 transition-all shadow-lg shadow-slate-100"
          >
            <Plus size={16} /> Input Pesanan
          </button>
        </div>
      </div>

      {/* Table */}
      <div className="overflow-x-auto">
        <table className="w-full text-left">
          <thead>
            <tr className="text-slate-400 text-[10px] font-black uppercase tracking-widest border-b border-slate-50">
              <th className="pb-4 pl-2">ID & Pelanggan</th>
              <th className="pb-4">Status & Sift</th>
              <th className="pb-4">Ringkasan Biaya</th>
              <th className="pb-4">Status Bayar</th>
              <th className="pb-4 text-right pr-2">Aksi Cepat</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {filteredOrders.map((o) => {
              const debt = o.totalPrice - o.amountPaid;
              return (
                <tr key={o.id} className="group hover:bg-slate-50/50 transition-colors">
                  <td className="py-5 pl-2">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-xl bg-slate-50 flex items-center justify-center text-slate-400 border border-slate-100">
                        {o.type === 'Corporate' ? <Building2 size={18} /> : <User2 size={18} />}
                      </div>
                      <div>
                        <p className="text-sm font-bold text-slate-800">#{o.id} {o.customerName}</p>
                        <p className="text-[10px] text-slate-400 font-medium">{o.type}</p>
                      </div>
                    </div>
                  </td>
                  <td className="py-5">
                    <div className="flex flex-col gap-1.5">
                      <div className="flex items-center gap-2">
                         <span className={`px-2 py-0.5 rounded-lg text-[8px] font-black uppercase tracking-widest border w-fit ${getStatusColor(o.status)}`}>
                          {o.status}
                        </span>
                        <span className="text-[8px] font-black text-slate-400 uppercase flex items-center gap-1">
                          {o.shift === 'Pagi' ? <Sun size={10} className="text-amber-500" /> : o.shift === 'Siang' ? <SunMedium size={10} className="text-sky-500" /> : <Moon size={10} className="text-indigo-500" />}
                          {o.shift}
                        </span>
                      </div>
                      <p className="text-[10px] text-slate-500 font-bold flex items-center gap-1.5">
                        <Clock size={12} /> {o.deliveryTime || '--:--'}
                      </p>
                    </div>
                  </td>
                  <td className="py-5">
                    <div className="space-y-0.5">
                      <p className="text-xs font-black text-slate-900">Rp {o.totalPrice.toLocaleString()}</p>
                      {debt > 0 && (
                        <p className="text-[9px] font-bold text-rose-500">Hutang: Rp {debt.toLocaleString()}</p>
                      )}
                    </div>
                  </td>
                  <td className="py-5">
                    <div className="flex flex-col gap-1">
                      <span className={`px-2 py-0.5 rounded-lg text-[8px] font-black uppercase tracking-widest border w-fit ${getPaymentBadge(o)}`}>
                        {o.paymentStatus}
                      </span>
                      <p className="text-[9px] font-bold text-slate-400">Masuk: Rp {o.amountPaid.toLocaleString()}</p>
                    </div>
                  </td>
                  <td className="py-5 pr-2 text-right">
                    <div className="flex items-center justify-end gap-2">
                      {o.paymentStatus !== 'Paid' && (
                        <button 
                          onClick={() => handleQuickPay(o)}
                          className="p-2 text-emerald-500 hover:bg-emerald-50 rounded-lg transition-colors border border-transparent hover:border-emerald-100"
                          title="Lunas"
                        >
                          <Banknote size={18} />
                        </button>
                      )}
                      {o.status === 'Pending' && (
                        <button 
                          onClick={() => onUpdateOrder(o.id, { status: 'Confirmed' })}
                          className="p-2 text-blue-500 hover:bg-blue-50 rounded-lg transition-colors border border-transparent hover:border-blue-100"
                          title="Konfirmasi"
                        >
                          <Check size={18} />
                        </button>
                      )}
                      {o.status === 'Confirmed' && (
                        <button 
                          onClick={() => onUpdateOrder(o.id, { status: 'Delivered' })}
                          className="p-2 text-indigo-500 hover:bg-indigo-50 rounded-lg transition-colors border border-transparent hover:border-indigo-100"
                          title="Kirim"
                        >
                          <Truck size={18} />
                        </button>
                      )}
                      <button className="p-2 text-slate-300 hover:text-slate-600 rounded-lg">
                        <MoreHorizontal size={18} />
                      </button>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
        {filteredOrders.length === 0 && (
          <div className="py-12 text-center text-slate-300 italic text-sm">Belum ada data pesanan.</div>
        )}
      </div>

      {/* Modal Input dengan Detail Finansial */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsModalOpen(false)}></div>
          <div className="bg-white rounded-[2.5rem] w-full max-w-xl overflow-hidden shadow-2xl relative z-10 animate-in zoom-in-95 duration-300">
            <div className="p-8 pb-4 flex justify-between items-center border-b border-slate-50">
              <h3 className="text-xl font-black text-slate-800">Pencatatan Pesanan Baru</h3>
              <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-slate-50 rounded-full text-slate-400"><X size={20} /></button>
            </div>

            <div className="p-8 space-y-6">
              <div className="bg-amber-50 border border-amber-100 p-4 rounded-2xl flex items-center gap-3">
                 <div className="p-2 bg-white rounded-xl text-amber-500 shadow-sm">
                   {currentShift === 'Pagi' ? <Sun size={18} /> : currentShift === 'Siang' ? <SunMedium size={18} /> : <Moon size={18} />}
                 </div>
                 <div>
                   <p className="text-[10px] font-black uppercase tracking-widest text-amber-600 leading-none mb-1">Pencatatan Sift Otomatis</p>
                   <p className="text-xs font-bold text-amber-700">Petugas sedang bertugas di Sift {currentShift || 'Pagi'}</p>
                 </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-4">
                  <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 mb-1.5 block">Nama Pelanggan</label>
                    <div className="relative">
                      <User size={14} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" />
                      <input 
                        type="text" 
                        className="w-full bg-slate-50 border border-slate-200 rounded-xl pl-10 pr-4 py-2.5 text-sm font-bold outline-none"
                        placeholder="Contoh: Bpk. Budi"
                        value={newOrder.customerName}
                        onChange={(e) => setNewOrder({...newOrder, customerName: e.target.value})}
                      />
                    </div>
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="text-[10px] font-black uppercase text-slate-400 mb-1.5 block">Jam Kirim</label>
                      <input 
                        type="time" 
                        className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-sm font-bold outline-none"
                        value={newOrder.deliveryTime}
                        onChange={(e) => setNewOrder({...newOrder, deliveryTime: e.target.value})}
                      />
                    </div>
                    <div>
                      <label className="text-[10px] font-black uppercase text-slate-400 mb-1.5 block">Tipe</label>
                      <select 
                        className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-sm font-bold outline-none appearance-none"
                        value={newOrder.type}
                        onChange={(e) => setNewOrder({...newOrder, type: e.target.value as any})}
                      >
                        <option value="Individual">Individual</option>
                        <option value="Corporate">Corporate</option>
                        <option value="Wedding">Wedding</option>
                      </select>
                    </div>
                  </div>
                </div>

                <div className="space-y-4 bg-slate-50 p-6 rounded-2xl border border-slate-100">
                  <h4 className="text-[9px] font-black uppercase tracking-widest text-slate-400 mb-2 flex items-center gap-2">
                    <Wallet size={12} className="text-indigo-500" /> Rincian Finansial
                  </h4>
                  <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 mb-1 block">Total Harga (Rp)</label>
                    <input 
                      type="number" 
                      className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2 text-sm font-black outline-none"
                      value={newOrder.totalPrice || ''}
                      onChange={(e) => setNewOrder({...newOrder, totalPrice: Number(e.target.value)})}
                    />
                  </div>
                  <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 mb-1 block">Uang Muka / Terbayar (Rp)</label>
                    <input 
                      type="number" 
                      className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-emerald-600 outline-none"
                      value={newOrder.amountPaid || ''}
                      onChange={(e) => setNewOrder({...newOrder, amountPaid: Number(e.target.value)})}
                    />
                  </div>
                  <div className="pt-2 border-t border-slate-200">
                    <div className="flex justify-between items-center text-[10px] font-black text-rose-500 uppercase">
                      <span>Sisa Hutang:</span>
                      <span>Rp {((newOrder.totalPrice || 0) - (newOrder.amountPaid || 0)).toLocaleString()}</span>
                    </div>
                  </div>
                </div>
              </div>

              <button 
                onClick={handleSaveOrder}
                className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] hover:bg-emerald-600 shadow-xl shadow-slate-200 transition-all flex items-center justify-center gap-3"
              >
                <CheckCircle2 size={18} /> Simpan Pesanan & Update Kas
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

