const SalesReport: React.FC<SalesReportProps> = ({ orders, menu }) => {
  const [activeTab, setActiveTab] = useState<'ikhtisar' | 'harian' | 'mingguan' | 'bulanan' | 'tahunan' | 'sift'>('ikhtisar');
  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');

  const getWeekNumber = (d: Date) => {
    const date = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
    date.setUTCDate(date.getUTCDate() + 4 - (date.getUTCDay() || 7));
    const yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1));
    return Math.ceil((((date.getTime() - yearStart.getTime()) / 86400000) + 1) / 7);
  };

  const filteredOrdersByDate = useMemo(() => {
    return orders.filter(o => {
      if (!startDate && !endDate) return true;
      const orderDate = new Date(o.date);
      const start = startDate ? new Date(startDate) : new Date('2000-01-01');
      const end = endDate ? new Date(endDate) : new Date('2100-01-01');
      end.setHours(23, 59, 59, 999);
      return orderDate >= start && orderDate <= end;
    });
  }, [orders, startDate, endDate]);

  const stats = useMemo(() => {
    const totalRevenue = filteredOrdersByDate.reduce((acc, o) => acc + o.totalPrice, 0);
    const totalPaid = filteredOrdersByDate.reduce((acc, o) => acc + o.amountPaid, 0);
    const totalReceivables = totalRevenue - totalPaid;
    const totalCost = totalRevenue * 0.4;
    const grossProfit = totalRevenue - totalCost;
    const collectionRate = totalRevenue > 0 ? (totalPaid / totalRevenue) * 100 : 0;

    return { totalRevenue, totalReceivables, grossProfit, totalCost, collectionRate, totalPaid };
  }, [filteredOrdersByDate]);

  const reports = useMemo(() => {
    const daily: any[] = [];
    const weekly: any[] = [];
    const monthly: any[] = [];
    const yearly: any[] = [];
    const shift: any[] = [];

    filteredOrdersByDate.forEach(o => {
      const d = new Date(o.date);
      const dayKey = o.date;
      const weekKey = `Minggu ${getWeekNumber(d)}, ${d.getFullYear()}`;
      const monthKey = d.toLocaleString('id-ID', { month: 'long', year: 'numeric' });
      const yearKey = `${d.getFullYear()}`;
      const shiftKey = o.shift || 'Pagi';

      const processEntry = (arr: any[], key: string, label: string) => {
        let entry = arr.find(x => x.key === key);
        if (!entry) {
          entry = { key, label, revenue: 0, paid: 0, receivables: 0, count: 0, cost: 0 };
          arr.push(entry);
        }
        entry.revenue += o.totalPrice;
        entry.paid += o.amountPaid;
        entry.receivables += (o.totalPrice - o.amountPaid);
        entry.count += 1;
        entry.cost += o.totalPrice * 0.4;
      };

      processEntry(daily, dayKey, dayKey);
      processEntry(weekly, weekKey, weekKey);
      processEntry(monthly, monthKey, monthKey);
      processEntry(yearly, yearKey, yearKey);
      processEntry(shift, shiftKey, `Sift ${shiftKey}`);
    });

    return {
      daily: daily.sort((a, b) => b.key.localeCompare(a.key)),
      weekly: weekly, 
      monthly: monthly,
      yearly: yearly,
      shift: shift
    };
  }, [filteredOrdersByDate]);

  const handleDownloadCSV = () => {
    let dataToExport = [];
    let fileName = "Laporan_Katering";

    switch(activeTab) {
      case 'harian': dataToExport = reports.daily; fileName += "_Harian"; break;
      case 'mingguan': dataToExport = reports.weekly; fileName += "_Mingguan"; break;
      case 'bulanan': dataToExport = reports.monthly; fileName += "_Bulanan"; break;
      case 'tahunan': dataToExport = reports.yearly; fileName += "_Tahunan"; break;
      case 'sift': dataToExport = reports.shift; fileName += "_Audit_Sift"; break;
      default: 
        dataToExport = reports.daily;
        fileName += "_Audit_Kas";
    }

    if (dataToExport.length === 0) {
      alert("Tidak ada data untuk periode ini.");
      return;
    }

    const headers = ["Periode/Sift", "Jumlah Pesanan", "Total Nilai Pesanan", "Kas Masuk", "Piutang"];
    const csvRows = [
      headers.join(","),
      ...dataToExport.map(row => [
        `"${row.label}"`,
        row.count,
        row.revenue,
        row.paid,
        row.receivables
      ].join(","))
    ];

    const blob = new Blob([csvRows.join("\n")], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `${fileName}_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const getShiftIcon = (shiftLabel: string) => {
    if (shiftLabel.includes('Pagi')) return <Sun size={18} className="text-amber-500" />;
    if (shiftLabel.includes('Siang')) return <SunMedium size={18} className="text-sky-500" />;
    if (shiftLabel.includes('Malam')) return <Moon size={18} className="text-indigo-500" />;
    return <Clock size={18} />;
  };

  const TableView = ({ data, title, desc, icon: Icon, isShift = false }: { data: any[], title: string, desc: string, icon: any, isShift?: boolean }) => (
    <div className="bg-white rounded-[3rem] p-10 border border-slate-100 shadow-sm animate-in fade-in slide-in-from-bottom-4">
      <div className="flex items-center justify-between mb-10">
        <div>
          <h3 className="text-2xl font-black text-slate-900 tracking-tight">{title}</h3>
          <p className="text-sm text-slate-400 font-medium mt-1">{desc}</p>
        </div>
        <div className="w-14 h-14 bg-slate-50 rounded-2xl flex items-center justify-center text-slate-300">
