                  </div>
                </td>
                <td className="py-6 bg-slate-50 border-y border-slate-100 group-hover:bg-white transition-all font-bold text-slate-500 text-xs">
                  {d.count} Pesanan
                </td>
                <td className="py-6 bg-slate-50 border-y border-slate-100 group-hover:bg-white transition-all font-black text-slate-900 text-sm">
                  Rp {d.revenue.toLocaleString()}
