                <td className="py-6 bg-slate-50 border-y border-slate-100 group-hover:bg-white transition-all font-black text-emerald-600 text-sm">
                  Rp {d.paid.toLocaleString()}
                </td>
                <td className="py-6 pr-6 bg-slate-50 border-y border-r border-slate-100 rounded-r-2xl group-hover:bg-white transition-all text-right">
                   <p className={`text-sm font-black ${d.receivables > 0 ? 'text-rose-500' : 'text-slate-300'}`}>
                    Rp {d.receivables.toLocaleString()}
                   </p>
