                    </div>
                  </td>
                  <td className="py-5">
                    <div className="space-y-0.5">
                      <p className="text-xs font-black text-slate-900">Rp {o.totalPrice.toLocaleString()}</p>
                      <div className="flex items-center gap-1">
                        <span className={`px-1.5 py-0.5 rounded text-[7px] font-black uppercase tracking-widest border ${getPaymentBadge(o)}`}>{o.paymentStatus}</span>
                        {debt > 0 && <span className="text-[8px] font-bold text-rose-500">-Rp {debt.toLocaleString()}</span>}
                      </div>
                    </div>
                  </td>
                  <td className="py-5">
                    <div className="flex items-center gap-2">
                       <div className="w-6 h-6 rounded-full bg-slate-100 flex items-center justify-center text-[10px] font-black text-slate-400 border border-slate-200">
                        {o.recordedBy?.charAt(0)}
                       </div>
                       <p className="text-[10px] font-black text-slate-600 uppercase tracking-tight">{o.recordedBy || 'System'}</p>
                    </div>
                  </td>
                  <td className="py-5 pr-2 text-right">
                    <div className="flex items-center justify-end gap-2">
                      {o.paymentStatus !== 'Paid' && (
                        <button onClick={() => handleQuickPay(o)} className="p-2 text-emerald-500 hover:bg-emerald-50 rounded-lg transition-colors border border-transparent hover:border-emerald-100" title="Lunas">
                          <Banknote size={18} />
                        </button>
                      )}
                      {o.status === 'Pending' && (
                        <button onClick={() => onUpdateOrder(o.id, { status: 'Confirmed' })} className="p-2 text-blue-500 hover:bg-blue-50 rounded-lg transition-colors border border-transparent hover:border-blue-100" title="Konfirmasi">
                          <Check size={18} />
                        </button>
                      )}
                      <button className="p-2 text-slate-300 hover:text-slate-600 rounded-lg">
                        <MoreHorizontal size={18} />
                      </button>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
        {filteredOrders.length === 0 && (
          <div className="py-12 text-center text-slate-300 italic text-sm">Belum ada data pesanan.</div>
        )}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsModalOpen(false)}></div>
          <div className="bg-white rounded-[2.5rem] w-full max-w-xl overflow-hidden shadow-2xl relative z-10 animate-in zoom-in-95 duration-300">
            <div className="p-8 pb-4 flex justify-between items-center border-b border-slate-50">
              <h3 className="text-xl font-black text-slate-800">Pencatatan Pesanan Baru</h3>
              <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-slate-50 rounded-full text-slate-400"><X size={20} /></button>
            </div>

            <div className="p-8 space-y-6">
              <div className="bg-slate-50 border border-slate-100 p-4 rounded-2xl flex items-center justify-between">
                 <div className="flex items-center gap-3">
                    <div className="p-2 bg-white rounded-xl text-indigo-500 shadow-sm">
                      <User size={18} />
                    </div>
                    <div>
                      <p className="text-[10px] font-black uppercase tracking-widest text-slate-400 leading-none mb-1">Admin Pencatat</p>
                      <p className="text-xs font-black text-slate-800 uppercase tracking-tight">{currentAdminName || 'Sistem'}</p>
                    </div>
                 </div>
                 <div className="flex items-center gap-3 border-l border-slate-200 pl-6">
                    <div className="p-2 bg-white rounded-xl text-amber-500 shadow-sm">
                      {currentShift === 'Pagi' ? <Sun size={18} /> : currentShift === 'Siang' ? <SunMedium size={18} /> : <Moon size={18} />}
                    </div>
                    <div>
                      <p className="text-[10px] font-black uppercase tracking-widest text-amber-600 leading-none mb-1">Sift Aktif</p>
                      <p className="text-xs font-bold text-amber-700">{currentShift || 'Pagi'}</p>
                    </div>
                 </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-4">
                  <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 mb-1.5 block">Nama Pelanggan</label>
                    <input 
                      type="text" 
                      className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-sm font-bold outline-none"
                      placeholder="Contoh: Bpk. Budi"
                      value={newOrder.customerName}
                      onChange={(e) => setNewOrder({...newOrder, customerName: e.target.value})}
                    />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="text-[10px] font-black uppercase text-slate-400 mb-1.5 block">Jam Kirim</label>
                      <input type="time" className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-sm font-bold outline-none" value={newOrder.deliveryTime} onChange={(e) => setNewOrder({...newOrder, deliveryTime: e.target.value})} />
                    </div>
                    <div>
                      <label className="text-[10px] font-black uppercase text-slate-400 mb-1.5 block">Tipe</label>
                      <select className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-sm font-bold outline-none appearance-none" value={newOrder.type} onChange={(e) => setNewOrder({...newOrder, type: e.target.value as any})}>
                        <option value="Individual">Individual</option>
                        <option value="Corporate">Corporate</option>
                        <option value="Wedding">Wedding</option>
                      </select>
                    </div>
                  </div>
