import React, { useState, useMemo } from 'react';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
} from 'recharts';
import { 
  TrendingUp, ShoppingBag, Calendar, Activity,
  Wallet, AlertCircle, Calculator, FileDown, Clock, Sun, Moon, SunMedium,
  Banknote, CheckCircle2
} from 'lucide-react';
import { Order, MenuItem } from '../types';

interface SalesReportProps {
  orders: Order[];
  menu: MenuItem[];
}

const CustomTooltip = ({ active, payload, label }: any) => {
  if (active && payload && payload.length) {
    return (
      <div className="bg-white/90 backdrop-blur-md p-4 rounded-2xl shadow-2xl border border-slate-100 animate-in zoom-in-95 duration-200">
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{label}</p>
        <p className="text-sm font-black text-indigo-600">Rp {payload[0].value.toLocaleString()}</p>
        <div className="mt-2 pt-2 border-t border-slate-50">
          <p className="text-[9px] font-bold text-slate-400">Total Nilai Pesanan</p>
        </div>
      </div>
    );
  }
  return null;
};

const SalesReport: React.FC<SalesReportProps> = ({ orders, menu }) => {
  const [activeTab, setActiveTab] = useState<'ikhtisar' | 'harian' | 'mingguan' | 'bulanan' | 'tahunan' | 'sift'>('ikhtisar');
  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');

  const getWeekNumber = (d: Date) => {
    const date = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
    date.setUTCDate(date.getUTCDate() + 4 - (date.getUTCDay() || 7));
    const yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1));
    return Math.ceil((((date.getTime() - yearStart.getTime()) / 86400000) + 1) / 7);
  };

  const filteredOrdersByDate = useMemo(() => {
    return orders.filter(o => {
      if (!startDate && !endDate) return true;
      const orderDate = new Date(o.date);
      const start = startDate ? new Date(startDate) : new Date('2000-01-01');
      const end = endDate ? new Date(endDate) : new Date('2100-01-01');
      end.setHours(23, 59, 59, 999);
      return orderDate >= start && orderDate <= end;
    });
  }, [orders, startDate, endDate]);

  const stats = useMemo(() => {
    const totalRevenue = filteredOrdersByDate.reduce((acc, o) => acc + o.totalPrice, 0);
    const totalPaid = filteredOrdersByDate.reduce((acc, o) => acc + o.amountPaid, 0);
    const totalReceivables = totalRevenue - totalPaid;
    const collectionRate = totalRevenue > 0 ? (totalPaid / totalRevenue) * 100 : 0;

    return { totalRevenue, totalReceivables, totalPaid, collectionRate };
  }, [filteredOrdersByDate]);

  const reports = useMemo(() => {
    const daily: any[] = [];
    const weekly: any[] = [];
    const monthly: any[] = [];
    const yearly: any[] = [];
    const shift: any[] = [];

    filteredOrdersByDate.forEach(o => {
      const d = new Date(o.date);
      const dayKey = o.date;
      const weekKey = `Minggu ${getWeekNumber(d)}, ${d.getFullYear()}`;
      const monthKey = d.toLocaleString('id-ID', { month: 'long', year: 'numeric' });
      const yearKey = `${d.getFullYear()}`;
      const shiftKey = o.shift || 'Pagi';

      const processEntry = (arr: any[], key: string, label: string) => {
        let entry = arr.find(x => x.key === key);
        if (!entry) {
          entry = { key, label, revenue: 0, paid: 0, receivables: 0, count: 0, admins: new Set<string>() };
          arr.push(entry);
        }
        entry.revenue += o.totalPrice;
        entry.paid += o.amountPaid;
        entry.receivables += (o.totalPrice - o.amountPaid);
        entry.count += 1;
        if (o.recordedBy) entry.admins.add(o.recordedBy);
      };

      processEntry(daily, dayKey, dayKey);
      processEntry(weekly, weekKey, weekKey);
      processEntry(monthly, monthKey, monthKey);
      processEntry(yearly, yearKey, yearKey);
      processEntry(shift, shiftKey, `Sift ${shiftKey}`);
    });

    const formatData = (arr: any[]) => arr.map(item => ({
      ...item,
      adminList: Array.from(item.admins).join(' & ') || 'Sistem'
    }));

    return {
      daily: formatData(daily.sort((a, b) => b.key.localeCompare(a.key))),
      weekly: formatData(weekly), 
      monthly: formatData(monthly),
      yearly: formatData(yearly),
      shift: formatData(shift)
    };
  }, [filteredOrdersByDate]);

  const handleDownloadCSV = () => {
    let dataToExport = [];
    let fileName = "Laporan_Katering";

    switch(activeTab) {
      case 'harian': dataToExport = reports.daily; fileName += "_Harian"; break;
      case 'mingguan': dataToExport = reports.weekly; fileName += "_Mingguan"; break;
      case 'bulanan': dataToExport = reports.monthly; fileName += "_Bulanan"; break;
      case 'tahunan': dataToExport = reports.yearly; fileName += "_Tahunan"; break;
      case 'sift': dataToExport = reports.shift; fileName += "_Audit_Sift"; break;
      default: dataToExport = reports.daily; fileName += "_Audit_Kas";
    }

    if (dataToExport.length === 0) return alert("Tidak ada data untuk periode ini.");

    const headers = ["Periode/Sift", "Jml Pesanan", "Total Omzet", "Kas Masuk", "Piutang", "Admin Bertugas"];
    const csvRows = [
      headers.join(","),
      ...dataToExport.map(row => [
        `"${row.label}"`,
        row.count,
        row.revenue,
        row.paid,
        row.receivables,
        `"${row.adminList}"`
      ].join(","))
    ];

    const blob = new Blob([csvRows.join("\n")], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `${fileName}_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const TableView = ({ data, title, desc, icon: Icon, isShift = false }: { data: any[], title: string, desc: string, icon: any, isShift?: boolean }) => (
    <div className="bg-white rounded-[3rem] p-8 md:p-10 border border-slate-100 shadow-sm animate-in fade-in slide-in-from-bottom-4">
      <div className="flex items-center justify-between mb-10">
        <div>
          <h3 className="text-2xl font-black text-slate-900 tracking-tight">{title}</h3>
          <p className="text-sm text-slate-400 font-medium mt-1">{desc}</p>
        </div>
        <div className="w-14 h-14 bg-slate-50 rounded-2xl flex items-center justify-center text-slate-300">
          <Icon size={28} />
        </div>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full text-left border-separate border-spacing-y-4">
          <thead>
            <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
              <th className="pb-4 pl-6">Periode {isShift ? "/ Sift" : ""}</th>
              <th className="pb-4">Kas Masuk (Ril)</th>
              <th className="pb-4">Hutang</th>
              <th className="pb-4">Admin Jaga</th>
            </tr>
          </thead>
          <tbody>
            {data.map((d, i) => (
              <tr key={i} className="group hover:bg-slate-50 transition-all">
                <td className="py-6 pl-6 bg-slate-50 border-y border-l border-slate-100 rounded-l-2xl group-hover:bg-white transition-all">
                  <p className="text-sm font-black text-slate-800">{d.label}</p>
                  <p className="text-[10px] font-bold text-slate-400 uppercase">{d.count} Transaksi</p>
                </td>
                <td className="py-6 bg-slate-50 border-y border-slate-100 group-hover:bg-white transition-all">
                  <p className="text-sm font-black text-emerald-600">Rp {d.paid.toLocaleString()}</p>
                  <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Dari: Rp {d.revenue.toLocaleString()}</p>
                </td>
                <td className="py-6 bg-slate-50 border-y border-slate-100 group-hover:bg-white transition-all">
                   <p className={`text-sm font-black ${d.receivables > 0 ? 'text-rose-500' : 'text-slate-300'}`}>Rp {d.receivables.toLocaleString()}</p>
                </td>
                <td className="py-6 pr-6 bg-slate-50 border-y border-r border-slate-100 rounded-r-2xl group-hover:bg-white transition-all">
                   <div className="flex items-center gap-2">
                      <div className="w-6 h-6 rounded-full bg-indigo-50 flex items-center justify-center text-[10px] font-black text-indigo-400 border border-indigo-100">
                        {d.adminList.charAt(0)}
                      </div>
                      <p className="text-[10px] font-black text-slate-600 truncate max-w-[120px] uppercase tracking-tight">{d.adminList}</p>
                   </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );

  return (
    <div className="space-y-10 animate-in fade-in slide-in-from-bottom-8 duration-1000 pb-20">
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-8 border-b border-slate-100 pb-8">
        <div>
          <h2 className="text-4xl font-black text-slate-900 tracking-tight">Audit Keuangan Lengkap</h2>
          <p className="text-sm text-slate-500 font-medium mt-1">Transparansi kas, piutang, dan penanggung jawab admin.</p>
        </div>

        <div className="flex flex-wrap gap-3 items-center w-full xl:w-auto">
          <div className="flex flex-wrap gap-2 bg-white p-2 rounded-[2rem] border border-slate-100 shadow-sm">
            {(['ikhtisar', 'harian', 'mingguan', 'bulanan', 'tahunan', 'sift'] as const).map((t) => (
              <button key={t} onClick={() => setActiveTab(t)} className={`whitespace-nowrap px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === t ? 'bg-slate-900 text-white shadow-xl' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-50'}`}>{t}</button>
            ))}
          </div>
          <button onClick={handleDownloadCSV} className="bg-emerald-600 text-white p-4 rounded-2xl flex items-center justify-center gap-2 hover:bg-emerald-700 transition-all shadow-xl shadow-emerald-50 font-black text-[10px] uppercase tracking-widest group">
            <FileDown size={18} className="group-hover:translate-y-0.5 transition-transform" />
            <span className="hidden md:inline">Unduh Rekap</span>
          </button>
        </div>
      </div>

      {activeTab === 'ikhtisar' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 flex items-center gap-2"><ShoppingBag size={12} className="text-indigo-500" /> Total Nilai Pesanan</p>
            <h3 className="text-3xl font-black text-slate-900 tracking-tighter">Rp {stats.totalRevenue.toLocaleString()}</h3>
          </div>
          <div className="bg-emerald-600 p-8 rounded-[2.5rem] text-white shadow-xl shadow-emerald-100">
            <p className="text-[10px] font-black text-white/70 uppercase tracking-widest mb-1 flex items-center gap-2"><Banknote size={12} className="text-emerald-300" /> Kas Masuk (Ril)</p>
            <h3 className="text-3xl font-black text-white tracking-tighter">Rp {stats.totalPaid.toLocaleString()}</h3>
          </div>
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 flex items-center gap-2"><AlertCircle size={12} className="text-rose-500" /> Total Piutang</p>
            <h3 className="text-3xl font-black text-rose-600 tracking-tighter">Rp {stats.totalReceivables.toLocaleString()}</h3>
          </div>
          <div className="bg-slate-900 p-8 rounded-[2.5rem] text-white shadow-xl shadow-slate-200">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 flex items-center gap-2"><Calculator size={12} className="text-indigo-400" /> Efisiensi Kas</p>
            <h3 className="text-3xl font-black text-white tracking-tighter">{stats.collectionRate.toFixed(1)}%</h3>
          </div>
        </div>
      )}

      {activeTab === 'harian' && <TableView data={reports.daily} title="Kas Masuk Harian" desc="Daftar arus kas harian dan penanggung jawab admin." icon={Calendar} />}
      {activeTab === 'mingguan' && <TableView data={reports.weekly} title="Rekap Mingguan" desc="Ringkasan kas mingguan." icon={Activity} />}
      {activeTab === 'bulanan' && <TableView data={reports.monthly} title="Rekap Bulanan" desc="Valuasi bulanan katering." icon={CalendarDays} />}
      {activeTab === 'tahunan' && <TableView data={reports.yearly} title="Audit Tahunan" desc="Arsip tahunan bisnis." icon={Layers} />}
      {activeTab === 'sift' && <TableView data={reports.shift} title="Audit Serah Terima Sift" desc="Laporan pertanggungjawaban admin tiap pergantian sift." icon={Clock} isShift={true} />}
    </div>
  );
};

export default SalesReport;

