import React, { useState, useRef, useMemo } from 'react';
import { 
  Sparkles, Camera, CheckCircle2, AlertCircle, Loader2, Package, 
  Utensils, Plus, Trash2, ShoppingCart, X, Copy, MessageCircle, Check, Save, Zap,
  FileText, Send, MessageSquare, ClipboardList, ArrowRight, Activity, TrendingDown
} from 'lucide-react';
import { analyzeKitchenStock, analyzeStockFromText } from '../services/geminiService';
import { AnalysisResult, IngredientStock, Order, MenuItem } from '../types';

interface SmartAdvisorProps {
  inventory: IngredientStock[];
  orders: Order[];
  menu: MenuItem[];
  onUpdateInventory: (inventory: IngredientStock[]) => void;
  onNotify?: (message: string, type: 'success' | 'error' | 'warning') => void;
}

const SmartAdvisor: React.FC<SmartAdvisorProps> = ({ inventory, orders, menu, onUpdateInventory, onNotify }) => {
  const [activeSubTab, setActiveSubTab] = useState<'monitor' | 'mrp'>('monitor');
  const [analyzing, setAnalyzing] = useState(false);
  const [result, setResult] = useState<AnalysisResult & { mrpStatus?: string } | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isApplied, setIsApplied] = useState(false);

  const [newItem, setNewItem] = useState<Partial<IngredientStock>>({
    name: '',
    quantity: 0,
    unit: 'kg',
    status: 'Aman'
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  // MRP LOGIC: Calculate total needed ingredients from confirmed/pending orders
  const mrpCalculations = useMemo(() => {
    const requirements: { [key: string]: { name: string, amount: number, unit: string } } = {};

    // Process active orders
    orders.filter(o => o.status === 'Pending' || o.status === 'Confirmed').forEach(order => {
      order.items.forEach(orderItemStr => {
        const match = orderItemStr.match(/(.*)\s\((\d+)\)/);
        if (!match) return;
        const [_, itemName, qtyStr] = match;
        const quantity = parseInt(qtyStr);

        const menuItem = menu.find(m => m.name === itemName.trim());
        if (menuItem?.recipe) {
          menuItem.recipe.forEach(ing => {
            const needed = ing.amountPerUnit * quantity;
            if (!requirements[ing.ingredientId]) {
              requirements[ing.ingredientId] = { name: ing.name, amount: 0, unit: ing.unit };
            }
            requirements[ing.ingredientId].amount += needed;
          });
        }
      });
    });

    return Object.entries(requirements).map(([id, data]) => {
      const stock = inventory.find(i => i.id === id);
      const stockQty = stock ? stock.quantity : 0;
      const deficit = Math.max(0, data.amount - stockQty);
      const percentFilled = data.amount > 0 ? (stockQty / data.amount) * 100 : 100;

      return {
        id,
        ...data,
        stockQty,
        deficit,
        percentFilled: Math.min(100, percentFilled)
      };
    });
  }, [orders, menu, inventory]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64String = reader.result as string;
        setPreview(base64String);
        setAnalyzing(true);
        setIsApplied(false);
        try {
          const res = await analyzeKitchenStock(base64String);
          setResult(res as any);
        } catch (error) {
          console.error("AI Analysis failed", error);
        } finally {
          setAnalyzing(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleApplyAIResult = () => {
    if (result) {
      const ingredient: IngredientStock = {
        id: Math.random().toString(36).substr(2, 9),
        name: result.status,
        quantity: parseFloat(result.estimatedQuantity) || 0,
        unit: 'kg',
        status: (result.mrpStatus as any) || 'Aman'
      };
      onUpdateInventory([ingredient, ...inventory]);
      setIsApplied(true);
      onNotify?.(`Bahan '${ingredient.name}' ditambahkan via AI.`, 'success');
      setTimeout(() => setIsApplied(false), 2000);
    }
  };

  const handleAddIngredient = () => {
    if (newItem.name && newItem.quantity) {
      const ingredient: IngredientStock = {
        id: Math.random().toString(36).substr(2, 9),
        name: newItem.name,
        quantity: Number(newItem.quantity),
        unit: newItem.unit || 'kg',
        status: newItem.status as any || 'Aman'
      };
      onUpdateInventory([ingredient, ...inventory]);
      setIsAddModalOpen(false);
      onNotify?.(`Stok '${newItem.name}' diperbarui manual.`, 'success');
      setNewItem({ name: '', quantity: 0, unit: 'kg', status: 'Aman' });
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-700 pb-20">
      {/* MRP Global Toggle */}
      <div className="flex items-center gap-3 bg-white p-2 rounded-[2rem] border border-slate-100 shadow-sm w-fit">
