  const calculateOrderCost = (order: Order) => {
    let totalCost = 0;
    order.items.forEach(itemStr => {
      const match = itemStr.match(/(.*)\s\((\d+)\)/);
      if (match) {
        const itemName = match[1].trim();
        const qty = parseInt(match[2]);
        const menuItem = menu.find(m => m.name === itemName);
        if (menuItem) {
          totalCost += menuItem.cost * qty;
        }
      }
    });
    // Jika tidak ada item terdeteksi (data dummy), asumsikan cost adalah 40% dari total
    return totalCost || order.totalPrice * 0.4;
