  const StatCard = ({ title, value, icon: Icon, colorClass, iconBg }: any) => (
    <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-50 flex items-center gap-6 group hover:shadow-md transition-all">
      <div className={`w-14 h-14 ${iconBg} ${colorClass} rounded-2xl flex items-center justify-center transition-transform group-hover:scale-110`}>
        <Icon size={24} />
      </div>
      <div>
        <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mb-1">{title}</p>
        <h3 className="text-2xl font-black text-slate-800 tracking-tight">
          {value}
        </h3>
      </div>
    </div>
  );

  return (
    <div className="space-y-6 animate-in fade-in duration-700">
      {deficits.length > 0 && (
        <div className="bg-amber-500 rounded-[2.5rem] p-6 text-white flex flex-col md:flex-row items-center justify-between gap-6 shadow-xl shadow-amber-100 border border-amber-400 animate-bounce-slow">
           <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-white/20 rounded-2xl flex items-center justify-center backdrop-blur-md">
                <AlertTriangle size={24} />
              </div>
              <div>
                <h4 className="font-black text-lg leading-tight">Perhatian: {deficits.length} Bahan Kurang</h4>
                <p className="text-white/80 text-xs font-bold uppercase tracking-widest">Segera lakukan pengadaan untuk pesanan aktif</p>
              </div>
           </div>
           <div className="flex items-center gap-2 bg-white/10 px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest border border-white/10">
              Cek Tab Dapur <ArrowRight size={14} />
           </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard 
          title="Net Revenue" 
          value={`Rp ${(totalRevenue/1000).toFixed(0)}k`} 
          icon={TrendingUp} 
          colorClass="text-[#10b981]" 
          iconBg="bg-[#ecfdf5]" 
        />
        <StatCard 
          title="Total Piutang" 
          value={`Rp ${(totalReceivables/1000).toFixed(0)}k`} 
          icon={Wallet} 
          colorClass="text-[#ef4444]" 
          iconBg="bg-[#fef2f2]" 
        />
        <StatCard 
          title="Total Pesanan" 
          value={orders.length} 
          icon={ShoppingBag} 
          colorClass="text-[#6366f1]" 
          iconBg="bg-[#eef2ff]" 
        />
        <StatCard 
          title="Corporate %" 
          value={`${((corporateOrders/Math.max(1, orders.length))*100).toFixed(0)}%`} 
          icon={Users} 
          colorClass="text-[#f59e0b]" 
          iconBg="bg-[#fffbeb]" 
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 bg-white p-8 rounded-[2.5rem] border border-slate-50 shadow-sm">
          <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest mb-8">Weekly Sales Growth</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={revenueData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10, fontWeight: 700}} />
                <YAxis hide />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}}
                  contentStyle={{borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}}
                />
                <Bar dataKey="sales" fill="#10b981" radius={[8, 8, 0, 0]} barSize={45} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-50 shadow-sm">
          <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest mb-8">Popular Dishes</h3>
