  const [activeTab, setActiveTab] = useState<'dashboard' | 'menu' | 'orders' | 'receivables' | 'advisor' | 'admins' | 'social' | 'security' | 'sales-report'>('dashboard');
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isProfileDropdownOpen, setIsProfileDropdownOpen] = useState(false);
  const [isShiftDropdownOpen, setIsShiftDropdownOpen] = useState(false);

  const [menu, setMenu] = useState<MenuItem[]>(INITIAL_MENU);
  const [orders, setOrders] = useState<Order[]>(INITIAL_ORDERS);
  const [inventory, setInventory] = useState<IngredientStock[]>(INITIAL_INVENTORY);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [settings, setSettings] = useState<StoreSettings>(INITIAL_SETTINGS);
  const [categories, setCategories] = useState<string[]>(INITIAL_CATEGORIES);
  const [shiftConfigs, setShiftConfigs] = useState<ShiftConfig[]>(INITIAL_SHIFTS);
  const [notifications, setNotifications] = useState<Notification[]>([]);

  const playAlertSound = useCallback((type: NotificationType) => {
    try {
      const context = new (window.AudioContext || (window as any).webkitAudioContext)();
      const oscillator = context.createOscillator();
      const gainNode = context.createGain();
      oscillator.connect(gainNode);
      gainNode.connect(context.destination);
      if (type === 'error') {
        oscillator.type = 'sawtooth';
        oscillator.frequency.setValueAtTime(150, context.currentTime);
        oscillator.frequency.exponentialRampToValueAtTime(50, context.currentTime + 0.3);
        gainNode.gain.setValueAtTime(0.1, context.currentTime);
      } else if (type === 'warning') {
        oscillator.type = 'sine';
        oscillator.frequency.setValueAtTime(440, context.currentTime);
        oscillator.frequency.exponentialRampToValueAtTime(880, context.currentTime + 0.1);
        gainNode.gain.setValueAtTime(0.1, context.currentTime);
      } else {
        oscillator.type = 'sine';
        oscillator.frequency.setValueAtTime(880, context.currentTime);
        oscillator.frequency.exponentialRampToValueAtTime(1200, context.currentTime + 0.1);
        gainNode.gain.setValueAtTime(0.05, context.currentTime);
      }
      oscillator.start();
      oscillator.stop(context.currentTime + 0.3);
    } catch (e) { console.warn("Audio Context blocked"); }
  }, []);

