      <Sidebar isOpen={isSidebarOpen} setIsOpen={setIsSidebarOpen} activeTab={activeTab} setActiveTab={setActiveTab} onPreviewMenu={() => setViewMode('admin')} logoUrl={settings.logoUrl} onOpenSettings={() => isSuperAdmin && setIsSettingsOpen(true)} role={currentUser.role} />

