    });

    if (insufficientItems.length > 0) {
      addNotification(`Gagal Konfirmasi! Stok tidak cukup: ${insufficientItems.join(', ')}`, 'error');
      return false;
    }

    setInventory(inventoryCopy);
    addNotification(`Stok inventori telah dipotong otomatis untuk Pesanan #${order.id}`, 'success');
    return true;
  }, [inventory, menu, addNotification]);

  const handleAddOrder = (newOrder: Order) => {
    setOrders(prev => [newOrder, ...prev]);
  };

  const handleUpdateOrder = (orderId: string, updates: Partial<Order>) => {
    const targetOrder = orders.find(o => o.id === orderId);
    if (!targetOrder) return;

    if (updates.status === 'Confirmed' && targetOrder.status !== 'Confirmed') {
      const success = deduceStockFromOrder(targetOrder);
      if (!success) return; 
    }

    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, ...updates } : o));
    if (updates.status === 'Delivered') addNotification(`Pesanan #${orderId} berhasil dikirim!`, 'success');
  };

  const handleLogin = (name: string, shift: ShiftType, role: UserRole) => {
    setCurrentUser({
      id: Math.random().toString(),
      name, role, shift,
      avatarUrl: name === 'Siti Aminah' 
        ? 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?auto=format&fit=facearea&facepad=2&w=100&h=100&q=80' 
        : 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?auto=format&fit=facearea&facepad=2&w=100&h=100&q=80'
    });
    addNotification(`Selamat datang kembali, ${name}!`, 'success');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setIsProfileDropdownOpen(false);
  };

  const getShiftColor = (shift: ShiftType) => {
    switch (shift) {
      case 'Pagi': return 'bg-amber-50 text-amber-700 border-amber-100';
      case 'Siang': return 'bg-sky-50 text-sky-700 border-sky-100';
      case 'Malam': return 'bg-indigo-50 text-indigo-700 border-indigo-100';
    }
  };

  const getShiftIcon = (shift: ShiftType) => {
    switch (shift) {
      case 'Pagi': return <Sun size={14} className="text-amber-500" />;
      case 'Siang': return <SunMedium size={14} className="text-sky-500" />;
      case 'Malam': return <Moon size={14} className="text-indigo-500" />;
    }
  };

  if (!currentUser) return <Login onLogin={handleLogin} shiftConfigs={shiftConfigs} />;
  const isSuperAdmin = currentUser.role === 'Super Admin';

  if (viewMode === 'customer') {
    return <PublicMenu menu={menu} settings={settings} categories={categories} onBackToAdmin={() => setViewMode('admin')} />;
  }

  return (
    <div className="min-h-screen bg-[#f8fafc] flex flex-col font-sans selection:bg-emerald-100 text-slate-900">

      <div className="fixed top-24 right-6 z-[200] flex flex-col gap-3 w-full max-w-sm pointer-events-none">
        {notifications.map((n) => (
          <div key={n.id} className={`pointer-events-auto p-4 rounded-[1.8rem] shadow-2xl backdrop-blur-xl border flex items-start gap-4 animate-in slide-in-from-right duration-500 ${
            n.type === 'error' ? 'bg-rose-600/90 text-white border-rose-500' :
            n.type === 'warning' ? 'bg-amber-500/90 text-white border-amber-400' : 'bg-emerald-600/90 text-white border-emerald-500'
          }`}>
            <div className="w-10 h-10 rounded-2xl bg-white/20 flex items-center justify-center shrink-0">
               {n.type === 'error' ? <AlertTriangle size={20} /> : n.type === 'warning' ? <Timer size={20} /> : <CheckCircle2 size={20} />}
            </div>
            <div className="flex-1">
              <p className="text-[10px] font-black uppercase tracking-widest opacity-70 mb-1">{n.type === 'error' ? 'Peringatan Sistem' : n.type === 'warning' ? 'Deadline' : 'Berhasil'}</p>
              <p className="text-sm font-bold leading-tight">{n.message}</p>
            </div>
            <button onClick={() => setNotifications(prev => prev.filter(x => x.id !== n.id))} className="text-white/40 hover:text-white"><X size={16} /></button>
          </div>
        ))}
      </div>

      <header className="h-20 bg-white border-b border-slate-100 flex items-center justify-between px-6 sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <button onClick={() => setIsSidebarOpen(true)} className="p-2 text-slate-400 lg:hidden"><MenuIcon size={22} /></button>
          <div className="hidden md:flex items-center gap-3">
            <div className={`flex items-center gap-2 px-3 py-1 rounded-full border ${isSuperAdmin ? 'bg-amber-50 text-amber-600 border-amber-200' : 'bg-slate-50 text-slate-500 border-slate-200'}`}>
              <div className={`w-1.5 h-1.5 rounded-full animate-pulse ${isSuperAdmin ? 'bg-amber-500' : 'bg-slate-400'}`}></div>
              <span className="text-[10px] font-black uppercase tracking-widest">{currentUser.role}</span>
            </div>
            <div className="relative">
              <button onClick={() => setIsShiftDropdownOpen(!isShiftDropdownOpen)} className={`flex items-center gap-2 px-3 py-1 rounded-full border transition-all hover:shadow-sm ${getShiftColor(currentUser.shift)}`}>
                {getShiftIcon(currentUser.shift)} <span className="text-[10px] font-black uppercase tracking-widest">Sift {currentUser.shift}</span> <ChevronDown size={10} />
              </button>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <div className="relative">
            <div className="flex items-center gap-3 cursor-pointer p-1 pr-3 rounded-full hover:bg-slate-50 border border-transparent hover:border-slate-100" onClick={() => setIsProfileDropdownOpen(!isProfileDropdownOpen)}>
              <div className="w-9 h-9 rounded-full bg-slate-100 border-2 border-white shadow-sm overflow-hidden">
                <img src={currentUser.avatarUrl || "https://picsum.photos/100/100"} alt="Profile" className="w-full h-full object-cover" />
              </div>
              <div className="hidden sm:block text-left">
                <p className="text-[10px] font-black text-slate-800 leading-none mb-1 uppercase tracking-tight">{currentUser.name}</p>
                <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">{currentUser.role}</p>
              </div>
            </div>
            {isProfileDropdownOpen && (
              <div className="absolute top-full right-0 mt-2 bg-white border border-slate-100 rounded-[2rem] shadow-2xl p-4 w-56 animate-in fade-in slide-in-from-top-4 z-[60]">
                <button onClick={handleLogout} className="w-full flex items-center gap-3 px-3 py-3 text-[10px] font-black uppercase tracking-widest text-rose-500 hover:bg-rose-50 rounded-xl transition-all">
                  <LogOut size={16} /> Logout Sesi
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      <Sidebar isOpen={isSidebarOpen} setIsOpen={setIsSidebarOpen} activeTab={activeTab} setActiveTab={setActiveTab} onPreviewMenu={() => setViewMode('customer')} logoUrl={settings.logoUrl} onOpenSettings={() => isSuperAdmin && setIsSettingsOpen(true)} role={currentUser.role} />

      <main className="flex-1 overflow-y-auto px-4 py-6 md:px-8 md:py-8 pb-32">
        <div className="max-w-6xl mx-auto space-y-6">
          {activeTab === 'dashboard' && <Dashboard orders={orders} menu={menu} inventory={inventory} />}
          {activeTab === 'menu' && <MenuManager menu={menu} onUpdateMenu={setMenu} categories={categories} onUpdateCategories={setCategories} inventory={inventory} onNotify={addNotification} />}
          {activeTab === 'orders' && <OrdersList orders={orders} onAddOrder={handleAddOrder} onUpdateOrder={handleUpdateOrder} onNotify={addNotification} currentShift={currentUser.shift} currentAdminName={currentUser.name} menu={menu} />}
          {activeTab === 'receivables' && <ReceivablesList orders={orders} onUpdateOrder={handleUpdateOrder} />}
          {activeTab === 'advisor' && <SmartAdvisor inventory={inventory} orders={orders} menu={menu} onUpdateInventory={setInventory} onNotify={addNotification} onAddExpense={handleAddExpense} currentAdmin={currentUser.name} />}
          {activeTab === 'security' && <AccountSecurity />}
          {activeTab === 'sales-report' && <SalesReport orders={orders} menu={menu} expenses={expenses} />}
          {activeTab === 'admins' && <AdminProfiles shiftConfigs={shiftConfigs} onUpdateShiftConfigs={setShiftConfigs} onNotify={addNotification} />}
          {activeTab === 'social' && <SocialAnalytics menu={menu} settings={settings} onUpdateSettings={setSettings} />}
        </div>
      </main>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-xl border-t border-slate-100 px-6 py-4 flex justify-between items-center z-[40] shadow-[0_-10px_40px_rgba(0,0,0,0.04)] rounded-t-[2.5rem] lg:hidden">
        {[
          { id: 'dashboard', label: 'Home', icon: LayoutDashboard },
          { id: 'orders', label: 'Pesanan', icon: ShoppingBag },
          { id: 'menu', label: 'Menu', icon: UtensilsCrossed, isProminent: true },
          { id: 'receivables', label: 'Piutang', icon: Wallet },
          { id: 'advisor', label: 'Dapur', icon: PackageSearch },
        ].map((item) => (
          <button key={item.id} onClick={() => setActiveTab(item.id as any)} className={`flex flex-col items-center justify-center transition-all px-2 ${activeTab === item.id ? 'text-emerald-600' : 'text-slate-400'}`}>
            <item.icon size={item.isProminent ? 24 : 20} />
            <span className="text-[8px] font-black mt-1.5 uppercase tracking-widest">{item.label}</span>
          </button>
        ))}
      </nav>

      {isSettingsOpen && isSuperAdmin && (
        <div className="fixed inset-0 z-[100] flex justify-end">
          <div className="absolute inset-0 bg-slate-900/20 backdrop-blur-[2px]" onClick={() => setIsSettingsOpen(false)}></div>
          <div className="w-full max-w-lg bg-white h-full relative z-10 shadow-2xl animate-in slide-in-from-right duration-300 border-l border-slate-100">
            <div className="p-6 border-b border-slate-50 flex items-center justify-between">
              <h2 className="text-xl font-bold text-slate-800">Konfigurasi Bisnis & Ekosistem</h2>
              <button onClick={() => setIsSettingsOpen(false)} className="p-2 text-slate-400"><X size={24} /></button>
            </div>
            <div className="flex-1 overflow-y-auto p-6">
              <Settings 
                settings={settings} 
                onUpdateSettings={setSettings} 
              />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useMemo } from 'react';
import { 
  Sparkles, Camera, CheckCircle2, AlertCircle, Loader2, Package, 
  Utensils, Plus, Trash2, ShoppingCart, X, Copy, MessageCircle, Check, Save, Zap,
  FileText, Send, MessageSquare, ClipboardList, ArrowRight, Activity, TrendingDown,
  Banknote, CalendarDays, ListChecks, ShoppingBag
} from 'lucide-react';
import { analyzeKitchenStock, analyzeStockFromText } from '../services/geminiService';
import { AnalysisResult, IngredientStock, Order, MenuItem, Expense } from '../types';

interface SmartAdvisorProps {
  inventory: IngredientStock[];
  orders: Order[];
  menu: MenuItem[];
  onUpdateInventory: (inventory: IngredientStock[]) => void;
  onNotify?: (message: string, type: 'success' | 'error' | 'warning') => void;
  onAddExpense?: (expense: Expense) => void;
  currentAdmin?: string;
}

const SmartAdvisor: React.FC<SmartAdvisorProps> = ({ inventory, orders, menu, onUpdateInventory, onNotify, onAddExpense, currentAdmin }) => {
  const [activeSubTab, setActiveSubTab] = useState<'monitor' | 'mrp'>('monitor');
  const [analyzing, setAnalyzing] = useState(false);
  const [result, setResult] = useState<AnalysisResult & { mrpStatus?: string } | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isPurchaseModalOpen, setIsPurchaseModalOpen] = useState(false);
  const [isBulkListOpen, setIsBulkListOpen] = useState(false);

  const [selectedForPurchase, setSelectedForPurchase] = useState<any>(null);
  const [purchaseData, setPurchaseData] = useState({ amount: 0, cost: 0 });

  const [bulkCosts, setBulkCosts] = useState<{ [key: string]: number }>({});
  const [newItem, setNewItem] = useState<Partial<IngredientStock>>({
    name: '',
    quantity: 0,
    unit: 'kg',
    status: 'Aman'
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const mrpCalculations = useMemo(() => {
    const requirements: { [key: string]: { name: string, amount: number, unit: string } } = {};

    orders.filter(o => o.status === 'Pending' || o.status === 'Confirmed').forEach(order => {
      order.items.forEach(orderItemStr => {
        const match = orderItemStr.match(/(.*)\s\((\d+)\)/);
        if (!match) return;
        const [_, itemName, qtyStr] = match;
        const quantity = parseInt(qtyStr);

        const menuItem = menu.find(m => m.name === itemName.trim());
        if (menuItem?.recipe) {
          menuItem.recipe.forEach(ing => {
            const needed = ing.amountPerUnit * quantity;
            if (!requirements[ing.ingredientId]) {
              requirements[ing.ingredientId] = { name: ing.name, amount: 0, unit: ing.unit };
            }
            requirements[ing.ingredientId].amount += needed;
          });
        }
      });
    });

    return Object.entries(requirements).map(([id, data]) => {
      const stock = inventory.find(i => i.id === id);
      const stockQty = stock ? stock.quantity : 0;
      const deficit = Math.max(0, data.amount - stockQty);
      const percentFilled = data.amount > 0 ? (stockQty / data.amount) * 100 : 100;

      return {
        id,
        ...data,
        stockQty,
        deficit,
        percentFilled: Math.min(100, percentFilled)
      };
    });
  }, [orders, menu, inventory]);

  const deficits = useMemo(() => mrpCalculations.filter(m => m.deficit > 0), [mrpCalculations]);

  const handleOpenPurchase = (item: any) => {
    setSelectedForPurchase(item);
    setPurchaseData({ amount: Math.ceil(item.deficit), cost: 0 });
    setIsPurchaseModalOpen(true);
  };

  const handleRecordPurchase = () => {
    if (onAddExpense && selectedForPurchase && purchaseData.cost > 0) {
      const expense: Expense = {
        id: Math.random().toString(36).substr(2, 9),
        name: selectedForPurchase.name,
        amount: purchaseData.amount,
        unit: selectedForPurchase.unit,
        totalCost: purchaseData.cost,
        date: new Date().toISOString().split('T')[0],
        recordedBy: currentAdmin || 'Admin Dapur',
        category: 'Bahan Baku'
      };
      onAddExpense(expense);
      setIsPurchaseModalOpen(false);
      setSelectedForPurchase(null);
    }
  };

  const handleBulkRecord = () => {
    if (!onAddExpense) return;

    let recordedCount = 0;
    deficits.forEach(item => {
      const cost = bulkCosts[item.id];
      if (cost && cost > 0) {
        const expense: Expense = {
          id: Math.random().toString(36).substr(2, 9),
          name: item.name,
          amount: Math.ceil(item.deficit),
          unit: item.unit,
          totalCost: cost,
          date: new Date().toISOString().split('T')[0],
          recordedBy: currentAdmin || 'Admin Dapur',
          category: 'Bahan Baku'
        };
        onAddExpense(expense);
        recordedCount++;
      }
    });

    if (recordedCount > 0) {
      setIsBulkListOpen(false);
      setBulkCosts({});
      onNotify?.(`${recordedCount} bahan berhasil dibelanjakan dan dicatat!`, 'success');
    } else {
      onNotify?.("Masukkan setidaknya satu harga belanja.", "warning");
    }
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64String = reader.result as string;
        setPreview(base64String);
        setAnalyzing(true);
        try {
          const res = await analyzeKitchenStock(base64String);
          setResult(res as any);
        } catch (error) {
          console.error("AI Analysis failed", error);
        } finally {
          setAnalyzing(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-700 pb-20">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
        <div className="flex items-center gap-3 bg-white p-2 rounded-[2rem] border border-slate-100 shadow-sm w-full md:w-fit">
          <button 
            onClick={() => setActiveSubTab('monitor')}
            className={`flex-1 md:flex-none px-8 py-3.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${activeSubTab === 'monitor' ? 'bg-slate-900 text-white shadow-xl' : 'text-slate-400 hover:bg-slate-50'}`}
          >
            <Package size={14} /> Monitor Stok
          </button>
          <button 
            onClick={() => setActiveSubTab('mrp')}
            className={`flex-1 md:flex-none px-8 py-3.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${activeSubTab === 'mrp' ? 'bg-indigo-600 text-white shadow-xl' : 'text-slate-400 hover:bg-slate-50'}`}
          >
            <ClipboardList size={14} /> MRP Planner
          </button>
        </div>

        {deficits.length > 0 && (
          <button 
            onClick={() => setIsBulkListOpen(true)}
            className="w-full md:w-auto flex items-center justify-center gap-4 bg-rose-600 text-white px-8 py-4 rounded-[2rem] shadow-2xl shadow-rose-100 border border-rose-500 group animate-in slide-in-from-right duration-500"
          >
            <div className="relative">
              <ShoppingBag size={20} className="group-hover:rotate-12 transition-transform" />
              <span className="absolute -top-2 -right-2 bg-white text-rose-600 w-5 h-5 rounded-full flex items-center justify-center text-[10px] font-black border-2 border-rose-600 shadow-sm">
                {deficits.length}
              </span>
            </div>
            <div className="text-left">
               <p className="text-[10px] font-black uppercase tracking-widest leading-none mb-1">Daftar Belanja Masal</p>
               <p className="text-[8px] font-bold opacity-80">Klik untuk mencatat belanjaan</p>
            </div>
          </button>
        )}
      </div>

      {activeSubTab === 'monitor' ? (
        <>
          <div className="bg-slate-900 rounded-[3rem] p-8 md:p-12 text-white relative overflow-hidden shadow-2xl">
            <div className="relative z-10 flex flex-col md:flex-row items-center gap-10">
              <div className="flex-1 text-left">
                <h2 className="text-4xl font-black mb-4 leading-tight">Kitchen Intelligence</h2>
                <p className="text-slate-400 text-lg mb-8 leading-relaxed font-medium">Pindai bahan baku untuk sinkronisasi stok otomatis.</p>
                <div className="flex flex-wrap gap-4">
                  <button onClick={() => fileInputRef.current?.click()} className="bg-white text-slate-900 px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-amber-500 hover:text-white transition-all flex items-center gap-3 shadow-xl">
                    <Camera size={20} /> Ambil Foto Stok
                  </button>
                  <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept="image/*" />
                </div>
              </div>

              <div className="w-full md:w-80 aspect-square bg-white/5 rounded-[3rem] border-2 border-dashed border-white/10 flex flex-col items-center justify-center relative overflow-hidden group">
                {preview ? <img src={preview} alt="Preview" className="w-full h-full object-cover" /> : <Package size={48} className="text-slate-600" />}
                {analyzing && (
                  <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-md flex flex-col items-center justify-center p-6 text-center">
                    <Loader2 className="animate-spin text-amber-500 mb-4" size={48} />
                    <span className="text-white text-[10px] font-black tracking-[0.3em] uppercase">AI SEDANG MENGANALISIS...</span>
                  </div>
                )}
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            <div className="lg:col-span-4 space-y-6">
              {deficits.length > 0 && (
                <div className="bg-white border border-rose-100 rounded-[2.5rem] p-8 shadow-sm">
                  <div className="flex items-center gap-3 mb-6">
                    <div className="w-10 h-10 bg-rose-50 text-rose-500 rounded-xl flex items-center justify-center border border-rose-100">
                      <TrendingDown size={18} />
                    </div>
                    <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest">Defisit Bahan</h3>
                  </div>
                  <div className="space-y-3 mb-6">
                     {deficits.slice(0, 3).map(d => (
                       <div key={d.id} className="flex justify-between items-center text-xs font-bold">
                          <span className="text-slate-500">{d.name}</span>
                          <span className="text-rose-500">-{d.deficit.toFixed(1)} {d.unit}</span>
                       </div>
                     ))}
                     {deficits.length > 3 && <p className="text-[10px] text-slate-300 font-black uppercase text-center">+{deficits.length - 3} Bahan Lainnya</p>}
                  </div>
                  <button onClick={() => setIsBulkListOpen(true)} className="w-full py-4 bg-slate-900 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-lg">
                    Lengkapi Stok Sekarang
                  </button>
                </div>
              )}

              <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
                <div className="flex items-center justify-between mb-8">
                  <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest">Inventori Fisik</h3>
                  <button onClick={() => setIsAddModalOpen(true)} className="p-2 bg-slate-50 text-slate-400 hover:text-amber-500 rounded-xl transition-all"><Plus size={20} /></button>
                </div>
                <div className="space-y-4 max-h-[400px] overflow-y-auto no-scrollbar">
                  {inventory.map(item => (
                    <div key={item.id} className="p-4 bg-slate-50 border border-slate-100 rounded-2xl flex items-center justify-between">
                      <div>
                        <p className="text-sm font-black text-slate-800 leading-none mb-1">{item.name}</p>
                        <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{item.quantity} {item.unit}</p>
                      </div>
                      <span className={`text-[8px] font-black px-2 py-1 rounded-lg border uppercase tracking-wider ${
                        item.status === 'Aman' ? 'text-emerald-500 bg-emerald-50 border-emerald-100' : 
                        item.status === 'Menipis' ? 'text-amber-500 bg-amber-50 border-amber-100' : 'text-rose-500 bg-rose-50 border-rose-100'
                      }`}>{item.status}</span>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            <div className="lg:col-span-8">
              {result ? (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 animate-in slide-in-from-right duration-700">
                  <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col items-center text-center justify-center">
                    <h4 className="text-xl font-black text-slate-800 mb-1">{result.status}</h4>
                    <p className="text-[10px] font-bold text-amber-500 uppercase tracking-widest mb-6">Deteksi: {result.estimatedQuantity}</p>
                    <button onClick={() => handleOpenPurchase({ name: result.status, unit: 'kg', deficit: 1 })} className="w-full py-4 bg-amber-500 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2">
                      <Zap size={16} /> Terapkan & Catat Belanja
                    </button>
                  </div>
                  <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
                    <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6">Rekomendasi Operasional</h3>
                    <p className="text-xs text-slate-600 leading-relaxed italic mb-4">"{result.diagnosis}"</p>
                    <div className="space-y-2">
                      {result.recommendations.map((rec, i) => (
                        <div key={i} className="flex gap-2 items-start text-[11px] font-bold text-slate-700">
                           <div className="w-1.5 h-1.5 rounded-full bg-indigo-500 mt-1 shrink-0"></div>
                           {rec}
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              ) : (
                <div className="h-full bg-white/50 rounded-[3rem] border-2 border-dashed border-slate-200 flex flex-col items-center justify-center p-12 text-center">
                  <Sparkles size={48} className="text-slate-200 mb-4" />
                  <p className="text-slate-400 font-bold italic max-w-xs">Pindai stok dapur untuk analisis AI instan.</p>
                </div>
              )}
            </div>
          </div>
        </>
      ) : (
        <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
          <div className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-10">
              <div>
                <h3 className="text-2xl font-black text-slate-900 tracking-tight">MRP Production Planner</h3>
                <p className="text-sm text-slate-400 font-medium mt-1">Daftar belanja otomatis berdasarkan kebutuhan pesanan.</p>
              </div>
              <div className="flex items-center gap-4 bg-indigo-50 px-6 py-3 rounded-2xl border border-indigo-100">
                <ShoppingCart size={20} className="text-indigo-600" />
                <div>
                   <p className="text-[8px] font-black text-indigo-400 uppercase tracking-widest">Kebutuhan Produksi</p>
                   <p className="text-sm font-black text-indigo-900">Live Calc</p>
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {mrpCalculations.map((ing) => (
                <div key={ing.id} className="bg-slate-50 border border-slate-100 rounded-[2.5rem] p-6 group hover:bg-white hover:shadow-xl transition-all">
                  <div className="flex justify-between items-start mb-4">
                    <div>
                      <h4 className="font-black text-slate-800 text-base">{ing.name}</h4>
                      <p className="text-[10px] font-bold text-slate-400 uppercase">Kebutuhan: {ing.amount} {ing.unit}</p>
                    </div>
                    {ing.deficit > 0 ? (
                      <div className="w-8 h-8 bg-rose-50 text-rose-500 rounded-xl flex items-center justify-center border border-rose-100 animate-pulse">
                        <TrendingDown size={16} />
                      </div>
                    ) : (
                      <div className="w-8 h-8 bg-emerald-50 text-emerald-500 rounded-xl flex items-center justify-center border border-emerald-100">
                        <Check size={16} />
                      </div>
                    )}
                  </div>

                  <div className="space-y-4">
                    <div className="h-2 w-full bg-slate-200 rounded-full overflow-hidden">
                      <div 
                        className={`h-full transition-all duration-1000 ${ing.deficit > 0 ? 'bg-rose-500' : 'bg-emerald-500'}`}
                        style={{ width: `${ing.percentFilled}%` }}
                      ></div>
                    </div>

                    {ing.deficit > 0 ? (
                      <button 
                        onClick={() => handleOpenPurchase(ing)}
                        className="w-full py-3 bg-rose-600 text-white rounded-xl font-black text-[9px] uppercase tracking-widest flex items-center justify-center gap-2 shadow-lg shadow-rose-100"
                      >
                        <ShoppingCart size={14} /> Belanja {ing.deficit.toFixed(1)} {ing.unit}
                      </button>
                    ) : (
                      <div className="bg-emerald-50 border border-emerald-100 p-3 rounded-xl flex items-center justify-center gap-2">
                         <CheckCircle2 size={12} className="text-emerald-500" />
                         <span className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Stok Mencukupi</span>
                      </div>
                    )}
                  </div>
                </div>
              ))}
              {mrpCalculations.length === 0 && (
                <div className="col-span-full py-20 text-center text-slate-300 italic border-2 border-dashed border-slate-100 rounded-[2.5rem]">
                   Belum ada pesanan aktif untuk dikalkulasi kebutuhan bahannya.
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Modal Daftar Belanja Masal */}
      {isBulkListOpen && (
        <div className="fixed inset-0 z-[160] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setIsBulkListOpen(false)}></div>
          <div className="bg-white rounded-[3rem] w-full max-w-2xl overflow-hidden shadow-2xl relative z-10 animate-in zoom-in-95 duration-300 flex flex-col max-h-[90vh]">
             <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-rose-600 text-white rounded-2xl flex items-center justify-center shadow-lg">
                    <ListChecks size={24} />
                  </div>
                  <div>
                    <h3 className="text-2xl font-black text-slate-900">Belanja Masal Katering</h3>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{deficits.length} bahan memerlukan pengadaan</p>
                  </div>
                </div>
                <button onClick={() => setIsBulkListOpen(false)} className="p-3 bg-white rounded-full text-slate-400 shadow-sm border border-slate-100 hover:text-rose-500 transition-colors"><X size={20} /></button>
             </div>

             <div className="flex-1 overflow-y-auto p-8 space-y-4 no-scrollbar">
                {deficits.map(item => (
                  <div key={item.id} className="p-5 bg-slate-50 border border-slate-100 rounded-3xl grid grid-cols-1 md:grid-cols-2 gap-4 items-center">
                     <div>
                        <p className="text-sm font-black text-slate-800 leading-none mb-1">{item.name}</p>
                        <p className="text-[10px] font-bold text-rose-500 uppercase tracking-widest">Butuh +{item.deficit.toFixed(1)} {item.unit}</p>
                     </div>
                     <div className="relative">
                        <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 text-[10px] font-black">Rp</span>
                        <input 
                          type="number" 
                          placeholder="Harga belanja..."
                          className="w-full bg-white border border-slate-200 rounded-2xl pl-10 pr-5 py-3 text-sm font-black outline-none focus:ring-4 focus:ring-rose-500/10 transition-all"
                          value={bulkCosts[item.id] || ''}
                          onChange={(e) => setBulkCosts({...bulkCosts, [item.id]: Number(e.target.value)})}
                        />
                     </div>
                  </div>
                ))}
             </div>

             <div className="p-8 border-t border-slate-100 bg-slate-50/50 flex gap-4">
                <button 
                  onClick={handleBulkRecord}
                  className="flex-1 bg-slate-900 text-white py-4 rounded-2xl font-black text-[11px] uppercase tracking-widest hover:bg-emerald-600 transition-all shadow-xl shadow-slate-200"
                >
                  Selesaikan Belanja & Update Stok
                </button>
                <button onClick={() => setIsBulkListOpen(false)} className="px-8 bg-white border border-slate-200 text-slate-400 py-4 rounded-2xl font-black text-[11px] uppercase tracking-widest">
                  Batal
                </button>
             </div>
          </div>
        </div>
      )}

      {/* Modal Belanja Bahan Tunggal */}
      {isPurchaseModalOpen && selectedForPurchase && (
        <div className="fixed inset-0 z-[160] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setIsPurchaseModalOpen(false)}></div>
          <div className="bg-white rounded-[3rem] w-full max-w-md overflow-hidden shadow-2xl relative z-10 p-8">
             <div className="flex items-center gap-4 mb-8">
                <div className="w-14 h-14 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center">
                  <Banknote size={28} />
                </div>
                <div>
                  <h3 className="text-xl font-black text-slate-900">Catat Pembelian</h3>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{selectedForPurchase.name}</p>
                </div>
             </div>

             <div className="space-y-5">
                <div>
                  <label className="text-[10px] font-black uppercase text-slate-400 mb-2 block">Jumlah yang Dibeli ({selectedForPurchase.unit})</label>
                  <input 
                    type="number" 
                    className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-3.5 text-sm font-bold outline-none" 
                    value={purchaseData.amount} 
                    onChange={e => setPurchaseData({...purchaseData, amount: Number(e.target.value)})} 
                  />
                </div>
                <div>
                  <label className="text-[10px] font-black uppercase text-slate-400 mb-2 block">Total Biaya Belanja (Rp)</label>
                  <input 
                    type="number" 
                    className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-3.5 text-sm font-black text-rose-500 outline-none" 
                    placeholder="Contoh: 150000"
                    value={purchaseData.cost || ''} 
                    onChange={e => setPurchaseData({...purchaseData, cost: Number(e.target.value)})} 
                  />
                </div>

                <div className="pt-4 flex gap-3">
                  <button onClick={handleRecordPurchase} className="flex-1 bg-slate-900 text-white py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-emerald-600 transition-all">
                    Konfirmasi & Tambah Stok
                  </button>
                  <button onClick={() => setIsPurchaseModalOpen(false)} className="px-6 bg-slate-100 text-slate-400 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest">
                    Batal
                  </button>
                </div>
             </div>
          </div>
        </div>
      )}

      {isAddModalOpen && (
        <div className="fixed inset-0 z-[160] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setIsAddModalOpen(false)}></div>
          <div className="bg-white rounded-[3rem] w-full max-w-md overflow-hidden shadow-2xl relative z-10 p-8">
             <h3 className="text-2xl font-black text-slate-900 mb-6">Tambah Bahan Baru</h3>
             <div className="space-y-5">
                <input type="text" className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-3.5 text-sm font-bold outline-none" value={newItem.name} onChange={e => setNewItem({...newItem, name: e.target.value})} placeholder="Nama Bahan" />
                <div className="grid grid-cols-2 gap-4">
                  <input type="number" className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-3.5 text-sm font-bold outline-none" value={newItem.quantity || ''} onChange={e => setNewItem({...newItem, quantity: Number(e.target.value)})} placeholder="Jumlah" />
                  <input type="text" className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-3.5 text-sm font-bold outline-none" value={newItem.unit} onChange={e => setNewItem({...newItem, unit: e.target.value})} placeholder="Satuan (kg/L/potong/ekor)" />
                </div>
                <button onClick={() => {
                  if (newItem.name && newItem.quantity !== undefined) {
                    onUpdateInventory([{
                      id: Math.random().toString(36).substr(2, 9),
                      name: newItem.name || '',
                      quantity: newItem.quantity || 0,
                      unit: newItem.unit || 'kg',
                      status: (newItem.quantity || 0) > 10 ? 'Aman' : ((newItem.quantity || 0) > 0 ? 'Menipis' : 'Habis')
                    }, ...inventory]);
                    setIsAddModalOpen(false);
                    setNewItem({ name: '', quantity: 0, unit: 'kg', status: 'Aman' });
                  }
                }} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest">Simpan Bahan</button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

