             </div>
             <div>
               <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest leading-none mb-1">Sisa Piutang</p>
               <p className="text-lg font-black text-slate-800">Rp {(totalReceivable/1000).toFixed(0)}k</p>
             </div>
          </div>
        </div>
      </div>

      {/* FILTER & SEARCH BAR */}
      <div className="bg-white p-4 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col md:flex-row gap-4 items-center">
        <div className="relative flex-1 group">
           <Search size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-indigo-500 transition-colors" />
           <input 
            type="text" 
            placeholder="Cari nama, ID pesanan, atau menu..." 
            className="w-full pl-12 pr-6 py-3.5 bg-slate-50 border border-transparent rounded-[1.2rem] text-sm font-bold outline-none focus:bg-white focus:border-indigo-100 focus:ring-4 focus:ring-indigo-500/5 transition-all"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
