        </div>
        <div className="flex gap-2 w-full md:w-auto">
          <div className="relative group">
            <Calendar size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
            <input 
              type="date" 
              className="pl-12 pr-4 py-3.5 bg-slate-50 border border-transparent rounded-[1.2rem] text-sm font-bold outline-none focus:bg-white transition-all min-w-[180px]"
              value={dateFilter}
              onChange={(e) => setDateFilter(e.target.value)}
            />
          </div>
          <button 
            onClick={() => setIsModalOpen(true)}
            className="bg-slate-900 text-white px-8 py-3.5 rounded-[1.2rem] font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-3 hover:bg-emerald-600 transition-all shadow-xl shadow-slate-200"
          >
            <Plus size={20} /> <span className="hidden sm:inline">Tambah Pesanan</span>
          </button>
        </div>
      </div>

      {/* ORDERS LIST UI */}
      <div className="space-y-4">
        {filteredOrders.map((o) => {
          const debt = o.totalPrice - o.amountPaid;
          return (
            <div key={o.id} className="bg-white p-5 rounded-[2rem] border border-slate-100 flex flex-col lg:flex-row items-start lg:items-center gap-6 group hover:shadow-xl hover:border-indigo-100 transition-all duration-300">
              {/* Customer Info */}
              <div className="flex items-center gap-5 lg:w-[250px] shrink-0">
                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shrink-0 border transition-all ${o.type === 'Corporate' ? 'bg-indigo-50 text-indigo-500 border-indigo-100' : 'bg-slate-50 text-slate-400 border-slate-100'}`}>
                   {o.type === 'Corporate' ? <Building2 size={24} /> : <User2 size={24} />}
                </div>
                <div className="overflow-hidden">
                   <p className="text-sm font-black text-slate-800 leading-tight truncate">#{o.id} {o.customerName}</p>
                   <p className={`text-[8px] font-black uppercase tracking-widest mt-1.5 px-2 py-0.5 rounded-md inline-block ${o.type === 'Corporate' ? 'bg-indigo-100 text-indigo-600' : 'bg-slate-100 text-slate-500'}`}>{o.type}</p>
