              </div>

              {/* Items List */}
              <div className="flex-1 flex flex-wrap gap-2 min-w-0">
                {o.items.map((it, idx) => (
                  <span key={idx} className="bg-slate-50 border border-slate-100 text-slate-500 text-[10px] font-bold px-3 py-1.5 rounded-xl flex items-center gap-1.5 whitespace-nowrap group-hover:bg-white transition-colors shadow-sm">
