              </div>

              {/* Status & Timing */}
              <div className="flex flex-row lg:flex-col items-center lg:items-start gap-4 lg:gap-1.5 lg:w-[180px] shrink-0">
                 <div className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest shadow-sm ${getStatusBadge(o.status)}`}>
