                const Icon = getShiftIcon(s.type);
                return (
                  <button
                    key={s.type}
                    type="button"
                    onClick={() => setSelectedShift(s.type)}
                    className={`p-4 rounded-2xl border-2 transition-all flex flex-col items-center gap-2 group ${
                      selectedShift === s.type 
                        ? 'bg-emerald-50 border-emerald-500 text-emerald-900 shadow-sm' 
                        : 'bg-white border-slate-100 text-slate-400 hover:border-slate-200'
                    }`}
                  >
                    <Icon size={20} className={selectedShift === s.type ? 'text-emerald-500' : getShiftColor(s.type)} />
                    <div className="text-center">
                      <p className="text-[10px] font-black uppercase tracking-wider">{s.type}</p>
                      <p className="text-[8px] font-bold opacity-60">{s.startTime}</p>
                    </div>
                  </button>
                );
