import React, { useState } from 'react';
import { UtensilsCrossed, Lock, Sun, SunMedium, Moon, Eye, EyeOff, ShieldCheck, AlertCircle } from 'lucide-react';
import { ShiftType, UserRole, ShiftConfig, User as AdminUser } from '../types';

interface LoginProps {
  onLogin: (name: string, shift: ShiftType, role: UserRole) => void;
  shiftConfigs: ShiftConfig[];
  admins: AdminUser[]; // Menggunakan data admin dinamis
}

const Login: React.FC<LoginProps> = ({ onLogin, shiftConfigs, admins }) => {
  const [selectedUserIndex, setSelectedUserIndex] = useState(0);
  const [selectedShift, setSelectedShift] = useState<ShiftType>('Pagi');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const user = admins[selectedUserIndex];

    // Validasi password dinamis dari input admin
    if (password === user.password) {
      setError(false);
      onLogin(user.name, selectedShift, user.role);
    } else {
      setError(true);
      setTimeout(() => setError(false), 2000);
    }
  };

  const getShiftIcon = (type: ShiftType) => {
    switch (type) {
      case 'Pagi': return Sun;
      case 'Siang': return SunMedium;
      case 'Malam': return Moon;
    }
  };

  const getShiftColor = (type: ShiftType) => {
    switch (type) {
      case 'Pagi': return 'text-amber-500';
      case 'Siang': return 'text-sky-500';
      case 'Malam': return 'text-indigo-500';
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 flex items-center justify-center p-6 relative overflow-hidden">
      <div className="absolute top-0 left-0 w-full h-full opacity-20 pointer-events-none">
        <img 
          src="https://images.unsplash.com/photo-1555244162-803834f70033?auto=format&fit=crop&q=80&w=2000" 
          className="w-full h-full object-cover grayscale blur-sm"
          alt="bg"
        />
      </div>

      <div className="w-full max-w-lg bg-white/95 backdrop-blur-xl rounded-[3rem] shadow-2xl overflow-hidden relative z-10 animate-in zoom-in-95 duration-500">
        <div className="bg-slate-900 p-12 text-center text-white relative">
          <div className="w-16 h-16 bg-emerald-500 rounded-2xl flex items-center justify-center mx-auto mb-6 shadow-xl shadow-emerald-500/20 rotate-3 transition-transform hover:rotate-0 cursor-pointer">
            <UtensilsCrossed size={32} />
          </div>
          <h1 className="text-3xl font-black tracking-tight mb-2 uppercase">CaterElite AI</h1>
          <p className="text-slate-400 font-bold text-xs uppercase tracking-[0.3em]">Console v3.0 • Multi-Admin System</p>
        </div>

        <form onSubmit={handleSubmit} className="p-10 space-y-8">
          <div className="space-y-4">
            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1">Pilih Akun Bertugas</label>
            <div className="grid grid-cols-1 gap-3 max-h-60 overflow-y-auto no-scrollbar pr-1">
              {admins.map((user, idx) => (
                <button
                  key={user.id}
                  type="button"
                  onClick={() => {
                    setSelectedUserIndex(idx);
                    setError(false);
                    setPassword('');
                  }}
                  className={`flex items-center justify-between p-4 rounded-2xl border-2 transition-all group ${
                    selectedUserIndex === idx 
                      ? 'bg-slate-900 border-slate-900 text-white shadow-lg' 
                      : 'bg-white border-slate-100 text-slate-600 hover:border-slate-200'
                  }`}
                >
                  <div className="flex items-center gap-4">
                    <div className="w-10 h-10 rounded-xl overflow-hidden border border-slate-100">
                      <img src={user.avatarUrl || `https://ui-avatars.com/api/?name=${user.name}`} alt="Avatar" className="w-full h-full object-cover" />
                    </div>
                    <div className="text-left">
                      <p className="font-bold text-sm leading-none mb-1">{user.name}</p>
                      <p className={`text-[10px] font-black uppercase tracking-widest ${selectedUserIndex === idx ? 'text-emerald-400' : 'text-slate-400'}`}>
                        {user.role}
                      </p>
                    </div>
                  </div>
                  {selectedUserIndex === idx && <ShieldCheck size={18} className="text-emerald-400" />}
                </button>
              ))}
            </div>
          </div>

          <div className="space-y-4">
            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1">Sift & Keamanan</label>
            <div className="grid grid-cols-3 gap-3">
              {shiftConfigs.map((s) => {
                const Icon = getShiftIcon(s.type);
                return (
                  <button
                    key={s.type}
                    type="button"
                    onClick={() => setSelectedShift(s.type)}
                    className={`p-4 rounded-2xl border-2 transition-all flex flex-col items-center gap-2 group ${
                      selectedShift === s.type 
                        ? 'bg-emerald-50 border-emerald-500 text-emerald-900 shadow-sm' 
                        : 'bg-white border-slate-100 text-slate-400 hover:border-slate-200'
                    }`}
                  >
                    <Icon size={20} className={selectedShift === s.type ? 'text-emerald-500' : getShiftColor(s.type)} />
                    <div className="text-center">
                      <p className="text-[10px] font-black uppercase tracking-wider">{s.type}</p>
                      <p className="text-[8px] font-bold opacity-60">{s.startTime}</p>
                    </div>
                  </button>
                );
              })}
            </div>

            <div className="relative mt-6">
              <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 mb-2 block">Masukkan Password Anda</label>
              <div className="relative">
                <div className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400">
                  <Lock size={18} />
                </div>
                <input 
                  type={showPassword ? "text" : "password"}
                  className={`w-full bg-slate-50 border ${error ? 'border-rose-500 animate-shake' : 'border-slate-100'} rounded-2xl pl-12 pr-12 py-4 text-sm font-black outline-none focus:bg-white focus:ring-4 focus:ring-slate-900/5 transition-all`}
                  placeholder="••••••••"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                />
                <button 
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-900"
                >
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
              {error && (
                <div className="flex items-center gap-2 mt-2 text-rose-500 animate-in fade-in slide-in-from-top-1">
                  <AlertCircle size={14} />
                  <p className="text-[10px] font-black uppercase tracking-widest">Kredensial Salah!</p>
                </div>
              )}
            </div>
          </div>

          <button 
            type="submit"
            className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center justify-center gap-3 hover:bg-emerald-600 transition-all shadow-xl shadow-slate-200 group active:scale-[0.98]"
          >
            Autentikasi & Masuk
            <ShieldCheck size={18} className="group-hover:animate-pulse" />
          </button>
        </form>
      </div>

      <style>{`
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          25% { transform: translateX(-5px); }
          75% { transform: translateX(5px); }
        }
        .animate-shake {
          animation: shake 0.2s cubic-bezier(.36,.07,.19,.97) both;
          animation-iteration-count: 2;
        }
      `}</style>
    </div>
  );
};

export default Login;

