        onOpenSettings={() => isSuperAdmin && setIsSettingsOpen(true)} 
        role={currentUser.role} 
        isDesktop={false} 
      />

      {/* MAIN CONTENT AREA */}
      <div className="flex-1 flex flex-col lg:ml-72 min-h-screen relative">

        {/* HEADER */}
        <header className="h-20 bg-white/80 backdrop-blur-md border-b border-slate-100 flex items-center justify-between px-6 sticky top-0 z-[60]">
          <div className="flex items-center gap-4">
