            </div>
            {isProfileDropdownOpen && (
              <div className="absolute top-full right-0 mt-2 bg-white border border-slate-100 rounded-[2rem] shadow-2xl p-4 w-56 animate-in fade-in slide-in-from-top-4 z-[70]">
                <button onClick={handleLogout} className="w-full flex items-center gap-3 px-3 py-3 text-[10px] font-black uppercase tracking-widest text-rose-500 hover:bg-rose-50 rounded-xl transition-all">
                  <LogOut size={16} /> Logout Sesi
                </button>
              </div>
            )}
          </div>
        </header>

        {/* CONTENT */}
        <main className="flex-1 px-4 py-6 md:px-8 md:py-8 pb-32 lg:pb-8 overflow-x-hidden">
          <div className="max-w-7xl mx-auto">
            {activeTab === 'dashboard' && <Dashboard orders={orders} menu={menu} inventory={inventory} />}
            {activeTab === 'admins' && <AdminProfiles shiftConfigs={shiftConfigs} onUpdateShiftConfigs={setShiftConfigs} admins={admins} onUpdateAdmins={setAdmins} onNotify={addNotification} />}
            {activeTab === 'menu' && <MenuManager menu={menu} onUpdateMenu={setMenu} categories={['Paket Buffet', 'Snack Box']} onUpdateCategories={() => {}} inventory={inventory} onNotify={addNotification} />}
            {activeTab === 'orders' && <OrdersList orders={orders} onAddOrder={(o) => setOrders([o, ...orders])} onUpdateOrder={() => {}} menu={menu} currentAdminName={currentUser.name} />}
            {activeTab === 'social' && <SocialAnalytics menu={menu} settings={settings} onUpdateSettings={setSettings} />}
            {activeTab === 'security' && <AccountSecurity />}
            {activeTab === 'sales-report' && <SalesReport orders={orders} menu={menu} expenses={expenses} />}
          </div>
        </main>
      </div>

      {/* SETTINGS DRAWER */}
      {isSettingsOpen && (
        <div className="fixed inset-0 z-[150] flex justify-end">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-[2px]" onClick={() => setIsSettingsOpen(false)}></div>
          <div className="w-full max-w-lg bg-white h-full relative z-[160] shadow-2xl border-l border-slate-100 animate-in slide-in-from-right duration-300">
            <div className="flex items-center justify-between p-6 border-b border-slate-50">
               <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight">Bisnis Settings</h3>
               <button onClick={() => setIsSettingsOpen(false)} className="p-2 text-slate-400 hover:bg-slate-50 rounded-xl transition-all"><X size={24} /></button>
            </div>
            <div className="h-full overflow-y-auto p-6 no-scrollbar pb-32">
              <Settings settings={settings} onUpdateSettings={setSettings} />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

