const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [viewMode, setViewMode] = useState<'admin' | 'customer'>('admin');
  const [activeTab, setActiveTab] = useState<'dashboard' | 'menu' | 'orders' | 'receivables' | 'advisor' | 'admins' | 'social' | 'security' | 'sales-report'>('dashboard');
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isProfileDropdownOpen, setIsProfileDropdownOpen] = useState(false);

  const [menu, setMenu] = useState<MenuItem[]>(INITIAL_MENU);
  const [orders, setOrders] = useState<Order[]>([]);
  const [inventory, setInventory] = useState<IngredientStock[]>(INITIAL_INVENTORY);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [settings, setSettings] = useState<StoreSettings>(INITIAL_SETTINGS);
  const [admins, setAdmins] = useState<User[]>(INITIAL_ADMINS);
  const [shiftConfigs, setShiftConfigs] = useState<ShiftConfig[]>(INITIAL_SHIFTS);
  const [notifications, setNotifications] = useState<Notification[]>([]);

  const addNotification = useCallback((message: string, type: NotificationType) => {
    const id = Math.random().toString(36).substr(2, 9);
    setNotifications(prev => [{ id, message, type }, ...prev]);
    setTimeout(() => setNotifications(prev => prev.filter(n => n.id !== id)), 5000);
  }, []);

  const handleLogin = (name: string, shift: ShiftType, role: UserRole) => {
    const user = admins.find(a => a.name === name);
    setCurrentUser({
      id: user?.id || Math.random().toString(),
      name, role, shift,
      avatarUrl: user?.avatarUrl || `https://ui-avatars.com/api/?name=${name}`
    } as User);
    addNotification(`Selamat datang kembali, ${name}!`, 'success');
  };

  const handleLogout = () => { setCurrentUser(null); setIsProfileDropdownOpen(false); };

  if (!currentUser) return <Login onLogin={handleLogin} shiftConfigs={shiftConfigs} admins={admins} />;
  if (viewMode === 'customer') return <PublicMenu menu={menu} settings={settings} categories={['Paket Buffet', 'Snack Box']} onBackToAdmin={() => setViewMode('admin')} />;

  const isSuperAdmin = currentUser.role === 'Super Admin';

  const renderContent = () => {
    switch(activeTab) {
      case 'dashboard': return <Dashboard orders={orders} menu={menu} inventory={inventory} />;
      case 'menu': return <MenuManager menu={menu} onUpdateMenu={setMenu} categories={['Paket Buffet', 'Snack Box']} onUpdateCategories={() => {}} inventory={inventory} onNotify={addNotification} />;
      case 'orders': return <OrdersList orders={orders} onAddOrder={(o) => setOrders([o, ...orders])} onUpdateOrder={() => {}} menu={menu} currentAdminName={currentUser.name} onNotify={addNotification} />;
      case 'receivables': return <ReceivablesList orders={orders} onUpdateOrder={() => {}} />;
      case 'advisor': return <SmartAdvisor inventory={inventory} orders={orders} menu={menu} onUpdateInventory={setInventory} onNotify={addNotification} currentAdmin={currentUser.name} />;
      case 'admins': return <AdminProfiles shiftConfigs={shiftConfigs} onUpdateShiftConfigs={setShiftConfigs} admins={admins} onUpdateAdmins={setAdmins} onNotify={addNotification} />;
      case 'social': return <SocialAnalytics menu={menu} settings={settings} onUpdateSettings={setSettings} />;
      case 'security': return <AccountSecurity />;
      case 'sales-report': return <SalesReport orders={orders} menu={menu} expenses={expenses} />;
      default: return <Dashboard orders={orders} menu={menu} inventory={inventory} />;
    }
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] flex font-sans selection:bg-emerald-100 text-slate-900 overflow-x-hidden">

      {/* Notifications */}
      <div className="fixed top-24 right-6 z-[300] flex flex-col gap-3 w-full max-w-sm pointer-events-none px-4">
        {notifications.map((n) => (
          <div key={n.id} className={`pointer-events-auto p-4 rounded-[1.8rem] shadow-2xl backdrop-blur-xl border flex items-start gap-4 animate-in slide-in-from-right duration-500 ${n.type === 'error' ? 'bg-rose-600/90 text-white border-rose-500' : n.type === 'warning' ? 'bg-amber-500/90 text-white border-amber-400' : 'bg-emerald-600/90 text-white border-emerald-500'}`}>
            <div className="flex-1">
              <p className="text-[10px] font-black uppercase tracking-widest opacity-70 mb-1">{n.type === 'error' ? 'Peringatan' : 'Berhasil'}</p>
              <p className="text-sm font-bold leading-tight">{n.message}</p>
            </div>
            <button onClick={() => setNotifications(prev => prev.filter(x => x.id !== n.id))} className="text-white/40 hover:text-white transition-colors"><X size={16} /></button>
          </div>
        ))}
      </div>

      {/* Sidebars */}
      <Sidebar 
        isOpen={true} setIsOpen={() => {}} activeTab={activeTab} setActiveTab={setActiveTab} 
        onPreviewMenu={() => setViewMode('customer')} logoUrl={settings.logoUrl} 
        onOpenSettings={() => isSuperAdmin && setIsSettingsOpen(true)} role={currentUser.role} isDesktop={true} 
      />

      <Sidebar 
        isOpen={isSidebarOpen} setIsOpen={setIsSidebarOpen} activeTab={activeTab} setActiveTab={setActiveTab} 
        onPreviewMenu={() => setViewMode('customer')} logoUrl={settings.logoUrl} 
        onOpenSettings={() => isSuperAdmin && setIsSettingsOpen(true)} role={currentUser.role} isDesktop={false} 
      />

      {/* Main Layout */}
      <div className="flex-1 flex flex-col lg:ml-72 min-h-screen relative">
        <header className="h-20 bg-white/80 backdrop-blur-md border-b border-slate-100 flex items-center justify-between px-6 sticky top-0 z-[100]">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setIsSidebarOpen(true)} 
              className="p-2.5 bg-slate-50 text-slate-600 lg:hidden rounded-xl hover:bg-slate-100 transition-all border border-slate-100"
            >
              <MenuIcon size={22} />
            </button>
            <div className="hidden md:flex items-center gap-2 px-3 py-1 rounded-full border bg-slate-50 text-slate-500 border-slate-200">
              <span className="text-[10px] font-black uppercase tracking-widest">{currentUser.role}</span>
            </div>
          </div>

          <div className="relative">
            <div className="flex items-center gap-3 cursor-pointer p-1 pr-3 rounded-full hover:bg-slate-50 border border-transparent hover:border-slate-100 transition-all" onClick={() => setIsProfileDropdownOpen(!isProfileDropdownOpen)}>
              <div className="w-9 h-9 rounded-full bg-slate-100 border-2 border-white shadow-sm overflow-hidden text-slate-400 flex items-center justify-center">
                {currentUser.avatarUrl ? <img src={currentUser.avatarUrl} alt="P" className="w-full h-full object-cover" /> : <UserCog size={20} />}
              </div>
              <div className="hidden sm:block text-left">
                <p className="text-[10px] font-black text-slate-800 leading-none uppercase tracking-tight">{currentUser.name}</p>
              </div>
            </div>
            {isProfileDropdownOpen && (
              <div className="absolute top-full right-0 mt-2 bg-white border border-slate-100 rounded-[2rem] shadow-2xl p-4 w-56 animate-in fade-in slide-in-from-top-4 z-[110]">
                <button onClick={handleLogout} className="w-full flex items-center gap-3 px-3 py-3 text-[10px] font-black uppercase tracking-widest text-rose-500 hover:bg-rose-50 rounded-xl transition-all">
                  <LogOut size={16} /> Logout Sesi
                </button>
              </div>
            )}
          </div>
        </header>

        <main className="flex-1 px-4 py-6 md:px-8 md:py-8 pb-32 lg:pb-8">
          <div className="max-w-7xl mx-auto">
            {renderContent()}
          </div>
        </main>
      </div>

      {isSettingsOpen && (
        <div className="fixed inset-0 z-[250] flex justify-end">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-[2px]" onClick={() => setIsSettingsOpen(false)}></div>
          <div className="w-full max-w-lg bg-white h-full relative z-[260] shadow-2xl border-l border-slate-100 animate-in slide-in-from-right duration-300">
            <div className="flex items-center justify-between p-6 border-b border-slate-50">
               <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight">Bisnis Settings</h3>
               <button onClick={() => setIsSettingsOpen(false)} className="p-2 text-slate-400 hover:bg-slate-50 rounded-xl transition-all"><X size={24} /></button>
            </div>
            <div className="h-full overflow-y-auto p-6 no-scrollbar pb-32">
              <Settings settings={settings} onUpdateSettings={setSettings} />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React from 'react';
import { 
  UtensilsCrossed, 
  Eye, 
  X,
  Settings as SettingsIcon,
  Share2,
  Shield,
  BarChart3,
  LayoutDashboard,
  ChevronRight,
  UserCog,
  ShoppingBag,
  ClipboardList,
  Wallet,
  CookingPot
} from 'lucide-react';
import { UserRole } from '../types';

interface SidebarProps {
  isOpen: boolean;
  setIsOpen: (open: boolean) => void;
  activeTab: string;
  setActiveTab: (tab: any) => void;
  onPreviewMenu: () => void;
  logoUrl?: string;
  onOpenSettings: () => void;
  role: UserRole;
  isDesktop?: boolean;
}

const Sidebar: React.FC<SidebarProps> = ({ 
  isOpen, 
  setIsOpen, 
  onPreviewMenu, 
  logoUrl,
  onOpenSettings,
  setActiveTab,
  activeTab,
  role,
  isDesktop = false
}) => {
  const isSuperAdmin = role === 'Super Admin';

  // Menu Operasional (Harian) - Diakses oleh semua role
  const mainMenuItems = [
    { id: 'dashboard', label: 'Dashboard Home', icon: LayoutDashboard },
    { id: 'menu', label: 'Katalog Menu', icon: ShoppingBag },
    { id: 'orders', label: 'Daftar Pesanan', icon: ClipboardList },
    { id: 'advisor', label: 'Dapur & MRP', icon: CookingPot },
    { id: 'receivables', label: 'Buku Piutang', icon: Wallet },
  ];

  // Menu Strategi & Pengaturan (Manajerial) - Beberapa dibatasi
  const secondaryMenuItems = [
    { id: 'sales-report', label: 'Laporan Keuangan', icon: BarChart3 },
    { id: 'social', label: 'Strategi Sosial', icon: Share2 },
    // Menu ini hanya ditampilkan jika Super Admin
    ...(isSuperAdmin ? [{ id: 'admins', label: 'Manajemen Admin', icon: UserCog }] : []),
    { id: 'security', label: 'Keamanan Akun', icon: Shield },
  ];

  const sidebarInnerContent = (
    <div className="h-full bg-white flex flex-col border-r border-slate-100 shadow-xl lg:shadow-none">
      {/* Header Sidebar */}
      <div className="p-8 flex items-center justify-between border-b border-slate-50">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 bg-slate-900 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-slate-200 overflow-hidden">
            {logoUrl ? <img src={logoUrl} alt="Logo" className="w-full h-full object-cover" /> : <UtensilsCrossed size={24} />}
          </div>
          <div>
            <h1 className="text-sm font-black text-slate-900 tracking-tighter uppercase leading-none">CaterElite</h1>
            <p className="text-[9px] font-black text-emerald-500 tracking-[0.2em] mt-1 uppercase">Console AI</p>
          </div>
        </div>
        {!isDesktop && (
          <button onClick={() => setIsOpen(false)} className="p-2 text-slate-400 hover:bg-slate-50 rounded-xl transition-all lg:hidden">
            <X size={20} />
          </button>
        )}
      </div>

      {/* Navigation Links */}
      <div className="flex-1 overflow-y-auto py-8 px-4 space-y-8 no-scrollbar pb-10">
        <div>
          <p className="text-[10px] font-black text-slate-300 uppercase tracking-[0.2em] mb-4 ml-4">Operasional Harian</p>
          <nav className="space-y-1">
            {mainMenuItems.map((item) => (
              <button
                key={item.id}
                onClick={() => {
                  setActiveTab(item.id);
                  if (!isDesktop) setIsOpen(false);
                }}
                className={`w-full flex items-center justify-between p-4 rounded-2xl transition-all group ${
                  activeTab === item.id 
                    ? 'bg-slate-900 text-white shadow-xl shadow-slate-200' 
                    : 'text-slate-400 hover:bg-slate-50 hover:text-slate-600'
                }`}
              >
                <div className="flex items-center gap-4">
                  <item.icon size={20} className={activeTab === item.id ? 'text-emerald-400' : 'group-hover:text-slate-900'} />
                  <span className="text-xs font-black uppercase tracking-widest">{item.label}</span>
                </div>
                {activeTab === item.id && <ChevronRight size={14} className="text-white/20" />}
              </button>
            ))}
          </nav>
        </div>

        <div>
          <p className="text-[10px] font-black text-slate-300 uppercase tracking-[0.2em] mb-4 ml-4">Strategi & Pengaturan</p>
          <nav className="space-y-1">
            {secondaryMenuItems.map((item) => (
              <button
                key={item.id}
                onClick={() => {
                  setActiveTab(item.id);
                  if (!isDesktop) setIsOpen(false);
                }}
                className={`w-full flex items-center justify-between p-4 rounded-2xl transition-all group ${
                  activeTab === item.id 
                    ? 'bg-slate-900 text-white shadow-xl shadow-slate-200' 
                    : 'text-slate-400 hover:bg-slate-50 hover:text-slate-600'
                }`}
              >
                <div className="flex items-center gap-4">
                  <item.icon size={20} className={activeTab === item.id ? 'text-indigo-400' : 'group-hover:text-slate-900'} />
                  <span className="text-xs font-black uppercase tracking-widest">{item.label}</span>
                </div>
              </button>
            ))}
          </nav>
        </div>
      </div>

      {/* Action Footer */}
      <div className="p-6 border-t border-slate-50 space-y-3">
        <button 
          onClick={() => {
            onPreviewMenu();
            if(!isDesktop) setIsOpen(false);
          }}
          className="w-full flex items-center gap-4 p-4 bg-emerald-50 text-emerald-600 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-emerald-600 hover:text-white transition-all border border-emerald-100 shadow-sm"
        >
          <Eye size={18} /> Preview Katalog
        </button>

        {/* Tombol Settings hanya tampil untuk Super Admin */}
        {isSuperAdmin && (
          <button 
            onClick={() => {
              onOpenSettings();
              if(!isDesktop) setIsOpen(false);
            }}
            className="w-full flex items-center gap-4 p-4 bg-slate-50 text-slate-500 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-slate-900 hover:text-white transition-all border border-slate-100"
          >
            <SettingsIcon size={18} /> Settings Bisnis
          </button>
        )}
      </div>
    </div>
  );

  if (isDesktop) {
    return (
      <aside className="hidden lg:block w-72 h-screen fixed left-0 top-0 z-40">
        {sidebarInnerContent}
      </aside>
    );
  }

  return (
    <div className={`fixed inset-0 z-[200] lg:hidden transition-all duration-300 ${isOpen ? 'visible' : 'invisible'}`}>
      <div 
        className={`absolute inset-0 bg-slate-950/60 backdrop-blur-sm transition-opacity duration-300 ${isOpen ? 'opacity-100' : 'opacity-0'}`} 
        onClick={() => setIsOpen(false)}
      ></div>
      <div className={`absolute top-0 left-0 w-80 h-full bg-white transition-transform duration-500 ease-out transform shadow-2xl ${isOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        {sidebarInnerContent}
      </div>
    </div>
  );
};

export default Sidebar;

