      {/* Main Layout */}
      <div className="flex-1 flex flex-col lg:ml-72 min-h-screen relative">
        <header className="h-24 bg-white/70 backdrop-blur-2xl border-b border-slate-100 flex items-center justify-between px-8 sticky top-0 z-[100]">
          <div className="flex items-center gap-6">
