import React, { useState } from 'react';
import { UtensilsCrossed, Lock, Sun, SunMedium, Moon, Eye, EyeOff, ShieldCheck, AlertCircle, ChevronRight, User } from 'lucide-react';
import { ShiftType, UserRole, ShiftConfig, User as AdminUser } from '../types';

interface LoginProps {
  onLogin: (name: string, shift: ShiftType, role: UserRole) => void;
  shiftConfigs: ShiftConfig[];
  admins: AdminUser[];
}

const Login: React.FC<LoginProps> = ({ onLogin, shiftConfigs, admins }) => {
  const [selectedUserIndex, setSelectedUserIndex] = useState(0);
  const [selectedShift, setSelectedShift] = useState<ShiftType>('Pagi');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const user = admins[selectedUserIndex];

    if (password === user.password) {
      setError(false);
      onLogin(user.name, selectedShift, user.role);
    } else {
      setError(true);
      setTimeout(() => setError(false), 2000);
    }
  };

  const getShiftIcon = (type: ShiftType) => {
    switch (type) {
      case 'Pagi': return Sun;
      case 'Siang': return SunMedium;
      case 'Malam': return Moon;
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 flex items-center justify-center p-4 sm:p-6 relative overflow-hidden font-sans">
      {/* Dynamic Ambient Background */}
      <div className="absolute inset-0 z-0">
        <img 
          src="https://images.unsplash.com/photo-1555244162-803834f70033?auto=format&fit=crop&q=80&w=2000" 
          className="w-full h-full object-cover scale-110 blur-[2px]"
          alt="Culinary Background"
        />
        <div className="absolute inset-0 bg-gradient-to-br from-slate-950 via-slate-900/90 to-slate-950/80"></div>
      </div>

      {/* Decorative Orbs */}
      <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-emerald-500/10 rounded-full blur-[120px] animate-pulse"></div>
      <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-indigo-500/10 rounded-full blur-[120px] animate-pulse" style={{ animationDelay: '2s' }}></div>

      <div className="w-full max-w-xl bg-white/10 backdrop-blur-2xl rounded-[3.5rem] shadow-[0_32px_64px_-16px_rgba(0,0,0,0.5)] border border-white/10 overflow-hidden relative z-10 animate-in zoom-in-95 duration-700">

        {/* Header Section */}
        <div className="p-10 pb-6 text-center">
          <div className="w-20 h-20 bg-emerald-500 rounded-[2rem] flex items-center justify-center mx-auto mb-8 shadow-2xl shadow-emerald-500/30 rotate-6 hover:rotate-0 transition-transform duration-500">
            <UtensilsCrossed size={36} className="text-white" />
          </div>
          <h1 className="text-5xl font-black text-white tracking-tighter mb-2 italic">Caterly</h1>
          <p className="text-slate-400 font-bold text-[10px] uppercase tracking-[0.4em]">Integrated Catering Management</p>
        </div>

        <form onSubmit={handleSubmit} className="px-8 sm:px-12 pb-12 space-y-10">
          {/* User Selection Grid */}
          <div className="space-y-4">
            <div className="flex justify-between items-end px-2">
              <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Pilih Akun Bertugas</label>
              <span className="text-[9px] font-bold text-emerald-400 uppercase tracking-widest">{admins.length} Admin Online</span>
            </div>
            <div className="grid grid-cols-1 gap-3">
              {admins.map((user, idx) => (
                <button
                  key={user.id}
                  type="button"
                  onClick={() => {
                    setSelectedUserIndex(idx);
                    setError(false);
                    setPassword('');
                  }}
                  className={`flex items-center justify-between p-4 rounded-[1.8rem] border-2 transition-all duration-300 group ${
                    selectedUserIndex === idx 
                      ? 'bg-white border-white text-slate-900 shadow-xl translate-x-1' 
                      : 'bg-white/5 border-white/5 text-slate-400 hover:bg-white/10 hover:border-white/10'
                  }`}
                >
                  <div className="flex items-center gap-4">
                    <div className={`w-12 h-12 rounded-2xl overflow-hidden border-2 transition-colors ${selectedUserIndex === idx ? 'border-emerald-500' : 'border-white/10'} bg-slate-800`}>
                      {user.avatarUrl ? <img src={user.avatarUrl} alt="A" className="w-full h-full object-cover" /> : <User size={24} className="m-3" />}
                    </div>
                    <div className="text-left">
                      <p className={`font-black text-sm tracking-tight ${selectedUserIndex === idx ? 'text-slate-900' : 'text-white'}`}>{user.name}</p>
                      <p className={`text-[9px] font-bold uppercase tracking-widest ${selectedUserIndex === idx ? 'text-emerald-600' : 'text-slate-500'}`}>
                        {user.role}
                      </p>
                    </div>
                  </div>
                  {selectedUserIndex === idx ? (
                    <div className="w-8 h-8 bg-emerald-500 rounded-full flex items-center justify-center text-white animate-in zoom-in duration-300">
                      <ShieldCheck size={18} />
                    </div>
                  ) : (
                    <ChevronRight size={18} className="opacity-20 group-hover:opacity-100 transition-opacity" />
                  )}
                </button>
              ))}
            </div>
          </div>

          {/* Shift Selection */}
          <div className="space-y-4">
            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 px-2">Sift Operasional</label>
            <div className="grid grid-cols-3 gap-3">
              {shiftConfigs.map((s) => {
                const Icon = getShiftIcon(s.type);
                const isActive = selectedShift === s.type;
                return (
                  <button
                    key={s.type}
                    type="button"
                    onClick={() => setSelectedShift(s.type)}
                    className={`p-4 rounded-2xl border-2 transition-all flex flex-col items-center gap-2 group relative overflow-hidden ${
                      isActive 
                        ? 'bg-emerald-500 border-emerald-500 text-white shadow-lg shadow-emerald-500/20' 
                        : 'bg-white/5 border-white/5 text-slate-500 hover:bg-white/10 hover:border-white/10'
                    }`}
                  >
                    <Icon size={20} className={isActive ? 'text-white' : 'text-slate-400 group-hover:text-white'} />
                    <p className="text-[9px] font-black uppercase tracking-widest">{s.type}</p>
                    {isActive && <div className="absolute bottom-0 left-0 w-full h-1 bg-white/20"></div>}
                  </button>
                );
              })}
            </div>
          </div>

          {/* Password Input */}
          <div className="space-y-4">
            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 px-2">Password Verifikasi</label>
            <div className="relative group">
              <div className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-emerald-400 transition-colors">
                <Lock size={20} />
              </div>
              <input 
                type={showPassword ? "text" : "password"}
                className={`w-full bg-white/5 border-2 ${error ? 'border-rose-500 animate-shake' : 'border-white/5'} rounded-[1.8rem] pl-16 pr-16 py-5 text-base font-black text-white outline-none focus:bg-white/10 focus:border-emerald-500/50 focus:ring-8 focus:ring-emerald-500/5 transition-all placeholder:text-slate-600`}
                placeholder="Masukkan kata sandi..."
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
              />
              <button 
                type="button" 
                onClick={() => setShowPassword(!showPassword)} 
                className="absolute right-6 top-1/2 -translate-y-1/2 text-slate-500 hover:text-white transition-colors"
              >
                {showPassword ? <EyeOff size={22} /> : <Eye size={22} />}
              </button>
              {error && (
                <div className="absolute -bottom-6 left-2 flex items-center gap-2 text-rose-500 animate-in slide-in-from-top-1">
                  <AlertCircle size={12} />
                  <p className="text-[9px] font-black uppercase tracking-widest">Kombinasi password tidak valid!</p>
                </div>
              )}
            </div>
          </div>

          <button 
            type="submit" 
            className="w-full bg-emerald-500 text-white py-6 rounded-[2rem] font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center gap-4 hover:bg-emerald-400 hover:scale-[1.02] active:scale-95 transition-all shadow-2xl shadow-emerald-500/30 group"
          >
            Mulai Sesi Bertugas <ShieldCheck size={20} className="group-hover:rotate-12 transition-transform" />
          </button>
        </form>
      </div>

      <style>{`
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          20% { transform: translateX(-8px); }
          40% { transform: translateX(8px); }
          60% { transform: translateX(-8px); }
          80% { transform: translateX(8px); }
        }
        .animate-shake { animation: shake 0.4s cubic-bezier(.36,.07,.19,.97) both; }
      `}</style>
    </div>
  );
};

export default Login;

