            if(!isDesktop) setIsOpen(false);
          }}
          className="w-full flex items-center gap-4 p-5 bg-emerald-50 text-emerald-600 rounded-[1.8rem] font-black text-[11px] uppercase tracking-widest hover:bg-emerald-600 hover:text-white transition-all border border-emerald-100 shadow-sm active:scale-95"
        >
          <Eye size={20} /> Preview Katalog
        </button>

        {isSuperAdmin && (
          <button 
            onClick={() => {
              onOpenSettings();
              if(!isDesktop) setIsOpen(false);
            }}
            className="w-full flex items-center gap-4 p-5 bg-white text-slate-500 rounded-[1.8rem] font-black text-[11px] uppercase tracking-widest hover:bg-slate-900 hover:text-white transition-all border border-slate-200 shadow-sm active:scale-95"
          >
            <SettingsIcon size={20} /> Settings Bisnis
          </button>
        )}
      </div>
    </div>
  );

  if (isDesktop) {
    return (
      <aside className="hidden lg:block w-72 h-screen fixed left-0 top-0 z-40">
        {sidebarInnerContent}
      </aside>
    );
  }

  return (
    <div className={`fixed inset-0 z-[200] lg:hidden transition-all duration-300 ${isOpen ? 'visible' : 'invisible'}`}>
      <div 
        className={`absolute inset-0 bg-slate-950/60 backdrop-blur-md transition-opacity duration-500 ${isOpen ? 'opacity-100' : 'opacity-0'}`} 
        onClick={() => setIsOpen(false)}
      ></div>
      <div className={`absolute top-0 left-0 w-80 h-full bg-white transition-transform duration-500 ease-out transform shadow-[0_0_80px_rgba(0,0,0,0.3)] ${isOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        {sidebarInnerContent}
      </div>
    </div>
  );
};

