  onPreviewMenu: () => void;
  logoUrl?: string;
  storeName: string; // Tambahkan ini
  onOpenSettings: () => void;
  role: UserRole;
  isDesktop?: boolean;
}

const Sidebar: React.FC<SidebarProps> = ({ 
  isOpen, 
  setIsOpen, 
  onPreviewMenu, 
  logoUrl,
  storeName, // Tambahkan ini
  onOpenSettings,
  setActiveTab,
  activeTab,
  role,
  isDesktop = false
}) => {
