        </div>
      </footer>

      {cartCount > 0 && (
        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 w-[90%] max-w-2xl bg-slate-900/95 backdrop-blur-xl p-5 rounded-[2.5rem] shadow-2xl flex items-center justify-between text-white z-[200] border border-white/20 animate-in slide-in-from-bottom-10">
           <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-emerald-500 rounded-2xl flex items-center justify-center font-black shadow-lg border border-emerald-400">
                {cartCount}
              </div>
              <div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Total Pesanan</p>
                <p className="text-base font-black">Rp {cartTotal.toLocaleString()}</p>
              </div>
           </div>
           <button 
             onClick={handleOrderWhatsApp}
             className="bg-emerald-500 hover:bg-emerald-400 text-white px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest transition-all active:scale-95 shadow-lg shadow-emerald-500/20 border border-emerald-400"
           >
             Order via WhatsApp
           </button>
        </div>
      )}
    </div>
  );
};

export default PublicMenu;

