        isOpen={true} setIsOpen={() => {}} activeTab={activeTab} setActiveTab={setActiveTab} 
        onPreviewMenu={() => setViewMode('customer')} logoUrl={settings.logoUrl} storeName={settings.storeName}
        onOpenSettings={() => isSuperAdmin && setIsSettingsOpen(true)} role={currentUser.role} isDesktop={true} 
      />

      <Sidebar 
        isOpen={isSidebarOpen} setIsOpen={setIsSidebarOpen} activeTab={activeTab} setActiveTab={setActiveTab} 
        onPreviewMenu={() => setViewMode('customer')} logoUrl={settings.logoUrl} storeName={settings.storeName}
        onOpenSettings={() => isSuperAdmin && setIsSettingsOpen(true)} role={currentUser.role} isDesktop={false} 
      />

      {/* Main Layout - Optimized for PC */}
      <div className="flex-1 flex flex-col lg:ml-72 min-h-screen relative bg-[#fbfcfd]">
        <header className="h-24 bg-white/80 backdrop-blur-3xl border-b border-slate-100 flex items-center justify-between px-8 lg:px-12 sticky top-0 z-[100] shadow-[0_1px_2px_rgba(0,0,0,0.02)]">
          <div className="flex items-center gap-8">
            <button 
              onClick={() => setIsSidebarOpen(true)} 
              className="p-3 bg-slate-50 text-slate-600 lg:hidden rounded-2xl hover:bg-slate-100 transition-all border border-slate-100"
            >
              <MenuIcon size={24} />
            </button>
            <div className="hidden md:flex flex-col">
              <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.25em] mb-1.5">{settings.storeName}</h2>
              <div className="flex items-center gap-2.5">
                <span className="text-base font-black text-slate-900 uppercase tracking-tight">{activeTab.replace('-', ' ')}</span>
                <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse ring-4 ring-emerald-50"></div>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-6">
            <div className="hidden xl:flex items-center gap-3 px-5 py-2.5 rounded-[1.25rem] border bg-slate-50 text-slate-500 border-slate-200">
               <div className="w-2 h-2 rounded-full bg-indigo-500"></div>
               <span className="text-[10px] font-black uppercase tracking-widest leading-none">{currentUser.shift} Shift Active</span>
            </div>

            <div className="h-10 w-px bg-slate-100 hidden sm:block"></div>

            <div className="relative">
              <div className="flex items-center gap-4 cursor-pointer p-1.5 pr-5 rounded-[1.75rem] hover:bg-slate-50 border border-transparent hover:border-slate-200 transition-all duration-300 group" onClick={() => setIsProfileDropdownOpen(!isProfileDropdownOpen)}>
                <div className="w-12 h-12 rounded-[1.25rem] bg-white border-2 border-white shadow-[0_8px_16px_-4px_rgba(0,0,0,0.1)] overflow-hidden text-slate-400 flex items-center justify-center transition-all duration-500 group-hover:scale-105 group-hover:shadow-emerald-100">
                  {currentUser.avatarUrl ? <img src={currentUser.avatarUrl} alt="P" className="w-full h-full object-cover" /> : <UserCog size={24} />}
                </div>
                <div className="hidden sm:block text-left">
                  <p className="text-xs font-black text-slate-900 leading-none uppercase tracking-tight">{currentUser.name}</p>
                  <p className="text-[9px] font-bold text-emerald-600 uppercase tracking-widest mt-1.5">{currentUser.role}</p>
                </div>
                <ChevronDown size={14} className={`text-slate-300 transition-transform duration-500 ${isProfileDropdownOpen ? 'rotate-180' : ''}`} />
              </div>

              {isProfileDropdownOpen && (
                <div className="absolute top-full right-0 mt-4 bg-white border border-slate-100 rounded-[2.5rem] shadow-[0_40px_80px_-20px_rgba(0,0,0,0.15)] p-5 w-72 animate-in fade-in slide-in-from-top-4 z-[110] border-t-4 border-t-emerald-500">
                  <div className="p-4 mb-3 border-b border-slate-50 flex items-center gap-4">
                    <div className="w-10 h-10 rounded-xl bg-slate-50 flex items-center justify-center text-slate-400">
                       <UserCog size={20} />
                    </div>
                    <div>
                      <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest mb-1">Akun Sesi</p>
                      <p className="text-xs font-bold text-slate-800">{currentUser.name}</p>
                    </div>
                  </div>
                  <button onClick={handleLogout} className="w-full flex items-center gap-3 px-5 py-4 text-[10px] font-black uppercase tracking-widest text-rose-500 hover:bg-rose-50 rounded-2xl transition-all">
                    <LogOut size={18} /> Keluar Sistem
                  </button>
                </div>
              )}
            </div>
