import React, { useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer
} from 'recharts';
import { TrendingUp, ShoppingBag, Wallet, Users, Star, AlertTriangle, ArrowRight } from 'lucide-react';
import { MenuItem, Order, IngredientStock } from '../types';

interface DashboardProps {
  orders: Order[];
  menu: MenuItem[];
  inventory: IngredientStock[];
}

const Dashboard: React.FC<DashboardProps> = ({ orders, menu, inventory }) => {
  const totalRevenue = orders.reduce((acc, curr) => acc + curr.totalPrice, 0);
  const totalReceivables = orders.reduce((acc, curr) => acc + (curr.totalPrice - curr.amountPaid), 0);
  const corporateOrders = orders.filter(o => o.type === 'Corporate').length;

  const popularDishes = [...menu]
    .sort((a, b) => b.salesCount - a.salesCount)
    .slice(0, 3);

  // MRP Calculation for Dashboard Alert
  const deficits = useMemo(() => {
    const requirements: { [key: string]: number } = {};
    orders.filter(o => o.status === 'Pending' || o.status === 'Confirmed').forEach(order => {
      order.items.forEach(orderItemStr => {
        const match = orderItemStr.match(/(.*)\s\((\d+)\)/);
        if (!match) return;
        const [_, itemName, qtyStr] = match;
        const quantity = parseInt(qtyStr);
        const menuItem = menu.find(m => m.name === itemName.trim());
        if (menuItem?.recipe) {
          menuItem.recipe.forEach(ing => {
            requirements[ing.ingredientId] = (requirements[ing.ingredientId] || 0) + (ing.amountPerUnit * quantity);
          });
        }
      });
    });

    return Object.entries(requirements).map(([id, needed]) => {
      const stock = inventory.find(i => i.id === id);
      const stockQty = stock ? stock.quantity : 0;
      return { name: stock?.name || 'Unknown', deficit: Math.max(0, needed - stockQty) };
    }).filter(d => d.deficit > 0);
  }, [orders, menu, inventory]);

  const revenueData = [
    { name: 'Mon', sales: 4000 },
    { name: 'Tue', sales: 3000 },
    { name: 'Wed', sales: 6500 },
    { name: 'Thu', sales: 4500 },
    { name: 'Fri', sales: 9000 },
    { name: 'Sat', sales: 12000 },
    { name: 'Sun', sales: 10500 },
  ];

  const StatCard = ({ title, value, icon: Icon, colorClass, iconBg }: any) => (
    <div className="bg-white p-8 rounded-[2.5rem] shadow-[0_2px_4px_rgba(0,0,0,0.01)] border border-slate-50 flex items-center gap-8 group hover:shadow-xl hover:border-indigo-100 transition-all duration-500">
      <div className={`w-16 h-16 ${iconBg} ${colorClass} rounded-[1.5rem] flex items-center justify-center transition-all duration-500 group-hover:scale-110 group-hover:rotate-6`}>
        <Icon size={28} />
      </div>
      <div>
        <p className="text-[11px] text-slate-400 font-black uppercase tracking-[0.2em] mb-2">{title}</p>
        <h3 className="text-3xl font-black text-slate-800 tracking-tight">
          {value}
        </h3>
      </div>
    </div>
  );

  return (
    <div className="space-y-10 animate-in fade-in duration-1000">
      {deficits.length > 0 && (
        <div className="bg-amber-500 rounded-[3rem] p-8 text-white flex flex-col md:flex-row items-center justify-between gap-8 shadow-2xl shadow-amber-100 border border-amber-400 relative overflow-hidden group">
           <div className="absolute inset-0 bg-white/5 opacity-0 group-hover:opacity-100 transition-opacity"></div>
           <div className="flex items-center gap-6 relative z-10">
              <div className="w-16 h-16 bg-white/20 rounded-[1.5rem] flex items-center justify-center backdrop-blur-xl border border-white/20 shadow-lg">
                <AlertTriangle size={32} className="animate-pulse" />
              </div>
              <div>
                <h4 className="font-black text-2xl leading-tight">Attention: {deficits.length} Ingredients Shortage</h4>
                <p className="text-white/80 text-[11px] font-bold uppercase tracking-[0.25em] mt-1.5">MRP System detects missing stock for active orders</p>
              </div>
           </div>
           <div className="flex items-center gap-4 bg-white/10 px-8 py-4 rounded-2xl text-[11px] font-black uppercase tracking-widest border border-white/10 hover:bg-white/20 transition-all cursor-pointer relative z-10">
              Check Kitchen Planner <ArrowRight size={18} />
           </div>
        </div>
      )}

      {/* Stats Grid - PC Optimized (4 cols) */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-6">
        <StatCard 
          title="Gross Revenue" 
          value={`Rp ${(totalRevenue/1000).toFixed(0)}k`} 
          icon={TrendingUp} 
          colorClass="text-emerald-500" 
          iconBg="bg-emerald-50" 
        />
        <StatCard 
          title="Account Receivables" 
          value={`Rp ${(totalReceivables/1000).toFixed(0)}k`} 
          icon={Wallet} 
          colorClass="text-rose-500" 
          iconBg="bg-rose-50" 
        />
        <StatCard 
          title="Active Orders" 
          value={orders.length} 
          icon={ShoppingBag} 
          colorClass="text-indigo-500" 
          iconBg="bg-indigo-50" 
        />
        <StatCard 
          title="Corporate Rate" 
          value={`${((corporateOrders/Math.max(1, orders.length))*100).toFixed(0)}%`} 
          icon={Users} 
          colorClass="text-amber-500" 
          iconBg="bg-amber-50" 
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        {/* Charts - PC Optimized (more space) */}
        <div className="lg:col-span-8 bg-white p-10 lg:p-12 rounded-[3.5rem] border border-slate-50 shadow-sm hover:shadow-xl transition-all duration-700">
          <div className="flex items-center justify-between mb-12">
            <div>
              <h3 className="text-[12px] font-black text-slate-400 uppercase tracking-[0.3em] mb-2">Performance Analysis</h3>
              <p className="text-2xl font-black text-slate-800">Weekly Revenue Trends</p>
            </div>
            <div className="flex items-center gap-2 px-4 py-2 bg-emerald-50 text-emerald-600 rounded-xl text-[10px] font-black uppercase tracking-widest">
               Live Data
            </div>
          </div>
          <div className="h-[400px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={revenueData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis 
                  dataKey="name" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#94a3b8', fontSize: 11, fontWeight: 800}} 
                  dy={10}
                />
                <YAxis hide />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}}
                  contentStyle={{
                    borderRadius: '24px', 
                    border: 'none', 
                    boxShadow: '0 25px 50px -12px rgba(0,0,0,0.15)',
                    padding: '20px',
                    fontWeight: '900'
                  }}
                />
                <Bar 
                  dataKey="sales" 
                  fill="#10b981" 
                  radius={[12, 12, 4, 4]} 
                  barSize={60} 
                  animationDuration={2000}
                />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Top Products - PC Optimized */}
        <div className="lg:col-span-4 bg-white p-10 rounded-[3.5rem] border border-slate-50 shadow-sm hover:shadow-xl transition-all duration-700">
          <div className="flex flex-col mb-10">
            <h3 className="text-[12px] font-black text-slate-400 uppercase tracking-[0.3em] mb-2">Product Leaderboard</h3>
            <p className="text-2xl font-black text-slate-800">Best Sellers</p>
          </div>
          <div className="space-y-6">
            {popularDishes.map((item, index) => (
              <div key={item.id} className="flex items-center gap-6 p-5 hover:bg-slate-50 rounded-[2rem] transition-all duration-500 border border-transparent hover:border-slate-100 group">
                <div className="relative">
                  <img src={item.imageUrl} className="w-20 h-20 rounded-2xl object-cover shadow-md group-hover:scale-110 transition-transform duration-500" alt={item.name} />
                  <div className="absolute -top-3 -left-3 w-8 h-8 bg-slate-900 text-white rounded-full flex items-center justify-center text-[11px] font-black border-4 border-white shadow-lg">
                    {index + 1}
                  </div>
                </div>
                <div className="flex-1 overflow-hidden">
                  <h4 className="text-sm font-black text-slate-800 truncate uppercase tracking-tight mb-1.5">{item.name}</h4>
                  <div className="flex items-center gap-2">
                    <div className="flex items-center gap-1.5 text-[10px] text-amber-500 font-black bg-amber-50 px-2.5 py-1 rounded-lg">
                      <Star size={12} fill="currentColor" /> {item.salesCount} Units
                    </div>
                  </div>
                </div>
                <div className="text-right">
                  <span className="text-xs font-black text-slate-400 tracking-wider">Rp {item.price/1000}k</span>
                </div>
              </div>
            ))}
            {popularDishes.length === 0 && (
               <div className="py-20 text-center opacity-20">
                  <ShoppingBag size={48} className="mx-auto mb-4" />
                  <p className="text-xs font-black uppercase tracking-widest">No Sales Data</p>
               </div>
            )}
          </div>
          <button className="w-full mt-10 py-5 bg-slate-50 text-slate-400 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] hover:bg-slate-900 hover:text-white transition-all duration-500 border border-slate-100">
             View All Inventory
          </button>
        </div>
      </div>
    </div>
  );
};

