      { ingredientId: 'inv_1', name: 'Beras Premium', amountPerUnit: 0.15, unit: 'kg' },
      { ingredientId: 'inv_2', name: 'Ayam Kampung Paha', amountPerUnit: 1, unit: 'potong' }
    ]
  },
];

const INITIAL_SETTINGS: StoreSettings = {
  storeName: 'Nama Bisnis Anda',
  whatsappNumber: '628123456789',
  address: 'Alamat Katering Belum Diatur',
  currencySymbol: 'Rp',
  logoUrl: '',
  socialAccounts: []
};

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [viewMode, setViewMode] = useState<'admin' | 'customer'>('admin');
  const [activeTab, setActiveTab] = useState<'dashboard' | 'menu' | 'orders' | 'receivables' | 'advisor' | 'admins' | 'social' | 'security' | 'sales-report'>('dashboard');
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isProfileDropdownOpen, setIsProfileDropdownOpen] = useState(false);

  const [menu, setMenu] = useState<MenuItem[]>(INITIAL_MENU);
  const [categories, setCategories] = useState<string[]>(['Paket Buffet', 'Snack Box', 'Nasi Kotak', 'Tumpeng']);
  const [orders, setOrders] = useState<Order[]>([]);
  const [inventory, setInventory] = useState<IngredientStock[]>(INITIAL_INVENTORY);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [settings, setSettings] = useState<StoreSettings>(INITIAL_SETTINGS);
  const [admins, setAdmins] = useState<User[]>(INITIAL_ADMINS);
  const [shiftConfigs, setShiftConfigs] = useState<ShiftConfig[]>(INITIAL_SHIFTS);
  const [notifications, setNotifications] = useState<Notification[]>([]);

  const addNotification = useCallback((message: string, type: NotificationType) => {
    const id = Math.random().toString(36).substr(2, 9);
    setNotifications(prev => [{ id, message, type }, ...prev]);
    setTimeout(() => setNotifications(prev => prev.filter(n => n.id !== id)), 5000);
  }, []);

  const handleLogin = (name: string, shift: ShiftType, role: UserRole) => {
    const user = admins.find(a => a.name === name);
    setCurrentUser({
      id: user?.id || Math.random().toString(),
      name, role, shift,
      avatarUrl: user?.avatarUrl || `https://ui-avatars.com/api/?name=${name}`
    } as User);
    addNotification(`Selamat datang di ${settings.storeName}, ${name}!`, 'success');
  };

  const handleLogout = () => { setCurrentUser(null); setIsProfileDropdownOpen(false); };

  if (!currentUser) return <Login onLogin={handleLogin} shiftConfigs={shiftConfigs} admins={admins} />;
  if (viewMode === 'customer') return <PublicMenu menu={menu} settings={settings} categories={categories} onBackToAdmin={() => setViewMode('admin')} />;

  const isSuperAdmin = currentUser.role === 'Super Admin';

  const renderContent = () => {
    switch(activeTab) {
      case 'dashboard': return <Dashboard orders={orders} menu={menu} inventory={inventory} />;
      case 'menu': return <MenuManager menu={menu} onUpdateMenu={setMenu} categories={categories} onUpdateCategories={setCategories} inventory={inventory} onNotify={addNotification} />;
      case 'orders': return <OrdersList orders={orders} onAddOrder={(o) => setOrders([o, ...orders])} onUpdateOrder={() => {}} menu={menu} currentAdminName={currentUser.name} onNotify={addNotification} />;
      case 'receivables': return <ReceivablesList orders={orders} onUpdateOrder={() => {}} />;
      case 'advisor': return <SmartAdvisor inventory={inventory} orders={orders} menu={menu} onUpdateInventory={setInventory} onNotify={addNotification} currentAdmin={currentUser.name} />;
      case 'admins': 
        return isSuperAdmin 
          ? <AdminProfiles shiftConfigs={shiftConfigs} onUpdateShiftConfigs={setShiftConfigs} admins={admins} onUpdateAdmins={setAdmins} onNotify={addNotification} />
          : <Dashboard orders={orders} menu={menu} inventory={inventory} />;
      case 'social': return <SocialAnalytics menu={menu} settings={settings} onUpdateSettings={setSettings} />;
      case 'security': return <AccountSecurity />;
      case 'sales-report': return <SalesReport orders={orders} menu={menu} expenses={expenses} />;
      default: return <Dashboard orders={orders} menu={menu} inventory={inventory} />;
    }
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] flex font-sans selection:bg-emerald-100 text-slate-900">

      {/* Notifications */}
      <div className="fixed top-20 right-6 z-[300] flex flex-col gap-3 w-full max-w-sm pointer-events-none px-4">
        {notifications.map((n) => (
          <div key={n.id} className={`pointer-events-auto p-4 rounded-2xl shadow-xl border flex items-start gap-3 animate-in slide-in-from-right duration-300 ${n.type === 'error' ? 'bg-rose-600 text-white border-rose-500' : n.type === 'warning' ? 'bg-amber-500 text-white border-amber-400' : 'bg-emerald-600 text-white border-emerald-500'}`}>
            <div className="flex-1">
              <p className="text-sm font-bold leading-tight">{n.message}</p>
            </div>
            <button onClick={() => setNotifications(prev => prev.filter(x => x.id !== n.id))} className="text-white/40 hover:text-white"><X size={16} /></button>
          </div>
        ))}
      </div>

      <Sidebar 
        isOpen={true} setIsOpen={() => {}} activeTab={activeTab} setActiveTab={setActiveTab} 
        onPreviewMenu={() => setViewMode('customer')} logoUrl={settings.logoUrl} storeName={settings.storeName}
        onOpenSettings={() => isSuperAdmin && setIsSettingsOpen(true)} role={currentUser.role} isDesktop={true} 
      />

      <Sidebar 
        isOpen={isSidebarOpen} setIsOpen={setIsSidebarOpen} activeTab={activeTab} setActiveTab={setActiveTab} 
        onPreviewMenu={() => setViewMode('customer')} logoUrl={settings.logoUrl} storeName={settings.storeName}
        onOpenSettings={() => isSuperAdmin && setIsSettingsOpen(true)} role={currentUser.role} isDesktop={false} 
      />

      <div className="flex-1 flex flex-col lg:ml-64 min-h-screen relative">
        <header className="h-20 bg-white/80 backdrop-blur-md border-b border-slate-100 flex items-center justify-between px-6 lg:px-8 sticky top-0 z-[100]">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setIsSidebarOpen(true)} 
              className="p-2 text-slate-600 lg:hidden rounded-xl hover:bg-slate-100 transition-all"
            >
              <MenuIcon size={24} />
            </button>
            <div className="hidden md:block">
              <h2 className="text-xs font-bold text-slate-400 uppercase tracking-widest leading-none mb-1">{settings.storeName}</h2>
              <p className="text-base font-black text-slate-900 uppercase tracking-tight">{activeTab.replace('-', ' ')}</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
            <div className="relative">
              <div className="flex items-center gap-3 cursor-pointer p-1.5 rounded-2xl hover:bg-slate-50 transition-all" onClick={() => setIsProfileDropdownOpen(!isProfileDropdownOpen)}>
                <div className="w-10 h-10 rounded-xl bg-slate-100 overflow-hidden text-slate-400 flex items-center justify-center border border-slate-200">
                  {currentUser.avatarUrl ? <img src={currentUser.avatarUrl} alt="P" className="w-full h-full object-cover" /> : <UserCog size={20} />}
                </div>
                <div className="hidden sm:block text-left">
                  <p className="text-xs font-black text-slate-900 leading-none">{currentUser.name}</p>
                  <p className="text-[10px] font-bold text-emerald-600 uppercase tracking-widest mt-1">{currentUser.role}</p>
                </div>
                <ChevronDown size={14} className={`text-slate-300 transition-transform ${isProfileDropdownOpen ? 'rotate-180' : ''}`} />
              </div>

              {isProfileDropdownOpen && (
                <div className="absolute top-full right-0 mt-2 bg-white border border-slate-100 rounded-2xl shadow-2xl p-2 w-56 animate-in fade-in slide-in-from-top-2 z-[110]">
                  <button onClick={handleLogout} className="w-full flex items-center gap-3 px-4 py-3 text-sm font-bold text-rose-500 hover:bg-rose-50 rounded-xl transition-all">
                    <LogOut size={18} /> Keluar Sistem
                  </button>
                </div>
              )}
            </div>
          </div>
        </header>

        <main className="flex-1 px-4 py-8 lg:px-8 lg:py-10 pb-24">
          <div className="max-w-7xl mx-auto w-full">
            {renderContent()}
          </div>
        </main>
      </div>

      {isSettingsOpen && isSuperAdmin && (
        <div className="fixed inset-0 z-[250] flex justify-end">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsSettingsOpen(false)}></div>
          <div className="w-full max-w-xl bg-white h-full relative z-[260] shadow-2xl border-l border-slate-100 animate-in slide-in-from-right duration-300">
            <div className="flex items-center justify-between p-6 border-b border-slate-100">
               <h3 className="text-xl font-black text-slate-900 uppercase">Bisnis Settings</h3>
               <button onClick={() => setIsSettingsOpen(false)} className="p-2 text-slate-400 hover:bg-slate-50 rounded-xl transition-all"><X size={24} /></button>
            </div>
            <div className="h-full overflow-y-auto p-6 no-scrollbar pb-24">
              <Settings settings={settings} onUpdateSettings={setSettings} />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

