import React, { useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer
} from 'recharts';
import { TrendingUp, ShoppingBag, Wallet, Users, Star, AlertTriangle, ArrowRight } from 'lucide-react';
import { MenuItem, Order, IngredientStock } from '../types';

interface DashboardProps {
  orders: Order[];
  menu: MenuItem[];
  inventory: IngredientStock[];
}

const Dashboard: React.FC<DashboardProps> = ({ orders, menu, inventory }) => {
  const totalRevenue = orders.reduce((acc, curr) => acc + curr.totalPrice, 0);
  const totalReceivables = orders.reduce((acc, curr) => acc + (curr.totalPrice - curr.amountPaid), 0);
  const corporateOrders = orders.filter(o => o.type === 'Corporate').length;

  const popularDishes = [...menu]
    .sort((a, b) => b.salesCount - a.salesCount)
    .slice(0, 3);

  const deficits = useMemo(() => {
    const requirements: { [key: string]: number } = {};
    orders.filter(o => o.status === 'Pending' || o.status === 'Confirmed').forEach(order => {
      order.items.forEach(orderItemStr => {
        const match = orderItemStr.match(/(.*)\s\((\d+)\)/);
        if (!match) return;
        const [_, itemName, qtyStr] = match;
        const quantity = parseInt(qtyStr);
        const menuItem = menu.find(m => m.name === itemName.trim());
        if (menuItem?.recipe) {
          menuItem.recipe.forEach(ing => {
            requirements[ing.ingredientId] = (requirements[ing.ingredientId] || 0) + (ing.amountPerUnit * quantity);
          });
        }
      });
    });

    return Object.entries(requirements).map(([id, needed]) => {
      const stock = inventory.find(i => i.id === id);
      const stockQty = stock ? stock.quantity : 0;
      return { name: stock?.name || 'Unknown', deficit: Math.max(0, needed - stockQty) };
    }).filter(d => d.deficit > 0);
  }, [orders, menu, inventory]);

  const revenueData = [
    { name: 'Mon', sales: 4000 },
    { name: 'Tue', sales: 3000 },
    { name: 'Wed', sales: 6500 },
    { name: 'Thu', sales: 4500 },
    { name: 'Fri', sales: 9000 },
    { name: 'Sat', sales: 12000 },
    { name: 'Sun', sales: 10500 },
  ];

  const StatCard = ({ title, value, icon: Icon, colorClass, iconBg }: any) => (
    <div className="bg-white p-6 rounded-3xl border border-slate-100 flex items-center gap-6 shadow-sm">
      <div className={`w-12 h-12 ${iconBg} ${colorClass} rounded-2xl flex items-center justify-center`}>
        <Icon size={24} />
      </div>
      <div>
        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mb-1">{title}</p>
        <h3 className="text-xl font-black text-slate-800 tracking-tight">{value}</h3>
      </div>
    </div>
  );

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      {deficits.length > 0 && (
        <div className="bg-amber-500 rounded-3xl p-6 text-white flex flex-col md:flex-row items-center justify-between gap-4 shadow-xl border border-amber-400">
           <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-white/20 rounded-2xl flex items-center justify-center backdrop-blur-md">
                <AlertTriangle size={24} className="animate-pulse" />
              </div>
              <div>
                <h4 className="font-bold text-lg">Stok Bahan Kurang ({deficits.length})</h4>
                <p className="text-white/80 text-xs font-medium">Beberapa pesanan membutuhkan bahan yang stoknya habis.</p>
              </div>
           </div>
           <button className="bg-white/10 px-6 py-3 rounded-xl text-xs font-bold uppercase tracking-widest border border-white/10 hover:bg-white/20 transition-all flex items-center gap-2">
              Cek Dapur <ArrowRight size={16} />
           </button>
        </div>
      )}

      {/* Grid Statistik - Kembali ke 3 Kolom */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        <StatCard 
          title="Omzet Gross" 
          value={`Rp ${(totalRevenue/1000).toFixed(0)}k`} 
          icon={TrendingUp} 
          colorClass="text-emerald-500" 
          iconBg="bg-emerald-50" 
        />
        <StatCard 
          title="Piutang (AR)" 
          value={`Rp ${(totalReceivables/1000).toFixed(0)}k`} 
          icon={Wallet} 
          colorClass="text-rose-500" 
          iconBg="bg-rose-50" 
        />
        <StatCard 
          title="Pesanan Aktif" 
          value={orders.length} 
          icon={ShoppingBag} 
          colorClass="text-indigo-500" 
          iconBg="bg-indigo-50" 
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-8 bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
          <div className="flex items-center justify-between mb-8">
            <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest">Tren Pendapatan Mingguan</h3>
            <div className="flex items-center gap-2 px-3 py-1 bg-emerald-50 text-emerald-600 rounded-lg text-[10px] font-bold">Live</div>
          </div>
          <div className="h-[350px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={revenueData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis 
                  dataKey="name" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#94a3b8', fontSize: 11}} 
                  dy={10}
                />
                <YAxis hide />
                <Tooltip 
                  contentStyle={{borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)'}}
                />
                <Bar 
                  dataKey="sales" 
                  fill="#10b981" 
                  radius={[8, 8, 0, 0]} 
                  barSize={40} 
                />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="lg:col-span-4 bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
          <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest mb-6">Menu Terpopuler</h3>
          <div className="space-y-4">
            {popularDishes.map((item, index) => (
              <div key={item.id} className="flex items-center gap-4 p-3 hover:bg-slate-50 rounded-2xl transition-all border border-transparent hover:border-slate-100">
                <div className="relative">
                  <img src={item.imageUrl} className="w-16 h-16 rounded-xl object-cover" alt={item.name} />
                  <div className="absolute -top-2 -left-2 w-6 h-6 bg-slate-900 text-white rounded-full flex items-center justify-center text-[10px] font-bold border-2 border-white">
                    {index + 1}
                  </div>
                </div>
                <div className="flex-1 min-w-0">
                  <h4 className="text-sm font-bold text-slate-800 truncate">{item.name}</h4>
                  <div className="flex items-center gap-2 mt-1">
                    <span className="text-[10px] text-amber-500 font-bold bg-amber-50 px-2 py-0.5 rounded-lg flex items-center gap-1">
                      <Star size={10} fill="currentColor" /> {item.salesCount} Terjual
                    </span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

