  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isProfileDropdownOpen, setIsProfileDropdownOpen] = useState(false);

  // States initialized from LocalStorage
  const [menu, setMenu] = useState<MenuItem[]>(() => getLocal('menu', INITIAL_MENU));
  const [categories, setCategories] = useState<string[]>(() => getLocal('categories', ['Paket Buffet', 'Snack Box', 'Nasi Kotak', 'Tumpeng']));
  const [orders, setOrders] = useState<Order[]>(() => getLocal('orders', []));
  const [inventory, setInventory] = useState<IngredientStock[]>(() => getLocal('inventory', INITIAL_INVENTORY));
  const [expenses, setExpenses] = useState<Expense[]>(() => getLocal('expenses', []));
  const [settings, setSettings] = useState<StoreSettings>(() => getLocal('settings', INITIAL_SETTINGS));
  const [admins, setAdmins] = useState<User[]>(() => getLocal('admins', INITIAL_ADMINS));
  const [shiftConfigs, setShiftConfigs] = useState<ShiftConfig[]>(() => getLocal('shifts', INITIAL_SHIFTS));
  const [notifications, setNotifications] = useState<Notification[]>([]);

  // Persistence Sync Effects
  useEffect(() => { localStorage.setItem('caterly_v1_menu', JSON.stringify(menu)); }, [menu]);
  useEffect(() => { localStorage.setItem('caterly_v1_categories', JSON.stringify(categories)); }, [categories]);
  useEffect(() => { localStorage.setItem('caterly_v1_orders', JSON.stringify(orders)); }, [orders]);
  useEffect(() => { localStorage.setItem('caterly_v1_inventory', JSON.stringify(inventory)); }, [inventory]);
  useEffect(() => { localStorage.setItem('caterly_v1_expenses', JSON.stringify(expenses)); }, [expenses]);
  useEffect(() => { localStorage.setItem('caterly_v1_settings', JSON.stringify(settings)); }, [settings]);
  useEffect(() => { localStorage.setItem('caterly_v1_admins', JSON.stringify(admins)); }, [admins]);
  useEffect(() => { localStorage.setItem('caterly_v1_shifts', JSON.stringify(shiftConfigs)); }, [shiftConfigs]);

  const addNotification = useCallback((message: string, type: NotificationType) => {
    const id = Math.random().toString(36).substr(2, 9);
