          if (key === 'admins') setAdmins(val);
          if (key === 'shifts') setShiftConfigs(val);
        }
      }
      setDbStatus('online');
    } catch (e) {
      setDbStatus('offline');
      console.error('MySQL connection failed', e);
    }
  };

