import express from 'express';
import mysql from 'mysql2/promise';
import cors from 'cors';

const app = express();
app.use(cors());
app.use(express.json({ limit: '50mb' }));

const dbConfig = {
  host: 'localhost',
  user: 'root',      // Pastikan User MySQL di XAMPP/MySQL Anda adalah 'root'
  password: '',      // Kosongkan jika menggunakan XAMPP default
  database: 'caterly_db'
};

let pool;

async function initDB() {
  console.log('--- Mencoba Menghubungkan ke MySQL ---');
  try {
    // Koneksi awal tanpa database untuk memastikan MySQL running
    const connection = await mysql.createConnection({
      host: dbConfig.host,
      user: dbConfig.user,
      password: dbConfig.password
    });

    console.log('✔ MySQL Service Terdeteksi.');
    await connection.query(`CREATE DATABASE IF NOT EXISTS ${dbConfig.database}`);
    await connection.end();

    // Buat pool koneksi ke database spesifik
    pool = mysql.createPool(dbConfig);

    // Inisialisasi Tabel
    await pool.query(`
      CREATE TABLE IF NOT EXISTS app_data (
        id VARCHAR(50) PRIMARY KEY,
        content LONGTEXT,
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
      )
    `);

    console.log(`✔ Database '${dbConfig.database}' Siap Digunakan.`);
    return true;
  } catch (err) {
    console.error('✘ KONEKSI MYSQL GAGAL:');
    if (err.code === 'ECONNREFUSED') {
      console.error('  Saran: Pastikan MySQL (XAMPP/MySQL Service) sudah di-START.');
    } else if (err.code === 'ER_ACCESS_DENIED_ERROR') {
      console.error('  Saran: Cek Username & Password MySQL di server.js.');
    } else {
      console.error('  Error:', err.message);
    }
    return false;
  }
}

// Health Check Endpoint
app.get('/api/health', (req, res) => {
  res.json({ status: pool ? 'online' : 'offline', database: dbConfig.database });
});

// API Endpoints
app.get('/api/data/:key', async (req, res) => {
  if (!pool) return res.status(503).json({ error: 'Database belum siap' });
  try {
    const [rows] = await pool.query('SELECT content FROM app_data WHERE id = ?', [req.params.key]);
    if (rows.length > 0) {
      res.json(JSON.parse(rows[0].content));
    } else {
      res.status(404).json({ error: 'Not found' });
    }
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/data/:key', async (req, res) => {
  if (!pool) return res.status(503).json({ error: 'Database belum siap' });
  try {
    const content = JSON.stringify(req.body);
    await pool.query(
      'INSERT INTO app_data (id, content) VALUES (?, ?) ON DUPLICATE KEY UPDATE content = ?',
      [req.params.key, content, content]
    );
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

const PORT = 5000;

// Jalankan inisialisasi DB baru jalankan server
initDB().then((success) => {
  app.listen(PORT, () => {
    console.log(`\n🚀 SERVER BACKEND AKTIF: http://localhost:${PORT}`);
    if (!success) {
      console.log('⚠ PERINGATAN: Server jalan tapi MySQL mati. Silakan Start MySQL dan Refresh.');
    }
  });
});

