import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { 
  X, Menu as MenuIcon, LogOut, Sun, SunMedium, Moon, ChevronDown, 
  AlertTriangle, CheckCircle2, Timer, LayoutDashboard, ShoppingBag, 
  UtensilsCrossed, Wallet, PackageSearch, BarChart3, Share2, Shield, Crown, UserCog,
  Cpu, Database, RefreshCw
} from 'lucide-react';
import Dashboard from './components/Dashboard.tsx';
import MenuManager from './components/MenuManager.tsx';
import PublicMenu from './components/PublicMenu.tsx';
import Sidebar from './components/Sidebar.tsx';
import OrdersList from './components/OrdersList.tsx';
import ReceivablesList from './components/ReceivablesList.tsx';
import SmartAdvisor from './components/SmartAdvisor.tsx';
import Settings from './components/Settings.tsx';
import AdminProfiles from './components/AdminProfiles.tsx';
import SocialAnalytics from './components/SocialAnalytics.tsx';
import AccountSecurity from './components/AccountSecurity.tsx';
import SalesReport from './components/SalesReport.tsx';
import Login from './components/Login.tsx';
import { MenuItem, Order, StoreSettings, User, ShiftType, UserRole, IngredientStock, ShiftConfig, SocialAccount, Expense } from './types.ts';

const API_BASE = 'http://localhost:5000/api/data';

const INITIAL_SHIFTS: ShiftConfig[] = [
  { type: 'Pagi', startTime: '06:00', endTime: '14:00' },
  { type: 'Siang', startTime: '14:00', endTime: '22:00' },
  { type: 'Malam', startTime: '22:00', endTime: '06:00' },
];

const INITIAL_ADMINS: User[] = [
  { id: 'admin_1', name: 'Admin', role: 'Super Admin', shift: 'Pagi', password: 'admin', avatarUrl: '' },
];

const App: React.FC = () => {
  const [dbStatus, setDbStatus] = useState<'connecting' | 'online' | 'offline'>('connecting');
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [viewMode, setViewMode] = useState<'admin' | 'customer'>('admin');
  const [activeTab, setActiveTab] = useState<'dashboard' | 'menu' | 'orders' | 'receivables' | 'advisor' | 'admins' | 'social' | 'security' | 'sales-report'>('dashboard');
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const [menu, setMenu] = useState<MenuItem[]>([]);
  const [categories, setCategories] = useState<string[]>(['Paket Buffet', 'Snack Box', 'Nasi Kotak', 'Tumpeng']);
  const [orders, setOrders] = useState<Order[]>([]);
  const [inventory, setInventory] = useState<IngredientStock[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [settings, setSettings] = useState<StoreSettings>({ storeName: 'Caterly Smart OS', whatsappNumber: '', address: '', currencySymbol: 'Rp', socialAccounts: [] });
  const [admins, setAdmins] = useState<User[]>(INITIAL_ADMINS);
  const [shiftConfigs, setShiftConfigs] = useState<ShiftConfig[]>(INITIAL_SHIFTS);
  const [notifications, setNotifications] = useState<any[]>([]);

  const addNotification = useCallback((message: string, type: string) => {
    const id = Math.random().toString(36).substr(2, 9);
    setNotifications(prev => [{ id, message, type }, ...prev]);
    setTimeout(() => setNotifications(prev => prev.filter(n => n.id !== id)), 5000);
  }, []);

  const saveData = async (key: string, data: any) => {
    if (dbStatus !== 'online') return;
    try {
      await fetch(`${API_BASE}/${key}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(data)
      });
    } catch (e) { 
      setDbStatus('offline');
    }
  };

  const loadAllData = async () => {
    setDbStatus('connecting');
    const keys = ['menu', 'categories', 'orders', 'inventory', 'expenses', 'settings', 'admins', 'shifts'];

    try {
      const healthRes = await fetch('http://localhost:5000/api/health').catch(() => null);
      if (!healthRes || !healthRes.ok) {
        setDbStatus('offline');
        return;
      }

      const healthData = await healthRes.json();
      if (healthData.status !== 'online') {
        setDbStatus('offline');
        return;
      }

      for (const key of keys) {
        try {
          const res = await fetch(`${API_BASE}/${key}`);
          if (res.ok) {
            const val = await res.json();
            if (key === 'menu') setMenu(val);
            if (key === 'categories') setCategories(val);
            if (key === 'orders') setOrders(val);
            if (key === 'inventory') setInventory(val);
            if (key === 'expenses') setExpenses(val);
            if (key === 'settings') setSettings(val);
            if (key === 'admins') setAdmins(val);
            if (key === 'shifts') setShiftConfigs(val);
          }
        } catch (innerErr) {}
      }
      setDbStatus('online');
    } catch (e) {
      setDbStatus('offline');
    }
  };

  useEffect(() => { loadAllData(); }, []);

  useEffect(() => { saveData('menu', menu); }, [menu]);
  useEffect(() => { saveData('orders', orders); }, [orders]);
  useEffect(() => { saveData('inventory', inventory); }, [inventory]);
  useEffect(() => { saveData('settings', settings); }, [settings]);
  useEffect(() => { saveData('admins', admins); }, [admins]);
  useEffect(() => { saveData('shifts', shiftConfigs); }, [shiftConfigs]);

  const handleLogin = (name: string, shift: ShiftType, role: UserRole) => {
    const user = admins.find(a => a.name === name);
    setCurrentUser({
      id: user?.id || '1',
      name, role, shift,
      avatarUrl: user?.avatarUrl
    } as User);
    addNotification(`Login sukses! Sesi bertugas dimulai.`, 'success');
  };

  if (dbStatus === 'offline' && !currentUser) {
    return (
      <div className="min-h-screen bg-slate-950 flex flex-col items-center justify-center p-6 text-center">
        <div className="relative mb-8">
          <div className="w-24 h-24 bg-rose-500 rounded-[2.5rem] flex items-center justify-center text-white shadow-2xl shadow-rose-500/20">
            <Database size={40} />
          </div>
          <div className="absolute -bottom-2 -right-2 w-10 h-10 bg-white rounded-full flex items-center justify-center shadow-lg border-4 border-slate-950 text-rose-500">
            <AlertTriangle size={20} />
          </div>
        </div>
        <h1 className="text-4xl font-black text-white mb-2 italic">Caterly Hub</h1>
        <h2 className="text-xl font-bold text-slate-400 mb-4">Database Offline</h2>
        <p className="text-slate-500 max-w-sm mb-10 leading-relaxed font-medium italic">"Sistem tidak dapat terhubung ke MySQL. Pastikan Service MySQL (XAMPP) Anda sudah Aktif (Running)."</p>
        <button 
          onClick={() => window.location.reload()}
          className="bg-white text-slate-950 px-10 py-5 rounded-3xl font-black text-xs uppercase tracking-widest flex items-center gap-3 hover:bg-emerald-400 hover:text-white transition-all shadow-2xl shadow-white/10"
        >
          <RefreshCw size={18} /> Re-Connect Database
        </button>
      </div>
    );
  }

  if (!currentUser) return <Login onLogin={handleLogin} shiftConfigs={shiftConfigs} admins={admins} />;
  if (viewMode === 'customer') return <PublicMenu menu={menu} settings={settings} categories={categories} onBackToAdmin={() => setViewMode('admin')} />;

  const isSuperAdmin = currentUser.role === 'Super Admin';

  return (
    <div className="min-h-screen bg-[#f8fafc] flex font-sans text-slate-900">
      <Sidebar 
        isOpen={true} setIsOpen={() => {}} activeTab={activeTab} setActiveTab={setActiveTab} 
        onPreviewMenu={() => setViewMode('customer')} logoUrl={settings.logoUrl} storeName={settings.storeName}
        onOpenSettings={() => isSuperAdmin && setIsSettingsOpen(true)} role={currentUser.role} isDesktop={true} 
      />

      <div className="flex-1 flex flex-col lg:ml-64 min-h-screen relative">
        <header className="h-20 bg-white/80 backdrop-blur-md border-b border-slate-100 flex items-center justify-between px-6 lg:px-8 sticky top-0 z-[100]">
          <div className="flex items-center gap-4">
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-2 text-slate-600"><MenuIcon /></button>
            <div>
