            {activeTab === 'menu' && <MenuManager menu={menu} onUpdateMenu={setMenu} categories={categories} onUpdateCategories={setCategories} inventory={inventory} onNotify={addNotification} />}
            {activeTab === 'orders' && <OrdersList orders={orders} onAddOrder={(o) => setOrders([o, ...orders])} onUpdateOrder={(id, up) => setOrders(orders.map(o => o.id === id ? {...o, ...up} : o))} menu={menu} currentAdminName={currentUser.name} onNotify={addNotification} />}
            {activeTab === 'advisor' && <SmartAdvisor inventory={inventory} orders={orders} menu={menu} onUpdateInventory={setInventory} onNotify={addNotification} currentAdmin={currentUser.name} onAddExpense={(e) => setExpenses([e, ...expenses])} />}
            {activeTab === 'sales-report' && <SalesReport orders={orders} menu={menu} expenses={expenses} />}
            {activeTab === 'receivables' && <ReceivablesList orders={orders} onUpdateOrder={(id, up) => setOrders(orders.map(o => o.id === id ? {...o, ...up} : o))} />}
            {activeTab === 'admins' && isSuperAdmin && <AdminProfiles shiftConfigs={shiftConfigs} onUpdateShiftConfigs={setShiftConfigs} admins={admins} onUpdateAdmins={setAdmins} onNotify={addNotification} />}
            {activeTab === 'social' && <SocialAnalytics menu={menu} settings={settings} onUpdateSettings={setSettings} />}
            {activeTab === 'security' && <AccountSecurity />}
          </div>
        </main>
      </div>

      {isSidebarOpen && (
        <Sidebar 
          isOpen={isSidebarOpen} setIsOpen={setIsSidebarOpen} activeTab={activeTab} setActiveTab={setActiveTab} 
          onPreviewMenu={() => setViewMode('customer')} logoUrl={settings.logoUrl} storeName={settings.storeName}
          onOpenSettings={() => isSuperAdmin && setIsSettingsOpen(true)} role={currentUser.role} isDesktop={false} 
        />
      )}

      {isSettingsOpen && (
        <div className="fixed inset-0 z-[250] flex justify-end">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsSettingsOpen(false)}></div>
          <div className="w-full max-w-xl bg-white h-full relative z-[260] shadow-2xl p-6 overflow-y-auto no-scrollbar animate-in slide-in-from-right duration-300">
             <div className="flex justify-between items-center mb-8 border-b border-slate-50 pb-6">
                <h3 className="text-xl font-black uppercase">Business Settings</h3>
                <button onClick={() => setIsSettingsOpen(false)} className="p-2 text-slate-400 hover:text-slate-900"><X /></button>
             </div>
             <Settings settings={settings} onUpdateSettings={setSettings} />
          </div>
        </div>
      )}

      <div className="fixed bottom-6 right-6 z-[300] flex flex-col gap-2">
        {notifications.map(n => (
          <div key={n.id} className={`p-4 rounded-2xl shadow-xl border animate-in slide-in-from-right duration-300 flex items-center gap-3 ${n.type === 'success' ? 'bg-emerald-600 text-white border-emerald-500' : 'bg-rose-600 text-white border-rose-500'}`}>
            <CheckCircle2 size={18} />
            <p className="text-xs font-bold">{n.message}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

