                    <Icon size={20} className={isActive ? 'text-white' : 'text-slate-400 group-hover:text-white'} />
                    <p className="text-[9px] font-black uppercase tracking-widest">{s.type}</p>
                  </button>
                );
              })}
            </div>
          </div>

          <div className="space-y-4">
            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 px-2">Password Verifikasi</label>
            <div className="relative group">
              <div className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-emerald-400 transition-colors">
                <Lock size={20} />
              </div>
              <input 
                type={showPassword ? "text" : "password"}
                className={`w-full bg-white/5 border-2 ${error ? 'border-rose-500 animate-shake' : 'border-white/5'} rounded-[2rem] pl-16 pr-16 py-5 text-base font-black text-white outline-none focus:bg-white/10 focus:border-emerald-500/50 focus:ring-8 focus:ring-emerald-500/5 transition-all placeholder:text-slate-600`}
                placeholder="Password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
              />
              <button 
                type="button" 
                onClick={() => setShowPassword(!showPassword)} 
                className="absolute right-6 top-1/2 -translate-y-1/2 text-slate-500 hover:text-white transition-colors"
              >
                {showPassword ? <EyeOff size={22} /> : <Eye size={22} />}
              </button>
            </div>
          </div>

          <button 
            type="submit" 
            className="w-full bg-emerald-500 text-white py-6 rounded-[2.5rem] font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center gap-4 hover:bg-emerald-400 hover:scale-[1.02] active:scale-95 transition-all shadow-2xl shadow-emerald-500/30 group"
          >
            Akses Dashboard <ShieldIcon size={20} />
          </button>
        </form>
      </div>

      <style>{`
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          20% { transform: translateX(-8px); }
          40% { transform: translateX(8px); }
          60% { transform: translateX(-8px); }
          80% { transform: translateX(8px); }
        }
        .animate-shake { animation: shake 0.4s cubic-bezier(.36,.07,.19,.97) both; }
      `}</style>
    </div>
  );
};

