import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { 
  X, Menu as MenuIcon, LogOut, Sun, SunMedium, Moon, ChevronDown, 
  AlertTriangle, CheckCircle2, Timer, LayoutDashboard, ShoppingBag, 
  UtensilsCrossed, Wallet, PackageSearch, BarChart3, Share2, Shield, Crown, UserCog,
  Cpu, Database, RefreshCw, Loader2
} from 'lucide-react';
import Dashboard from './components/Dashboard.tsx';
import MenuManager from './components/MenuManager.tsx';
import PublicMenu from './components/PublicMenu.tsx';
import Sidebar from './components/Sidebar.tsx';
import OrdersList from './components/OrdersList.tsx';
import ReceivablesList from './components/ReceivablesList.tsx';
import SmartAdvisor from './components/SmartAdvisor.tsx';
import Settings from './components/Settings.tsx';
import AdminProfiles from './components/AdminProfiles.tsx';
import SocialAnalytics from './components/SocialAnalytics.tsx';
import AccountSecurity from './components/AccountSecurity.tsx';
import SalesReport from './components/SalesReport.tsx';
import Login from './components/Login.tsx';
import { MenuItem, Order, StoreSettings, User, ShiftType, UserRole, IngredientStock, ShiftConfig, SocialAccount, Expense } from './types.ts';

// Gunakan 127.0.0.1 untuk stabilitas lebih tinggi di Windows dibanding 'localhost'
const API_BASE = 'http://127.0.0.1:5000/api/data';
const HEALTH_URL = 'http://127.0.0.1:5000/api/health';

const INITIAL_SHIFTS: ShiftConfig[] = [
  { type: 'Pagi', startTime: '06:00', endTime: '14:00' },
  { type: 'Siang', startTime: '14:00', endTime: '22:00' },
  { type: 'Malam', startTime: '22:00', endTime: '06:00' },
];

const INITIAL_ADMINS: User[] = [
  { id: 'admin_1', name: 'Admin', role: 'Super Admin', shift: 'Pagi', password: 'admin', avatarUrl: '' },
];

const App: React.FC = () => {
  const [dbStatus, setDbStatus] = useState<'connecting' | 'online' | 'offline'>('connecting');
  const [retryCount, setRetryCount] = useState(0);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [viewMode, setViewMode] = useState<'admin' | 'customer'>('admin');
  const [activeTab, setActiveTab] = useState<'dashboard' | 'menu' | 'orders' | 'receivables' | 'advisor' | 'admins' | 'social' | 'security' | 'sales-report'>('dashboard');
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const [menu, setMenu] = useState<MenuItem[]>([]);
  const [categories, setCategories] = useState<string[]>(['Paket Buffet', 'Snack Box', 'Nasi Kotak', 'Tumpeng']);
  const [orders, setOrders] = useState<Order[]>([]);
  const [inventory, setInventory] = useState<IngredientStock[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [settings, setSettings] = useState<StoreSettings>({ storeName: 'Caterly Smart OS', whatsappNumber: '', address: '', currencySymbol: 'Rp', socialAccounts: [] });
  const [admins, setAdmins] = useState<User[]>(INITIAL_ADMINS);
  const [shiftConfigs, setShiftConfigs] = useState<ShiftConfig[]>(INITIAL_SHIFTS);
  const [notifications, setNotifications] = useState<any[]>([]);

  const addNotification = useCallback((message: string, type: string) => {
    const id = Math.random().toString(36).substr(2, 9);
    setNotifications(prev => [{ id, message, type }, ...prev]);
    setTimeout(() => setNotifications(prev => prev.filter(n => n.id !== id)), 5000);
  }, []);

  const saveData = async (key: string, data: any) => {
    if (dbStatus !== 'online') return;
    try {
      // Kita tidak menggunakan await di sini agar tidak memblock UI, 
      // dan tidak mematikan status koneksi jika gagal sekali saja (fire and forget with error log)
      fetch(`${API_BASE}/${key}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(data)
      }).catch(err => console.warn(`Silent Save failed for ${key}:`, err));
    } catch (e) { 
      console.error(`Persistent save failed for ${key}`);
    }
  };

  const loadAllData = async (attempt = 0) => {
    setDbStatus('connecting');
    setRetryCount(attempt);
    const keys = ['menu', 'categories', 'orders', 'inventory', 'expenses', 'settings', 'admins', 'shifts'];

    try {
      const healthRes = await fetch(HEALTH_URL).catch(() => null);

      if (!healthRes || !healthRes.ok) {
        if (attempt < 4) {
          console.log(`Koneksi gagal, mencoba kembali... (Percobaan ${attempt + 1}/5)`);
          setTimeout(() => loadAllData(attempt + 1), 1500); // Tunggu 1.5 detik sebelum coba lagi
          return;
        }
        setDbStatus('offline');
        return;
      }

      const healthData = await healthRes.json();
      if (healthData.status !== 'online') {
        setDbStatus('offline');
        return;
      }

      for (const key of keys) {
        try {
          const res = await fetch(`${API_BASE}/${key}`);
          if (res.ok) {
            const val = await res.json();
            if (key === 'menu') setMenu(val);
            if (key === 'categories') setCategories(val);
            if (key === 'orders') setOrders(val);
            if (key === 'inventory') setInventory(val);
            if (key === 'expenses') setExpenses(val);
            if (key === 'settings') setSettings(val);
            if (key === 'admins') setAdmins(val);
            if (key === 'shifts') setShiftConfigs(val);
          }
        } catch (innerErr) {}
      }
      setDbStatus('online');
    } catch (e) {
      if (attempt < 4) {
        setTimeout(() => loadAllData(attempt + 1), 1500);
      } else {
        setDbStatus('offline');
      }
    }
  };

  useEffect(() => { loadAllData(); }, []);

  // Gunakan debounce sederhana untuk saving agar tidak terlalu sering menabrak server
  useEffect(() => { const t = setTimeout(() => saveData('menu', menu), 1000); return () => clearTimeout(t); }, [menu]);
  useEffect(() => { const t = setTimeout(() => saveData('orders', orders), 1000); return () => clearTimeout(t); }, [orders]);
  useEffect(() => { const t = setTimeout(() => saveData('inventory', inventory), 1000); return () => clearTimeout(t); }, [inventory]);
  useEffect(() => { const t = setTimeout(() => saveData('settings', settings), 1000); return () => clearTimeout(t); }, [settings]);
  useEffect(() => { const t = setTimeout(() => saveData('admins', admins), 1000); return () => clearTimeout(t); }, [admins]);
  useEffect(() => { const t = setTimeout(() => saveData('shifts', shiftConfigs), 1000); return () => clearTimeout(t); }, [shiftConfigs]);

  const handleLogin = (name: string, shift: ShiftType, role: UserRole) => {
    const user = admins.find(a => a.name === name);
    setCurrentUser({
      id: user?.id || '1',
      name, role, shift,
      avatarUrl: user?.avatarUrl
    } as User);
    addNotification(`Login sukses! Sesi bertugas dimulai.`, 'success');
  };

  if (dbStatus === 'offline' && !currentUser) {
    return (
      <div className="min-h-screen bg-slate-950 flex flex-col items-center justify-center p-6 text-center">
        <div className="relative mb-8">
          <div className="w-24 h-24 bg-rose-500 rounded-[2.5rem] flex items-center justify-center text-white shadow-2xl shadow-rose-500/20">
            <Database size={40} />
          </div>
          <div className="absolute -bottom-2 -right-2 w-10 h-10 bg-white rounded-full flex items-center justify-center shadow-lg border-4 border-slate-950 text-rose-500">
            <AlertTriangle size={20} />
          </div>
        </div>
        <h1 className="text-4xl font-black text-white mb-2 italic">Caterly Hub</h1>
        <h2 className="text-xl font-bold text-slate-400 mb-4">Gagal Menghubungkan ke Server</h2>
        <p className="text-slate-500 max-w-sm mb-10 leading-relaxed font-medium italic">
          "Backend API atau MySQL belum aktif. Pastikan Anda menjalankan 'Caterly.bat' dan MySQL di XAMPP sudah berwarna hijau."
        </p>
        <div className="flex flex-col gap-3">
          <button 
            onClick={() => loadAllData(0)}
            className="bg-white text-slate-950 px-10 py-5 rounded-3xl font-black text-xs uppercase tracking-widest flex items-center gap-3 hover:bg-emerald-400 hover:text-white transition-all shadow-2xl shadow-white/10"
          >
            <RefreshCw size={18} /> Re-Connect Database
          </button>
          <p className="text-[10px] text-slate-600 font-bold uppercase tracking-widest">Target: 127.0.0.1:5000</p>
        </div>
      </div>
    );
  }

  // Loading State during retries
  if (dbStatus === 'connecting' && !currentUser) {
     return (
       <div className="min-h-screen bg-slate-950 flex flex-col items-center justify-center p-6 text-center">
          <Loader2 className="w-16 h-16 text-emerald-500 animate-spin mb-6" />
          <h1 className="text-2xl font-black text-white mb-2">Sinkronisasi Database...</h1>
          <p className="text-slate-500 text-xs font-bold uppercase tracking-widest">Mencoba Percobaan {retryCount + 1} dari 5</p>
       </div>
     )
  }

  if (!currentUser) return <Login onLogin={handleLogin} shiftConfigs={shiftConfigs} admins={admins} />;
  if (viewMode === 'customer') return <PublicMenu menu={menu} settings={settings} categories={categories} onBackToAdmin={() => setViewMode('admin')} />;

  const isSuperAdmin = currentUser.role === 'Super Admin';

  return (
    <div className="min-h-screen bg-[#f8fafc] flex font-sans text-slate-900">
      <Sidebar 
        isOpen={true} setIsOpen={() => {}} activeTab={activeTab} setActiveTab={setActiveTab} 
        onPreviewMenu={() => setViewMode('customer')} logoUrl={settings.logoUrl} storeName={settings.storeName}
        onOpenSettings={() => isSuperAdmin && setIsSettingsOpen(true)} role={currentUser.role} isDesktop={true} 
      />

      <div className="flex-1 flex flex-col lg:ml-64 min-h-screen relative">
        <header className="h-20 bg-white/80 backdrop-blur-md border-b border-slate-100 flex items-center justify-between px-6 lg:px-8 sticky top-0 z-[100]">
          <div className="flex items-center gap-4">
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-2 text-slate-600"><MenuIcon /></button>
            <div>
              <h2 className="text-xs font-bold text-slate-400 uppercase tracking-widest leading-none mb-1">{settings.storeName}</h2>
              <p className="text-base font-black uppercase tracking-tight">{activeTab.replace('-', ' ')}</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
             <div className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-[8px] font-black uppercase tracking-widest border transition-all ${
               dbStatus === 'online' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 
               dbStatus === 'connecting' ? 'bg-amber-50 text-amber-600 border-amber-100 animate-pulse' : 'bg-rose-50 text-rose-600 border-rose-100'
             }`}>
                <Database size={10} />
                {dbStatus === 'online' ? 'SQL Online' : dbStatus === 'connecting' ? 'Connecting...' : 'SQL Offline'}
             </div>
             <button onClick={() => setCurrentUser(null)} className="p-2 text-slate-400 hover:text-rose-500 transition-colors"><LogOut size={20} /></button>
          </div>
        </header>

        <main className="flex-1 p-6 lg:p-10 pb-24">
          <div className="max-w-7xl mx-auto">
            {activeTab === 'dashboard' && <Dashboard orders={orders} menu={menu} inventory={inventory} />}
            {activeTab === 'menu' && <MenuManager menu={menu} onUpdateMenu={setMenu} categories={categories} onUpdateCategories={setCategories} inventory={inventory} onNotify={addNotification} />}
            {activeTab === 'orders' && <OrdersList orders={orders} onAddOrder={(o) => setOrders([o, ...orders])} onUpdateOrder={(id, up) => setOrders(orders.map(o => o.id === id ? {...o, ...up} : o))} menu={menu} currentAdminName={currentUser.name} onNotify={addNotification} />}
            {activeTab === 'advisor' && <SmartAdvisor inventory={inventory} orders={orders} menu={menu} onUpdateInventory={setInventory} onNotify={addNotification} currentAdmin={currentUser.name} onAddExpense={(e) => setExpenses([e, ...expenses])} />}
            {activeTab === 'sales-report' && <SalesReport orders={orders} menu={menu} expenses={expenses} />}
            {activeTab === 'receivables' && <ReceivablesList orders={orders} onUpdateOrder={(id, up) => setOrders(orders.map(o => o.id === id ? {...o, ...up} : o))} />}
            {activeTab === 'admins' && isSuperAdmin && <AdminProfiles shiftConfigs={shiftConfigs} onUpdateShiftConfigs={setShiftConfigs} admins={admins} onUpdateAdmins={setAdmins} onNotify={addNotification} />}
            {activeTab === 'social' && <SocialAnalytics menu={menu} settings={settings} onUpdateSettings={setSettings} />}
            {activeTab === 'security' && <AccountSecurity />}
          </div>
        </main>
      </div>

      {isSidebarOpen && (
        <Sidebar 
          isOpen={isSidebarOpen} setIsOpen={setIsSidebarOpen} activeTab={activeTab} setActiveTab={setActiveTab} 
          onPreviewMenu={() => setViewMode('customer')} logoUrl={settings.logoUrl} storeName={settings.storeName}
          onOpenSettings={() => isSuperAdmin && setIsSettingsOpen(true)} role={currentUser.role} isDesktop={false} 
        />
      )}

      {isSettingsOpen && (
        <div className="fixed inset-0 z-[250] flex justify-end">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsSettingsOpen(false)}></div>
          <div className="w-full max-w-xl bg-white h-full relative z-[260] shadow-2xl p-6 overflow-y-auto no-scrollbar animate-in slide-in-from-right duration-300">
             <div className="flex justify-between items-center mb-8 border-b border-slate-50 pb-6">
                <h3 className="text-xl font-black uppercase">Business Settings</h3>
                <button onClick={() => setIsSettingsOpen(false)} className="p-2 text-slate-400 hover:text-slate-900"><X /></button>
             </div>
             <Settings settings={settings} onUpdateSettings={setSettings} />
          </div>
        </div>
      )}

      <div className="fixed bottom-6 right-6 z-[300] flex flex-col gap-2">
        {notifications.map(n => (
          <div key={n.id} className={`p-4 rounded-2xl shadow-xl border animate-in slide-in-from-right duration-300 flex items-center gap-3 ${n.type === 'success' ? 'bg-emerald-600 text-white border-emerald-500' : 'bg-rose-600 text-white border-rose-500'}`}>
            <CheckCircle2 size={18} />
            <p className="text-xs font-bold">{n.message}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

export default App;

import express from 'express';
import mysql from 'mysql2/promise';
import cors from 'cors';

const app = express();
app.use(cors());
app.use(express.json({ limit: '50mb' }));

// Middleware untuk Log Aktivitas
app.use((req, res, next) => {
  console.log(`[${new Date().toLocaleTimeString()}] ${req.method} ${req.url}`);
  next();
});

const dbConfig = {
  host: 'localhost',
  user: 'root',
  password: '',
  database: 'caterly_db',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0
};

let pool;

async function initDB() {
  console.log('--- Mencoba Menghubungkan ke MySQL ---');
  try {
    const connection = await mysql.createConnection({
      host: dbConfig.host,
      user: dbConfig.user,
      password: dbConfig.password
    });

    await connection.query(`CREATE DATABASE IF NOT EXISTS ${dbConfig.database}`);
    await connection.end();

    pool = mysql.createPool(dbConfig);

    // Test koneksi pool
    const [rows] = await pool.query('SELECT 1 + 1 AS result');

    await pool.query(`
      CREATE TABLE IF NOT EXISTS app_data (
        id VARCHAR(50) PRIMARY KEY,
        content LONGTEXT,
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
      )
    `);

    console.log(`✔ Database '${dbConfig.database}' Berhasil Dihubungkan.`);
    return true;
  } catch (err) {
    console.error('✘ KONEKSI MYSQL GAGAL:', err.message);
    return false;
  }
}

// Health Check
app.get('/api/health', (req, res) => {
  res.json({ 
    status: pool ? 'online' : 'offline', 
    timestamp: new Date().toISOString() 
  });
});

// API Endpoints
app.get('/api/data/:key', async (req, res) => {
  if (!pool) return res.status(503).json({ error: 'Database belum siap' });
  try {
    const [rows] = await pool.query('SELECT content FROM app_data WHERE id = ?', [req.params.key]);
    if (rows.length > 0) {
      res.json(JSON.parse(rows[0].content));
    } else {
      res.status(404).json({ error: 'Not found' });
    }
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/data/:key', async (req, res) => {
  if (!pool) return res.status(503).json({ error: 'Database belum siap' });
  try {
    const content = JSON.stringify(req.body);
    await pool.query(
      'INSERT INTO app_data (id, content) VALUES (?, ?) ON DUPLICATE KEY UPDATE content = ?',
      [req.params.key, content, content]
    );
    res.json({ success: true });
  } catch (err) {
    console.error(`Gagal menyimpan data ke ${req.params.key}:`, err.message);
    res.status(500).json({ error: err.message });
  }
});

const PORT = 5000;

initDB().then((success) => {
  app.listen(PORT, '0.0.0.0', () => {
    console.log(`\n🚀 SERVER BACKEND AKTIF: http://localhost:${PORT}`);
    if (!success) {
      console.log('⚠ MySQL terdeteksi OFFLINE. Silakan Start MySQL di XAMPP.');
    }
  });
});

