import express from 'express';
import mysql from 'mysql2/promise';
import cors from 'cors';

const app = express();
app.use(cors());
app.use(express.json({ limit: '50mb' }));

// Middleware untuk Log Aktivitas
app.use((req, res, next) => {
  console.log(`[${new Date().toLocaleTimeString()}] ${req.method} ${req.url}`);
  next();
});

const dbConfig = {
  host: '127.0.0.1', // Lebih stabil dibanding 'localhost' di beberapa Windows
  user: 'root',
  password: '',
  database: 'caterly_db',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0,
  connectTimeout: 10000
};

let pool = null;
let isDbConnected = false;

async function initDB() {
  console.log('--- Mencoba Menghubungkan ke MySQL ---');
  try {
    const connection = await mysql.createConnection({
      host: dbConfig.host,
      user: dbConfig.user,
      password: dbConfig.password
    });

    await connection.query(`CREATE DATABASE IF NOT EXISTS ${dbConfig.database}`);
    await connection.end();

    pool = mysql.createPool(dbConfig);

    // Test koneksi pool
    await pool.query('SELECT 1');

    await pool.query(`
      CREATE TABLE IF NOT EXISTS app_data (
        id VARCHAR(50) PRIMARY KEY,
        content LONGTEXT,
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
      )
    `);

    console.log(`✔ Database '${dbConfig.database}' Berhasil Dihubungkan.`);
    isDbConnected = true;
    return true;
  } catch (err) {
    console.error('✘ KONEKSI MYSQL GAGAL:', err.message);
    isDbConnected = false;
    // Coba lagi dalam 5 detik jika gagal
    setTimeout(initDB, 5000);
    return false;
  }
}

// Health Check - Memberikan info detail
app.get('/api/health', (req, res) => {
  res.json({ 
    status: isDbConnected ? 'online' : 'maintenance', 
    server: 'up',
    database: isDbConnected ? 'connected' : 'disconnected',
    timestamp: new Date().toISOString() 
  });
});

// API Endpoints dengan pengecekan pool
app.get('/api/data/:key', async (req, res) => {
  if (!isDbConnected || !pool) return res.status(503).json({ error: 'Database belum siap atau terputus' });
  try {
    const [rows] = await pool.query('SELECT content FROM app_data WHERE id = ?', [req.params.key]);
    if (rows.length > 0) {
      res.json(JSON.parse(rows[0].content));
    } else {
      res.status(404).json({ error: 'Not found' });
    }
  } catch (err) {
    console.error(`Error reading ${req.params.key}:`, err.message);
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/data/:key', async (req, res) => {
  if (!isDbConnected || !pool) return res.status(503).json({ error: 'Database belum siap atau terputus' });
  try {
    const content = JSON.stringify(req.body);
    await pool.query(
      'INSERT INTO app_data (id, content) VALUES (?, ?) ON DUPLICATE KEY UPDATE content = ?',
      [req.params.key, content, content]
    );
    res.json({ success: true });
  } catch (err) {
    console.error(`Gagal menyimpan data ke ${req.params.key}:`, err.message);
    res.status(500).json({ error: err.message });
  }
});

const PORT = 3000;

initDB().then(() => {
  app.listen(PORT, '0.0.0.0', () => {
    console.log(`\n🚀 SERVER BACKEND AKTIF: http://localhost:${PORT}`);
    console.log(`Target Frontend: http://localhost:5000\n`);
  });
});

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { 
  X, Menu as MenuIcon, LogOut, Sun, SunMedium, Moon, ChevronDown, 
  AlertTriangle, CheckCircle2, Timer, LayoutDashboard, ShoppingBag, 
  UtensilsCrossed, Wallet, PackageSearch, BarChart3, Share2, Shield, Crown, UserCog,
  Cpu, Database, RefreshCw, Loader2
} from 'lucide-react';
import Dashboard from './components/Dashboard.tsx';
import MenuManager from './components/MenuManager.tsx';
import PublicMenu from './components/PublicMenu.tsx';
import Sidebar from './components/Sidebar.tsx';
import OrdersList from './components/OrdersList.tsx';
import ReceivablesList from './components/ReceivablesList.tsx';
import SmartAdvisor from './components/SmartAdvisor.tsx';
import Settings from './components/Settings.tsx';
import AdminProfiles from './components/AdminProfiles.tsx';
import SocialAnalytics from './components/SocialAnalytics.tsx';
import AccountSecurity from './components/AccountSecurity.tsx';
import SalesReport from './components/SalesReport.tsx';
import Login from './components/Login.tsx';
import { MenuItem, Order, StoreSettings, User, ShiftType, UserRole, IngredientStock, ShiftConfig, SocialAccount, Expense } from './types.ts';

// Gunakan 127.0.0.1 untuk stabilitas
const API_BASE = 'http://127.0.0.1:3000/api/data';
const HEALTH_URL = 'http://127.0.0.1:3000/api/health';

const INITIAL_SHIFTS: ShiftConfig[] = [
  { type: 'Pagi', startTime: '06:00', endTime: '14:00' },
  { type: 'Siang', startTime: '14:00', endTime: '22:00' },
  { type: 'Malam', startTime: '22:00', endTime: '06:00' },
];

const INITIAL_ADMINS: User[] = [
  { id: 'admin_1', name: 'Admin', role: 'Super Admin', shift: 'Pagi', password: 'admin', avatarUrl: '' },
];

const App: React.FC = () => {
  const [dbStatus, setDbStatus] = useState<'connecting' | 'online' | 'offline'>('connecting');
  const [retryCount, setRetryCount] = useState(0);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [viewMode, setViewMode] = useState<'admin' | 'customer'>('admin');
  const [activeTab, setActiveTab] = useState<'dashboard' | 'menu' | 'orders' | 'receivables' | 'advisor' | 'admins' | 'social' | 'security' | 'sales-report'>('dashboard');
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const [menu, setMenu] = useState<MenuItem[]>([]);
  const [categories, setCategories] = useState<string[]>(['Paket Buffet', 'Snack Box', 'Nasi Kotak', 'Tumpeng']);
  const [orders, setOrders] = useState<Order[]>([]);
  const [inventory, setInventory] = useState<IngredientStock[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [settings, setSettings] = useState<StoreSettings>({ storeName: 'Caterly Smart OS', whatsappNumber: '', address: '', currencySymbol: 'Rp', socialAccounts: [] });
  const [admins, setAdmins] = useState<User[]>(INITIAL_ADMINS);
  const [shiftConfigs, setShiftConfigs] = useState<ShiftConfig[]>(INITIAL_SHIFTS);
  const [notifications, setNotifications] = useState<any[]>([]);

  const addNotification = useCallback((message: string, type: string) => {
    const id = Math.random().toString(36).substr(2, 9);
    setNotifications(prev => [{ id, message, type }, ...prev]);
    setTimeout(() => setNotifications(prev => prev.filter(n => n.id !== id)), 5000);
  }, []);

  const saveData = async (key: string, data: any) => {
    if (dbStatus !== 'online') return;
    try {
      // Async save tanpa await agar tidak mengganggu UI
      fetch(`${API_BASE}/${key}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(data)
      }).catch(err => console.warn(`Silent Save failed for ${key}:`, err));
    } catch (e) {}
  };

  const loadAllData = async (attempt = 0) => {
    setDbStatus('connecting');
    setRetryCount(attempt);

    try {
      // 1. Cek kesehatan server & database
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 3000);

      const healthRes = await fetch(HEALTH_URL, { signal: controller.signal }).catch(() => null);
      clearTimeout(timeoutId);

      if (!healthRes || !healthRes.ok) {
        if (attempt < 5) {
          const delay = Math.min(1000 * Math.pow(1.5, attempt), 5000);
          setTimeout(() => loadAllData(attempt + 1), delay);
          return;
        }
        setDbStatus('offline');
        return;
      }

      const healthData = await healthRes.json();
      if (healthData.status !== 'online') {
        // Server hidup tapi SQL mati (maintenance)
        if (attempt < 5) {
          setTimeout(() => loadAllData(attempt + 1), 2000);
          return;
        }
        setDbStatus('offline');
        return;
      }

      // 2. Jika online, muat semua data
      const keys = ['menu', 'categories', 'orders', 'inventory', 'expenses', 'settings', 'admins', 'shifts'];
      const fetchPromises = keys.map(async (key) => {
        try {
          const res = await fetch(`${API_BASE}/${key}`);
          if (res.ok) {
            const val = await res.json();
            if (key === 'menu') setMenu(val);
            if (key === 'categories') setCategories(val);
            if (key === 'orders') setOrders(val);
            if (key === 'inventory') setInventory(val);
            if (key === 'expenses') setExpenses(val);
            if (key === 'settings') setSettings(val);
            if (key === 'admins') setAdmins(val);
            if (key === 'shifts') setShiftConfigs(val);
          }
        } catch (err) {
          console.warn(`Gagal memuat ${key}`);
        }
      });

      await Promise.all(fetchPromises);
      setDbStatus('online');
    } catch (e) {
      if (attempt < 5) {
        setTimeout(() => loadAllData(attempt + 1), 2000);
      } else {
        setDbStatus('offline');
      }
    }
  };

  useEffect(() => {
    loadAllData();
  }, []);

  // Debounced auto-save
  useEffect(() => { 
    if (dbStatus !== 'online') return;
    const t = setTimeout(() => saveData('menu', menu), 2000); 
    return () => clearTimeout(t); 
  }, [menu, dbStatus]);

  useEffect(() => { 
    if (dbStatus !== 'online') return;
    const t = setTimeout(() => saveData('orders', orders), 2000); 
    return () => clearTimeout(t); 
  }, [orders, dbStatus]);

  useEffect(() => { 
    if (dbStatus !== 'online') return;
    const t = setTimeout(() => saveData('settings', settings), 2000); 
    return () => clearTimeout(t); 
  }, [settings, dbStatus]);

  const handleLogin = (name: string, shift: ShiftType, role: UserRole) => {
    const user = admins.find(a => a.name === name);
    setCurrentUser({
      id: user?.id || '1',
      name, role, shift,
      avatarUrl: user?.avatarUrl
    } as User);
    addNotification(`Login sukses! Sesi bertugas dimulai.`, 'success');
  };

  if (dbStatus === 'offline' && !currentUser) {
