import express from 'express';
import mysql from 'mysql2/promise';
import cors from 'cors';

const app = express();
app.use(cors());
app.use(express.json({ limit: '50mb' }));

// Middleware untuk Log Aktivitas
app.use((req, res, next) => {
  console.log(`[${new Date().toLocaleTimeString()}] ${req.method} ${req.url}`);
  next();
});

const dbConfig = {
  host: '127.0.0.1',
  user: 'root',
  password: '',
  database: 'caterly_db',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0,
  connectTimeout: 5000
};

let pool = null;
let isDbConnected = false;

async function initDB() {
  console.log('--- Mencoba Menghubungkan ke MySQL ---');
  try {
    const connection = await mysql.createConnection({
      host: dbConfig.host,
      user: dbConfig.user,
      password: dbConfig.password
    });

    await connection.query(`CREATE DATABASE IF NOT EXISTS ${dbConfig.database}`);
    await connection.end();

    pool = mysql.createPool(dbConfig);

    // Test koneksi pool
    await pool.query('SELECT 1');

    await pool.query(`
      CREATE TABLE IF NOT EXISTS app_data (
        id VARCHAR(50) PRIMARY KEY,
        content LONGTEXT,
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
      )
    `);

    console.log(`✔ Database '${dbConfig.database}' Berhasil Dihubungkan.`);
    isDbConnected = true;
    return true;
  } catch (err) {
    console.error('✘ KONEKSI MYSQL GAGAL:', err.message);
    isDbConnected = false;
    // Coba lagi dalam 5 detik
    setTimeout(initDB, 5000);
    return false;
  }
}

// Endpoint Dasar untuk cek apakah Node.js Aktif
app.get('/api/ping', (req, res) => {
  res.json({ status: 'alive', message: 'Backend Server is running' });
});

// Health Check Detail
app.get('/api/health', (req, res) => {
  res.json({ 
    status: isDbConnected ? 'online' : 'maintenance', 
    server: 'up',
    mysql: isDbConnected ? 'connected' : 'disconnected',
    timestamp: new Date().toISOString() 
  });
});

// API Endpoints
app.get('/api/data/:key', async (req, res) => {
  if (!isDbConnected || !pool) return res.status(503).json({ error: 'Database Offline' });
  try {
    const [rows] = await pool.query('SELECT content FROM app_data WHERE id = ?', [req.params.key]);
    if (rows.length > 0) {
      res.json(JSON.parse(rows[0].content));
    } else {
      res.status(404).json({ error: 'Not found' });
    }
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/data/:key', async (req, res) => {
  if (!isDbConnected || !pool) return res.status(503).json({ error: 'Database Offline' });
  try {
    const content = JSON.stringify(req.body);
    await pool.query(
      'INSERT INTO app_data (id, content) VALUES (?, ?) ON DUPLICATE KEY UPDATE content = ?',
      [req.params.key, content, content]
    );
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

const PORT = 3000;

const startServer = () => {
  const server = app.listen(PORT, '0.0.0.0', () => {
    console.log(`\n🚀 SERVER BACKEND AKTIF: http://127.0.0.1:${PORT}`);
    console.log(`Target Frontend: http://127.0.0.1:5000\n`);
    initDB();
  });

  server.on('error', (e) => {
    if (e.code === 'EADDRINUSE') {
      console.error(`\n✘ ERROR: Port ${PORT} sudah digunakan aplikasi lain.`);
      console.error(`Pastikan tidak ada proses Node.js lain yang sedang berjalan.`);
      process.exit(1);
    }
  });
};

startServer();

