const dbConfig = {
  host: '127.0.0.1',
  user: 'root',
  password: '',
  database: 'caterly_db',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0,
  connectTimeout: 5000
};

let pool = null;
let isDbConnected = false;

async function initDB() {
  console.log('--- Mencoba Menghubungkan ke MySQL (XAMPP) ---');
  try {
    const connection = await mysql.createConnection({
      host: dbConfig.host,
      user: dbConfig.user,
      password: dbConfig.password
    });

    await connection.query(`CREATE DATABASE IF NOT EXISTS ${dbConfig.database}`);
    await connection.end();

    pool = mysql.createPool(dbConfig);
    await pool.query('SELECT 1'); // Test query

    await pool.query(`
      CREATE TABLE IF NOT EXISTS app_data (
        id VARCHAR(50) PRIMARY KEY,
        content LONGTEXT,
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
      )
    `);

    console.log(`✔ DATABASE SIAP: Terhubung ke '${dbConfig.database}'`);
    isDbConnected = true;
  } catch (err) {
    console.error('✘ KONEKSI MYSQL GAGAL!');
    console.error(`  Detail: ${err.message}`);
    console.error('  TIPS: Pastikan XAMPP > MySQL sudah di-START (Hijau)');
    isDbConnected = false;
    setTimeout(initDB, 5000);
  }
}

