    console.log('Biarkan jendela ini tetap terbuka selama bekerja.\n');
    initDB();
  });

  server.on('error', (e) => {
    if (e.code === 'EADDRINUSE') {
      console.error(`\n✘ ERROR: Port ${PORT} sedang dipakai aplikasi lain.`);
      console.error(`TIPS: Tutup aplikasi lain atau restart komputer Anda.`);
