import React, { useState, useEffect, useCallback } from 'react';
import { 
  X, Menu as MenuIcon, LogOut, AlertTriangle, 
  RefreshCw, Loader2, Database, ShieldAlert, Cpu, 
  CheckCircle2, Terminal, ExternalLink, Activity
} from 'lucide-react';
import Dashboard from './components/Dashboard.tsx';
import MenuManager from './components/MenuManager.tsx';
import PublicMenu from './components/PublicMenu.tsx';
import Sidebar from './components/Sidebar.tsx';
import OrdersList from './components/OrdersList.tsx';
import ReceivablesList from './components/ReceivablesList.tsx';
import SmartAdvisor from './components/SmartAdvisor.tsx';
import Settings from './components/Settings.tsx';
import AdminProfiles from './components/AdminProfiles.tsx';
import SocialAnalytics from './components/SocialAnalytics.tsx';
import AccountSecurity from './components/AccountSecurity.tsx';
import SalesReport from './components/SalesReport.tsx';
import Login from './components/Login.tsx';
import { MenuItem, Order, StoreSettings, User, ShiftType, UserRole, IngredientStock, ShiftConfig, Expense } from './types.ts';

const API_BASE = 'http://127.0.0.1:3000/api/data';
const HEALTH_URL = 'http://127.0.0.1:3000/api/health';
const PING_URL = 'http://127.0.0.1:3000/api/ping';

const INITIAL_SHIFTS: ShiftConfig[] = [
  { type: 'Pagi', startTime: '06:00', endTime: '14:00' },
  { type: 'Siang', startTime: '14:00', endTime: '22:00' },
  { type: 'Malam', startTime: '22:00', endTime: '06:00' },
];

const INITIAL_ADMINS: User[] = [
  { id: 'admin_1', name: 'Admin', role: 'Super Admin', shift: 'Pagi', password: 'admin', avatarUrl: '' },
];

const App: React.FC = () => {
  const [dbStatus, setDbStatus] = useState<'connecting' | 'online' | 'offline' | 'maintenance'>('connecting');
  const [lastError, setLastError] = useState<string | null>(null);
  const [retryCount, setRetryCount] = useState(0);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [viewMode, setViewMode] = useState<'admin' | 'customer'>('admin');
  const [activeTab, setActiveTab] = useState<'dashboard' | 'menu' | 'orders' | 'receivables' | 'advisor' | 'admins' | 'social' | 'security' | 'sales-report'>('dashboard');
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const [menu, setMenu] = useState<MenuItem[]>([]);
  const [categories, setCategories] = useState<string[]>(['Paket Buffet', 'Snack Box', 'Nasi Kotak', 'Tumpeng']);
  const [orders, setOrders] = useState<Order[]>([]);
  const [inventory, setInventory] = useState<IngredientStock[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [settings, setSettings] = useState<StoreSettings>({ storeName: 'Caterly Smart OS', whatsappNumber: '', address: '', currencySymbol: 'Rp', socialAccounts: [] });
  const [admins, setAdmins] = useState<User[]>(INITIAL_ADMINS);
  const [shiftConfigs, setShiftConfigs] = useState<ShiftConfig[]>(INITIAL_SHIFTS);
  const [notifications, setNotifications] = useState<any[]>([]);

  const addNotification = useCallback((message: string, type: string) => {
    const id = Math.random().toString(36).substr(2, 9);
    setNotifications(prev => [{ id, message, type }, ...prev]);
    setTimeout(() => setNotifications(prev => prev.filter(n => n.id !== id)), 5000);
  }, []);

  const loadAllData = async (attempt = 0) => {
    setDbStatus('connecting');
    setRetryCount(attempt);
    setLastError(null);

    try {
      // Step 1: Cek apakah SERVER Node.js hidup?
      const pingRes = await fetch(PING_URL).catch(err => {
        setLastError(err.message);
        return null;
      });

      if (!pingRes || !pingRes.ok) {
        if (attempt < 3) {
          setTimeout(() => loadAllData(attempt + 1), 2000);
          return;
        }
        setDbStatus('offline');
        return;
      }

      // Step 2: Cek apakah MYSQL hidup?
      const healthRes = await fetch(HEALTH_URL).catch(() => null);
      if (!healthRes || !healthRes.ok) {
        setDbStatus('maintenance');
        return;
      }

      const healthData = await healthRes.json();
      if (healthData.status !== 'online') {
        setDbStatus('maintenance');
        return;
      }

      // Step 3: Muat semua data
      const keys = ['menu', 'categories', 'orders', 'inventory', 'expenses', 'settings', 'admins', 'shifts'];
      const fetchPromises = keys.map(async (key) => {
        try {
          const res = await fetch(`${API_BASE}/${key}`);
          if (res.ok) {
            const val = await res.json();
            if (key === 'menu') setMenu(val);
            if (key === 'categories') setCategories(val);
            if (key === 'orders') setOrders(val);
            if (key === 'inventory') setInventory(val);
            if (key === 'expenses') setExpenses(val);
            if (key === 'settings') setSettings(val);
            if (key === 'admins') setAdmins(val);
            if (key === 'shifts') setShiftConfigs(val);
          }
        } catch (err) {}
      });

      await Promise.all(fetchPromises);
      setDbStatus('online');
    } catch (e: any) {
      setLastError(e.message);
      setDbStatus('offline');
    }
  };

  const saveData = async (key: string, data: any) => {
    if (dbStatus !== 'online') return;
    try {
      fetch(`${API_BASE}/${key}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(data)
      }).catch(() => {});
    } catch (e) {}
  };

  useEffect(() => { loadAllData(); }, []);

  // Auto-Save effects
  useEffect(() => { if (dbStatus === 'online') { const t = setTimeout(() => saveData('menu', menu), 2000); return () => clearTimeout(t); } }, [menu, dbStatus]);
  useEffect(() => { if (dbStatus === 'online') { const t = setTimeout(() => saveData('orders', orders), 2000); return () => clearTimeout(t); } }, [orders, dbStatus]);

  if ((dbStatus === 'offline' || dbStatus === 'maintenance') && !currentUser) {
    return (
      <div className="min-h-screen bg-[#0f172a] flex flex-col items-center justify-center p-6 text-center">
        <div className="relative mb-12">
          <div className={`w-24 h-24 rounded-[2.5rem] flex items-center justify-center text-white shadow-2xl transition-all duration-700 ${dbStatus === 'offline' ? 'bg-rose-600 shadow-rose-900/40' : 'bg-amber-500 shadow-amber-900/40 animate-pulse'}`}>
            {dbStatus === 'offline' ? <ShieldAlert size={40} /> : <Database size={40} />}
          </div>
          <div className="absolute -bottom-2 -right-2 w-12 h-12 bg-slate-900 rounded-full flex items-center justify-center border-4 border-[#0f172a] text-rose-500 shadow-xl">
            <Activity size={24} className="animate-pulse" />
          </div>
        </div>

        <h1 className="text-5xl font-black text-white mb-3 italic tracking-tighter">Caterly Hub</h1>
        <h2 className="text-xl font-bold text-slate-400 mb-8 max-w-lg">
          {dbStatus === 'offline' ? 'System Connection Interrupted' : 'Database Synchronization Failed'}
        </h2>

        <div className="bg-slate-800/50 backdrop-blur-xl p-8 rounded-[2.5rem] border border-white/5 max-w-xl mb-12 text-left space-y-6">
          <div>
            <p className="text-slate-200 text-sm font-bold flex items-center gap-2 mb-2">
              <Terminal size={16} className="text-emerald-400" /> Diagnosa Masalah:
            </p>
            <p className="text-slate-400 text-xs leading-relaxed italic">
              {dbStatus === 'offline' 
                ? "Frontend tidak dapat menjangkau port 3000. Kemungkinan besar file 'Caterly.bat' belum dijalankan atau port 3000 diblokir oleh antivirus/aplikasi lain."
                : "Backend terhubung, namun MySQL di XAMPP tidak merespons. Pastikan modul MySQL sudah di-START."}
            </p>
          </div>

          {lastError && (
            <div className="p-4 bg-black/40 rounded-2xl border border-white/5">
              <p className="text-[10px] font-black text-rose-400 uppercase tracking-widest mb-1">Technical Log:</p>
              <p className="text-[10px] font-mono text-slate-500 break-all">{lastError}</p>
            </div>
          )}

          <div className="space-y-3">
             <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Langkah Perbaikan:</p>
             <div className="flex items-start gap-3 text-[11px] text-slate-300">
                <div className="w-5 h-5 rounded-full bg-slate-700 flex items-center justify-center shrink-0">1</div>
                <p>Jalankan <strong>Caterly.bat</strong> dan pastikan jendela CMD tetap terbuka.</p>
             </div>
             <div className="flex items-start gap-3 text-[11px] text-slate-300">
                <div className="w-5 h-5 rounded-full bg-slate-700 flex items-center justify-center shrink-0">2</div>
                <p>Buka XAMPP Control Panel, klik tombol <strong>Start</strong> pada baris MySQL.</p>
             </div>
          </div>
        </div>

        <div className="flex flex-col sm:flex-row gap-4">
          <button 
            onClick={() => loadAllData(0)}
            className="bg-emerald-500 text-white px-10 py-5 rounded-3xl font-black text-xs uppercase tracking-widest flex items-center justify-center gap-3 hover:bg-emerald-400 transition-all shadow-xl shadow-emerald-500/20 active:scale-95"
          >
            <RefreshCw size={18} /> Re-Connect System
          </button>

          <a 
            href="http://127.0.0.1:3000/api/ping" 
            target="_blank" 
            rel="noopener noreferrer"
            className="bg-white/5 text-slate-400 px-10 py-5 rounded-3xl font-black text-xs uppercase tracking-widest flex items-center justify-center gap-3 hover:bg-white/10 hover:text-white transition-all border border-white/10"
          >
            <ExternalLink size={18} /> Test Port 3000
          </a>
        </div>

        <p className="mt-12 text-[9px] font-black text-slate-600 uppercase tracking-[0.4em]">Target Endpoint: 127.0.0.1:3000</p>
      </div>
    );
  }

  if (dbStatus === 'connecting' && !currentUser) {
     return (
       <div className="min-h-screen bg-[#0f172a] flex flex-col items-center justify-center p-6 text-center">
          <Loader2 className="w-16 h-16 text-emerald-500 animate-spin mb-6" />
          <h1 className="text-2xl font-black text-white mb-2">Membangun Jalur Data...</h1>
          <p className="text-slate-500 text-[10px] font-black uppercase tracking-[0.3em]">Checking API & Database Stability</p>
       </div>
     )
  }

  if (!currentUser) return <Login onLogin={(n, s, r) => { setCurrentUser({ id: '1', name: n, role: r, shift: s } as User); }} shiftConfigs={shiftConfigs} admins={admins} />;
  if (viewMode === 'customer') return <PublicMenu menu={menu} settings={settings} categories={categories} onBackToAdmin={() => setViewMode('admin')} />;

  return (
    <div className="min-h-screen bg-[#f8fafc] flex font-sans text-slate-900">
      <Sidebar 
        isOpen={true} setIsOpen={() => {}} activeTab={activeTab} setActiveTab={setActiveTab} 
        onPreviewMenu={() => setViewMode('customer')} logoUrl={settings.logoUrl} storeName={settings.storeName}
        onOpenSettings={() => setIsSettingsOpen(true)} role={currentUser.role} isDesktop={true} 
      />

      <div className="flex-1 flex flex-col lg:ml-64 min-h-screen relative">
        <header className="h-20 bg-white/80 backdrop-blur-md border-b border-slate-100 flex items-center justify-between px-6 lg:px-8 sticky top-0 z-[100]">
          <div className="flex items-center gap-4">
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-2 text-slate-600"><MenuIcon /></button>
            <div>
              <h2 className="text-xs font-bold text-slate-400 uppercase tracking-widest leading-none mb-1">{settings.storeName}</h2>
              <p className="text-base font-black uppercase tracking-tight">{activeTab.replace('-', ' ')}</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
             <div className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-[8px] font-black uppercase tracking-widest border transition-all ${
               dbStatus === 'online' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-rose-50 text-rose-600 border-rose-100 animate-pulse'
             }`}>
                <Database size={10} />
                {dbStatus === 'online' ? 'SQL Online' : 'SQL Offline'}
             </div>
             <button onClick={() => setCurrentUser(null)} className="p-2 text-slate-400 hover:text-rose-500 transition-colors"><LogOut size={20} /></button>
          </div>
        </header>

        <main className="flex-1 p-6 lg:p-10 pb-24">
          <div className="max-w-7xl mx-auto">
            {activeTab === 'dashboard' && <Dashboard orders={orders} menu={menu} inventory={inventory} />}
            {activeTab === 'menu' && <MenuManager menu={menu} onUpdateMenu={setMenu} categories={categories} onUpdateCategories={setCategories} inventory={inventory} onNotify={addNotification} />}
            {activeTab === 'orders' && <OrdersList orders={orders} onAddOrder={(o) => setOrders([o, ...orders])} onUpdateOrder={(id, up) => setOrders(orders.map(o => o.id === id ? {...o, ...up} : o))} menu={menu} currentAdminName={currentUser.name} onNotify={addNotification} />}
            {activeTab === 'advisor' && <SmartAdvisor inventory={inventory} orders={orders} menu={menu} onUpdateInventory={setInventory} onNotify={addNotification} currentAdmin={currentUser.name} onAddExpense={(e) => setExpenses([e, ...expenses])} />}
            {activeTab === 'sales-report' && <SalesReport orders={orders} menu={menu} expenses={expenses} />}
            {activeTab === 'receivables' && <ReceivablesList orders={orders} onUpdateOrder={(id, up) => setOrders(orders.map(o => o.id === id ? {...o, ...up} : o))} />}
            {activeTab === 'admins' && <AdminProfiles shiftConfigs={shiftConfigs} onUpdateShiftConfigs={setShiftConfigs} admins={admins} onUpdateAdmins={setAdmins} onNotify={addNotification} />}
            {activeTab === 'social' && <SocialAnalytics menu={menu} settings={settings} onUpdateSettings={setSettings} />}
            {activeTab === 'security' && <AccountSecurity />}
          </div>
        </main>
      </div>

      {isSidebarOpen && (
        <Sidebar 
          isOpen={isSidebarOpen} setIsOpen={setIsSidebarOpen} activeTab={activeTab} setActiveTab={setActiveTab} 
          onPreviewMenu={() => setViewMode('customer')} logoUrl={settings.logoUrl} storeName={settings.storeName}
          onOpenSettings={() => setIsSettingsOpen(true)} role={currentUser.role} isDesktop={false} 
        />
      )}

      {isSettingsOpen && (
        <div className="fixed inset-0 z-[250] flex justify-end">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsSettingsOpen(false)}></div>
          <div className="w-full max-w-xl bg-white h-full relative z-[260] shadow-2xl p-6 overflow-y-auto no-scrollbar animate-in slide-in-from-right duration-300">
             <div className="flex justify-between items-center mb-8 border-b border-slate-50 pb-6">
                <h3 className="text-xl font-black uppercase">Business Settings</h3>
                <button onClick={() => setIsSettingsOpen(false)} className="p-2 text-slate-400 hover:text-slate-900"><X /></button>
             </div>
             <Settings settings={settings} onUpdateSettings={setSettings} />
          </div>
