          <div className="bg-black/40 p-4 rounded-2xl font-mono text-[11px] text-slate-400 leading-relaxed mb-6">
            {techLog}
          </div>

          <div className="space-y-3">
             <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Instruksi Solusi:</p>
