    fetch(`${API_BASE}/${key}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data)
    }).catch(() => {});
  };

  useEffect(() => { loadAllData(); }, []);

  useEffect(() => { if (dbStatus === 'online') { const t = setTimeout(() => saveData('menu', menu), 2000); return () => clearTimeout(t); } }, [menu, dbStatus]);
  useEffect(() => { if (dbStatus === 'online') { const t = setTimeout(() => saveData('orders', orders), 2000); return () => clearTimeout(t); } }, [orders, dbStatus]);

  if ((dbStatus === 'offline' || dbStatus === 'maintenance') && !currentUser) {
    return (
      <div className="min-h-screen bg-[#020617] flex flex-col items-center justify-center p-6 text-center">
        <div className="relative mb-8">
          <div className={`w-20 h-20 rounded-3xl flex items-center justify-center text-white shadow-2xl transition-all ${dbStatus === 'offline' ? 'bg-rose-500 shadow-rose-950/50' : 'bg-amber-500 animate-pulse'}`}>
            <ShieldAlert size={40} />
          </div>
        </div>

        <h1 className="text-3xl font-black text-white mb-2 italic">Caterly Smart OS</h1>
        <h2 className="text-sm font-bold text-slate-500 mb-8 uppercase tracking-widest">
          {dbStatus === 'offline' ? 'Sistem Terputus' : 'MySQL Belum Siap'}
        </h2>

        <div className="bg-slate-900 border border-white/5 p-8 rounded-[2.5rem] max-w-lg w-full mb-10 text-left">
          <p className="text-[10px] font-black text-emerald-400 uppercase tracking-widest mb-3 flex items-center gap-2">
            <Terminal size={14} /> Jurnal Diagnosa:
          </p>
          <div className="bg-black/60 p-4 rounded-2xl font-mono text-[11px] text-slate-400 leading-relaxed mb-6 border border-white/5">
            {techLog}
          </div>

          <div className="space-y-4">
             <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Langkah Perbaikan:</p>
             <div className="flex items-start gap-4">
                <div className="w-6 h-6 rounded-lg bg-emerald-500/10 text-emerald-500 flex items-center justify-center shrink-0 font-bold text-xs">1</div>
                <p className="text-[11px] text-slate-400">Tutup jendela CMD hitam yang lama, lalu buka kembali file <strong>Caterly.bat</strong>.</p>
             </div>
             <div className="flex items-start gap-4">
                <div className="w-6 h-6 rounded-lg bg-emerald-500/10 text-emerald-500 flex items-center justify-center shrink-0 font-bold text-xs">2</div>
                <p className="text-[11px] text-slate-400">Buka XAMPP Control Panel, pastikan baris <strong>MySQL</strong> sudah berwarna HIJAU.</p>
             </div>
          </div>
        </div>

        <div className="flex flex-col sm:flex-row gap-4">
          <button 
            onClick={loadAllData}
            className="bg-emerald-600 text-white px-10 py-5 rounded-3xl font-black text-xs uppercase tracking-widest flex items-center gap-3 hover:bg-emerald-500 transition-all shadow-xl shadow-emerald-950/20 active:scale-95"
          >
            <RefreshCw size={18} /> Hubungkan Kembali
          </button>
          <a 
            href="http://127.0.0.1:5050/api/ping" 
            target="_blank" 
            className="bg-white/5 text-slate-400 px-10 py-5 rounded-3xl font-black text-xs uppercase tracking-widest flex items-center gap-3 hover:bg-white/10 transition-all border border-white/10"
          >
            <ExternalLink size={18} /> Tes Manual Link API
          </a>
        </div>
      </div>
    );
  }

  if (dbStatus === 'connecting' && !currentUser) {
     return (
       <div className="min-h-screen bg-[#020617] flex flex-col items-center justify-center p-6 text-center">
          <Loader2 className="w-16 h-16 text-emerald-500 animate-spin mb-6" />
          <h1 className="text-xl font-black text-white mb-2">Sinkronisasi Sistem...</h1>
          <p className="text-slate-600 text-[10px] font-black uppercase tracking-[0.3em]">Checking API & Database Stability</p>
       </div>
     )
  }

  if (!currentUser) return <Login onLogin={(n, s, r) => { setCurrentUser({ id: '1', name: n, role: r, shift: s } as User); }} shiftConfigs={shiftConfigs} admins={admins} />;
  if (viewMode === 'customer') return <PublicMenu menu={menu} settings={settings} categories={categories} onBackToAdmin={() => setViewMode('admin')} />;

  return (
    <div className="min-h-screen bg-[#f8fafc] flex font-sans text-slate-900">
      <Sidebar 
        isOpen={true} setIsOpen={() => {}} activeTab={activeTab} setActiveTab={setActiveTab} 
        onPreviewMenu={() => setViewMode('customer')} logoUrl={settings.logoUrl} storeName={settings.storeName}
        onOpenSettings={() => setIsSettingsOpen(true)} role={currentUser.role} isDesktop={true} 
      />

      <div className="flex-1 flex flex-col lg:ml-64 min-h-screen relative">
        <header className="h-20 bg-white/80 backdrop-blur-md border-b border-slate-100 flex items-center justify-between px-6 lg:px-8 sticky top-0 z-[100]">
          <div className="flex items-center gap-4">
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-2 text-slate-600"><MenuIcon /></button>
            <div>
              <h2 className="text-xs font-bold text-slate-400 uppercase tracking-widest leading-none mb-1">{settings.storeName}</h2>
              <p className="text-base font-black uppercase tracking-tight">{activeTab.replace('-', ' ')}</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
             <div className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-[8px] font-black uppercase tracking-widest border transition-all ${
               dbStatus === 'online' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-rose-50 text-rose-600 border-rose-100 animate-pulse'
             }`}>
                <Database size={10} />
                {dbStatus === 'online' ? 'SQL Online' : 'SQL Offline'}
             </div>
             <button onClick={() => setCurrentUser(null)} className="p-2 text-slate-400 hover:text-rose-500 transition-colors"><LogOut size={20} /></button>
          </div>
        </header>

        <main className="flex-1 p-6 lg:p-10 pb-24">
          <div className="max-w-7xl mx-auto">
            {activeTab === 'dashboard' && <Dashboard orders={orders} menu={menu} inventory={inventory} />}
            {activeTab === 'menu' && <MenuManager menu={menu} onUpdateMenu={setMenu} categories={categories} onUpdateCategories={setCategories} inventory={inventory} onNotify={addNotification} />}
            {activeTab === 'orders' && <OrdersList orders={orders} onAddOrder={(o) => setOrders([o, ...orders])} onUpdateOrder={(id, up) => setOrders(orders.map(o => o.id === id ? {...o, ...up} : o))} menu={menu} currentAdminName={currentUser.name} onNotify={addNotification} />}
            {activeTab === 'advisor' && <SmartAdvisor inventory={inventory} orders={orders} menu={menu} onUpdateInventory={setInventory} onNotify={addNotification} currentAdmin={currentUser.name} onAddExpense={(e) => setExpenses([e, ...expenses])} />}
            {activeTab === 'sales-report' && <SalesReport orders={orders} menu={menu} expenses={expenses} />}
            {activeTab === 'receivables' && <ReceivablesList orders={orders} onUpdateOrder={(id, up) => setOrders(orders.map(o => o.id === id ? {...o, ...up} : o))} />}
            {activeTab === 'admins' && <AdminProfiles shiftConfigs={shiftConfigs} onUpdateShiftConfigs={setShiftConfigs} admins={admins} onUpdateAdmins={setAdmins} onNotify={addNotification} />}
            {activeTab === 'social' && <SocialAnalytics menu={menu} settings={settings} onUpdateSettings={setSettings} />}
            {activeTab === 'security' && <AccountSecurity />}
          </div>
        </main>
      </div>

      {isSidebarOpen && (
        <Sidebar 
          isOpen={isSidebarOpen} setIsOpen={setIsSidebarOpen} activeTab={activeTab} setActiveTab={setActiveTab} 
          onPreviewMenu={() => setViewMode('customer')} logoUrl={settings.logoUrl} storeName={settings.storeName}
          onOpenSettings={() => setIsSettingsOpen(true)} role={currentUser.role} isDesktop={false} 
        />
      )}

      {isSettingsOpen && (
        <div className="fixed inset-0 z-[250] flex justify-end">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsSettingsOpen(false)}></div>
          <div className="w-full max-w-xl bg-white h-full relative z-[260] shadow-2xl p-6 overflow-y-auto no-scrollbar animate-in slide-in-from-right duration-300">
             <div className="flex justify-between items-center mb-8 border-b border-slate-50 pb-6">
                <h3 className="text-xl font-black uppercase">Business Settings</h3>
                <button onClick={() => setIsSettingsOpen(false)} className="p-2 text-slate-400 hover:text-slate-900"><X /></button>
             </div>
             <Settings settings={settings} onUpdateSettings={setSettings} />
          </div>
        </div>
      )}

      <div className="fixed bottom-6 right-6 z-[300] flex flex-col gap-2">
        {notifications.map(n => (
          <div key={n.id} className={`p-4 rounded-2xl shadow-xl border animate-in slide-in-from-right duration-300 flex items-center gap-3 ${n.type === 'success' ? 'bg-emerald-600 text-white border-emerald-500' : 'bg-rose-600 text-white border-rose-500'}`}>
            <CheckCircle2 size={18} />
            <p className="text-xs font-bold">{n.message}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

export default App;

import express from 'express';
import mysql from 'mysql2/promise';
import cors from 'cors';

const app = express();

// Menangani error agar server tidak langsung mati jika ada kesalahan
process.on('uncaughtException', (err) => {
  console.error('\n[DATABASE ERROR] Ada masalah pada sistem:');
  console.error(err.message);
});

app.use(cors());
app.use(express.json({ limit: '50mb' }));

const dbConfig = {
  host: '127.0.0.1',
  user: 'root',
  password: '',
  database: 'caterly_db',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0,
  connectTimeout: 5000
};

let pool = null;
let isDbConnected = false;

async function initDB() {
  console.log('>>> Mengecek status XAMPP MySQL...');
  try {
    const connection = await mysql.createConnection({
      host: dbConfig.host,
      user: dbConfig.user,
      password: dbConfig.password
    });

    await connection.query(`CREATE DATABASE IF NOT EXISTS ${dbConfig.database}`);
    await connection.end();

    pool = mysql.createPool(dbConfig);
    await pool.query('SELECT 1');

    await pool.query(`
      CREATE TABLE IF NOT EXISTS app_data (
        id VARCHAR(50) PRIMARY KEY,
        content LONGTEXT,
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
      )
    `);

    console.log('✔ DATABASE: TERHUBUNG (MySQL Aktif)');
    isDbConnected = true;
  } catch (err) {
    console.error('✘ DATABASE: TIDAK TERHUBUNG');
    console.log('   Pesan: ' + err.message);
    console.log('   SOLUSI: Pastikan XAMPP > MySQL sudah di-START (Hijau)');
    isDbConnected = false;
    setTimeout(initDB, 5000);
  }
}

app.get('/api/ping', (req, res) => {
  res.json({ status: 'alive', info: 'Caterly Backend Port 5050' });
});

app.get('/api/health', (req, res) => {
  res.json({ 
    status: isDbConnected ? 'online' : 'maintenance', 
    db: isDbConnected ? 'connected' : 'disconnected'
  });
});

app.get('/api/data/:key', async (req, res) => {
  if (!isDbConnected || !pool) return res.status(503).json({ error: 'DB Offline' });
  try {
    const [rows] = await pool.query('SELECT content FROM app_data WHERE id = ?', [req.params.key]);
    if (rows.length > 0) {
      res.json(JSON.parse(rows[0].content));
    } else {
      res.status(404).json({ error: 'Not found' });
    }
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/data/:key', async (req, res) => {
  if (!isDbConnected || !pool) return res.status(503).json({ error: 'DB Offline' });
  try {
    const content = JSON.stringify(req.body);
    await pool.query(
      'INSERT INTO app_data (id, content) VALUES (?, ?) ON DUPLICATE KEY UPDATE content = ?',
      [req.params.key, content, content]
    );
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

const PORT = 5050;
const HOST = '127.0.0.1';

app.listen(PORT, HOST, () => {
  console.log('\n====================================================');
  console.log(`🚀 BACKEND AKTIF DI: http://${HOST}:${PORT}`);
  console.log('====================================================');
  console.log('Biarkan jendela ini tetap terbuka.');
  console.log('Hubungi browser Anda di port 5000.\n');
  initDB();
});
